function New-FileTransferV4PromotionDecisionLines {
    param(
        [Parameter(Mandatory = $true)][string]$ArtifactDir,
        [string]$SafeBaselineArtifactDir = ''
    )

    $operatorVerdict = Read-FileTransferPromotionKeyValueArtifact -Path (Join-Path $ArtifactDir 'filetransfer-operator-verdict.txt')
    $liveSummary = Read-FileTransferPromotionKeyValueArtifact -Path (Join-Path $ArtifactDir 'filetransfer-live-nkn-summary.txt')
    $localSummary = Read-FileTransferPromotionKeyValueArtifact -Path (Join-Path $ArtifactDir 'filetransfer-local-soak-summary.txt')
    $throughput = Read-FileTransferPromotionKeyValueArtifact -Path (Join-Path $ArtifactDir 'throughput-summary.txt')
    $decomposition = Read-FileTransferPromotionKeyValueArtifact -Path (Join-Path $ArtifactDir 'throughput-decomposition-summary.txt')
    $payload = Read-FileTransferPromotionKeyValueArtifact -Path (Join-Path $ArtifactDir 'payload-efficiency-summary.txt')
    $protocol = Read-FileTransferPromotionKeyValueArtifact -Path (Join-Path $ArtifactDir 'protocol-shape-summary.txt')
    $bridge = Read-FileTransferPromotionKeyValueArtifact -Path (Join-Path $ArtifactDir 'bridge-bulk-summary.txt')
    $baseline = Read-FileTransferPromotionKeyValueArtifact -Path (Join-Path $ArtifactDir 'baseline-comparison.txt')

    $safeSummary = @{}
    if (-not [string]::IsNullOrWhiteSpace($SafeBaselineArtifactDir)) {
        $safeLiveSummaryPath = Join-Path $SafeBaselineArtifactDir 'filetransfer-live-nkn-summary.txt'
        $safeLocalSummaryPath = Join-Path $SafeBaselineArtifactDir 'filetransfer-local-soak-summary.txt'
        if (Test-Path -LiteralPath $safeLiveSummaryPath -PathType Leaf) {
            $safeSummary = Read-FileTransferPromotionKeyValueArtifact -Path $safeLiveSummaryPath
        }
        elseif (Test-Path -LiteralPath $safeLocalSummaryPath -PathType Leaf) {
            $safeSummary = Read-FileTransferPromotionKeyValueArtifact -Path $safeLocalSummaryPath
        }
    }

    $sources = @($liveSummary, $localSummary, $throughput, $decomposition, $payload, $protocol, $bridge)
    $verdict = Get-FileTransferPromotionValue -Sources @($operatorVerdict, $liveSummary, $localSummary) -Name 'verdict' -Default '(unknown)'
    $dataProtocolVersion = Get-FileTransferPromotionValue -Sources @($liveSummary, $localSummary, $throughput, $decomposition, $baseline) -Name 'data_protocol_version' -Default '(unknown)'
    if ($dataProtocolVersion -eq '(unknown)' -and $baseline.ContainsKey('current_data_protocol_version')) {
        $dataProtocolVersion = [string]$baseline['current_data_protocol_version']
    }

    $payloadProfile = Get-FileTransferPromotionValue -Sources @($liveSummary, $localSummary, $payload) -Name 'payload_efficiency_profile' -Default '(unknown)'
    $limiter = Get-FileTransferPromotionValue -Sources @($decomposition) -Name 'likely_limiter' -Default 'inconclusive'
    $targetGoodput = $script:FileTransferRegularNknTargetGoodputBytesPerSecond
    $currentAverageGoodput = ConvertTo-FileTransferPromotionDouble -Values $liveSummary -Name 'average_goodput_bytes_per_second'
    if ($currentAverageGoodput -le 0) {
        $currentAverageGoodput = ConvertTo-FileTransferPromotionDouble -Values $localSummary -Name 'average_goodput_bytes_per_second'
    }
    if ($currentAverageGoodput -le 0) {
        $currentAverageGoodput = ConvertTo-FileTransferPromotionDouble -Values $decomposition -Name 'cycle_goodput_average_bytes_per_second'
    }

    $safeAverageGoodput = ConvertTo-FileTransferPromotionDouble -Values $safeSummary -Name 'average_goodput_bytes_per_second'
    $currentMatrix = Get-FileTransferPromotionLiveMatrixStats -ArtifactDir $ArtifactDir
    $safeMatrix = Get-FileTransferPromotionLiveMatrixStats -ArtifactDir $SafeBaselineArtifactDir
    $longProofMatrixComplete = if ($currentMatrix.MatrixComplete -eq 1 -or $safeMatrix.MatrixComplete -eq 1) { 1 } else { 0 }
    $longProofAverageGoodput = if ($currentMatrix.MatrixComplete -eq 1) {
        $currentAverageGoodput
    }
    elseif ($safeMatrix.MatrixComplete -eq 1) {
        $safeAverageGoodput
    }
    else {
        $currentAverageGoodput
    }
    $goodputTargetMet = if ($longProofAverageGoodput -ge $targetGoodput) { 1 } else { 0 }

    $safeBaselineAvailable = if ($baseline.ContainsKey('safe_baseline_available')) { [string]$baseline['safe_baseline_available'] } else { '0' }
    $baselineProtocolMismatch = if ($baseline.ContainsKey('baseline_protocol_mismatch')) { [string]$baseline['baseline_protocol_mismatch'] } else { '0' }
    $baselineRegressionFailed = if ($baseline.ContainsKey('regression_failed')) { [string]$baseline['regression_failed'] } else { '0' }
    $safeDataProtocolVersion = if ($baseline.ContainsKey('safe_data_protocol_version')) { [string]$baseline['safe_data_protocol_version'] } else { '(unknown)' }
    $sameProtocolV6BaselinePass = if (
        $safeBaselineAvailable -eq '1' -and
        $baselineProtocolMismatch -eq '0' -and
        $baselineRegressionFailed -eq '0' -and
        $dataProtocolVersion -eq '6' -and
        $safeDataProtocolVersion -eq '6') {
        1
    }
    else {
        0
    }

    $hardCounterNames = @(
        'payload_rejected_count',
        'decode_failure_count',
        'message_rejected_count',
        'bridge_bulk_send_failure_count',
        'bridge_bulk_queue_clear_count',
        'gui_progress_timeout_count',
        'terminal_missing_after_progress_timeout',
        'v4_feedback_both_failed_count',
        'v4_sender_failed_count',
        'v4_receiver_failed_count',
        'legacy_data_protocol_started_count',
        'unexpected_legacy_data_frame_during_v4_count')
    $hardCounterCount = 0
    foreach ($counterName in $hardCounterNames) {
        if ((ConvertTo-FileTransferPromotionDouble -Values $liveSummary -Name $counterName) -gt 0 -or
            (ConvertTo-FileTransferPromotionDouble -Values $localSummary -Name $counterName) -gt 0 -or
            (ConvertTo-FileTransferPromotionDouble -Values $protocol -Name $counterName) -gt 0 -or
            (ConvertTo-FileTransferPromotionDouble -Values $bridge -Name $counterName) -gt 0) {
            $hardCounterCount++
        }
    }
    $progressTimeoutCounter = [Math]::Max(
        (ConvertTo-FileTransferPromotionDouble -Values $liveSummary -Name 'gui_progress_timeout_count'),
        (ConvertTo-FileTransferPromotionDouble -Values $decomposition -Name 'gui_progress_timeout_count'))
    $cleanCorrectness = $verdict -eq 'PASS' -and $hardCounterCount -eq 0
    $decision = 'hold_inconclusive'
    $status = 'hold'
    $reason = 'inconclusive'
    $nextFocus = 'fix_harness_or_analyzer_evidence'

    if ($limiter -eq 'filetransfer_data_session_dispatch_missing') {
        $reason = 'filetransfer_data_session_dispatch_missing'
        $nextFocus = 'transport_data_session_lifecycle_dispatch'
    }
    elseif ($dataProtocolVersion -ne '6') {
        $reason = 'non_v6_protocol'
    }
    elseif ($progressTimeoutCounter -gt 0 -or
        (Get-FileTransferPromotionValue -Sources @($liveSummary, $decomposition) -Name 'terminal_missing_after_progress_timeout' -Default '0') -ne '0') {
        $reason = 'progress_timeout_incomplete_long_proof'
        switch ($limiter) {
            'v4_frontier_tail_repair_needed' {
                $nextFocus = 'frontier_tail_missing_range_generation'
            }
            'v4_frontier_tail_repair_not_filled' {
                $nextFocus = 'frontier_tail_repair_fill_delivery'
            }
            'v4_missing_range_repair_limited' {
                $nextFocus = 'missing_range_request_to_fill_latency'
            }
            'v4_repair_requested_not_received_by_sender' {
                $nextFocus = 'missing_range_repair_request_delivery'
            }
            'v4_repair_sent_not_observed_by_receiver' {
                $nextFocus = 'missing_range_repair_transport_delivery'
            }
            'v4_repair_observed_but_not_accepted' {
                $nextFocus = 'missing_range_repair_receiver_acceptance'
            }
            'v4_repair_accepted_but_frontier_not_advanced' {
                $nextFocus = 'missing_range_repair_frontier_advancement'
            }
            'v4_missing_range_due_state_mismatch' {
                $nextFocus = 'missing_range_state_reporting_consistency'
            }
            default {
                $nextFocus = 'fix_harness_or_analyzer_evidence'
            }
        }
    }
    elseif (-not $cleanCorrectness) {
        $reason = 'hard_failure_blocks_promotion'
    }
    elseif ($longProofMatrixComplete -ne 1) {
        $reason = 'long_live_matrix_incomplete'
    }
    elseif ($goodputTargetMet -ne 1) {
        switch ($limiter) {
            'v4_sender_pump_underfed' {
                $decision = 'iterate_sender_pump'
                $status = 'iterate'
                $reason = 'goodput_target_not_met'
                $nextFocus = 'sender_pump_scheduling_feed_capacity'
            }
            'v4_state_feedback_limited' {
                $decision = 'iterate_state_feedback'
                $status = 'iterate'
                $reason = 'goodput_target_not_met'
                $nextFocus = 'state_feedback_delivery_epoch_handling'
            }
            'v4_missing_range_repair_limited' {
                $decision = 'iterate_missing_range_repair'
                $status = 'iterate'
                $reason = 'goodput_target_not_met'
                $nextFocus = 'missing_range_request_to_fill_latency'
            }
            'v4_frontier_tail_repair_needed' {
                $decision = 'iterate_missing_range_repair'
                $status = 'iterate'
                $reason = 'goodput_target_not_met'
                $nextFocus = 'frontier_tail_missing_range_generation'
            }
            'v4_frontier_tail_repair_not_filled' {
                $decision = 'iterate_missing_range_repair'
                $status = 'iterate'
                $reason = 'goodput_target_not_met'
                $nextFocus = 'frontier_tail_repair_fill_delivery'
            }
            'v4_missing_range_repair_spam_limited' {
                $decision = 'iterate_missing_range_repair'
                $status = 'iterate'
                $reason = 'goodput_target_not_met'
                $nextFocus = 'missing_range_repair_deduplication'
            }
            'v4_repair_sent_but_not_filled' {
                $decision = 'iterate_missing_range_repair'
                $status = 'iterate'
                $reason = 'goodput_target_not_met'
                $nextFocus = 'missing_range_repair_fill_delivery'
            }
            'v4_repair_request_not_served' {
                $decision = 'iterate_missing_range_repair'
                $status = 'iterate'
                $reason = 'goodput_target_not_met'
                $nextFocus = 'missing_range_repair_sender_service'
            }
            'v4_repair_requested_not_received_by_sender' {
                $decision = 'iterate_missing_range_repair'
                $status = 'iterate'
                $reason = 'goodput_target_not_met'
                $nextFocus = 'missing_range_repair_request_delivery'
            }
            'v4_repair_sent_not_observed_by_receiver' {
                $decision = 'iterate_missing_range_repair'
                $status = 'iterate'
                $reason = 'goodput_target_not_met'
                $nextFocus = 'missing_range_repair_transport_delivery'
            }
            'v4_repair_observed_but_not_accepted' {
                $decision = 'iterate_missing_range_repair'
                $status = 'iterate'
                $reason = 'goodput_target_not_met'
                $nextFocus = 'missing_range_repair_receiver_acceptance'
            }
            'v4_repair_accepted_but_frontier_not_advanced' {
                $decision = 'iterate_missing_range_repair'
                $status = 'iterate'
                $reason = 'goodput_target_not_met'
                $nextFocus = 'missing_range_repair_frontier_advancement'
            }
            'v4_missing_range_due_state_mismatch' {
                $decision = 'iterate_missing_range_repair'
                $status = 'iterate'
                $reason = 'goodput_target_not_met'
                $nextFocus = 'missing_range_state_reporting_consistency'
            }
            'nkn_bulk_underutilized' {
                $decision = 'iterate_nkn_bulk'
                $status = 'iterate'
                $reason = 'goodput_target_not_met'
                $nextFocus = 'bridge_nkn_bulk_utilization'
            }
            'external_transport_limited' {
                $decision = 'iterate_external_transport'
                $status = 'iterate'
                $reason = 'goodput_target_not_met'
                $nextFocus = 'nkn_bridge_receive_health'
            }
            default {
                $reason = 'goodput_target_not_met_with_inconclusive_limiter'
            }
        }
    }
    elseif ($sameProtocolV6BaselinePass -ne 1) {
        if ($safeBaselineAvailable -ne '1') {
            $reason = 'baseline_rerun_required'
        }
        elseif ($baselineProtocolMismatch -ne '0') {
            $reason = 'baseline_protocol_mismatch_report_only'
        }
        elseif ($baselineRegressionFailed -ne '0') {
            $reason = 'safe_baseline_regression'
        }
        else {
            $reason = 'same_protocol_v6_baseline_not_confirmed'
        }
    }
    else {
        $decision = 'promote_v6_file_only'
        $status = 'promote'
        $reason = 'long_proof_and_baseline_clean'
        $nextFocus = 'capture_safe_v6_file_only_baseline'
    }

    return @(
        ("decision={0}" -f $decision),
        ("promotion_status={0}" -f $status),
        ("reason={0}" -f $reason),
        ("next_focus={0}" -f $nextFocus),
        ("required_live_matrix=16MiB,64MiB_x2"),
        ("required_cycle_count=4"),
        ("target_goodput_bytes_per_second={0}" -f $targetGoodput.ToString('F3', [System.Globalization.CultureInfo]::InvariantCulture)),
        ("data_protocol_version={0}" -f $dataProtocolVersion),
        ("payload_efficiency_profile={0}" -f $payloadProfile),
        ("operator_verdict={0}" -f $verdict),
        ("likely_limiter={0}" -f $limiter),
        ("current_average_goodput_bytes_per_second={0}" -f $currentAverageGoodput.ToString('F3', [System.Globalization.CultureInfo]::InvariantCulture)),
        ("long_proof_average_goodput_bytes_per_second={0}" -f $longProofAverageGoodput.ToString('F3', [System.Globalization.CultureInfo]::InvariantCulture)),
        ("goodput_target_met={0}" -f $goodputTargetMet),
        ("current_long_proof_cycle_count={0}" -f $currentMatrix.CycleCount),
        ("current_long_proof_completed_cycle_count={0}" -f $currentMatrix.CompletedCount),
        ("current_long_proof_16m_completed_count={0}" -f $currentMatrix.SixteenMiBCompletedCount),
        ("current_long_proof_64m_completed_count={0}" -f $currentMatrix.SixtyFourMiBCompletedCount),
        ("current_long_proof_matrix_complete={0}" -f $currentMatrix.MatrixComplete),
        ("safe_long_proof_cycle_count={0}" -f $safeMatrix.CycleCount),
        ("safe_long_proof_completed_cycle_count={0}" -f $safeMatrix.CompletedCount),
        ("safe_long_proof_16m_completed_count={0}" -f $safeMatrix.SixteenMiBCompletedCount),
        ("safe_long_proof_64m_completed_count={0}" -f $safeMatrix.SixtyFourMiBCompletedCount),
        ("safe_long_proof_matrix_complete={0}" -f $safeMatrix.MatrixComplete),
        ("long_proof_matrix_complete={0}" -f $longProofMatrixComplete),
        ("safe_baseline_available={0}" -f $safeBaselineAvailable),
        ("same_protocol_v6_baseline_pass={0}" -f $sameProtocolV6BaselinePass),
        ("baseline_protocol_mismatch={0}" -f $baselineProtocolMismatch),
        ("baseline_regression_failed={0}" -f $baselineRegressionFailed),
        ("safe_data_protocol_version={0}" -f $safeDataProtocolVersion),
        ("promotion_blocking_hard_counter_count={0}" -f $hardCounterCount),
        ("v4_feedback_both_failed_count={0}" -f (Get-FileTransferPromotionValue -Sources @($liveSummary, $protocol) -Name 'v4_feedback_both_failed_count' -Default '0')),
        ("v4_sender_failed_count={0}" -f (Get-FileTransferPromotionValue -Sources @($liveSummary, $protocol) -Name 'v4_sender_failed_count' -Default '0')),
        ("v4_receiver_failed_count={0}" -f (Get-FileTransferPromotionValue -Sources @($liveSummary, $protocol) -Name 'v4_receiver_failed_count' -Default '0')),
        ("legacy_data_protocol_started_count={0}" -f (Get-FileTransferPromotionValue -Sources @($liveSummary, $protocol) -Name 'legacy_data_protocol_started_count' -Default '0')),
        ("unexpected_legacy_data_frame_during_v4_count={0}" -f (Get-FileTransferPromotionValue -Sources @($liveSummary, $protocol) -Name 'unexpected_legacy_data_frame_during_v4_count' -Default '0'))
    )
}

function Write-FileTransferV4PromotionDecision {
    param(
        [Parameter(Mandatory = $true)][string]$ArtifactDir,
        [string]$SafeBaselineArtifactDir = ''
    )

    $lines = New-FileTransferV4PromotionDecisionLines -ArtifactDir $ArtifactDir -SafeBaselineArtifactDir $SafeBaselineArtifactDir
    Write-FileTransferArtifact -ArtifactDir $ArtifactDir -FileName 'v4-promotion-decision.txt' -Lines $lines | Out-Null

    $object = [ordered]@{}
    foreach ($line in @($lines)) {
        $separator = $line.IndexOf('=')
        if ($separator -le 0) {
            continue
        }

        $object[$line.Substring(0, $separator)] = $line.Substring($separator + 1)
    }

    $object | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath (Join-Path $ArtifactDir 'v4-promotion-decision.json') -Encoding UTF8
}

function Add-FileTransferProofChainFailureCandidates {
    param(
        [Parameter(Mandatory = $true)]$Candidates,
        [Parameter(Mandatory = $true)][string]$Class,
        [AllowEmptyCollection()][object[]]$Events = @(),
        [string]$DefaultReason = '',
        [switch]$UseDefaultReason
    )

    foreach ($event in @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)) {
        $sequence = [int64]$event.Sequence
        if ($sequence -le 0) {
            continue
        }

        $reason = if ($UseDefaultReason) { $DefaultReason } else { '' }
        if (-not $UseDefaultReason) {
            foreach ($fieldName in @(
                    'decision_reason',
                    'rejection_reason',
                    'failure_reason',
                    'settlement_reason',
                    'reason',
                    'error_code')) {
                $candidateReason = Get-FileTransferEventField -Event $event -Name $fieldName -Default ''
                if ([string]::IsNullOrWhiteSpace($candidateReason) -or
                    $candidateReason -in @('(none)', 'none', 'accepted', 'pass')) {
                    continue
                }

                $reason = $candidateReason
                break
            }
        }

        if ([string]::IsNullOrWhiteSpace($reason)) {
            $reason = if ([string]::IsNullOrWhiteSpace($DefaultReason)) { $Class } else { $DefaultReason }
        }

        $Candidates.Add([pscustomobject]@{
            Class = $Class
            Event = [string]$event.EventName
            Reason = $reason
            Sequence = $sequence
            SourcePath = [string]$event.FilePath
            LineNumber = [int]$event.LineNumber
            WriterSequence = Get-FileTransferEventInt64Field `
                -Event $event `
                -Name 'log_writer_sequence' `
                -Default 0
        }) | Out-Null
    }
}

function Get-FileTransferRegularV4RecoveryLeaseField {
    param(
        [Parameter(Mandatory = $true)]$Event,
        [Parameter(Mandatory = $true)][string[]]$Names,
        [string]$Default = ''
    )

    foreach ($name in @($Names)) {
        $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
        if (-not [string]::IsNullOrWhiteSpace($value) -and $value -notin @('(none)', 'none')) {
            return [string]$value
        }
    }

    return $Default
}

function Test-FileTransferRegularV4RecoveryLeaseIdentityMatch {
    param(
        [Parameter(Mandatory = $true)]$Left,
        [Parameter(Mandatory = $true)]$Right,
        [switch]$IncludeDirection
    )

    $fields = New-Object System.Collections.Generic.List[string]
    foreach ($field in @('session_id', 'transfer_id')) {
        $fields.Add($field) | Out-Null
    }
    if ($IncludeDirection) {
        $fields.Add('direction') | Out-Null
    }

    foreach ($field in $fields) {
        $leftValue = Get-FileTransferEventField -Event $Left -Name $field -Default ''
        $rightValue = Get-FileTransferEventField -Event $Right -Name $field -Default ''
        if ([string]::IsNullOrWhiteSpace($leftValue) -or
            $leftValue -in @('(none)', 'none') -or
            [string]::IsNullOrWhiteSpace($rightValue) -or
            $rightValue -in @('(none)', 'none') -or
            -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    return $true
}

function Test-FileTransferRegularV4RecoveryLeaseGrantMatch {
    param(
        [Parameter(Mandatory = $true)]$LeaseGrant,
        [Parameter(Mandatory = $true)]$LifecycleDecision
    )

    if (-not (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
            -Left $LeaseGrant `
            -Right $LifecycleDecision `
            -IncludeDirection)) {
        return $false
    }

    $leaseGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $LeaseGrant `
        -Names @('recovery_liveness_lease_generation', 'lease_generation', 'regular_v4_liveness_generation')
    $lifecycleGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $LifecycleDecision `
        -Names @('regular_v4_liveness_generation', 'recovery_liveness_lease_generation', 'lease_generation')
    if ([string]::IsNullOrWhiteSpace($leaseGeneration) -or
        [string]::IsNullOrWhiteSpace($lifecycleGeneration) -or
        $leaseGeneration -ne $lifecycleGeneration) {
        return $false
    }

    foreach ($field in @(
            'route',
            'protocol_version',
            'live_route_epoch',
            'runtime_generation',
            'terminal_generation',
            'leg_generation',
            'transport_epoch',
            'bridge_recovery_generation',
            'bridge_decision_generation')) {
        $leaseValue = Get-FileTransferEventField -Event $LeaseGrant -Name $field -Default ''
        $lifecycleValue = Get-FileTransferEventField -Event $LifecycleDecision -Name $field -Default ''
        if ([string]::IsNullOrWhiteSpace($leaseValue) -or
            $leaseValue -in @('(none)', 'none') -or
            [string]::IsNullOrWhiteSpace($lifecycleValue) -or
            $lifecycleValue -in @('(none)', 'none')) {
            continue
        }

        if (-not [string]::Equals($leaseValue, $lifecycleValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    $leaseAuthorityId = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $LeaseGrant `
        -Names @('lease_authority_id', 'recovery_liveness_lease_authority_id')
    $lifecycleAuthorityId = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $LifecycleDecision `
        -Names @('lease_authority_id', 'recovery_liveness_lease_authority_id')
    if (-not [string]::IsNullOrWhiteSpace($leaseAuthorityId) -and
        -not [string]::IsNullOrWhiteSpace($lifecycleAuthorityId) -and
        -not [string]::Equals($leaseAuthorityId, $lifecycleAuthorityId, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }

    return $true
}

function Get-FileTransferRegularV4RecoveryLeaseTupleKey {
    param([Parameter(Mandatory = $true)]$Event)

    $generation = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Event `
        -Names @('regular_v4_liveness_generation', 'recovery_liveness_lease_generation', 'lease_generation') `
        -Default '(missing)'
    $leaseAuthorityId = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Event `
        -Names @('lease_authority_id', 'recovery_liveness_lease_authority_id') `
        -Default '(missing)'
    $tupleParts = @(
            'session_id',
            'transfer_id',
            'direction',
            'route',
            'protocol_version',
            'live_route_epoch',
            'runtime_generation',
            'terminal_generation',
            'leg_generation',
            'transport_epoch',
            'bridge_recovery_generation',
            'bridge_decision_generation') |
            ForEach-Object { Get-FileTransferEventField -Event $Event -Name $_ -Default '(missing)' }
    return ($tupleParts -join '|') + '|' + $generation + '|' + $leaseAuthorityId
}

function Get-FileTransferRegularV4RecoveryBoundaryTupleKey {
    param([Parameter(Mandatory = $true)]$Event)

    return (@(
            'session_id',
            'transfer_id',
            'direction',
            'route',
            'protocol_version',
            'live_route_epoch',
            'regular_v4_liveness_generation',
            'bridge_decision_generation') |
            ForEach-Object { Get-FileTransferEventField -Event $Event -Name $_ -Default '(missing)' }) -join '|'
}

function Test-FileTransferRegularV4RecoveryBoundaryTupleMatch {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$Candidate
    )

    foreach ($field in @(
            'session_id',
            'transfer_id',
            'direction',
            'route',
            'protocol_version',
            'live_route_epoch',
            'regular_v4_liveness_generation',
            'bridge_decision_generation')) {
        $receiptValue = Get-FileTransferEventField -Event $Receipt -Name $field -Default ''
        $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $field -Default ''
        if ([string]::IsNullOrWhiteSpace($receiptValue) -or
            $receiptValue -in @('(none)', 'none') -or
            [string]::IsNullOrWhiteSpace($candidateValue) -or
            $candidateValue -in @('(none)', 'none') -or
            -not [string]::Equals($receiptValue, $candidateValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    return $true
}

function Test-FileTransferRegularV4RecoveryClosureHoldTupleMatch {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$Candidate
    )

    $candidateSchema = Get-FileTransferEventField -Event $Candidate -Name 'closure_proof_schema' -Default ''
    $currentFormat = $candidateSchema -eq '1'
    if (-not [string]::IsNullOrWhiteSpace($candidateSchema) -and -not $currentFormat) {
        return $false
    }

    $strictCurrentRejection = $currentFormat -and
        $Candidate.EventName -eq 'runtime_unlock_retry_rejected_after_regular_v4_receive_recovery'
    $currentProofEvent = $currentFormat -and $Candidate.EventName -in @(
        'runtime_unlock_retry_regular_v4_recovery_lease_closure_hold_preserved',
        'runtime_unlock_retry_rejected_after_regular_v4_receive_recovery')

    foreach ($field in @('session_id', 'transfer_id')) {
        $receiptValue = Get-FileTransferEventField -Event $Receipt -Name $field -Default ''
        $candidateValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Candidate `
            -Names @($field, ('closure_' + $field))
        if ([string]::IsNullOrWhiteSpace($receiptValue) -or
            $receiptValue -in @('(none)', 'none') -or
            [string]::IsNullOrWhiteSpace($candidateValue) -or
            $candidateValue -in @('(none)', 'none') -or
            -not [string]::Equals($receiptValue, $candidateValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
        if ($currentProofEvent) {
            $proofValue = Get-FileTransferEventField `
                -Event $Candidate `
                -Name ('closure_' + $field) `
                -Default ''
            if ([string]::IsNullOrWhiteSpace($proofValue) -or
                $proofValue -in @('(none)', 'none') -or
                -not [string]::Equals($receiptValue, $proofValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
    }

    $candidateDirection = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Candidate `
        -Names @('direction', 'closure_direction')
    if ($currentFormat -and
        ([string]::IsNullOrWhiteSpace($candidateDirection) -or $candidateDirection -in @('(none)', 'none'))) {
        return $false
    }
    if (-not [string]::IsNullOrWhiteSpace($candidateDirection) -and
        $candidateDirection -notin @('(none)', 'none')) {
        $receiptDirection = Get-FileTransferEventField -Event $Receipt -Name 'direction' -Default ''
        if ([string]::IsNullOrWhiteSpace($receiptDirection) -or
            $receiptDirection -in @('(none)', 'none') -or
            -not [string]::Equals(
                $receiptDirection,
                $candidateDirection,
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
        if ($currentProofEvent) {
            $proofDirection = Get-FileTransferEventField `
                -Event $Candidate `
                -Name 'closure_direction' `
                -Default ''
            if (-not [string]::Equals(
                    $receiptDirection,
                    $proofDirection,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        if ($strictCurrentRejection) {
            $currentDirection = Get-FileTransferEventField `
                -Event $Candidate `
                -Name 'current_direction' `
                -Default ''
            if (-not [string]::Equals(
                    $receiptDirection,
                    $currentDirection,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
    }

    $fieldAliases = [ordered]@{
        route = @('route', 'closure_route', 'current_route')
        protocol_version = @('protocol_version', 'closure_protocol_version', 'current_protocol_version')
        live_route_epoch = @('live_route_epoch', 'closure_live_route_epoch', 'current_live_route_epoch')
        runtime_generation = @('runtime_generation', 'closure_runtime_generation', 'current_runtime_generation')
        terminal_generation = @('terminal_generation', 'closure_terminal_generation', 'current_terminal_generation')
        leg_generation = @('leg_generation', 'closure_leg_generation', 'current_leg_generation')
        transport_epoch = @('transport_epoch', 'closure_transport_epoch', 'current_transport_epoch')
        bridge_recovery_generation = @('bridge_recovery_generation', 'closure_bridge_recovery_generation', 'current_bridge_recovery_generation')
    }
    foreach ($field in $fieldAliases.Keys) {
        $candidateValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Candidate `
            -Names $fieldAliases[$field]
        if ([string]::IsNullOrWhiteSpace($candidateValue) -or $candidateValue -in @('(none)', 'none')) {
            if ($currentFormat) {
                return $false
            }
            continue
        }

        $receiptValue = Get-FileTransferEventField -Event $Receipt -Name $field -Default ''
        if ([string]::IsNullOrWhiteSpace($receiptValue) -or
            $receiptValue -in @('(none)', 'none') -or
            -not [string]::Equals($receiptValue, $candidateValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }

        if ($strictCurrentRejection) {
            $attemptedValue = Get-FileTransferEventField `
                -Event $Candidate `
                -Name $field `
                -Default ''
            $currentValue = Get-FileTransferEventField `
                -Event $Candidate `
                -Name ('current_' + $field) `
                -Default ''
            if ([string]::IsNullOrWhiteSpace($attemptedValue) -or
                $attemptedValue -in @('(none)', 'none') -or
                -not [string]::Equals($receiptValue, $attemptedValue, [System.StringComparison]::OrdinalIgnoreCase) -or
                [string]::IsNullOrWhiteSpace($currentValue) -or
                $currentValue -in @('(none)', 'none') -or
                -not [string]::Equals($receiptValue, $currentValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        if ($currentProofEvent) {
            $proofValue = Get-FileTransferEventField `
                -Event $Candidate `
                -Name ('closure_' + $field) `
                -Default ''
            if ([string]::IsNullOrWhiteSpace($proofValue) -or
                $proofValue -in @('(none)', 'none') -or
                -not [string]::Equals($receiptValue, $proofValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
    }

    $receiptLivenessGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Receipt `
        -Names @('regular_v4_liveness_generation', 'recovery_liveness_lease_generation', 'lease_generation')
    $candidateLivenessGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Candidate `
        -Names @(
            'regular_v4_liveness_generation',
            'closure_liveness_generation',
            'current_regular_v4_liveness_generation',
            'adopted_recovery_liveness_generation',
            'recovery_liveness_lease_generation',
            'lease_generation')
    if ([string]::IsNullOrWhiteSpace($receiptLivenessGeneration) -or
        [string]::IsNullOrWhiteSpace($candidateLivenessGeneration) -or
        $receiptLivenessGeneration -ne $candidateLivenessGeneration) {
        return $false
    }

    $receiptBridgeDecisionGeneration = Get-FileTransferEventField `
        -Event $Receipt `
        -Name 'bridge_decision_generation' `
        -Default ''
    $candidateBridgeDecisionGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Candidate `
        -Names @(
            'bridge_decision_generation',
            'closure_bridge_decision_generation',
            'current_bridge_decision_generation',
            'adopted_bridge_decision_generation')
    if ($strictCurrentRejection) {
        $attemptedLivenessGeneration = Get-FileTransferEventField `
            -Event $Candidate `
            -Name 'regular_v4_liveness_generation' `
            -Default ''
        $currentLivenessGeneration = Get-FileTransferEventField `
            -Event $Candidate `
            -Name 'current_regular_v4_liveness_generation' `
            -Default ''
        $currentBridgeDecisionGeneration = Get-FileTransferEventField `
            -Event $Candidate `
            -Name 'current_bridge_decision_generation' `
            -Default ''
        $attemptedBridgeDecisionGeneration = Get-FileTransferEventField `
            -Event $Candidate `
            -Name 'bridge_decision_generation' `
            -Default ''
        if ($attemptedLivenessGeneration -ne $receiptLivenessGeneration -or
            $currentLivenessGeneration -ne $receiptLivenessGeneration -or
            $attemptedBridgeDecisionGeneration -ne $receiptBridgeDecisionGeneration -or
            $currentBridgeDecisionGeneration -ne $receiptBridgeDecisionGeneration) {
            return $false
        }
    }
    if ($currentProofEvent) {
        $proofLivenessGeneration = Get-FileTransferEventField `
            -Event $Candidate `
            -Name 'closure_liveness_generation' `
            -Default ''
        $proofBridgeDecisionGeneration = Get-FileTransferEventField `
            -Event $Candidate `
            -Name 'closure_bridge_decision_generation' `
            -Default ''
        if ($proofLivenessGeneration -ne $receiptLivenessGeneration -or
            $proofBridgeDecisionGeneration -ne $receiptBridgeDecisionGeneration) {
            return $false
        }
    }

    return -not [string]::IsNullOrWhiteSpace($receiptBridgeDecisionGeneration) -and
        -not [string]::IsNullOrWhiteSpace($candidateBridgeDecisionGeneration) -and
        $receiptBridgeDecisionGeneration -eq $candidateBridgeDecisionGeneration
}

function Test-FileTransferRegularV4RecoveryClosureHoldLegacyBindingUnique {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$Candidate,
        [Parameter(Mandatory = $true)][object[]]$Receipts
    )

    $receiptSchema = Get-FileTransferEventField -Event $Receipt -Name 'closure_proof_schema' -Default ''
    $candidateSchema = Get-FileTransferEventField -Event $Candidate -Name 'closure_proof_schema' -Default ''
    if ($receiptSchema -eq '1' -and $candidateSchema -eq '1') {
        return $true
    }
    if (-not [string]::IsNullOrWhiteSpace($receiptSchema) -or
        -not [string]::IsNullOrWhiteSpace($candidateSchema)) {
        return $false
    }

    $matches = @($Receipts | Where-Object {
        [int64]$_.Sequence -le [int64]$Candidate.Sequence -and
        [string]::IsNullOrWhiteSpace(
            (Get-FileTransferEventField -Event $_ -Name 'closure_proof_schema' -Default '')) -and
        (Test-FileTransferRegularV4RecoveryClosureHoldTupleMatch `
            -Receipt $_ `
            -Candidate $Candidate)
    })
    return $matches.Count -eq 1 -and [int64]$matches[0].Sequence -eq [int64]$Receipt.Sequence
}

function Test-FileTransferRegularV4RepairSettlementAdoptionMatch {
    param(
        [Parameter(Mandatory = $true)]$Settlement,
        [Parameter(Mandatory = $true)]$Adoption
    )

    foreach ($field in @(
            'session_id',
            'transfer_id',
            'direction',
            'route',
            'protocol_version',
            'live_route_epoch',
            'runtime_generation',
            'terminal_generation',
            'leg_generation',
            'transport_epoch',
            'bridge_recovery_generation',
            'bridge_decision_generation',
            'route_publication_generation',
            'route_commit_generation',
            'target_transport',
            'repair_request_key')) {
        $settlementValue = Get-FileTransferEventField -Event $Settlement -Name $field -Default ''
        $adoptionValue = Get-FileTransferEventField -Event $Adoption -Name $field -Default ''
        if ([string]::IsNullOrWhiteSpace($settlementValue) -or
            $settlementValue -in @('(none)', 'none') -or
            [string]::IsNullOrWhiteSpace($adoptionValue) -or
            $adoptionValue -in @('(none)', 'none') -or
            -not [string]::Equals($settlementValue, $adoptionValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    $settlementGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Settlement `
        -Names @('decision_generation', 'settlement_decision_generation')
    $adoptionGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Adoption `
        -Names @('settlement_decision_generation', 'decision_generation')
    if ([string]::IsNullOrWhiteSpace($settlementGeneration) -or
        [string]::IsNullOrWhiteSpace($adoptionGeneration) -or
        $settlementGeneration -ne $adoptionGeneration) {
        return $false
    }

    $settlementOutcome = (Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Settlement `
        -Names @('outcome', 'settlement_outcome')).ToLowerInvariant()
    $adoptionOutcome = (Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Adoption `
        -Names @('settlement_outcome', 'outcome')).ToLowerInvariant()
    return $settlementOutcome -in @('missing_dispatch', 'settled_stalled') -and
        $settlementOutcome -eq $adoptionOutcome
}

function Test-FileTransferRuntimeUnlockRetryCurrentBinding {
    param([Parameter(Mandatory = $true)]$Event)

    $proofSchema = Get-FileTransferEventField -Event $Event -Name 'closure_proof_schema' -Default ''
    $currentFormat = $proofSchema -eq '1'
    if (-not [string]::IsNullOrWhiteSpace($proofSchema) -and -not $currentFormat) {
        return $false
    }

    $generationFields = @(
        'contract_generation',
        'retired_generation',
        'offer_generation',
        'dispatch_attempt_generation',
        'missing_dispatch_successor_generation')
    foreach ($field in $generationFields) {
        $value = Get-FileTransferEventField -Event $Event -Name $field -Default ''
        $currentValue = Get-FileTransferEventField -Event $Event -Name ('current_' + $field) -Default ''
        if ($currentFormat -and
            ([string]::IsNullOrWhiteSpace($value) -or
             $value -in @('(none)', 'none') -or
             [string]::IsNullOrWhiteSpace($currentValue) -or
             $currentValue -in @('(none)', 'none'))) {
            return $false
        }
        if (-not [string]::IsNullOrWhiteSpace($value) -and
            -not [string]::IsNullOrWhiteSpace($currentValue) -and
            -not [string]::Equals($value, $currentValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    if ($currentFormat) {
        $predecessorAuthorityId = Get-FileTransferEventField `
            -Event $Event `
            -Name 'predecessor_authority_id' `
            -Default '__missing__'
        $currentPredecessorAuthorityId = Get-FileTransferEventField `
            -Event $Event `
            -Name 'current_predecessor_authority_id' `
            -Default '__missing__'
        if ($predecessorAuthorityId -eq '__missing__' -or
            $currentPredecessorAuthorityId -eq '__missing__' -or
            -not [string]::Equals(
                $predecessorAuthorityId,
                $currentPredecessorAuthorityId,
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    return $true
}

function Test-FileTransferRegularV4RecoveryClosureHoldDeadlineCurrent {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$Candidate
    )

    $deadlineText = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Receipt `
        -Names @(
            'maximum_liveness_deferral_deadline_utc_ms',
            'maximum_local_proof_liveness_deadline_utc_ms',
            'maximum_liveness_deadline_utc_ms',
            'continuation_deadline_utc_ms',
            'local_proof_liveness_deadline_utc_ms')
    $proofSchema = Get-FileTransferEventField -Event $Receipt -Name 'closure_proof_schema' -Default ''
    if ([string]::IsNullOrWhiteSpace($proofSchema)) {
        # Legacy artifacts before closure-proof schema 1 did not retain the
        # immutable deadline. They remain classifiable only through the
        # separately enforced exact, unique settlement/adoption lineage.
        return $true
    }
    if ($proofSchema -ne '1') {
        return $false
    }

    $candidateSchema = Get-FileTransferEventField -Event $Candidate -Name 'closure_proof_schema' -Default ''
    if ($candidateSchema -ne '1') {
        return $false
    }

    [int64]$deadlineUtcMs = 0
    if ([string]::IsNullOrWhiteSpace($deadlineText) -or
        -not [int64]::TryParse($deadlineText, [ref]$deadlineUtcMs) -or
        $deadlineUtcMs -le 0 -or
        $null -eq $Candidate.TimestampUtc) {
        return $false
    }

    $candidateDeadlineText = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Candidate `
        -Names @(
            'maximum_liveness_deferral_deadline_utc_ms',
            'maximum_local_proof_liveness_deadline_utc_ms',
            'maximum_liveness_deadline_utc_ms',
            'continuation_deadline_utc_ms',
            'local_proof_liveness_deadline_utc_ms')
    [int64]$candidateDeadlineUtcMs = 0
    if ([string]::IsNullOrWhiteSpace($candidateDeadlineText) -or
        -not [int64]::TryParse($candidateDeadlineText, [ref]$candidateDeadlineUtcMs) -or
        $candidateDeadlineUtcMs -ne $deadlineUtcMs) {
        return $false
    }

    $candidateUtcMs = [DateTimeOffset]$Candidate.TimestampUtc
    return $candidateUtcMs.ToUnixTimeMilliseconds() -le $deadlineUtcMs
}

function Test-FileTransferRecoveryAuthorityEvidenceCompatible {
    param([AllowEmptyCollection()][object[]]$Values = @())

    $concrete = New-Object 'System.Collections.Generic.HashSet[string]' `
        ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($valueObject in @($Values)) {
        $value = [string]$valueObject
        if ([string]::IsNullOrWhiteSpace($value) -or
            $value -in @('(none)', 'none', '(missing)', '__missing__')) {
            return $false
        }
        if ($value -notin @('[redacted]', 'redacted', '(redacted)')) {
            $concrete.Add($value) | Out-Null
        }
    }

    # Redacted copied identities are absent evidence, not mismatches.  The
    # caller must corroborate an all-redacted boundary through its unique
    # complete recovery tuple and one concrete authority-bearing Phase-2 chain.
    return $concrete.Count -le 1
}

function Test-FileTransferRegularV4RecoveryClosureGrantMatch {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$Grant
    )

    foreach ($field in @(
            'session_id', 'transfer_id', 'direction', 'route', 'protocol_version',
            'live_route_epoch', 'runtime_generation', 'terminal_generation',
            'leg_generation', 'transport_epoch', 'bridge_recovery_generation')) {
        $receiptValue = Get-FileTransferEventField -Event $Receipt -Name $field -Default ''
        $grantValue = Get-FileTransferEventField -Event $Grant -Name $field -Default ''
        if ([string]::IsNullOrWhiteSpace($receiptValue) -or
            [string]::IsNullOrWhiteSpace($grantValue) -or
            -not [string]::Equals($receiptValue, $grantValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    if ((Get-FileTransferEventField -Event $Grant -Name 'release_kind' -Default '') -ne 'ReceiveRecoveryLeaseClosure') {
        return $false
    }

    $receiptLivenessGeneration = Get-FileTransferEventField `
        -Event $Receipt `
        -Name 'regular_v4_liveness_generation' `
        -Default ''
    $grantLivenessGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Grant `
        -Names @('request_regular_v4_liveness_generation', 'regular_v4_liveness_generation')
    $receiptBridgeGeneration = Get-FileTransferEventField `
        -Event $Receipt `
        -Name 'bridge_decision_generation' `
        -Default ''
    $grantBridgeGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Grant `
        -Names @('request_bridge_decision_generation', 'bridge_decision_generation')
    if ($receiptLivenessGeneration -ne $grantLivenessGeneration -or
        $receiptBridgeGeneration -ne $grantBridgeGeneration) {
        return $false
    }

    $receiptAuthorityId = Get-FileTransferEventField -Event $Receipt -Name 'lease_authority_id' -Default ''
    $grantAuthorityId = Get-FileTransferEventField -Event $Grant -Name 'release_authority_id' -Default ''
    $receiptLeaseGeneration = Get-FileTransferEventField -Event $Receipt -Name 'lease_generation' -Default ''
    $grantReleaseGeneration = Get-FileTransferEventField -Event $Grant -Name 'release_generation' -Default ''
    return (Test-FileTransferRecoveryAuthorityEvidenceCompatible -Values @(
            $receiptAuthorityId,
            $grantAuthorityId)) -and
        -not [string]::IsNullOrWhiteSpace($receiptLeaseGeneration) -and
        $receiptLeaseGeneration -eq $grantReleaseGeneration
}

function Test-FileTransferRegularV4RecoveryTerminalMatch {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$Terminal
    )

    if (-not (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch -Left $Receipt -Right $Terminal)) {
        return $false
    }

    $receiptDirection = Get-FileTransferEventField -Event $Receipt -Name 'direction' -Default ''
    $terminalDirection = Get-FileTransferEventField -Event $Terminal -Name 'direction' -Default ''
    if ([string]::IsNullOrWhiteSpace($terminalDirection)) {
        if ($Terminal.EventName -eq 'file_transfer_inbound_terminal') {
            $terminalDirection = 'inbound'
        }
        elseif ($Terminal.EventName -eq 'file_transfer_outbound_terminal') {
            $terminalDirection = 'outbound'
        }
    }

    return [string]::IsNullOrWhiteSpace($terminalDirection) -or
        [string]::Equals($receiptDirection, $terminalDirection, [System.StringComparison]::OrdinalIgnoreCase)
}

function Test-FileTransferRegularV4RecoveryLeaseClosureRejectionMatch {
    param(
        [Parameter(Mandatory = $true)]$LifecycleDecision,
        [Parameter(Mandatory = $true)]$ClosureRejection
    )

    if (-not (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
            -Left $LifecycleDecision `
            -Right $ClosureRejection)) {
        return $false
    }

    $lifecycleGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $LifecycleDecision `
        -Names @('regular_v4_liveness_generation', 'recovery_liveness_lease_generation', 'lease_generation')
    $rejectionGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $ClosureRejection `
        -Names @('regular_v4_liveness_generation', 'recovery_liveness_lease_generation', 'lease_generation')
    if (-not [string]::IsNullOrWhiteSpace($lifecycleGeneration) -and
        -not [string]::IsNullOrWhiteSpace($rejectionGeneration) -and
        $lifecycleGeneration -ne $rejectionGeneration) {
        return $false
    }

    $rejectionDirection = Get-FileTransferEventField -Event $ClosureRejection -Name 'direction' -Default ''
    if (-not [string]::IsNullOrWhiteSpace($rejectionDirection) -and
        $rejectionDirection -notin @('(none)', 'none') -and
        -not (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
            -Left $LifecycleDecision `
            -Right $ClosureRejection `
            -IncludeDirection)) {
        return $false
    }

    $mismatchKind = Get-FileTransferEventField -Event $ClosureRejection -Name 'mismatch_kind' -Default ''
    $decisionReason = Get-FileTransferEventField -Event $ClosureRejection -Name 'decision_reason' -Default ''
    if ($mismatchKind -in @(
            'coordinator_recovery_liveness_lease_mismatch',
            'coordinator_recovery_liveness_lease_stale') -or
        $decisionReason -in @(
            'coordinator_recovery_liveness_lease_mismatch',
            'coordinator_recovery_liveness_lease_stale')) {
        return $false
    }

    return $true
}

function Test-FileTransferRegularV4RecoveryClosureLivenessTupleMatch {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$Candidate
    )

    if (-not (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
            -Left $Receipt `
            -Right $Candidate `
            -IncludeDirection)) {
        return $false
    }

    # Legacy recovery-authority telemetry prefixes the attempted/current tuple,
    # while the dedicated closure-window events emit the tuple directly. Match
    # every field the candidate carries and require the immutable receipt to
    # provide the corresponding value.
    $fieldAliases = [ordered]@{
        route = @('route', 'attempted_route', 'current_route')
        protocol_version = @('protocol_version', 'attempted_protocol_version', 'current_protocol_version')
        live_route_epoch = @('live_route_epoch', 'attempted_live_route_epoch', 'current_live_route_epoch')
        runtime_generation = @('runtime_generation', 'attempted_runtime_generation', 'current_runtime_generation')
        terminal_generation = @('terminal_generation', 'attempted_terminal_generation', 'current_terminal_generation')
        leg_generation = @('leg_generation', 'attempted_leg_generation')
        transport_epoch = @('transport_epoch', 'attempted_transport_epoch')
        bridge_recovery_generation = @('bridge_recovery_generation', 'attempted_bridge_recovery_generation')
        bridge_decision_generation = @('bridge_decision_generation', 'recovery_decision_generation')
    }
    foreach ($field in $fieldAliases.Keys) {
        $receiptValue = Get-FileTransferEventField -Event $Receipt -Name $field -Default ''
        $candidateValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Candidate `
            -Names $fieldAliases[$field]
        if ([string]::IsNullOrWhiteSpace($candidateValue) -or $candidateValue -in @('(none)', 'none')) {
            continue
        }

        # The legacy generic rejection loses the retired bridge/lease generations
        # and records them as zero. Preserve classification of those historical
        # artifacts, but require the complete tuple from the dedicated events.
        if ($Candidate.EventName -eq 'filetransfer_recovery_authority_rejected' -and
            $field -eq 'bridge_decision_generation' -and
            $candidateValue -eq '0') {
            continue
        }

        if ([string]::IsNullOrWhiteSpace($receiptValue) -or
            $receiptValue -in @('(none)', 'none') -or
            -not [string]::Equals($receiptValue, $candidateValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    $candidateLivenessGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Candidate `
        -Names @('regular_v4_liveness_generation', 'recovery_liveness_lease_generation', 'lease_generation')
    if (-not [string]::IsNullOrWhiteSpace($candidateLivenessGeneration) -and
        $candidateLivenessGeneration -ne '0') {
        $receiptLivenessGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Receipt `
            -Names @('regular_v4_liveness_generation', 'recovery_liveness_lease_generation', 'lease_generation')
        if ($candidateLivenessGeneration -ne $receiptLivenessGeneration) {
            return $false
        }
    }

    $exactFieldAliases = @(
        [pscustomobject]@{
            Receipt = @('lease_authority_id', 'recovery_liveness_lease_authority_id')
            Candidate = @('recovery_liveness_lease_authority_id', 'lease_authority_id')
        },
        [pscustomobject]@{
            Receipt = @('lease_state', 'recovery_liveness_lease_state')
            Candidate = @('recovery_liveness_lease_state', 'lease_state')
        },
        [pscustomobject]@{
            Receipt = @('lifecycle_outcome')
            Candidate = @('lifecycle_outcome')
        },
        [pscustomobject]@{
            Receipt = @('lifecycle_decision_status')
            Candidate = @('lifecycle_decision_status')
        },
        [pscustomobject]@{
            Receipt = @('lifecycle_decision_reason')
            Candidate = @('lifecycle_decision_reason')
        }
    )
    foreach ($aliases in $exactFieldAliases) {
        $candidateValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Candidate `
            -Names $aliases.Candidate
        if ([string]::IsNullOrWhiteSpace($candidateValue)) {
            continue
        }

        $receiptValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Receipt `
            -Names $aliases.Receipt
        if ([string]::IsNullOrWhiteSpace($receiptValue) -or
            -not [string]::Equals($receiptValue, $candidateValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    return $true
}

function Test-FileTransferRegularV4RecoveryClosureLivenessProofMatch {
    param(
        [Parameter(Mandatory = $true)]$Rejection,
        [Parameter(Mandatory = $true)]$Grant
    )

    # Historical generic rejection telemetry predates the immutable proof and
    # cannot bind its maximum deadline. Its grant is still checked against the
    # retained receipt by the caller. Dedicated telemetry must match wholesale.
    if ($Rejection.EventName -ne
        'runtime_unlock_regular_v4_recovery_lease_closure_liveness_deferral_rejected') {
        return $true
    }

    $fieldAliases = @(
        [pscustomobject]@{ Left = @('session_id'); Right = @('session_id') },
        [pscustomobject]@{ Left = @('transfer_id'); Right = @('transfer_id') },
        [pscustomobject]@{ Left = @('direction'); Right = @('direction') },
        [pscustomobject]@{ Left = @('route'); Right = @('route') },
        [pscustomobject]@{ Left = @('protocol_version'); Right = @('protocol_version') },
        [pscustomobject]@{ Left = @('live_route_epoch'); Right = @('live_route_epoch') },
        [pscustomobject]@{ Left = @('runtime_generation'); Right = @('runtime_generation') },
        [pscustomobject]@{ Left = @('terminal_generation'); Right = @('terminal_generation') },
        [pscustomobject]@{ Left = @('leg_generation'); Right = @('leg_generation') },
        [pscustomobject]@{ Left = @('transport_epoch'); Right = @('transport_epoch') },
        [pscustomobject]@{ Left = @('bridge_recovery_generation'); Right = @('bridge_recovery_generation') },
        [pscustomobject]@{ Left = @('bridge_decision_generation'); Right = @('bridge_decision_generation') },
        [pscustomobject]@{
            Left = @('recovery_liveness_lease_authority_id', 'lease_authority_id')
            Right = @('recovery_liveness_lease_authority_id', 'lease_authority_id')
        },
        [pscustomobject]@{
            Left = @('recovery_liveness_lease_generation', 'lease_generation', 'regular_v4_liveness_generation')
            Right = @('recovery_liveness_lease_generation', 'lease_generation', 'regular_v4_liveness_generation')
        },
        [pscustomobject]@{
            Left = @('recovery_liveness_lease_state', 'lease_state')
            Right = @('recovery_liveness_lease_state', 'lease_state')
        },
        [pscustomobject]@{ Left = @('lifecycle_outcome'); Right = @('lifecycle_outcome') },
        [pscustomobject]@{ Left = @('lifecycle_decision_status'); Right = @('lifecycle_decision_status') },
        [pscustomobject]@{ Left = @('lifecycle_decision_reason'); Right = @('lifecycle_decision_reason') },
        [pscustomobject]@{
            Left = @('maximum_liveness_deferral_deadline_utc_ms')
            Right = @('maximum_liveness_deferral_deadline_utc_ms')
        }
    )
    foreach ($aliases in $fieldAliases) {
        $leftValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Rejection `
            -Names $aliases.Left
        $rightValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Grant `
            -Names $aliases.Right
        if ([string]::IsNullOrWhiteSpace($leftValue) -or
            [string]::IsNullOrWhiteSpace($rightValue) -or
            -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    return $true
}

function Test-FileTransferRegularV4RecoveryAuthorityReplacesClosure {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$Authority
    )

    if (-not (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
            -Left $Receipt `
            -Right $Authority `
            -IncludeDirection)) {
        return $false
    }

    $recoveryTupleAliases = @(
        [pscustomobject]@{
            Receipt = @('lease_authority_id', 'recovery_liveness_lease_authority_id')
            Authority = @('recovery_liveness_lease_authority_id', 'lease_authority_id')
        },
        [pscustomobject]@{
            Receipt = @('regular_v4_liveness_generation', 'recovery_liveness_lease_generation', 'lease_generation')
            Authority = @('recovery_liveness_lease_generation', 'lease_generation', 'regular_v4_liveness_generation')
        },
        [pscustomobject]@{
            Receipt = @('bridge_decision_generation')
            Authority = @('bridge_decision_generation')
        },
        [pscustomobject]@{
            Receipt = @('bridge_recovery_generation')
            Authority = @('bridge_recovery_generation')
        }
    )
    foreach ($aliases in $recoveryTupleAliases) {
        $receiptValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Receipt `
            -Names $aliases.Receipt
        $authorityValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Authority `
            -Names $aliases.Authority
        if ([string]::IsNullOrWhiteSpace($receiptValue) -or
            [string]::IsNullOrWhiteSpace($authorityValue)) {
            continue
        }

        if (-not [string]::Equals($receiptValue, $authorityValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $true
        }
    }

    return $false
}

function Get-FileTransferUncoveredRuntimeUnlockRegularV4RecoverySettlementMissingEvents {
    param(
        [AllowEmptyCollection()][object[]]$SettlementMissingEvents = @(),
        [AllowEmptyCollection()][object[]]$ClosureLivenessFailureEvents = @()
    )

    $uncovered = New-Object System.Collections.Generic.List[object]
    foreach ($missingCandidate in @($SettlementMissingEvents)) {
        $coveredByClosureLivenessFailure = @(
            $ClosureLivenessFailureEvents |
                Where-Object {
                    [int64]$_.Sequence -lt [int64]$missingCandidate.Sequence -and
                    (Test-FileTransferRegularV4RecoveryTerminalMatch `
                        -Receipt $_ `
                        -Terminal $missingCandidate)
                } |
                Select-Object -First 1
        ).Count -gt 0
        if (-not $coveredByClosureLivenessFailure) {
            $uncovered.Add($missingCandidate) | Out-Null
        }
    }

    return @($uncovered.ToArray())
}

function Get-FileTransferRuntimeUnlockRegularV4RecoveryLeaseCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [AllowEmptyCollection()][object[]]$EffectiveGrantEvents = @()
    )

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$lifecycleDecisions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lifecycle_decided' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @('Accepted', 'Idempotent') -and
        (Get-FileTransferEventField -Event $_ -Name 'lifecycle_outcome' -Default '') -in @('Completed', 'ReceiveProofObserved')
    })
    [object[]]$leaseGrants = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_recovery_liveness_lease_granted' -or
        (
            $_.EventName -eq 'filetransfer_bridge_recovery_authority_granted' -and
            [int](Get-FileTransferEventField -Event $_ -Name 'recovery_liveness_lease_generation' -Default '0') -gt 0 -and
            (Get-FileTransferEventField -Event $_ -Name 'recovery_liveness_lease_state' -Default '') -eq 'Active'
        )
    })
    [object[]]$bridgeRecoveryAuthorities = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_bridge_recovery_authority_granted' -and
        (Get-FileTransferEventField -Event $_ -Name 'bridge_recovery_kind' -Default 'BridgeReceiveStallRecovery') -eq
            'BridgeReceiveStallRecovery'
    })
    [object[]]$closureRejections = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_rejected'
    })
    [object[]]$closureRetainedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_retained'
    })
    [object[]]$closureAdoptedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_adopted'
    })
    [object[]]$closureConsumedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_consumed'
    })
    [object[]]$retryHeldEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'runtime_unlock_retry_blocked_by_regular_v4_receive_recovery',
            'runtime_unlock_retry_dispatch_held_by_regular_v4_receive_recovery')
    })
    [object[]]$retryAuthorityGrantedEvents = @($EffectiveGrantEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_authority_granted'
    })
    [object[]]$terminalEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'transfer_terminal',
            'file_transfer_inbound_terminal',
            'file_transfer_outbound_terminal')
    })
    [object[]]$closureLivenessDeferralRejectedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_liveness_deferral_rejected'
    })
    [object[]]$closureLivenessRejectedEvents = @($orderedEvents | Where-Object {
        if ($_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_liveness_deferral_rejected') {
            return (Get-FileTransferRegularV4RecoveryLeaseField `
                -Event $_ `
                -Names @('rejection_reason', 'decision_reason', 'reason')) -eq
                    'recovery_liveness_lease_missing'
        }

        return $_.EventName -eq 'filetransfer_recovery_authority_rejected' -and
            (Get-FileTransferEventField -Event $_ -Name 'action_kind' -Default '') -eq 'LivenessDeferral' -and
             (Get-FileTransferRegularV4RecoveryLeaseField `
                 -Event $_ `
                 -Names @('rejection_reason', 'decision_reason', 'reason')) -eq 'recovery_liveness_lease_missing'
    })
    [object[]]$closureLivenessDeferralGrantedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_liveness_deferral_granted'
    })
    [object[]]$closureLivenessGrantedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_liveness_deferral_granted' -or
        ($_.EventName -eq 'filetransfer_recovery_liveness_lease_granted' -and
            (Get-FileTransferEventField -Event $_ -Name 'action_kind' -Default '') -eq
                'RecoveryLeaseClosureLivenessDeferral')
    })
    [object[]]$frontierRepairSettlementAcceptedEvents = @($orderedEvents | Where-Object {
        if ($_.EventName -ne 'filetransfer_regular_v4_frontier_repair_settlement_accepted') {
            return $false
        }

        $outcome = (Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $_ `
            -Names @('outcome', 'settlement_outcome')).ToLowerInvariant()
        return $outcome -in @('missing_dispatch', 'settled_stalled')
    })
    [object[]]$frontierRepairSettlementAdoptedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_frontier_repair_settlement_handoff_adopted' -and
        (Get-FileTransferEventField -Event $_ -Name 'handoff_disposition' -Default 'Adopted') -eq 'Adopted'
    })
    [object[]]$closureHoldPreservedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_regular_v4_recovery_lease_closure_hold_preserved'
    })
    [object[]]$closureHoldRejectedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_rejected_after_regular_v4_receive_recovery' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'v4_recovery_terminal_no_proof'
    })

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $seenLifecycleTuples = @{}

    for ($index = 0; $index -lt $lifecycleDecisions.Count; $index++) {
        $lifecycle = $lifecycleDecisions[$index]
        $lifecycleSequence = [int64]$lifecycle.Sequence

        $nextLifecycleSequence = [int64]::MaxValue
        for ($nextIndex = $index + 1; $nextIndex -lt $lifecycleDecisions.Count; $nextIndex++) {
            $nextLifecycle = $lifecycleDecisions[$nextIndex]
            if (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
                    -Left $lifecycle `
                    -Right $nextLifecycle `
                    -IncludeDirection) {
                $nextLifecycleSequence = [int64]$nextLifecycle.Sequence
                break
            }
        }

        $matchingAuthority = @($bridgeRecoveryAuthorities | Where-Object {
            [int64]$_.Sequence -lt $lifecycleSequence -and
            (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
                -Left $_ `
                -Right $lifecycle `
                -IncludeDirection)
        } | Select-Object -Last 1)
        $recoveryWindowStart = if ($matchingAuthority.Count -gt 0) {
            [int64]$matchingAuthority[0].Sequence
        }
        else {
            $previousLifecycle = @($lifecycleDecisions | Where-Object {
                [int64]$_.Sequence -lt $lifecycleSequence -and
                (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
                    -Left $_ `
                    -Right $lifecycle `
                    -IncludeDirection)
            } | Select-Object -Last 1)
            if ($previousLifecycle.Count -gt 0) { [int64]$previousLifecycle[0].Sequence } else { -1L }
        }

        # Any lease grant in the exact recovery window means the defect is a
        # stale/mismatched lease, not a lease that was never issued. Keep those
        # domains disjoint even when the old telemetry lacks mismatch_kind.
        $windowLeaseGrants = @($leaseGrants | Where-Object {
            [int64]$_.Sequence -ge $recoveryWindowStart -and
            [int64]$_.Sequence -lt $lifecycleSequence -and
            (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
                -Left $_ `
                -Right $lifecycle `
                -IncludeDirection)
        })
        $matchingLeaseGrant = @($windowLeaseGrants | Where-Object {
            Test-FileTransferRegularV4RecoveryLeaseGrantMatch `
                -LeaseGrant $_ `
                -LifecycleDecision $lifecycle
        } | Select-Object -Last 1)
        if ($matchingLeaseGrant.Count -gt 0 -or $windowLeaseGrants.Count -gt 0) {
            continue
        }

        $matchingRejection = @($closureRejections | Where-Object {
            [int64]$_.Sequence -gt $lifecycleSequence -and
            [int64]$_.Sequence -lt $nextLifecycleSequence -and
            (Test-FileTransferRegularV4RecoveryLeaseClosureRejectionMatch `
                -LifecycleDecision $lifecycle `
                -ClosureRejection $_)
        } | Select-Object -First 1)
        if ($matchingRejection.Count -eq 0) {
            continue
        }

        $candidate = $matchingRejection[0]
        $rawCandidates.Add($candidate) | Out-Null
        $tupleKey = Get-FileTransferRegularV4RecoveryLeaseTupleKey -Event $lifecycle
        if ($seenLifecycleTuples.ContainsKey($tupleKey)) {
            continue
        }

        $seenLifecycleTuples[$tupleKey] = $true
        $distinctCandidates.Add($candidate) | Out-Null
        $unresolvedCandidates.Add($candidate) | Out-Null
    }

    $issuanceVerdict = if ($unresolvedCandidates.Count -gt 0) {
        'fail'
    }
    elseif ($distinctCandidates.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    # A completed bridge lifecycle retires the coordinator lease, but the exact
    # retained closure keeps the existing retry Held until local receive proof.
    # An accepted/adopted repair settlement transfers ownership into this
    # closure window; a terminal-no-proof disposition before that window closes
    # is therefore the conclusive failure, not the earlier repair deferral.
    $closureHoldRawCandidates = New-Object System.Collections.Generic.List[object]
    $closureHoldDistinctCandidates = New-Object System.Collections.Generic.List[object]
    $closureHoldRecoveredCandidates = New-Object System.Collections.Generic.List[object]
    $closureHoldUnresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $closureWindowOwnedReceiptKeys = @{}
    $seenClosureHoldTuples = @{}
    foreach ($receipt in @($closureRetainedEvents | Sort-Object Sequence, LineNumber)) {
        $receiptSequence = [int64]$receipt.Sequence
        $receiptTupleKey = Get-FileTransferRegularV4RecoveryLeaseTupleKey -Event $receipt
        $lifecycle = @($lifecycleDecisions | Where-Object {
            [int64]$_.Sequence -le $receiptSequence -and
            (Get-FileTransferEventField -Event $_ -Name 'lifecycle_outcome' -Default '') -eq 'Completed' -and
            (Test-FileTransferRegularV4RecoveryClosureHoldTupleMatch -Receipt $receipt -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        if ($lifecycle.Count -eq 0) {
            continue
        }

        $nextReceipt = @($closureRetainedEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
                -Left $receipt `
                -Right $_ `
                -IncludeDirection)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $nextRecoveryAuthority = @($bridgeRecoveryAuthorities | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryAuthorityReplacesClosure `
                -Receipt $receipt `
                -Authority $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $terminal = @($terminalEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryTerminalMatch -Receipt $receipt -Terminal $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $adoptionOrConsumption = @(@($closureAdoptedEvents + $closureConsumedEvents) | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryBoundaryTupleMatch -Receipt $receipt -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $boundarySequence = [int64]::MaxValue
        foreach ($boundary in @($nextReceipt + $nextRecoveryAuthority + $terminal + $adoptionOrConsumption)) {
            if ($null -ne $boundary -and [int64]$boundary.Sequence -lt $boundarySequence) {
                $boundarySequence = [int64]$boundary.Sequence
            }
        }

        $matchingAdoptions = @($frontierRepairSettlementAdoptedEvents | Where-Object {
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferRegularV4RecoveryClosureHoldTupleMatch -Receipt $receipt -Candidate $_)
        } | Sort-Object Sequence, LineNumber)
        $matchingAdoption = @()
        $matchingSettlement = @()
        foreach ($adoption in $matchingAdoptions) {
            $settlement = @($frontierRepairSettlementAcceptedEvents | Where-Object {
                [int64]$_.Sequence -lt [int64]$adoption.Sequence -and
                (Test-FileTransferRegularV4RepairSettlementAdoptionMatch `
                    -Settlement $_ `
                    -Adoption $adoption)
            } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
            if ($settlement.Count -gt 0) {
                $matchingAdoption = @($adoption)
                $matchingSettlement = $settlement
                break
            }
        }
        $hasAcceptedAdoptedRepairSettlement =
            $matchingAdoption.Count -gt 0 -and $matchingSettlement.Count -gt 0
        if (-not $hasAcceptedAdoptedRepairSettlement) {
            continue
        }
        $adoptionSequence = [int64]$matchingAdoption[0].Sequence
        $rejections = @($closureHoldRejectedEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            [int64]$_.Sequence -ge $adoptionSequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferRegularV4RecoveryClosureHoldTupleMatch -Receipt $receipt -Candidate $_) -and
            (Test-FileTransferRegularV4RecoveryClosureHoldLegacyBindingUnique `
                -Receipt $receipt `
                -Candidate $_ `
                -Receipts $closureRetainedEvents) -and
            (Test-FileTransferRegularV4RecoveryClosureHoldDeadlineCurrent -Receipt $receipt -Candidate $_) -and
            (Test-FileTransferRuntimeUnlockRetryCurrentBinding -Event $_)
        } | Sort-Object Sequence, LineNumber)
        $matchingPreservedHold = @($closureHoldPreservedEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferRegularV4RecoveryClosureHoldTupleMatch -Receipt $receipt -Candidate $_) -and
            (Test-FileTransferRegularV4RecoveryClosureHoldLegacyBindingUnique `
                -Receipt $receipt `
                -Candidate $_ `
                -Receipts $closureRetainedEvents) -and
            (Test-FileTransferRegularV4RecoveryClosureHoldDeadlineCurrent -Receipt $receipt -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($rejections.Count -gt 0 -or $matchingPreservedHold.Count -gt 0) {
            $closureWindowOwnedReceiptKeys[$receiptTupleKey] = $true
        }

        foreach ($rejection in $rejections) {
            $closureHoldRawCandidates.Add($rejection) | Out-Null
            $repairRequestKey = Get-FileTransferEventField `
                -Event $matchingSettlement[0] `
                -Name 'repair_request_key' `
                -Default '(missing)'
            $settlementGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
                -Event $matchingSettlement[0] `
                -Names @('decision_generation', 'settlement_decision_generation') `
                -Default '(missing)'
            $retryTuple = (@('contract_generation', 'retired_generation', 'offer_generation') |
                    ForEach-Object { Get-FileTransferEventField -Event $rejection -Name $_ -Default '(missing)' }) -join '|'
            $candidateKey = $receiptTupleKey + '|' + $repairRequestKey + '|' + $settlementGeneration + '|' + $retryTuple
            if ($seenClosureHoldTuples.ContainsKey($candidateKey)) {
                continue
            }

            $seenClosureHoldTuples[$candidateKey] = $true
            $closureHoldDistinctCandidates.Add($rejection) | Out-Null
            $closureHoldUnresolvedCandidates.Add($rejection) | Out-Null
        }
    }

    $closureHoldVerdict = if ($closureHoldUnresolvedCandidates.Count -gt 0) {
        'fail'
    }
    elseif ($closureHoldDistinctCandidates.Count -gt 0 -or $closureHoldPreservedEvents.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    # Closure adoption is a separate proof boundary. It starts only when Infra
    # retained the coordinator-issued receipt, then becomes conclusive at the
    # first exact same-tuple retry hold. Lifecycle completion by itself is not a
    # non-adoption failure.
    $closureNotAdoptedRawCandidates = New-Object System.Collections.Generic.List[object]
    $closureNotAdoptedDistinctCandidates = New-Object System.Collections.Generic.List[object]
    $closureNotAdoptedRecoveredCandidates = New-Object System.Collections.Generic.List[object]
    $closureNotAdoptedUnresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $seenClosureReceiptTuples = @{}
    foreach ($receipt in @($closureRetainedEvents | Sort-Object Sequence, LineNumber)) {
        $receiptSequence = [int64]$receipt.Sequence
        $receiptTupleKey = Get-FileTransferRegularV4RecoveryLeaseTupleKey -Event $receipt
        if ($closureWindowOwnedReceiptKeys.ContainsKey($receiptTupleKey)) {
            continue
        }

        $terminal = @($terminalEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryTerminalMatch -Receipt $receipt -Terminal $_)
        } | Select-Object -First 1)
        $terminalSequence = if ($terminal.Count -gt 0) {
            [int64]$terminal[0].Sequence
        }
        else {
            [int64]::MaxValue
        }
        $hold = @($retryHeldEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            [int64]$_.Sequence -lt $terminalSequence -and
            (Test-FileTransferRegularV4RecoveryBoundaryTupleMatch `
                -Receipt $receipt `
                -Candidate $_)
        } | Select-Object -First 1)
        if ($hold.Count -eq 0) {
            continue
        }

        $holdEvent = $hold[0]
        $closureNotAdoptedRawCandidates.Add($holdEvent) | Out-Null
        $tupleKey = Get-FileTransferRegularV4RecoveryBoundaryTupleKey -Event $receipt
        if ($seenClosureReceiptTuples.ContainsKey($tupleKey)) {
            continue
        }

        $seenClosureReceiptTuples[$tupleKey] = $true
        $closureNotAdoptedDistinctCandidates.Add($holdEvent) | Out-Null
        $holdSequence = [int64]$holdEvent.Sequence
        $adoption = @($closureAdoptedEvents | Where-Object {
            [int64]$_.Sequence -gt $holdSequence -and
            [int64]$_.Sequence -lt $terminalSequence -and
            (Test-FileTransferRegularV4RecoveryBoundaryTupleMatch `
                -Receipt $receipt `
                -Candidate $_)
        } | Select-Object -First 1)
        $consumption = @($closureConsumedEvents | Where-Object {
            [int64]$_.Sequence -gt $holdSequence -and
            [int64]$_.Sequence -lt $terminalSequence -and
            (Test-FileTransferRegularV4RecoveryBoundaryTupleMatch `
                -Receipt $receipt `
                -Candidate $_)
        } | Select-Object -First 1)
        $grant = @($retryAuthorityGrantedEvents | Where-Object {
            [int64]$_.Sequence -gt $holdSequence -and
            [int64]$_.Sequence -lt $terminalSequence -and
            (Test-FileTransferRegularV4RecoveryClosureGrantMatch `
                -Receipt $receipt `
                -Grant $_)
        } | Select-Object -First 1)
        if ($adoption.Count -gt 0 -and
            $consumption.Count -gt 0 -and
            $grant.Count -gt 0 -and
            [int64]$adoption[0].Sequence -lt [int64]$consumption[0].Sequence -and
            [int64]$consumption[0].Sequence -le [int64]$grant[0].Sequence) {
            $closureNotAdoptedRecoveredCandidates.Add($holdEvent) | Out-Null
        }
        else {
            $closureNotAdoptedUnresolvedCandidates.Add($holdEvent) | Out-Null
        }
    }

    $closureAdoptionVerdict = if ($closureNotAdoptedUnresolvedCandidates.Count -gt 0) {
        'fail'
    }
    elseif ($closureNotAdoptedDistinctCandidates.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    # Lifecycle completion legitimately retires the active recovery lease while
    # Infra keeps waiting for local receive proof. A same-tuple LivenessDeferral
    # rejection in that interval is the first conclusive proof that the bounded
    # closure window lost its coordinator authority.
    $closureLivenessRawCandidates = New-Object System.Collections.Generic.List[object]
    $closureLivenessDistinctCandidates = New-Object System.Collections.Generic.List[object]
    $closureLivenessRecoveredCandidates = New-Object System.Collections.Generic.List[object]
    $closureLivenessUnresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $seenClosureLivenessTuples = @{}
    foreach ($receipt in @($closureRetainedEvents | Sort-Object Sequence, LineNumber)) {
        $receiptSequence = [int64]$receipt.Sequence
        $nextReceipt = @($closureRetainedEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
                -Left $receipt `
                -Right $_ `
                -IncludeDirection)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $nextRecoveryAuthority = @($bridgeRecoveryAuthorities | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryAuthorityReplacesClosure `
                -Receipt $receipt `
                -Authority $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $terminal = @($terminalEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryTerminalMatch -Receipt $receipt -Terminal $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $boundarySequence = [int64]::MaxValue
        if ($nextReceipt.Count -gt 0) {
            $boundarySequence = [int64]$nextReceipt[0].Sequence
        }
        if ($nextRecoveryAuthority.Count -gt 0 -and
            [int64]$nextRecoveryAuthority[0].Sequence -lt $boundarySequence) {
            $boundarySequence = [int64]$nextRecoveryAuthority[0].Sequence
        }
        if ($terminal.Count -gt 0 -and [int64]$terminal[0].Sequence -lt $boundarySequence) {
            $boundarySequence = [int64]$terminal[0].Sequence
        }

        $adoptionOrConsumption = @(@($closureAdoptedEvents + $closureConsumedEvents) | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferRegularV4RecoveryBoundaryTupleMatch -Receipt $receipt -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $proofBoundarySequence = if ($adoptionOrConsumption.Count -gt 0) {
            [int64]$adoptionOrConsumption[0].Sequence
        }
        else {
            $boundarySequence
        }
        $rejections = @($closureLivenessRejectedEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            [int64]$_.Sequence -lt $proofBoundarySequence -and
            (Test-FileTransferRegularV4RecoveryClosureLivenessTupleMatch `
                -Receipt $receipt `
                -Candidate $_)
        } | Sort-Object Sequence, LineNumber)
        foreach ($rejection in $rejections) {
            $closureLivenessRawCandidates.Add($rejection) | Out-Null
        }
        if ($rejections.Count -eq 0) {
            continue
        }

        $tupleKey = Get-FileTransferRegularV4RecoveryLeaseTupleKey -Event $receipt
        if ($seenClosureLivenessTuples.ContainsKey($tupleKey)) {
            continue
        }

        $seenClosureLivenessTuples[$tupleKey] = $true
        $candidate = $rejections[0]
        $closureLivenessDistinctCandidates.Add($candidate) | Out-Null
        $matchingGrant = @($closureLivenessGrantedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$candidate.Sequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferRegularV4RecoveryClosureLivenessTupleMatch `
                -Receipt $receipt `
                -Candidate $_) -and
            (Test-FileTransferRegularV4RecoveryClosureLivenessProofMatch `
                -Rejection $candidate `
                -Grant $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($matchingGrant.Count -gt 0) {
            $closureLivenessRecoveredCandidates.Add($candidate) | Out-Null
        }
        else {
            $closureLivenessUnresolvedCandidates.Add($candidate) | Out-Null
        }
    }

    $closureLivenessVerdict = if ($closureLivenessUnresolvedCandidates.Count -gt 0) {
        'fail'
    }
    elseif ($closureLivenessDistinctCandidates.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    return [pscustomobject]@{
        ClosureRejectedCount = $closureRejections.Count
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = 0
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = $issuanceVerdict
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
        ClosureNotAdoptedRawCount = $closureNotAdoptedRawCandidates.Count
        ClosureNotAdoptedDistinctCount = $closureNotAdoptedDistinctCandidates.Count
        ClosureNotAdoptedRecoveredCount = $closureNotAdoptedRecoveredCandidates.Count
        ClosureNotAdoptedUnresolvedCount = $closureNotAdoptedUnresolvedCandidates.Count
        ClosureAdoptionVerdict = $closureAdoptionVerdict
        ClosureNotAdoptedRawCandidateEvents = @($closureNotAdoptedRawCandidates.ToArray())
        ClosureNotAdoptedDistinctCandidateEvents = @($closureNotAdoptedDistinctCandidates.ToArray())
        ClosureNotAdoptedRecoveredCandidateEvents = @($closureNotAdoptedRecoveredCandidates.ToArray())
        ClosureNotAdoptedUnresolvedCandidateEvents = @($closureNotAdoptedUnresolvedCandidates.ToArray())
        ClosureLivenessRejectedCount = $closureLivenessDeferralRejectedEvents.Count
        ClosureLivenessGrantedCount = $closureLivenessDeferralGrantedEvents.Count
        ClosureLivenessRawCount = $closureLivenessRawCandidates.Count
        ClosureLivenessDistinctCount = $closureLivenessDistinctCandidates.Count
        ClosureLivenessRecoveredCount = $closureLivenessRecoveredCandidates.Count
        ClosureLivenessUnresolvedCount = $closureLivenessUnresolvedCandidates.Count
        ClosureLivenessVerdict = $closureLivenessVerdict
        ClosureLivenessRawCandidateEvents = @($closureLivenessRawCandidates.ToArray())
        ClosureLivenessDistinctCandidateEvents = @($closureLivenessDistinctCandidates.ToArray())
        ClosureLivenessRecoveredCandidateEvents = @($closureLivenessRecoveredCandidates.ToArray())
        ClosureLivenessUnresolvedCandidateEvents = @($closureLivenessUnresolvedCandidates.ToArray())
        ClosureHoldNotPreservedRawCount = $closureHoldRawCandidates.Count
        ClosureHoldNotPreservedDistinctCount = $closureHoldDistinctCandidates.Count
        ClosureHoldNotPreservedRecoveredCount = $closureHoldRecoveredCandidates.Count
        ClosureHoldNotPreservedUnresolvedCount = $closureHoldUnresolvedCandidates.Count
        ClosureHoldPreservationVerdict = $closureHoldVerdict
        ClosureHoldNotPreservedRawCandidateEvents = @($closureHoldRawCandidates.ToArray())
        ClosureHoldNotPreservedDistinctCandidateEvents = @($closureHoldDistinctCandidates.ToArray())
        ClosureHoldNotPreservedRecoveredCandidateEvents = @($closureHoldRecoveredCandidates.ToArray())
        ClosureHoldNotPreservedUnresolvedCandidateEvents = @($closureHoldUnresolvedCandidates.ToArray())
    }
}

function Test-FileTransferRegularV4RecoveryClosureOfferTimeoutTupleMatch {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$Candidate,
        [switch]$RequireCompleteRecoveryTuple
    )

    $receiptSession = Get-FileTransferEventField -Event $Receipt -Name 'session_id' -Default ''
    $candidateSession = Get-FileTransferEventField -Event $Candidate -Name 'session_id' -Default ''
    if ([string]::IsNullOrWhiteSpace($receiptSession) -or
        [string]::IsNullOrWhiteSpace($candidateSession) -or
        -not [string]::Equals($receiptSession, $candidateSession, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }

    $candidateTransfer = Get-FileTransferEventField -Event $Candidate -Name 'transfer_id' -Default ''
    if (-not [string]::IsNullOrWhiteSpace($candidateTransfer) -and
        $candidateTransfer -notin @('(none)', 'none', 'runtime_unlock')) {
        $receiptTransfer = Get-FileTransferEventField -Event $Receipt -Name 'transfer_id' -Default ''
        if ([string]::IsNullOrWhiteSpace($receiptTransfer) -or
            -not [string]::Equals($receiptTransfer, $candidateTransfer, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    $candidateDirection = Get-FileTransferEventField -Event $Candidate -Name 'direction' -Default ''
    if (-not [string]::IsNullOrWhiteSpace($candidateDirection) -and
        $candidateDirection -notin @('(none)', 'none')) {
        $receiptDirection = Get-FileTransferEventField -Event $Receipt -Name 'direction' -Default ''
        if (-not [string]::Equals($receiptDirection, $candidateDirection, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    $fieldAliases = [ordered]@{
        route = @('route')
        protocol_version = @('protocol_version')
        live_route_epoch = @('live_route_epoch')
        runtime_generation = @('runtime_generation')
        terminal_generation = @('terminal_generation')
        leg_generation = @('leg_generation')
        transport_epoch = @('transport_epoch')
        bridge_recovery_generation = @('bridge_recovery_generation')
        bridge_decision_generation = @('bridge_decision_generation')
        regular_v4_liveness_generation = @(
            'regular_v4_liveness_generation',
            'recovery_liveness_lease_generation',
            'lease_generation')
        lease_authority_id = @(
            'lease_authority_id',
            'recovery_liveness_lease_authority_id')
    }
    foreach ($receiptField in $fieldAliases.Keys) {
        $receiptValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Receipt `
            -Names @($receiptField)
        $candidateValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Candidate `
            -Names $fieldAliases[$receiptField]
        if ([string]::IsNullOrWhiteSpace($candidateValue)) {
            if ($RequireCompleteRecoveryTuple) {
                return $false
            }

            continue
        }

        $valuesMatch = if ($receiptField -eq 'lease_authority_id') {
            Test-FileTransferRecoveryAuthorityEvidenceCompatible -Values @(
                $receiptValue,
                $candidateValue)
        }
        else {
            -not [string]::IsNullOrWhiteSpace($receiptValue) -and
                [string]::Equals(
                    $receiptValue,
                    $candidateValue,
                    [System.StringComparison]::OrdinalIgnoreCase)
        }
        if (-not $valuesMatch) {
            return $false
        }
    }

    if ($RequireCompleteRecoveryTuple) {
        $publicationFieldAliases = [ordered]@{
            session_id = 'source_publication_session_id'
            transfer_id = 'source_publication_transfer_id'
            direction = 'source_publication_direction'
            route = 'source_publication_route'
            protocol_version = 'source_publication_protocol_version'
            live_route_epoch = 'source_publication_live_route_epoch'
            runtime_generation = 'source_publication_runtime_generation'
            terminal_generation = 'source_publication_terminal_generation'
            leg_generation = 'source_publication_leg_generation'
        }
        foreach ($receiptField in $publicationFieldAliases.Keys) {
            $receiptValue = Get-FileTransferEventField -Event $Receipt -Name $receiptField -Default ''
            $publicationValue = Get-FileTransferEventField `
                -Event $Candidate `
                -Name $publicationFieldAliases[$receiptField] `
                -Default ''
            if ([string]::IsNullOrWhiteSpace($receiptValue) -or
                [string]::IsNullOrWhiteSpace($publicationValue) -or
                -not [string]::Equals($receiptValue, $publicationValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        if ([int64](Get-FileTransferEventField `
                -Event $Candidate `
                -Name 'source_publication_route_publication_generation' `
                -Default '0') -le 0) {
            return $false
        }
    }

    return $true
}

function Test-FileTransferRegularV4RecoveryClosureOfferTimeoutStalePredecessorMatch {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$RejectedAuthority
    )

    if (-not (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
            -Left $Receipt `
            -Right $RejectedAuthority `
            -IncludeDirection)) {
        return $false
    }

    if ((Get-FileTransferEventField -Event $RejectedAuthority -Name 'mismatch_field' -Default '') -ne
            'infra_current_binding' -or
        (Get-FileTransferEventField -Event $RejectedAuthority -Name 'decision_reason' -Default '') -ne
            'runtime_unlock_retry_dispatch_authority_tuple_mismatch') {
        return $false
    }

    foreach ($field in @(
            'route',
            'protocol_version',
            'live_route_epoch',
            'runtime_generation',
            'terminal_generation',
            'leg_generation',
            'transport_epoch',
            'bridge_recovery_generation')) {
        $receiptValue = Get-FileTransferEventField -Event $Receipt -Name $field -Default ''
        $authorityValue = Get-FileTransferEventField -Event $RejectedAuthority -Name $field -Default ''
        if ([string]::IsNullOrWhiteSpace($receiptValue) -or
            [string]::IsNullOrWhiteSpace($authorityValue) -or
            -not [string]::Equals($receiptValue, $authorityValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    $receiptBridgeDecisionGeneration = [int64](Get-FileTransferEventField `
        -Event $Receipt `
        -Name 'bridge_decision_generation' `
        -Default '0')
    $authorityBridgeDecisionGeneration = [int64](Get-FileTransferEventField `
        -Event $RejectedAuthority `
        -Name 'bridge_decision_generation' `
        -Default '0')
    $receiptLeaseGeneration = [int64](Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Receipt `
        -Names @('lease_generation', 'regular_v4_liveness_generation') `
        -Default '0')
    $authorityReleaseGeneration = [int64](Get-FileTransferEventField `
        -Event $RejectedAuthority `
        -Name 'release_generation' `
        -Default '0')
    if ($receiptBridgeDecisionGeneration -le 0 -or
        $receiptLeaseGeneration -le 0 -or
        $authorityBridgeDecisionGeneration -le 0 -or
        $authorityReleaseGeneration -le 0 -or
        $authorityBridgeDecisionGeneration -ge $receiptBridgeDecisionGeneration -or
        $authorityReleaseGeneration -ge $receiptLeaseGeneration) {
        return $false
    }

    return (Get-FileTransferEventField -Event $RejectedAuthority -Name 'release_kind' -Default '') -eq
            'ReceiveRecoveryLeaseClosure' -and
        (Get-FileTransferEventField -Event $RejectedAuthority -Name 'release_outcome' -Default '') -eq 'Retired'
}

function Test-FileTransferRegularV4RecoveryClosureOfferTimeoutOfferIdentityMatch {
    param(
        [Parameter(Mandatory = $true)]$Timeout,
        [Parameter(Mandatory = $true)]$Candidate,
        $Join = $null
    )

    $timeoutSession = Get-FileTransferEventField -Event $Timeout -Name 'session_id' -Default ''
    $candidateSession = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Candidate `
        -Names @('offer_session_id', 'session_id')
    if ([string]::IsNullOrWhiteSpace($timeoutSession) -or
        [string]::IsNullOrWhiteSpace($candidateSession) -or
        -not [string]::Equals($timeoutSession, $candidateSession, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }

    $timeoutInterruptionReason = Get-FileTransferEventField `
        -Event $Timeout `
        -Name 'interruption_reason' `
        -Default ''
    $expectedTimeoutPurpose = switch ($timeoutInterruptionReason) {
        'offer_answer_timeout' { 'offer_answer'; break }
        'offer_peer_response_timeout' { 'offer_peer_response'; break }
        'runtime_unlock_offer_peer_response_timeout' { 'offer_peer_response'; break }
        default { ''; break }
    }
    $candidateTimeoutPurpose = Get-FileTransferEventField `
        -Event $Candidate `
        -Name 'timeout_purpose' `
        -Default ''
    if ([string]::IsNullOrWhiteSpace($expectedTimeoutPurpose) -or
        [string]::IsNullOrWhiteSpace($candidateTimeoutPurpose) -or
        -not [string]::Equals(
            $expectedTimeoutPurpose,
            $candidateTimeoutPurpose,
            [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }

    $timeoutPayerDecisionId = Get-FileTransferEventField -Event $Timeout -Name 'payer_decision_id' -Default ''
    $candidatePayerDecisionId = Get-FileTransferEventField -Event $Candidate -Name 'payer_decision_id' -Default ''
    $timeoutOfferGeneration = Get-FileTransferEventField -Event $Timeout -Name 'generation' -Default ''
    $candidateOfferGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Candidate `
        -Names @('offer_generation', 'generation')
    if ([string]::IsNullOrWhiteSpace($timeoutPayerDecisionId) -or
        [string]::IsNullOrWhiteSpace($candidatePayerDecisionId) -or
        $timeoutPayerDecisionId -ne $candidatePayerDecisionId -or
        [string]::IsNullOrWhiteSpace($timeoutOfferGeneration) -or
        [string]::IsNullOrWhiteSpace($candidateOfferGeneration) -or
        $timeoutOfferGeneration -ne $candidateOfferGeneration) {
        return $false
    }

    $timeoutNonce = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Timeout `
        -Names @('offer_nonce', 'nonce')
    $candidateNonce = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Candidate `
        -Names @('offer_nonce', 'nonce')
    if (-not [string]::IsNullOrWhiteSpace($timeoutNonce) -and
        ([string]::IsNullOrWhiteSpace($candidateNonce) -or
            -not [string]::Equals($timeoutNonce, $candidateNonce, [System.StringComparison]::Ordinal))) {
        return $false
    }

    if ($null -ne $Join) {
        $joinGeneration = Get-FileTransferEventField -Event $Join -Name 'join_generation' -Default ''
        $candidateJoinGeneration = Get-FileTransferEventField -Event $Candidate -Name 'join_generation' -Default ''
        if ([string]::IsNullOrWhiteSpace($joinGeneration) -or
            [string]::IsNullOrWhiteSpace($candidateJoinGeneration) -or
            $joinGeneration -ne $candidateJoinGeneration) {
            return $false
        }

        foreach ($aliases in @(
                [pscustomobject]@{ Join = @('offer_session_id', 'session_id'); Candidate = @('offer_session_id', 'session_id') },
                [pscustomobject]@{ Join = @('offer_nonce', 'nonce'); Candidate = @('offer_nonce', 'nonce') },
                [pscustomobject]@{ Join = @('payer_decision_id'); Candidate = @('payer_decision_id') },
                [pscustomobject]@{ Join = @('offer_generation', 'generation'); Candidate = @('offer_generation', 'generation') })) {
            $joinValue = Get-FileTransferRegularV4RecoveryLeaseField -Event $Join -Names $aliases.Join
            $candidateValue = Get-FileTransferRegularV4RecoveryLeaseField -Event $Candidate -Names $aliases.Candidate
            if ([string]::IsNullOrWhiteSpace($joinValue) -or
                [string]::IsNullOrWhiteSpace($candidateValue) -or
                -not [string]::Equals($joinValue, $candidateValue, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }
    }

    return $true
}

function Test-FileTransferRegularV4RecoveryClosureOfferTimeoutFreshArm {
    param(
        [Parameter(Mandatory = $true)]$Arm
    )

    $contractGeneration = [int64](Get-FileTransferEventField `
        -Event $Arm `
        -Name 'contract_generation' `
        -Default '0')
    $predecessorAuthorityId = Get-FileTransferEventField `
        -Event $Arm `
        -Name 'predecessor_authority_id' `
        -Default '(none)'
    return $contractGeneration -gt 0 -and
        (Get-FileTransferEventField -Event $Arm -Name 'dispatch_attempt_generation' -Default '') -eq '1' -and
        (Get-FileTransferEventField -Event $Arm -Name 'missing_dispatch_successor_generation' -Default '') -eq '0' -and
        $predecessorAuthorityId -in @('', '(none)', 'none')
}

function Test-FileTransferRegularV4RecoveryClosureOfferTimeoutGrantBinding {
    param(
        [Parameter(Mandatory = $true)]$Arm,
        [Parameter(Mandatory = $true)]$Consumption,
        [Parameter(Mandatory = $true)]$Grant
    )

    if (-not (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutFreshArm -Arm $Arm)) {
        return $false
    }

    $armContractGeneration = Get-FileTransferEventField -Event $Arm -Name 'contract_generation' -Default ''
    $grantContractGeneration = Get-FileTransferEventField -Event $Grant -Name 'contract_generation' -Default ''
    $grantPredecessorAuthorityId = Get-FileTransferEventField `
        -Event $Grant `
        -Name 'predecessor_authority_id' `
        -Default '(none)'
    if ([string]::IsNullOrWhiteSpace($armContractGeneration) -or
        [string]::IsNullOrWhiteSpace($grantContractGeneration) -or
        $armContractGeneration -ne $grantContractGeneration -or
        (Get-FileTransferEventField -Event $Grant -Name 'dispatch_attempt_generation' -Default '') -ne '1' -or
        (Get-FileTransferEventField -Event $Grant -Name 'missing_dispatch_successor_generation' -Default '') -ne '0' -or
        $grantPredecessorAuthorityId -notin @('', '(none)', 'none')) {
        return $false
    }

    $grantAuthorityId = Get-FileTransferEventField -Event $Grant -Name 'authority_id' -Default ''
    $consumedAuthorityId = Get-FileTransferEventField `
        -Event $Consumption `
        -Name 'retry_authority_id' `
        -Default ''
    return (Test-FileTransferRecoveryAuthorityEvidenceCompatible -Values @(
            $grantAuthorityId,
            $consumedAuthorityId)) -and
        (Get-FileTransferEventField -Event $Consumption -Name 'dispatch_attempt_generation' -Default '') -eq '1' -and
        (Get-FileTransferEventField -Event $Consumption -Name 'missing_dispatch_successor_generation' -Default '') -eq '0'
}

function Test-FileTransferRegularV4RecoveryClosureOfferTimeoutInvalidationDiscard {
    param(
        [Parameter(Mandatory = $true)]$Discard
    )

    $decisionReason = Get-FileTransferEventField -Event $Discard -Name 'decision_reason' -Default ''
    return $decisionReason -in @(
        'retry_join_intent_replaced',
        'regular_v4_recovery_retry_join_intent_replaced',
        'regular_v4_recovery_state_missing',
        'regular_v4_recovery_lease_closure_already_consumed',
        'regular_v4_recovery_lease_closure_stale',
        'regular_v4_recovery_lease_closure_deadline_expired',
        'regular_v4_recovery_route_replaced',
        'regular_v4_recovery_route_publication_replaced',
        'current_filetransfer_owner_authority_mismatch',
        'missing_current_filetransfer_route_publication_authority',
        'ambiguous_current_filetransfer_owner_authority',
        'missing_session_id',
        'phase1_dispatch_contract_owns_successor',
        'dispatch_observed_settlement_not_applied',
        'dispatch_observed_settlement_replaced_before_retry_install',
        'regular_v4_peer_visible_window_failed',
        'existing_regular_v4_receive_recovery_deferral_owned_timeout')
}

function Get-FileTransferRuntimeUnlockRegularV4RecoveryClosureOfferTimeoutCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [AllowEmptyCollection()][object[]]$EffectiveGrantEvents = @()
    )

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$receipts = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_retained' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
        (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'regular_nkn_v4_fast' -and
        (Get-FileTransferEventField -Event $_ -Name 'protocol_version' -Default '') -eq '4' -and
        (Get-FileTransferEventField -Event $_ -Name 'lifecycle_outcome' -Default '') -in @('Completed', 'ReceiveProofObserved') -and
        (Get-FileTransferEventField -Event $_ -Name 'lifecycle_decision_status' -Default '') -in @('Accepted', 'Idempotent')
    })
    [object[]]$timeouts = @($orderedEvents | Where-Object {
        if ($_.EventName -ne 'tuna_acceleration_activation_offer_not_observed') {
            return $false
        }

        $interruption = Get-FileTransferEventField -Event $_ -Name 'interruption_reason' -Default ''
        $recoveryReason = Get-FileTransferEventField -Event $_ -Name 'recovery_reason' -Default ''
        $retryReason = Get-FileTransferEventField -Event $_ -Name 'retry_reason' -Default ''
        return $interruption -in @(
                'offer_answer_timeout',
                'offer_peer_response_timeout',
                'runtime_unlock_offer_peer_response_timeout') -and
            (Get-FileTransferEventField -Event $_ -Name 'peer_received' -Default '') -eq '0' -and
            ($recoveryReason -like '*runtime_unlock*' -or
                $retryReason -like '*runtime_unlock*' -or
                $recoveryReason -in @(
                    'tuna_activation_offer_peer_response_timeout',
                    'tuna_activation_offer_answer_timeout'))
    })
    [object[]]$joinedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_offer_timeout_joined'
    })
    [object[]]$armedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_offer_timeout_retry_armed'
    })
    [object[]]$discardedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_offer_timeout_join_discarded'
    })
    [object[]]$adoptedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_adopted'
    })
    [object[]]$consumedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_consumed'
    })
    [object[]]$grantEvents = @($EffectiveGrantEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_authority_granted' -and
        (Get-FileTransferEventField -Event $_ -Name 'release_kind' -Default '') -eq 'ReceiveRecoveryLeaseClosure' -and
        (Get-FileTransferEventField -Event $_ -Name 'dispatch_attempt_generation' -Default '') -eq '1' -and
        (Get-FileTransferEventField -Event $_ -Name 'missing_dispatch_successor_generation' -Default '') -eq '0' -and
        (Get-FileTransferEventField -Event $_ -Name 'predecessor_authority_id' -Default '(none)') -in @('', '(none)', 'none')
    })
    [object[]]$staleAuthorityEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_current_authority_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'mismatch_field' -Default '') -eq 'infra_current_binding' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'runtime_unlock_retry_dispatch_authority_tuple_mismatch'
    })
    [object[]]$terminalEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'transfer_terminal',
            'file_transfer_inbound_terminal',
            'file_transfer_outbound_terminal',
            'filetransfer_runtime_terminalized')
    })
    [object[]]$replacementAuthorities = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_bridge_recovery_authority_granted'
    })

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $recoveredCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $correlatedStaleAuthorityEvents = New-Object System.Collections.Generic.List[object]
    $seen = @{}

    foreach ($receipt in @($receipts | Sort-Object Sequence, LineNumber)) {
        $receiptSequence = [int64]$receipt.Sequence
        $boundarySequence = [int64]::MaxValue

        $terminal = @($terminalEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryTerminalMatch -Receipt $receipt -Terminal $_)
        } | Select-Object -First 1)
        if ($terminal.Count -gt 0) {
            $boundarySequence = [int64]$terminal[0].Sequence
        }

        $replacement = @($replacementAuthorities | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryAuthorityReplacesClosure -Receipt $receipt -Authority $_)
        } | Select-Object -First 1)
        if ($replacement.Count -gt 0 -and [int64]$replacement[0].Sequence -lt $boundarySequence) {
            $boundarySequence = [int64]$replacement[0].Sequence
        }

        $nextReceipt = @($receipts | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch -Left $receipt -Right $_ -IncludeDirection)
        } | Select-Object -First 1)
        if ($nextReceipt.Count -gt 0 -and [int64]$nextReceipt[0].Sequence -lt $boundarySequence) {
            $boundarySequence = [int64]$nextReceipt[0].Sequence
        }

        foreach ($timeout in @($timeouts | Where-Object {
                    [int64]$_.Sequence -gt $receiptSequence -and
                    [int64]$_.Sequence -lt $boundarySequence -and
                    (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutTupleMatch `
                        -Receipt $receipt `
                        -Candidate $_)
                } | Sort-Object Sequence, LineNumber)) {
            $timeoutSequence = [int64]$timeout.Sequence
            $adoptionBeforeTimeout = @($adoptedEvents | Where-Object {
                [int64]$_.Sequence -gt $receiptSequence -and
                [int64]$_.Sequence -lt $timeoutSequence -and
                (Test-FileTransferRegularV4RecoveryBoundaryTupleMatch -Receipt $receipt -Candidate $_)
            } | Select-Object -First 1)
            if ($adoptionBeforeTimeout.Count -gt 0) {
                continue
            }

            $matchingJoin = @($joinedEvents | Where-Object {
                [int64]$_.Sequence -gt $receiptSequence -and
                [int64]$_.Sequence -le $timeoutSequence -and
                [int64]$_.Sequence -lt $boundarySequence -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutTupleMatch `
                    -Receipt $receipt `
                    -Candidate $_ `
                    -RequireCompleteRecoveryTuple) -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutOfferIdentityMatch `
                    -Timeout $timeout `
                    -Candidate $_)
            } | Select-Object -First 1)
            $matchingArm = @($armedEvents | Where-Object {
                [int64]$_.Sequence -ge $timeoutSequence -and
                [int64]$_.Sequence -lt $boundarySequence -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutTupleMatch `
                    -Receipt $receipt `
                    -Candidate $_ `
                    -RequireCompleteRecoveryTuple) -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutOfferIdentityMatch `
                    -Timeout $timeout `
                    -Candidate $_ `
                    -Join $(if ($matchingJoin.Count -gt 0) { $matchingJoin[0] } else { $null })) -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutFreshArm -Arm $_)
            } | Select-Object -First 1)
            $matchingInvalidationDiscard = @($discardedEvents | Where-Object {
                [int64]$_.Sequence -ge $timeoutSequence -and
                [int64]$_.Sequence -lt $boundarySequence -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutTupleMatch `
                    -Receipt $receipt `
                    -Candidate $_) -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutOfferIdentityMatch `
                    -Timeout $timeout `
                    -Candidate $_ `
                    -Join $(if ($matchingJoin.Count -gt 0) { $matchingJoin[0] } else { $null })) -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutInvalidationDiscard -Discard $_)
            } | Select-Object -First 1)
            $matchingStaleAuthority = @($staleAuthorityEvents | Where-Object {
                [int64]$_.Sequence -gt $timeoutSequence -and
                [int64]$_.Sequence -lt $boundarySequence -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutStalePredecessorMatch `
                    -Receipt $receipt `
                    -RejectedAuthority $_)
            } | Select-Object -First 1)

            $hasLegacyFailureShape =
                (Get-FileTransferEventField -Event $timeout -Name 'recovery_requested' -Default '') -eq '0' -and
                (Get-FileTransferEventField -Event $timeout -Name 'retry_after_recovery_armed' -Default '') -eq '0' -and
                $matchingJoin.Count -eq 0 -and
                $matchingStaleAuthority.Count -gt 0
            $hasExplicitJoinShape = $matchingJoin.Count -gt 0 -or
                $matchingArm.Count -gt 0
            if (-not $hasLegacyFailureShape -and -not $hasExplicitJoinShape) {
                continue
            }
            if ($matchingInvalidationDiscard.Count -gt 0) {
                continue
            }

            $rawCandidates.Add($timeout) | Out-Null
            $key = (Get-FileTransferRegularV4RecoveryLeaseTupleKey -Event $receipt) + '|' +
                (Get-FileTransferEventField -Event $timeout -Name 'payer_decision_id' -Default '(missing)') + '|' +
                (Get-FileTransferEventField -Event $timeout -Name 'generation' -Default '(missing)') + '|' +
                (Get-FileTransferEventField -Event $timeout -Name 'interruption_reason' -Default '(missing)')
            if ($seen.ContainsKey($key)) {
                continue
            }

            $seen[$key] = $true
            $distinctCandidates.Add($timeout) | Out-Null
            if ($matchingStaleAuthority.Count -gt 0) {
                $correlatedStaleAuthorityEvents.Add($matchingStaleAuthority[0]) | Out-Null
            }

            $matchingAdoption = @($adoptedEvents | Where-Object {
                [int64]$_.Sequence -gt $timeoutSequence -and
                [int64]$_.Sequence -lt $boundarySequence -and
                (Test-FileTransferRegularV4RecoveryBoundaryTupleMatch -Receipt $receipt -Candidate $_)
            } | Select-Object -First 1)
            $matchingConsumption = @($consumedEvents | Where-Object {
                [int64]$_.Sequence -gt $timeoutSequence -and
                [int64]$_.Sequence -lt $boundarySequence -and
                (Test-FileTransferRegularV4RecoveryBoundaryTupleMatch -Receipt $receipt -Candidate $_)
            } | Select-Object -First 1)
            $matchingGrant = @($grantEvents | Where-Object {
                [int64]$_.Sequence -gt $timeoutSequence -and
                [int64]$_.Sequence -lt $boundarySequence -and
                $matchingConsumption.Count -gt 0 -and
                [int64]$_.Sequence -ge [int64]$matchingConsumption[0].Sequence -and
                (Test-FileTransferRegularV4RecoveryClosureGrantMatch -Receipt $receipt -Grant $_) -and
                $matchingArm.Count -gt 0 -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutGrantBinding `
                    -Arm $matchingArm[0] `
                    -Consumption $matchingConsumption[0] `
                    -Grant $_)
            })

            if ($matchingJoin.Count -gt 0 -and
                $matchingArm.Count -gt 0 -and
                $matchingAdoption.Count -gt 0 -and
                $matchingConsumption.Count -gt 0 -and
                $matchingGrant.Count -eq 1 -and
                [int64]$matchingJoin[0].Sequence -le [int64]$matchingArm[0].Sequence -and
                [int64]$matchingJoin[0].Sequence -lt [int64]$matchingAdoption[0].Sequence -and
                [int64]$matchingArm[0].Sequence -lt [int64]$matchingConsumption[0].Sequence -and
                [int64]$matchingAdoption[0].Sequence -lt [int64]$matchingConsumption[0].Sequence -and
                [int64]$matchingConsumption[0].Sequence -le [int64]$matchingGrant[0].Sequence) {
                $recoveredCandidates.Add($timeout) | Out-Null
            }
            else {
                $unresolvedCandidates.Add($timeout) | Out-Null
            }
        }
    }

    $verdict = if ($unresolvedCandidates.Count -gt 0) {
        'fail'
    }
    elseif ($distinctCandidates.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = $recoveredCandidates.Count
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = $verdict
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @($recoveredCandidates.ToArray())
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
        CorrelatedStaleAuthorityEvents = @($correlatedStaleAuthorityEvents.ToArray())
    }
}

function Get-FileTransferRuntimeUnlockRetryZeroOfferSuccessorCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [AllowEmptyCollection()][object[]]$EffectiveGrantEvents = @()
    )

    function Test-ZeroOfferRetryScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right,
            [switch]$IncludeAuthority
        )

        $fields = @(
            'session_id',
            'transfer_id',
            'direction',
            'route',
            'protocol_version',
            'live_route_epoch',
            'runtime_generation',
            'terminal_generation',
            'leg_generation',
            'transport_epoch',
            'bridge_recovery_generation',
            'bridge_decision_generation',
            'route_publication_generation',
            'route_commit_generation',
            'contract_generation',
            'retry_reason',
            'recovery_reason')
        if ($IncludeAuthority) {
            $fields += @(
                'authority_id',
                'retired_generation',
                'dispatch_attempt_generation',
                'missing_dispatch_successor_generation')
        }

        foreach ($field in $fields) {
            $leftValue = Get-FileTransferEventField -Event $Left -Name $field -Default ''
            $rightValue = Get-FileTransferEventField -Event $Right -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals(
                    $leftValue,
                    $rightValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    [object[]]$settlementEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_contract_settled' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'MissingDispatch' -and
        [int64](Get-FileTransferEventField -Event $_ -Name 'retired_generation' -Default '-1') -eq 0 -and
        [int64](Get-FileTransferEventField -Event $_ -Name 'offer_generation' -Default '-1') -eq 0
    } | Sort-Object Sequence)
    [object[]]$settlementDecisionEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_settlement_decided' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'MissingDispatch' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @('Accepted', 'Idempotent')
    } | Sort-Object Sequence)
    [object[]]$rejectionEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_successor_intent_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'retry_dispatch_successor_retired_offer_mismatch'
    } | Sort-Object Sequence)
    [object[]]$grantEvents = @($EffectiveGrantEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_authority_granted'
    } | Sort-Object Sequence)

    $acceptedSettlements = New-Object System.Collections.Generic.List[object]
    foreach ($settlement in $settlementEvents) {
        $authorityId = Get-FileTransferEventField -Event $settlement -Name 'authority_id' -Default ''
        if ([string]::IsNullOrWhiteSpace($authorityId) -or $authorityId -in @('(none)', 'none')) {
            continue
        }

        $matchingDecision = @($settlementDecisionEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$settlement.Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default '') -eq $authorityId -and
            (Test-ZeroOfferRetryScopeMatch -Left $settlement -Right $_ -IncludeAuthority)
        } | Sort-Object Sequence | Select-Object -First 1)
        if ($matchingDecision.Count -gt 0) {
            $acceptedSettlements.Add($settlement) | Out-Null
        }
    }

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $recoveredCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($rejection in $rejectionEvents) {
        $authorityId = Get-FileTransferEventField -Event $rejection -Name 'authority_id' -Default ''
        $requestedPredecessor = Get-FileTransferEventField `
            -Event $rejection `
            -Name 'requested_predecessor_authority_id' `
            -Default ''
        $predecessorAttempt = [int](Get-FileTransferEventField `
            -Event $rejection `
            -Name 'dispatch_attempt_generation' `
            -Default '0')
        $predecessorMissingGeneration = [int](Get-FileTransferEventField `
            -Event $rejection `
            -Name 'missing_dispatch_successor_generation' `
            -Default '-1')
        $requestedAttempt = [int](Get-FileTransferEventField `
            -Event $rejection `
            -Name 'requested_dispatch_attempt_generation' `
            -Default '0')
        $requestedMissingGeneration = [int](Get-FileTransferEventField `
            -Event $rejection `
            -Name 'requested_missing_dispatch_successor_generation' `
            -Default '-1')
        $requestedRetiredGeneration = [int64](Get-FileTransferEventField `
            -Event $rejection `
            -Name 'requested_retired_generation' `
            -Default '-1')
        $predecessorRetiredGeneration = [int64](Get-FileTransferEventField `
            -Event $rejection `
            -Name 'retired_generation' `
            -Default '-1')
        $supersession = Get-FileTransferEventField `
            -Event $rejection `
            -Name 'request_active_predecessor_supersession' `
            -Default '0'

        if ([string]::IsNullOrWhiteSpace($authorityId) -or
            $authorityId -in @('(none)', 'none') -or
            $requestedPredecessor -ne $authorityId -or
            $requestedRetiredGeneration -ne 0 -or
            $predecessorRetiredGeneration -ne 0 -or
            $requestedAttempt -ne ($predecessorAttempt + 1) -or
            $requestedMissingGeneration -ne ($predecessorMissingGeneration + 1) -or
            $supersession -notin @('0', 'false', 'False')) {
            continue
        }

        $matchingSettlement = @($acceptedSettlements.ToArray() | Where-Object {
            [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default '') -eq $authorityId -and
            [int](Get-FileTransferEventField -Event $_ -Name 'dispatch_attempt_generation' -Default '0') -eq
                $predecessorAttempt -and
            [int](Get-FileTransferEventField -Event $_ -Name 'missing_dispatch_successor_generation' -Default '-1') -eq
                $predecessorMissingGeneration -and
            (Test-ZeroOfferRetryScopeMatch -Left $_ -Right $rejection -IncludeAuthority)
        } | Sort-Object Sequence -Descending | Select-Object -First 1)
        if ($matchingSettlement.Count -eq 0) {
            continue
        }

        $rawCandidates.Add($rejection) | Out-Null
        $key = '{0}|{1}|{2}|{3}|{4}|{5}' -f `
            (Get-FileTransferEventField -Event $rejection -Name 'session_id' -Default ''), `
            (Get-FileTransferEventField -Event $rejection -Name 'transfer_id' -Default ''), `
            (Get-FileTransferEventField -Event $rejection -Name 'direction' -Default ''), `
            $authorityId, `
            $requestedAttempt, `
            $requestedMissingGeneration
        if ($seen.ContainsKey($key)) {
            continue
        }

        $seen[$key] = 1
        $distinctCandidates.Add($rejection) | Out-Null
        $matchingGrant = @($grantEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$rejection.Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'predecessor_authority_id' -Default '') -eq $authorityId -and
            [int64](Get-FileTransferEventField -Event $_ -Name 'retired_generation' -Default '-1') -eq 0 -and
            [int](Get-FileTransferEventField -Event $_ -Name 'dispatch_attempt_generation' -Default '0') -eq
                $requestedAttempt -and
            [int](Get-FileTransferEventField -Event $_ -Name 'missing_dispatch_successor_generation' -Default '-1') -eq
                $requestedMissingGeneration -and
            (Test-ZeroOfferRetryScopeMatch -Left $matchingSettlement[0] -Right $_)
        } | Sort-Object Sequence | Select-Object -First 1)
        if ($matchingGrant.Count -gt 0) {
            $recoveredCandidates.Add($rejection) | Out-Null
        }
        else {
            $unresolvedCandidates.Add($rejection) | Out-Null
        }
    }

    $verdict = if ($unresolvedCandidates.Count -gt 0) {
        'fail'
    }
    elseif ($distinctCandidates.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = $recoveredCandidates.Count
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = $verdict
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @($recoveredCandidates.ToArray())
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
        AcceptedMissingDispatchSettlementEvents = @($acceptedSettlements.ToArray())
    }
}

function Get-FileTransferRuntimeUnlockRetryFallbackPairedYieldSuccessorReleaseCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [AllowEmptyCollection()][object[]]$EffectiveGrantEvents = @()
    )

    function Test-FallbackPairedYieldReleaseTupleMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        foreach ($field in @(
                'release_kind',
                'release_authority_id',
                'release_generation',
                'release_outcome')) {
            $leftValue = Get-FileTransferEventField -Event $Left -Name $field -Default ''
            $rightValue = Get-FileTransferEventField -Event $Right -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                $leftValue -in @('(none)', 'none') -or
                $rightValue -in @('(none)', 'none') -or
                -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        return $true
    }

    function Test-FallbackPairedYieldSuccessorRequestMatch {
        param(
            [Parameter(Mandatory = $true)]$Request,
            [Parameter(Mandatory = $true)]$Rejection,
            [Parameter(Mandatory = $true)]$Settlement
        )

        foreach ($field in @('session_id', 'transfer_id', 'direction', 'contract_generation')) {
            $requestValue = Get-FileTransferEventField -Event $Request -Name $field -Default ''
            $rejectionValue = Get-FileTransferEventField -Event $Rejection -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($requestValue) -or
                [string]::IsNullOrWhiteSpace($rejectionValue) -or
                -not [string]::Equals($requestValue, $rejectionValue, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        $authorityId = Get-FileTransferEventField -Event $Settlement -Name 'authority_id' -Default ''
        $requestPredecessor = Get-FileTransferEventField -Event $Request -Name 'predecessor_authority_id' -Default ''
        $rejectedPredecessor = Get-FileTransferEventField -Event $Rejection -Name 'requested_predecessor_authority_id' -Default ''
        if ([string]::IsNullOrWhiteSpace($authorityId) -or
            $authorityId -in @('(none)', 'none') -or
            $requestPredecessor -ne $authorityId -or
            $rejectedPredecessor -ne $authorityId) {
            return $false
        }

        [int64]$offerGeneration = Get-FileTransferEventInt64Field -Event $Settlement -Name 'offer_generation' -Default -1
        [int64]$requestRetiredGeneration = Get-FileTransferEventInt64Field -Event $Request -Name 'retired_generation' -Default -1
        [int64]$rejectedRetiredGeneration = Get-FileTransferEventInt64Field -Event $Rejection -Name 'requested_retired_generation' -Default -1
        [int64]$predecessorAttempt = Get-FileTransferEventInt64Field -Event $Settlement -Name 'dispatch_attempt_generation' -Default -1
        [int64]$predecessorMissingGeneration = Get-FileTransferEventInt64Field -Event $Settlement -Name 'missing_dispatch_successor_generation' -Default -1
        [int64]$requestAttempt = Get-FileTransferEventInt64Field -Event $Request -Name 'dispatch_attempt_generation' -Default -1
        [int64]$rejectedAttempt = Get-FileTransferEventInt64Field -Event $Rejection -Name 'requested_dispatch_attempt_generation' -Default -1
        [int64]$requestMissingGeneration = Get-FileTransferEventInt64Field -Event $Request -Name 'missing_dispatch_successor_generation' -Default -1
        [int64]$rejectedMissingGeneration = Get-FileTransferEventInt64Field -Event $Rejection -Name 'requested_missing_dispatch_successor_generation' -Default -1
        $requestSupersession = Get-FileTransferEventField -Event $Request -Name 'request_active_predecessor_supersession' -Default ''
        $rejectedSupersession = Get-FileTransferEventField -Event $Rejection -Name 'request_active_predecessor_supersession' -Default ''

        return $offerGeneration -gt 0 -and
            $requestRetiredGeneration -eq $offerGeneration -and
            $rejectedRetiredGeneration -eq $offerGeneration -and
            $requestAttempt -eq ($predecessorAttempt + 1) -and
            $rejectedAttempt -eq $requestAttempt -and
            $requestMissingGeneration -eq ($predecessorMissingGeneration + 1) -and
            $rejectedMissingGeneration -eq $requestMissingGeneration -and
            $requestSupersession -in @('0', 'false', 'False') -and
            $rejectedSupersession -in @('0', 'false', 'False')
    }

    function Test-FallbackPairedYieldSuccessorGrantMatch {
        param(
            [Parameter(Mandatory = $true)]$PredecessorGrant,
            [Parameter(Mandatory = $true)]$Request,
            [Parameter(Mandatory = $true)]$SuccessorGrant
        )

        foreach ($field in @(
                'session_id',
                'transfer_id',
                'direction',
                'route',
                'route_kind',
                'protocol_version',
                'live_route_epoch',
                'terminal_generation',
                'leg_generation',
                'contract_generation',
                'retry_reason',
                'recovery_reason',
                'target_route',
                'target_route_kind',
                'target_protocol_version',
                'target_transport',
                'runtime_owner_session_id',
                'runtime_owner_transfer_id',
                'runtime_owner_direction',
                'runtime_owner_route',
                'runtime_owner_route_kind',
                'runtime_owner_protocol_version',
                'runtime_owner_live_route_epoch',
                'runtime_owner_terminal_generation',
                'runtime_owner_family',
                'source_publication_session_id',
                'source_publication_transfer_id',
                'source_publication_direction',
                'source_publication_route',
                'source_publication_route_kind',
                'source_publication_protocol_version',
                'source_publication_live_route_epoch',
                'source_publication_terminal_generation',
                'source_publication_leg_generation',
                'source_publication_route_commit_generation',
                'source_publication_target_route',
                'source_publication_target_route_kind',
                'source_publication_target_protocol_version',
                'source_publication_target_transport',
                'source_publication_action_kind')) {
            $predecessorValue = Get-FileTransferEventField -Event $PredecessorGrant -Name $field -Default ''
            $successorValue = Get-FileTransferEventField -Event $SuccessorGrant -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($predecessorValue) -or
                [string]::IsNullOrWhiteSpace($successorValue) -or
                -not [string]::Equals($predecessorValue, $successorValue, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        $predecessorAuthorityId = Get-FileTransferEventField -Event $PredecessorGrant -Name 'authority_id' -Default ''
        if ((Get-FileTransferEventField -Event $SuccessorGrant -Name 'predecessor_authority_id' -Default '') -ne
                $predecessorAuthorityId -or
            -not (Test-FallbackPairedYieldReleaseTupleMatch -Left $PredecessorGrant -Right $SuccessorGrant)) {
            return $false
        }

        return (Get-FileTransferEventInt64Field -Event $SuccessorGrant -Name 'retired_generation' -Default -1) -eq
                (Get-FileTransferEventInt64Field -Event $Request -Name 'retired_generation' -Default -2) -and
            (Get-FileTransferEventInt64Field -Event $SuccessorGrant -Name 'dispatch_attempt_generation' -Default -1) -eq
                (Get-FileTransferEventInt64Field -Event $Request -Name 'dispatch_attempt_generation' -Default -2) -and
            (Get-FileTransferEventInt64Field -Event $SuccessorGrant -Name 'missing_dispatch_successor_generation' -Default -1) -eq
                (Get-FileTransferEventInt64Field -Event $Request -Name 'missing_dispatch_successor_generation' -Default -2) -and
            (Get-FileTransferEventField -Event $SuccessorGrant -Name 'request_active_predecessor_supersession' -Default '') -in
                @('0', 'false', 'False')
    }

    [object[]]$predecessorGrantEvents = @($EffectiveGrantEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_authority_granted' -and
        (Get-FileTransferEventField -Event $_ -Name 'release_kind' -Default '') -eq 'FallbackPairedTailYield' -and
        (Get-FileTransferEventField -Event $_ -Name 'release_outcome' -Default '') -eq 'Quiescent'
    } | Sort-Object Sequence, LineNumber)
    [object[]]$settlementEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_contract_settled' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'MissingDispatch' -and
        (Get-FileTransferEventField -Event $_ -Name 'dispatch_observed' -Default '') -eq '0'
    } | Sort-Object Sequence, LineNumber)
    [object[]]$reportedEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_settlement_reported' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'MissingDispatch'
    } | Sort-Object Sequence, LineNumber)
    [object[]]$decidedEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_settlement_decided' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'MissingDispatch' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @('Accepted', 'Idempotent')
    } | Sort-Object Sequence, LineNumber)
    [object[]]$requestEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_successor_intent_requested'
    } | Sort-Object Sequence, LineNumber)
    [object[]]$rejectionEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_successor_intent_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'retry_dispatch_predecessor_release_invalid'
    } | Sort-Object Sequence, LineNumber)

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $recoveredCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $acceptedSettlements = New-Object System.Collections.Generic.List[object]
    $seen = @{}

    foreach ($rejection in $rejectionEvents) {
        [object[]]$matchingSettlements = @($settlementEvents | Where-Object {
            [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
            (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $_ -Right $rejection)
        } | Sort-Object Sequence, LineNumber -Descending)
        $matched = $null
        foreach ($settlement in $matchingSettlements) {
            [object[]]$matchingGrants = @($predecessorGrantEvents | Where-Object {
                [int64]$_.Sequence -lt [int64]$settlement.Sequence -and
                (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $_ -Right $settlement)
            } | Sort-Object Sequence, LineNumber -Descending)
            if ($matchingGrants.Count -eq 0) {
                continue
            }

            [object[]]$matchingReports = @($reportedEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$settlement.Sequence -and
                [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
                (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $settlement -Right $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'settlement_reason' -Default '') -eq
                    (Get-FileTransferEventField -Event $settlement -Name 'decision_reason' -Default '')
            } | Sort-Object Sequence, LineNumber)
            if ($matchingReports.Count -eq 0) {
                continue
            }

            [object[]]$matchingDecisions = @($decidedEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$matchingReports[0].Sequence -and
                [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
                (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $settlement -Right $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'settlement_reason' -Default '') -eq
                    (Get-FileTransferEventField -Event $matchingReports[0] -Name 'settlement_reason' -Default '')
            } | Sort-Object Sequence, LineNumber)
            if ($matchingDecisions.Count -eq 0) {
                continue
            }

            [object[]]$matchingRequests = @($requestEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$matchingDecisions[0].Sequence -and
                [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
                (Test-FallbackPairedYieldSuccessorRequestMatch `
                    -Request $_ `
                    -Rejection $rejection `
                    -Settlement $settlement)
            } | Sort-Object Sequence, LineNumber)
            if ($matchingRequests.Count -eq 0) {
                continue
            }

            $matched = [pscustomobject]@{
                Grant = $matchingGrants[0]
                Settlement = $settlement
                Request = $matchingRequests[0]
            }
            break
        }

        if ($null -eq $matched) {
            continue
        }

        $rawCandidates.Add($rejection) | Out-Null
        $acceptedSettlements.Add($matched.Settlement) | Out-Null
        $keyFields = @(Get-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleFields)
        $key = (@($keyFields | ForEach-Object {
            Get-FileTransferEventField -Event $rejection -Name $_ -Default '(missing)'
        }) + @(
            (Get-FileTransferEventField -Event $rejection -Name 'requested_retired_generation' -Default '(missing)'),
            (Get-FileTransferEventField -Event $rejection -Name 'requested_dispatch_attempt_generation' -Default '(missing)'),
            (Get-FileTransferEventField -Event $rejection -Name 'requested_missing_dispatch_successor_generation' -Default '(missing)'))) -join '|'
        if ($seen.ContainsKey($key)) {
            continue
        }

        $seen[$key] = $true
        $distinctCandidates.Add($rejection) | Out-Null
        [object[]]$matchingSuccessorGrants = @($EffectiveGrantEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$rejection.Sequence -and
            (Test-FallbackPairedYieldSuccessorGrantMatch `
                -PredecessorGrant $matched.Grant `
                -Request $matched.Request `
                -SuccessorGrant $_)
        } | Sort-Object Sequence, LineNumber)
        if ($matchingSuccessorGrants.Count -gt 0) {
            $recoveredCandidates.Add($rejection) | Out-Null
        }
        else {
            $unresolvedCandidates.Add($rejection) | Out-Null
        }
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = $recoveredCandidates.Count
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = if ($unresolvedCandidates.Count -gt 0) {
            'fail'
        }
        elseif ($distinctCandidates.Count -gt 0) {
            'pass'
        }
        else {
            'none'
        }
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @($recoveredCandidates.ToArray())
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
        AcceptedMissingDispatchSettlementEvents = @($acceptedSettlements.ToArray())
    }
}

function Get-FileTransferRuntimeUnlockRetryFallbackTailUnblockRecheckCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [AllowEmptyCollection()][object[]]$EffectiveGrantEvents = @(),
        [bool]$Phase2ProtocolObserved = $false
    )

    # Raw Phase-2 grant telemetry is not authority until the exact staged
    # decision has a committed install receipt. Keep non-grant evidence intact,
    # but expose only install-proven grants to this correlation.
    [object[]]$nonGrantEvents = @($Events | Where-Object {
        $_.EventName -ne 'runtime_unlock_retry_dispatch_authority_granted'
    })
    $Events = @($nonGrantEvents + @($EffectiveGrantEvents) | Sort-Object Sequence, LineNumber)

    [object[]]$heldEvents = @($Events | Where-Object {
        $_.EventName -in @(
            'runtime_unlock_retry_dispatch_authority_held',
            'runtime_unlock_retry_dispatch_authority_hold_preserved') -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'fallback_paired_tail_yield_pending'
    } | Sort-Object Sequence)
    [object[]]$pairedYieldEvents = @($Events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_paired_yield_granted' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
        (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'post_tuna_fallback_v6' -and
        (Get-FileTransferEventField -Event $_ -Name 'protocol_version' -Default '') -eq '6'
    } | Sort-Object Sequence)
    [object[]]$tailUnblockedEvents = @($Events | Where-Object {
        $_.EventName -eq 'filetransfer_v6_epoch_tail_unblocked' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
        (Get-FileTransferEventField -Event $_ -Name 'target_transport' -Default '') -eq 'regular_nkn' -and
        (Get-FileTransferEventField -Event $_ -Name 'handoff_kind' -Default '') -in @(
            'tuna_to_normal_fallback',
            'regular_nkn_recovery')
    } | Sort-Object Sequence)
    [object[]]$recheckRequestedEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_fallback_tail_unblock_recheck_requested'
    } | Sort-Object Sequence)
    [object[]]$recheckDecidedEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_fallback_tail_unblock_recheck_decided'
    } | Sort-Object Sequence)
    [object[]]$recheckDiscardedEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_fallback_tail_unblock_recheck_discarded'
    } | Sort-Object Sequence)

    function Get-FallbackTailRecheckField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Names,
            [string]$Default = ''
        )

        foreach ($name in $Names) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and $value -notin @('(none)', 'none')) {
                return $value
            }
        }

        return $Default
    }

    function Get-FallbackTailRecheckExactField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Names
        )

        foreach ($name in $Names) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value)) {
                return $value
            }
        }

        return ''
    }

    function Test-FallbackTailRecheckEventComplete {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][ValidateSet('Hold', 'Requested', 'Decided', 'Boundary')][string]$Kind
        )

        if ($Kind -eq 'Boundary') {
            $required = @(
                'session_id',
                'transfer_id',
                'direction',
                'transport_epoch',
                'handoff_kind',
                'source_transport',
                'target_transport')

            $recoveryBoundaryGeneration = Get-FallbackTailRecheckExactField `
                -Event $Event `
                -Names @('recovery_boundary_generation')
            $observationReason = Get-FallbackTailRecheckExactField `
                -Event $Event `
                -Names @('observation_reason')
            if (-not [string]::IsNullOrWhiteSpace($recoveryBoundaryGeneration) -or
                -not [string]::IsNullOrWhiteSpace($observationReason)) {
                $required += @('recovery_boundary_generation', 'observation_reason')
            }
        }
        else {
            $required = @(
                'session_id',
                'transfer_id',
                'direction|attempted_source_publication_direction',
                'contract_generation',
                'retired_generation|retired_offer_generation',
                'dispatch_attempt_generation',
                'missing_dispatch_successor_generation',
                'predecessor_authority_id',
                'request_active_predecessor_supersession',
                'retry_reason',
                'recovery_reason',
                'regular_v4_liveness_generation',
                'bridge_decision_generation',
                'source_session_id|source_publication_session_id|attempted_source_publication_session_id',
                'source_transfer_id|source_publication_transfer_id|attempted_source_publication_transfer_id',
                'source_direction|source_publication_direction|attempted_source_publication_direction',
                'source_route|source_publication_route|attempted_source_publication_route',
                'source_protocol_version|source_publication_protocol_version|attempted_source_publication_protocol_version',
                'source_live_route_epoch|source_publication_live_route_epoch|attempted_source_publication_live_route_epoch',
                'source_runtime_generation|source_publication_runtime_generation|attempted_source_publication_runtime_generation',
                'source_terminal_generation|source_publication_terminal_generation|attempted_source_publication_terminal_generation',
                'source_leg_generation|source_publication_leg_generation|attempted_source_publication_leg_generation',
                'source_route_publication_generation|source_publication_generation|attempted_source_publication_route_publication_generation',
                'source_route_commit_generation|source_publication_route_commit_generation|attempted_source_publication_route_commit_generation',
                'source_route_commit_generation_present|source_publication_route_commit_generation_present|attempted_source_publication_route_commit_generation_present',
                'source_target_route|source_publication_target_route|attempted_source_publication_target_route',
                'source_target_protocol_version|source_publication_target_protocol_version|attempted_source_publication_target_protocol_version',
                'source_target_transport|source_publication_target_transport|attempted_source_publication_target_transport',
                'source_route_publication_action_kind|source_publication_action_kind|attempted_source_publication_route_publication_action_kind',
                'source_coordinator_decision_reason|source_publication_reason|attempted_source_publication_coordinator_decision_reason')

            if ($Kind -in @('Requested', 'Decided')) {
                $required += @(
                    'recovered_transport_epoch',
                    'handoff_kind',
                    'boundary_source_transport',
                    'boundary_target_transport',
                    'fallback_epoch',
                    'boundary_reason',
                    'boundary_identity',
                    'original_hold_reason',
                    'recheck_generation')
            }
            if ($Kind -eq 'Decided') {
                $required += @(
                    'decision_status',
                    'decision_valid',
                    'decision_reason')
            }
        }

        foreach ($aliasSpec in $required) {
            [string[]]$aliases = $aliasSpec -split '\|'
            if ([string]::IsNullOrWhiteSpace(
                    (Get-FallbackTailRecheckExactField -Event $Event -Names $aliases))) {
                return $false
            }
        }

        return $true
    }

    function Test-FallbackTailRecheckHoldEligible {
        param(
            [Parameter(Mandatory = $true)]$Event
        )

        if (Test-FallbackTailRecheckEventComplete -Event $Event -Kind Hold) {
            return $true
        }

        # Artifacts captured before the recheck protocol logged the complete request tuple.
        # Retain those holds only as evidence that the historical boundary was abandoned;
        # they can never satisfy the strict requested/decided recovery proof below.
        foreach ($aliasSpec in @(
                'session_id',
                'transfer_id',
                'contract_generation',
                'retired_generation|retired_offer_generation',
                'regular_v4_liveness_generation',
                'bridge_decision_generation',
                'attempted_source_publication_session_id',
                'attempted_source_publication_transfer_id',
                'attempted_source_publication_direction',
                'attempted_source_publication_route',
                'attempted_source_publication_protocol_version',
                'attempted_source_publication_live_route_epoch',
                'attempted_source_publication_runtime_generation',
                'attempted_source_publication_terminal_generation',
                'attempted_source_publication_leg_generation',
                'attempted_source_publication_route_publication_generation',
                'attempted_source_publication_route_commit_generation',
                'attempted_source_publication_target_route',
                'attempted_source_publication_target_protocol_version',
                'attempted_source_publication_target_transport',
                'attempted_source_publication_route_publication_action_kind')) {
            [string[]]$aliases = $aliasSpec -split '\|'
            if ([string]::IsNullOrWhiteSpace(
                    (Get-FallbackTailRecheckExactField -Event $Event -Names $aliases))) {
                return $false
            }
        }

        return $true
    }

    function Test-FallbackTailRecheckIdentityMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        foreach ($field in @('session_id', 'transfer_id')) {
            $leftValue = Get-FallbackTailRecheckField -Event $Left -Names @($field)
            $rightValue = Get-FallbackTailRecheckField -Event $Right -Names @($field)
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Test-FallbackTailRecheckRequestMatch {
        param(
            [Parameter(Mandatory = $true)]$Hold,
            [Parameter(Mandatory = $true)]$Decision,
            [ValidateSet('Hold', 'Requested', 'Decided')][string]$DecisionKind = 'Requested'
        )

        if (-not (Test-FallbackTailRecheckIdentityMatch -Left $Hold -Right $Decision)) {
            return $false
        }

        if (-not (Test-FallbackTailRecheckEventComplete -Event $Hold -Kind Hold) -or
            -not (Test-FallbackTailRecheckEventComplete -Event $Decision -Kind $DecisionKind)) {
            return $false
        }

        $fieldAliases = @(
            [pscustomobject]@{ Hold = @('direction', 'attempted_source_publication_direction'); Decision = @('direction', 'request_direction') },
            [pscustomobject]@{ Hold = @('source_route', 'source_publication_route', 'attempted_source_publication_route', 'route'); Decision = @('source_route', 'source_publication_route', 'request_source_route') },
            [pscustomobject]@{ Hold = @('source_protocol_version', 'source_publication_protocol_version', 'attempted_source_publication_protocol_version', 'protocol_version'); Decision = @('source_protocol_version', 'source_publication_protocol_version', 'request_source_protocol_version') },
            [pscustomobject]@{ Hold = @('source_live_route_epoch', 'source_publication_live_route_epoch', 'attempted_source_publication_live_route_epoch', 'live_route_epoch'); Decision = @('source_live_route_epoch', 'source_publication_live_route_epoch', 'request_source_live_route_epoch') },
            [pscustomobject]@{ Hold = @('source_runtime_generation', 'source_publication_runtime_generation', 'attempted_source_publication_runtime_generation', 'runtime_generation'); Decision = @('source_runtime_generation', 'source_publication_runtime_generation', 'request_source_runtime_generation') },
            [pscustomobject]@{ Hold = @('source_terminal_generation', 'source_publication_terminal_generation', 'attempted_source_publication_terminal_generation', 'terminal_generation'); Decision = @('source_terminal_generation', 'source_publication_terminal_generation', 'request_source_terminal_generation') },
            [pscustomobject]@{ Hold = @('source_leg_generation', 'source_publication_leg_generation', 'attempted_source_publication_leg_generation', 'leg_generation'); Decision = @('source_leg_generation', 'source_publication_leg_generation', 'request_source_leg_generation') },
            [pscustomobject]@{ Hold = @('source_route_commit_generation', 'source_publication_route_commit_generation', 'attempted_source_publication_route_commit_generation', 'route_commit_generation'); Decision = @('source_route_commit_generation', 'source_publication_route_commit_generation', 'request_source_route_commit_generation') },
            [pscustomobject]@{ Hold = @('contract_generation'); Decision = @('contract_generation', 'request_contract_generation') },
            [pscustomobject]@{ Hold = @('retired_generation'); Decision = @('retired_generation', 'request_retired_generation') },
            [pscustomobject]@{ Hold = @('dispatch_attempt_generation'); Decision = @('dispatch_attempt_generation', 'request_dispatch_attempt_generation') },
            [pscustomobject]@{ Hold = @('missing_dispatch_successor_generation'); Decision = @('missing_dispatch_successor_generation', 'request_missing_dispatch_successor_generation') },
            [pscustomobject]@{ Hold = @('predecessor_authority_id'); Decision = @('predecessor_authority_id', 'request_predecessor_authority_id') },
            [pscustomobject]@{ Hold = @('request_active_predecessor_supersession'); Decision = @('request_active_predecessor_supersession') },
            [pscustomobject]@{ Hold = @('retry_reason'); Decision = @('retry_reason') },
            [pscustomobject]@{ Hold = @('recovery_reason'); Decision = @('recovery_reason') },
            [pscustomobject]@{ Hold = @('regular_v4_liveness_generation'); Decision = @('regular_v4_liveness_generation') },
            [pscustomobject]@{ Hold = @('bridge_decision_generation'); Decision = @('bridge_decision_generation') },
            [pscustomobject]@{ Hold = @('source_session_id', 'source_publication_session_id', 'attempted_source_publication_session_id'); Decision = @('source_session_id') },
            [pscustomobject]@{ Hold = @('source_transfer_id', 'source_publication_transfer_id', 'attempted_source_publication_transfer_id'); Decision = @('source_transfer_id') },
            [pscustomobject]@{ Hold = @('source_direction', 'source_publication_direction', 'attempted_source_publication_direction'); Decision = @('source_direction') },
            [pscustomobject]@{ Hold = @('source_route_publication_generation', 'source_publication_generation', 'attempted_source_publication_route_publication_generation'); Decision = @('source_route_publication_generation') },
            [pscustomobject]@{ Hold = @('source_route_commit_generation_present', 'source_publication_route_commit_generation_present', 'attempted_source_publication_route_commit_generation_present'); Decision = @('source_route_commit_generation_present') },
            [pscustomobject]@{ Hold = @('source_target_route', 'source_publication_target_route', 'attempted_source_publication_target_route'); Decision = @('source_target_route') },
            [pscustomobject]@{ Hold = @('source_target_protocol_version', 'source_publication_target_protocol_version', 'attempted_source_publication_target_protocol_version'); Decision = @('source_target_protocol_version') },
            [pscustomobject]@{ Hold = @('source_target_transport', 'source_publication_target_transport', 'attempted_source_publication_target_transport'); Decision = @('source_target_transport') },
            [pscustomobject]@{ Hold = @('source_route_publication_action_kind', 'source_publication_action_kind', 'attempted_source_publication_route_publication_action_kind'); Decision = @('source_route_publication_action_kind') },
            [pscustomobject]@{ Hold = @('source_coordinator_decision_reason', 'source_publication_reason', 'attempted_source_publication_coordinator_decision_reason'); Decision = @('source_coordinator_decision_reason') }
        )
        foreach ($aliases in $fieldAliases) {
            $holdValue = Get-FallbackTailRecheckExactField -Event $Hold -Names $aliases.Hold
            $decisionValue = Get-FallbackTailRecheckExactField -Event $Decision -Names $aliases.Decision
            if ([string]::IsNullOrWhiteSpace($holdValue) -or
                [string]::IsNullOrWhiteSpace($decisionValue) -or
                -not [string]::Equals($holdValue, $decisionValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Test-FallbackTailRecheckBoundaryMatch {
        param(
            [Parameter(Mandatory = $true)]$Boundary,
            [Parameter(Mandatory = $true)]$Decision
        )

        if (-not (Test-FallbackTailRecheckEventComplete -Event $Boundary -Kind Boundary) -or
            -not (Test-FallbackTailRecheckEventComplete -Event $Decision -Kind Requested) -or
            -not (Test-FallbackTailRecheckIdentityMatch -Left $Boundary -Right $Decision)) {
            return $false
        }

        foreach ($aliases in @(
                [pscustomobject]@{ Boundary = @('transport_epoch'); Decision = @('recovered_transport_epoch', 'transport_epoch') },
                [pscustomobject]@{ Boundary = @('handoff_kind'); Decision = @('handoff_kind', 'recovery_handoff_kind') },
                [pscustomobject]@{ Boundary = @('source_transport'); Decision = @('boundary_source_transport') },
                [pscustomobject]@{ Boundary = @('target_transport'); Decision = @('boundary_target_transport') })) {
            $boundaryValue = Get-FallbackTailRecheckExactField -Event $Boundary -Names $aliases.Boundary
            $decisionValue = Get-FallbackTailRecheckExactField -Event $Decision -Names $aliases.Decision
            if ([string]::IsNullOrWhiteSpace($boundaryValue) -or
                [string]::IsNullOrWhiteSpace($decisionValue) -or
                -not [string]::Equals($boundaryValue, $decisionValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        $boundaryGeneration = Get-FallbackTailRecheckExactField `
            -Event $Boundary `
            -Names @('recovery_boundary_generation')
        $observationReason = Get-FallbackTailRecheckExactField `
            -Event $Boundary `
            -Names @('observation_reason')
        if (-not [string]::IsNullOrWhiteSpace($boundaryGeneration) -or
            -not [string]::IsNullOrWhiteSpace($observationReason)) {
            $decisionGeneration = Get-FallbackTailRecheckExactField `
                -Event $Decision `
                -Names @('recovery_boundary_generation')
            $decisionObservationReason = Get-FallbackTailRecheckExactField `
                -Event $Decision `
                -Names @('boundary_reason', 'recovery_boundary_reason')
            if ([string]::IsNullOrWhiteSpace($boundaryGeneration) -or
                [string]::IsNullOrWhiteSpace($observationReason) -or
                -not [string]::Equals(
                    $boundaryGeneration,
                    $decisionGeneration,
                    [System.StringComparison]::OrdinalIgnoreCase) -or
                -not [string]::Equals(
                    $observationReason,
                    $decisionObservationReason,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Test-FallbackTailRecheckPublishedDecisionMatch {
        param(
            [Parameter(Mandatory = $true)]$Requested,
            [Parameter(Mandatory = $true)]$Decided
        )

        if (-not (Test-FallbackTailRecheckEventComplete -Event $Requested -Kind Requested) -or
            -not (Test-FallbackTailRecheckEventComplete -Event $Decided -Kind Decided) -or
            -not (Test-FallbackTailRecheckRequestMatch `
                -Hold $Requested `
                -Decision $Decided `
                -DecisionKind Decided)) {
            return $false
        }

        foreach ($field in @(
                'recovered_transport_epoch',
                'handoff_kind',
                'boundary_source_transport',
                'boundary_target_transport',
                'fallback_epoch',
                'recovery_boundary_generation',
                'boundary_reason',
                'boundary_identity',
                'original_hold_reason',
                'recheck_generation')) {
            $requestedValue = Get-FallbackTailRecheckExactField -Event $Requested -Names @($field)
            $decidedValue = Get-FallbackTailRecheckExactField -Event $Decided -Names @($field)
            if ([string]::IsNullOrWhiteSpace($requestedValue) -or
                [string]::IsNullOrWhiteSpace($decidedValue) -or
                -not [string]::Equals(
                    $requestedValue,
                    $decidedValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return (Get-FileTransferEventField -Event $Decided -Name 'decision_valid' -Default '') -eq '1' -and
               (Get-FileTransferEventField -Event $Decided -Name 'decision_status' -Default '') -in @(
                   'Held',
                   'Granted',
                   'Rejected')
    }

    function Test-FallbackTailRecheckInvalidationEvent {
        param(
            [Parameter(Mandatory = $true)]$Anchor,
            [Parameter(Mandatory = $true)]$Requested,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if (-not (Test-FallbackTailRecheckIdentityMatch -Left $Anchor -Right $Candidate)) {
            return $false
        }

        $direction = Get-FallbackTailRecheckExactField -Event $Candidate -Names @('direction')
        if (-not [string]::IsNullOrWhiteSpace($direction) -and $direction -ne 'outbound') {
            return $false
        }

        if ($Candidate.EventName -in @(
                'file_transfer_inbound_terminal',
                'file_transfer_outbound_terminal',
                'transfer_terminal',
                'filetransfer_runtime_terminalized',
                'runtime_unlock_retry_dispatch_chain_closed')) {
            return $true
        }

        if ($Candidate.EventName -in @(
                'runtime_unlock_retry_dispatch_authority_granted',
                'runtime_unlock_retry_dispatch_authority_rejected')) {
            return $true
        }

        if ($Candidate.EventName -in @(
                'runtime_unlock_retry_dispatch_authority_held',
                'runtime_unlock_retry_dispatch_authority_hold_preserved')) {
            $requestOrdinalAliases = @(
                [pscustomobject]@{ Requested = @('contract_generation'); Candidate = @('contract_generation') },
                [pscustomobject]@{ Requested = @('retired_generation', 'retired_offer_generation'); Candidate = @('retired_generation', 'retired_offer_generation') },
                [pscustomobject]@{ Requested = @('dispatch_attempt_generation'); Candidate = @('dispatch_attempt_generation') },
                [pscustomobject]@{ Requested = @('missing_dispatch_successor_generation'); Candidate = @('missing_dispatch_successor_generation') })
            $completeOrdinalTuple = $true
            $ordinalMismatch = $false
            foreach ($aliases in $requestOrdinalAliases) {
                $requestedValue = Get-FallbackTailRecheckExactField -Event $Requested -Names $aliases.Requested
                $candidateValue = Get-FallbackTailRecheckExactField -Event $Candidate -Names $aliases.Candidate
                if ([string]::IsNullOrWhiteSpace($requestedValue) -or
                    [string]::IsNullOrWhiteSpace($candidateValue)) {
                    $completeOrdinalTuple = $false
                    break
                }
                if (-not [string]::Equals(
                        $requestedValue,
                        $candidateValue,
                        [System.StringComparison]::OrdinalIgnoreCase)) {
                    $ordinalMismatch = $true
                }
            }
            if ($completeOrdinalTuple -and $ordinalMismatch) {
                return $true
            }

            if (Test-FallbackTailRecheckEventComplete -Event $Candidate -Kind Hold) {
                return -not (Test-FallbackTailRecheckRequestMatch `
                    -Hold $Requested `
                    -Decision $Candidate `
                    -DecisionKind Hold)
            }

            return $false
        }

        $requestedContract = Get-FallbackTailRecheckExactField -Event $Requested -Names @('contract_generation')
        $candidateContract = Get-FallbackTailRecheckExactField -Event $Candidate -Names @('contract_generation')
        if ($Candidate.EventName -like 'session_recovery_contract_*') {
            if ($Candidate.EventName -in @(
                    'session_recovery_contract_completed',
                    'session_recovery_contract_failed')) {
                return $true
            }

            if (-not [string]::IsNullOrWhiteSpace($candidateContract) -and
                $candidateContract -ne $requestedContract) {
                return $true
            }
        }

        if ($Candidate.EventName -notin @(
                'filetransfer_route_transitioned',
                'filetransfer_route_selected',
                'filetransfer_live_route_epoch_started',
                'filetransfer_live_route_epoch_recovered',
                'filetransfer_runtime_started',
                'filetransfer_runtime_owner_changed',
                'filetransfer_bridge_recovery_authority_granted')) {
            return $false
        }

        $tupleAliases = @(
            [pscustomobject]@{ Requested = @('source_route'); Candidate = @('route', 'current_route') },
            [pscustomobject]@{ Requested = @('source_protocol_version'); Candidate = @('protocol_version', 'current_protocol_version') },
            [pscustomobject]@{ Requested = @('source_live_route_epoch'); Candidate = @('live_route_epoch', 'current_live_route_epoch') },
            [pscustomobject]@{ Requested = @('source_runtime_generation'); Candidate = @('runtime_generation', 'current_runtime_generation') },
            [pscustomobject]@{ Requested = @('source_terminal_generation'); Candidate = @('terminal_generation', 'current_terminal_generation') },
            [pscustomobject]@{ Requested = @('source_leg_generation'); Candidate = @('leg_generation', 'current_leg_generation') },
            [pscustomobject]@{ Requested = @('source_route_publication_generation'); Candidate = @('route_publication_generation', 'source_publication_generation') },
            [pscustomobject]@{ Requested = @('bridge_decision_generation'); Candidate = @('bridge_decision_generation') })
        foreach ($aliases in $tupleAliases) {
            $requestedValue = Get-FallbackTailRecheckExactField -Event $Requested -Names $aliases.Requested
            $candidateValue = Get-FallbackTailRecheckExactField -Event $Candidate -Names $aliases.Candidate
            if ([string]::IsNullOrWhiteSpace($candidateValue)) {
                continue
            }

            if ([string]::IsNullOrWhiteSpace($requestedValue) -or
                -not [string]::Equals(
                    $requestedValue,
                    $candidateValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $true
            }
        }

        return $false
    }

    function Test-FallbackTailRecheckAuthorityResultMatchesPublishedDecision {
        param(
            [Parameter(Mandatory = $true)]$Hold,
            [Parameter(Mandatory = $true)]$Boundary,
            [Parameter(Mandatory = $true)]$Candidate
        )

        $expectedStatus = if ($Candidate.EventName -eq 'runtime_unlock_retry_dispatch_authority_granted') {
            'Granted'
        }
        elseif ($Candidate.EventName -eq 'runtime_unlock_retry_dispatch_authority_rejected') {
            'Rejected'
        }
        else {
            return $false
        }

        $candidateSequence = [int64]$Candidate.Sequence
        foreach ($requested in @($recheckRequestedEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$Hold.Sequence -and
                    [int64]$_.Sequence -lt $candidateSequence -and
                    (Test-FallbackTailRecheckRequestMatch -Hold $Hold -Decision $_) -and
                    (Test-FallbackTailRecheckBoundaryMatch -Boundary $Boundary -Decision $_)
                })) {
            $decided = @($recheckDecidedEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$requested.Sequence -and
                    [int64]$_.Sequence -lt $candidateSequence -and
                    (Test-FallbackTailRecheckPublishedDecisionMatch -Requested $requested -Decided $_) -and
                    [string]::Equals(
                        (Get-FallbackTailRecheckExactField -Event $_ -Names @('decision_status')),
                        $expectedStatus,
                        [System.StringComparison]::OrdinalIgnoreCase)
                } | Sort-Object Sequence | Select-Object -First 1)
            if ($decided.Count -eq 0) {
                continue
            }

            $tupleMatches = $true
            foreach ($aliases in @(
                    [pscustomobject]@{ Requested = @('direction'); Candidate = @('direction') },
                    [pscustomobject]@{ Requested = @('contract_generation'); Candidate = @('contract_generation') },
                    [pscustomobject]@{ Requested = @('retired_generation', 'retired_offer_generation'); Candidate = @('retired_generation', 'retired_offer_generation') },
                    [pscustomobject]@{ Requested = @('dispatch_attempt_generation'); Candidate = @('dispatch_attempt_generation') },
                    [pscustomobject]@{ Requested = @('missing_dispatch_successor_generation'); Candidate = @('missing_dispatch_successor_generation') })) {
                $requestedValue = Get-FallbackTailRecheckExactField -Event $requested -Names $aliases.Requested
                $candidateValue = Get-FallbackTailRecheckExactField -Event $Candidate -Names $aliases.Candidate
                if ([string]::IsNullOrWhiteSpace($requestedValue) -or
                    [string]::IsNullOrWhiteSpace($candidateValue) -or
                    -not [string]::Equals(
                        $requestedValue,
                        $candidateValue,
                        [System.StringComparison]::OrdinalIgnoreCase)) {
                    $tupleMatches = $false
                    break
                }
            }
            if ($tupleMatches) {
                return $true
            }
        }

        return $false
    }

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $recoveredCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $seenCandidateKeys = @{}

    foreach ($boundary in $tailUnblockedEvents) {
        $boundarySequence = [int64]$boundary.Sequence
        $matchingHolds = @($heldEvents | Where-Object {
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FallbackTailRecheckIdentityMatch -Left $_ -Right $boundary) -and
            (Test-FallbackTailRecheckHoldEligible -Event $_) -and
            (Get-FallbackTailRecheckExactField -Event $_ -Names @('direction', 'attempted_source_publication_direction')) -eq 'outbound' -and
            (Get-FallbackTailRecheckExactField -Event $_ -Names @('source_route', 'source_publication_route', 'attempted_source_publication_route', 'route')) -eq 'post_tuna_fallback_v6' -and
            (Get-FallbackTailRecheckExactField -Event $_ -Names @('source_protocol_version', 'source_publication_protocol_version', 'attempted_source_publication_protocol_version', 'protocol_version')) -eq '6'
        } | Sort-Object Sequence -Descending)
        if ($matchingHolds.Count -eq 0) {
            continue
        }

        $hold = $matchingHolds[0]
        $holdSequence = [int64]$hold.Sequence
        $pairedYield = @($pairedYieldEvents | Where-Object {
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FallbackTailRecheckIdentityMatch -Left $_ -Right $boundary)
        } | Sort-Object Sequence -Descending | Select-Object -First 1)
        if ($pairedYield.Count -eq 0) {
            continue
        }

        $holdRoute = Get-FallbackTailRecheckField `
            -Event $hold `
            -Names @('source_route', 'source_publication_route', 'attempted_source_publication_route', 'route')
        $holdProtocol = Get-FallbackTailRecheckField `
            -Event $hold `
            -Names @('source_protocol_version', 'source_publication_protocol_version', 'attempted_source_publication_protocol_version', 'protocol_version')
        $holdDirection = Get-FallbackTailRecheckField `
            -Event $hold `
            -Names @('direction', 'attempted_source_publication_direction')
        if ($holdRoute -ne 'post_tuna_fallback_v6' -or
            $holdProtocol -ne '6' -or
            $holdDirection -ne 'outbound') {
            continue
        }

        $ownerTupleMatches = $true
        foreach ($aliases in @(
                [pscustomobject]@{ Hold = @('source_live_route_epoch', 'source_publication_live_route_epoch', 'attempted_source_publication_live_route_epoch', 'live_route_epoch'); Paired = @('live_route_epoch') },
                [pscustomobject]@{ Hold = @('source_runtime_generation', 'source_publication_runtime_generation', 'attempted_source_publication_runtime_generation', 'runtime_generation'); Paired = @('runtime_generation') },
                [pscustomobject]@{ Hold = @('source_terminal_generation', 'source_publication_terminal_generation', 'attempted_source_publication_terminal_generation', 'terminal_generation'); Paired = @('terminal_generation') },
                [pscustomobject]@{ Hold = @('source_leg_generation', 'source_publication_leg_generation', 'attempted_source_publication_leg_generation', 'leg_generation'); Paired = @('leg_generation') })) {
            $holdValue = Get-FallbackTailRecheckField -Event $hold -Names $aliases.Hold
            $pairedValue = Get-FallbackTailRecheckField -Event $pairedYield[0] -Names $aliases.Paired
            if ([string]::IsNullOrWhiteSpace($holdValue) -or
                [string]::IsNullOrWhiteSpace($pairedValue) -or
                $holdValue -ne $pairedValue) {
                $ownerTupleMatches = $false
                break
            }
        }
        if (-not $ownerTupleMatches) {
            continue
        }

        $invalidatedBeforeBoundary = @($Events | Where-Object {
            if ([int64]$_.Sequence -le $holdSequence -or
                [int64]$_.Sequence -ge $boundarySequence -or
                -not (Test-FallbackTailRecheckInvalidationEvent `
                    -Anchor $hold `
                    -Requested $hold `
                    -Candidate $_)) {
                return $false
            }

            return -not (Test-FallbackTailRecheckAuthorityResultMatchesPublishedDecision `
                -Hold $hold `
                -Boundary $boundary `
                -Candidate $_)
        } | Select-Object -First 1).Count -gt 0
        if ($invalidatedBeforeBoundary) {
            continue
        }

        $rawCandidates.Add($boundary) | Out-Null
        $requestKeyParts = @(
            Get-FallbackTailRecheckField -Event $hold -Names @('session_id') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $hold -Names @('transfer_id') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $hold -Names @('direction', 'attempted_source_publication_direction') -Default 'outbound'
            Get-FallbackTailRecheckField -Event $hold -Names @('contract_generation') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $hold -Names @('retired_generation') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $hold -Names @('dispatch_attempt_generation') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $hold -Names @('missing_dispatch_successor_generation') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $hold -Names @('predecessor_authority_id') -Default '(none)'
            Get-FallbackTailRecheckField -Event $hold -Names @('source_route_publication_generation', 'source_publication_generation', 'attempted_source_publication_route_publication_generation') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $boundary -Names @('transport_epoch') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $boundary -Names @('handoff_kind') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $boundary -Names @('source_transport') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $boundary -Names @('target_transport') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $boundary -Names @('recovery_boundary_generation') -Default '(legacy)'
            Get-FallbackTailRecheckField -Event $boundary -Names @('observation_reason') -Default '(legacy)'
        )
        $candidateKey = $requestKeyParts -join '|'
        if ($seenCandidateKeys.ContainsKey($candidateKey)) {
            continue
        }

        $seenCandidateKeys[$candidateKey] = $true
        $distinctCandidates.Add($boundary) | Out-Null
        $firstBoundaryInvalidation = @($Events | Where-Object {
            [int64]$_.Sequence -gt $boundarySequence -and
            (Test-FallbackTailRecheckInvalidationEvent `
                -Anchor $hold `
                -Requested $hold `
                -Candidate $_)
        } | Sort-Object Sequence | Select-Object -First 1)
        $boundaryInvalidationSequence = if ($firstBoundaryInvalidation.Count -gt 0) {
            [int64]$firstBoundaryInvalidation[0].Sequence
        }
        else {
            [int64]::MaxValue
        }
        $matchingRequested = @($recheckRequestedEvents | Where-Object {
            [int64]$_.Sequence -gt $holdSequence -and
            [int64]$_.Sequence -lt $boundaryInvalidationSequence -and
            (Test-FallbackTailRecheckRequestMatch -Hold $hold -Decision $_) -and
            (Test-FallbackTailRecheckBoundaryMatch -Boundary $boundary -Decision $_)
        } | Sort-Object Sequence | Select-Object -First 1)
        $matchingDecision = @()
        if ($matchingRequested.Count -gt 0) {
            $requested = $matchingRequested[0]
            $requestedSequence = [int64]$requested.Sequence
            $firstInvalidation = @($Events | Where-Object {
                [int64]$_.Sequence -gt $requestedSequence -and
                (Test-FallbackTailRecheckInvalidationEvent `
                    -Anchor $hold `
                    -Requested $requested `
                    -Candidate $_)
            } | Sort-Object Sequence | Select-Object -First 1)
            $invalidationSequence = if ($firstInvalidation.Count -gt 0) {
                [int64]$firstInvalidation[0].Sequence
            }
            else {
                [int64]::MaxValue
            }
            $matchingDecision = @($recheckDecidedEvents | Where-Object {
                [int64]$_.Sequence -gt $requestedSequence -and
                [int64]$_.Sequence -lt $invalidationSequence -and
                (Test-FallbackTailRecheckPublishedDecisionMatch `
                    -Requested $requested `
                    -Decided $_)
            } | Sort-Object Sequence | Select-Object -First 1)
            if ($Phase2ProtocolObserved -and
                $matchingDecision.Count -gt 0 -and
                (Get-FallbackTailRecheckExactField `
                    -Event $matchingDecision[0] `
                    -Names @('decision_status')) -eq 'Granted') {
                $matchingCommittedGrant = @($EffectiveGrantEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$matchingDecision[0].Sequence -and
                    (Test-FallbackTailRecheckAuthorityResultMatchesPublishedDecision `
                        -Hold $hold `
                        -Boundary $boundary `
                        -Candidate $_)
                } | Sort-Object Sequence | Select-Object -First 1)
                if ($matchingCommittedGrant.Count -eq 0) {
                    $matchingDecision = @()
                }
            }
        }
        if ($matchingDecision.Count -gt 0) {
            $recoveredCandidates.Add($boundary) | Out-Null
        }
        else {
            $unresolvedCandidates.Add($boundary) | Out-Null
        }
    }

    $verdict = if ($distinctCandidates.Count -eq 0) {
        'none'
    }
    elseif ($unresolvedCandidates.Count -eq 0) {
        'pass'
    }
    else {
        'fail'
    }

    return [pscustomobject]@{
        RequestedCount = $recheckRequestedEvents.Count
        DecidedCount = $recheckDecidedEvents.Count
        DiscardedCount = $recheckDiscardedEvents.Count
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = $recoveredCandidates.Count
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = $verdict
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @($recoveredCandidates.ToArray())
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
    }
}

function Get-FileTransferRegularV4RepairProjectionRange {
    param([Parameter(Mandatory = $true)]$Event)

    $startText = ''
    foreach ($name in @(
            'projected_first_start_chunk_index',
            'projected_start_chunk_index',
            'first_start_chunk_index',
            'start_chunk_index',
            'frontier_chunk_index',
            'contiguous_committed_chunk_index')) {
        $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
        if ($value -match '^\d+$') {
            $startText = $value
            break
        }
    }

    $endText = ''
    foreach ($name in @(
            'projected_last_end_chunk_exclusive',
            'projected_end_chunk_exclusive',
            'last_end_chunk_exclusive',
            'end_chunk_exclusive')) {
        $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
        if ($value -match '^\d+$') {
            $endText = $value
            break
        }
    }

    $rangesText = ''
    foreach ($name in @(
            'projected_ranges',
            'repair_projection_projected_ranges',
            'source_ranges',
            'repair_projection_source_ranges')) {
        $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
        if (-not [string]::IsNullOrWhiteSpace($value) -and $value -notin @('(none)', 'none')) {
            $rangesText = $value
            break
        }
    }
    $parsedRanges = New-Object System.Collections.Generic.List[object]
    if (-not [string]::IsNullOrWhiteSpace($rangesText)) {
        $rangeStart = [int64]::MaxValue
        $rangeEnd = -1L
        foreach ($rangeToken in @($rangesText -split ',')) {
            if ($rangeToken.Trim() -notmatch '^(?<start>\d+):(?<count>\d+)$') {
                continue
            }
            $tokenStart = [int64]$Matches['start']
            $tokenCount = [int64]$Matches['count']
            if ($tokenCount -le 0) {
                continue
            }
            $parsedRanges.Add([pscustomobject]@{
                    Valid = $true
                    Start = $tokenStart
                    End = $tokenStart + $tokenCount
                }) | Out-Null
            if ($tokenStart -lt $rangeStart) {
                $rangeStart = $tokenStart
            }
            if (($tokenStart + $tokenCount) -gt $rangeEnd) {
                $rangeEnd = $tokenStart + $tokenCount
            }
        }
        if ($rangeStart -ne [int64]::MaxValue -and $rangeEnd -gt $rangeStart) {
            $startText = [string]$rangeStart
            $endText = [string]$rangeEnd
        }
    }

    $repairKey = ''
    foreach ($name in @(
            'projected_repair_request_key',
            'repair_projection_projected_key',
            'source_repair_request_key',
            'repair_projection_source_key',
            'repair_request_key')) {
        $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
        if (-not [string]::IsNullOrWhiteSpace($value) -and $value -notin @('(none)', 'none')) {
            $repairKey = $value
            break
        }
    }
    if ($startText -notmatch '^\d+$' -or $endText -notmatch '^\d+$') {
        [object[]]$keyParts = @($repairKey -split ':')
        if ($keyParts.Count -ge 4) {
            $keyStartText = [string]$keyParts[$keyParts.Count - 4]
            $keyCountText = [string]$keyParts[$keyParts.Count - 3]
            $keyFrontierText = [string]$keyParts[$keyParts.Count - 2]
            $keyHighestText = [string]$keyParts[$keyParts.Count - 1]
            if ($keyStartText -match '^\d+$' -and
                $keyCountText -match '^\d+$' -and
                $keyFrontierText -match '^\d+$' -and
                $keyHighestText -match '^-?\d+$') {
                $keyStart = [int64]$keyStartText
                $keyCount = [int64]$keyCountText
                if ($startText -notmatch '^\d+$') {
                    $startText = [string]$keyStart
                }
                if ($endText -notmatch '^\d+$') {
                    $endText = [string]($keyStart + $keyCount)
                }
            }
        }
    }

    if ($startText -match '^\d+$' -and $endText -notmatch '^\d+$') {
        foreach ($name in @('projected_chunk_count', 'projected_requested_chunk_count', 'requested_chunk_count', 'pending_repair_count')) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if ($value -match '^\d+$' -and [int64]$value -gt 0) {
                $endText = [string]([int64]$startText + [int64]$value)
                break
            }
        }
    }

    $valid = $startText -match '^\d+$' -and
        $endText -match '^\d+$' -and
        [int64]$endText -gt [int64]$startText
    [object[]]$exactRanges = if ($parsedRanges.Count -gt 0) {
        @($parsedRanges.ToArray() | ForEach-Object {
                [pscustomobject]@{
                    Valid = $true
                    Start = [int64]$_.Start
                    End = [int64]$_.End
                    RepairKey = if ([string]::IsNullOrWhiteSpace($repairKey)) { '(none)' } else { $repairKey }
                }
            })
    }
    elseif ($valid) {
        @([pscustomobject]@{
                Valid = $true
                Start = [int64]$startText
                End = [int64]$endText
                RepairKey = if ([string]::IsNullOrWhiteSpace($repairKey)) { '(none)' } else { $repairKey }
            })
    }
    else {
        @()
    }
    return [pscustomobject]@{
        Valid = $valid
        Start = if ($startText -match '^\d+$') { [int64]$startText } else { -1L }
        End = if ($endText -match '^\d+$') { [int64]$endText } else { -1L }
        RepairKey = if ([string]::IsNullOrWhiteSpace($repairKey)) { '(none)' } else { $repairKey }
        Ranges = $exactRanges
    }
}

function Get-FileTransferRegularV4RepairProjectionScopeField {
    param(
        [Parameter(Mandatory = $true)]$Event,
        [Parameter(Mandatory = $true)][string]$Name,
        [string]$Default = ''
    )

    [string[]]$names = switch ($Name) {
        'data_session_generation' { @('data_session_generation', 'repair_projection_data_session_generation') }
        'authority_id' { @('authority_id', 'repair_projection_authority_id') }
        'predecessor_authority_id' { @('predecessor_authority_id', 'repair_projection_predecessor_authority_id') }
        default { @($Name) }
    }
    foreach ($candidateName in $names) {
        $value = Get-FileTransferEventField -Event $Event -Name $candidateName -Default ''
        if (-not [string]::IsNullOrWhiteSpace($value) -and $value -notin @('(none)', 'none')) {
            return $value
        }
    }
    return $Default
}

function Test-FileTransferRegularV4RepairProjectionScopeMatch {
    param(
        [Parameter(Mandatory = $true)]$Anchor,
        [Parameter(Mandatory = $true)]$Candidate
    )

    if (-not (Test-FileTransferRegularV4RepairProjectionTransferMatch -Anchor $Anchor -Candidate $Candidate)) {
        return $false
    }
    foreach ($name in @(
            'route',
            'protocol_version',
            'live_route_epoch',
            'runtime_generation',
            'terminal_generation',
            'leg_generation',
            'transport_epoch',
            'bridge_recovery_generation',
            'bridge_decision_generation',
            'route_publication_generation',
            'route_commit_generation',
            'data_session_generation')) {
        $left = Get-FileTransferRegularV4RepairProjectionScopeField -Event $Anchor -Name $name
        $right = Get-FileTransferRegularV4RepairProjectionScopeField -Event $Candidate -Name $name
        if (-not [string]::IsNullOrWhiteSpace($left) -and
            -not [string]::IsNullOrWhiteSpace($right) -and
            -not [string]::Equals($left, $right, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }
    return $true
}

function Get-FileTransferRegularV4RepairProjectionScopeKey {
    param(
        [Parameter(Mandatory = $true)]$Event,
        [int64]$Frontier = -1L
    )

    $direction = Get-FileTransferEventField -Event $Event -Name 'direction' -Default 'inbound'
    if ($direction -in @('', 'receiver')) {
        $direction = 'inbound'
    }
    $parts = @(
        (Get-FileTransferEventField -Event $Event -Name 'session_id' -Default '(none)'),
        (Get-FileTransferEventField -Event $Event -Name 'transfer_id' -Default '(none)'),
        $direction,
        [string]$Frontier,
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'route' -Default 'regular_nkn_v4_fast'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'protocol_version' -Default '4'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'live_route_epoch' -Default '0'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'runtime_generation' -Default '0'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'terminal_generation' -Default '0'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'leg_generation' -Default '0'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'transport_epoch' -Default '0'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'bridge_recovery_generation' -Default '0'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'bridge_decision_generation' -Default '0'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'route_publication_generation' -Default '0'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'route_commit_generation' -Default '0'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'data_session_generation' -Default '0')
    )
    return ($parts -join '|').ToLowerInvariant()
}

