function Get-FileTransferRegularV4RepairProjectionReauthorizationProof {
    param([AllowEmptyCollection()][object[]]$Events = @())

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$invalidationEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_projection_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'coordinator_action_BridgeReceiveStallRecovery' -and
        -not [string]::IsNullOrWhiteSpace(
            (Get-FileTransferRegularV4RepairProjectionScopeField -Event $_ -Name 'authority_id'))
    })
    [object[]]$bridgeAuthorityEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_bridge_recovery_authority_granted' -and
        (Get-FileTransferEventField -Event $_ -Name 'action_kind' -Default '') -eq 'BridgeReceiveStallRecovery'
    })
    [object[]]$lifecycleDecisionEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lifecycle_decided' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @('Accepted', 'Idempotent') -and
        (Get-FileTransferEventField -Event $_ -Name 'lifecycle_outcome' -Default '') -in @('Completed', 'ReceiveProofObserved')
    })
    [object[]]$closureEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_retained' -and
        (Get-FileTransferEventField -Event $_ -Name 'lifecycle_decision_status' -Default '') -in @('Accepted', 'Idempotent') -and
        (Get-FileTransferEventField -Event $_ -Name 'lifecycle_outcome' -Default '') -in @('Completed', 'ReceiveProofObserved')
    })
    [object[]]$resumeEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_transport_resumed'
    })
    [object[]]$rejectionEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_projection_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'fresh_projection_required_before_unrestricted_state'
    })
    [object[]]$projectionRetainedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_projection_retained'
    })
    [object[]]$projectionPublishedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_projection_published'
    })

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $recoveredCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $metadataBySequence = @{}
    $seenTuples = @{}

    foreach ($invalidation in $invalidationEvents) {
        $invalidationSequence = [int64]$invalidation.Sequence
        $range = Get-FileTransferRegularV4RepairProjectionRange -Event $invalidation
        $frontier = Get-FileTransferEventInt64Field -Event $invalidation -Name 'frontier_chunk_index' -Default -1
        $durableHighest = Get-FileTransferEventInt64Field -Event $invalidation -Name 'durable_received_highest_chunk_index' -Default -1
        if (-not $range.Valid -or $frontier -lt 0 -or $durableHighest -le $frontier) {
            continue
        }

        $oldBridgeDecisionGeneration = Get-FileTransferRegularV4RepairProjectionScopeField `
            -Event $invalidation `
            -Name 'bridge_decision_generation' `
            -Default '0'
        $bridgeAuthority = @($bridgeAuthorityEvents | Where-Object {
            [int64]$_.Sequence -gt $invalidationSequence -and
            (Test-FileTransferRegularV4RepairProjectionReauthorizationBaseScopeMatch `
                -Anchor $invalidation `
                -Candidate $_) -and
            (Get-FileTransferEventField -Event $_ -Name 'bridge_decision_generation' -Default '0') -ne
                $oldBridgeDecisionGeneration
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($bridgeAuthority.Count -eq 0) {
            continue
        }
        $bridgeAuthority = $bridgeAuthority[0]
        $currentBridgeDecisionGeneration = Get-FileTransferEventField `
            -Event $bridgeAuthority `
            -Name 'bridge_decision_generation' `
            -Default '0'

        $lifecycleDecision = @($lifecycleDecisionEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$bridgeAuthority.Sequence -and
            (Test-FileTransferRegularV4RepairProjectionReauthorizationBaseScopeMatch `
                -Anchor $bridgeAuthority `
                -Candidate $_) -and
            (Get-FileTransferEventField -Event $_ -Name 'bridge_decision_generation' -Default '0') -eq
                $currentBridgeDecisionGeneration
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($lifecycleDecision.Count -eq 0) {
            continue
        }
        $lifecycleDecision = $lifecycleDecision[0]

        $closure = @($closureEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$lifecycleDecision.Sequence -and
            (Test-FileTransferRegularV4RepairProjectionReauthorizationBaseScopeMatch `
                -Anchor $bridgeAuthority `
                -Candidate $_) -and
            (Get-FileTransferEventField -Event $_ -Name 'bridge_decision_generation' -Default '0') -eq
                $currentBridgeDecisionGeneration
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($closure.Count -eq 0) {
            continue
        }
        $closure = $closure[0]

        $resume = @($resumeEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$closure.Sequence -and
            (Test-FileTransferRegularV4RepairProjectionReauthorizationBaseScopeMatch `
                -Anchor $invalidation `
                -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($resume.Count -eq 0) {
            continue
        }
        $resume = $resume[0]

        [object[]]$matchingRejections = @($rejectionEvents | Where-Object {
            $candidateBridgeDecisionGeneration =
                Get-FileTransferRegularV4RepairProjectionScopeField `
                    -Event $_ `
                    -Name 'bridge_decision_generation'
            [int64]$_.Sequence -gt [int64]$resume.Sequence -and
            (Test-FileTransferRegularV4RepairProjectionReauthorizationBaseScopeMatch `
                -Anchor $invalidation `
                -Candidate $_) -and
            ([string]::IsNullOrWhiteSpace($candidateBridgeDecisionGeneration) -or
                $candidateBridgeDecisionGeneration -eq $currentBridgeDecisionGeneration) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'frontier_chunk_index' -Default -1) -eq $frontier -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'durable_received_highest_chunk_index' -Default -1) -gt $frontier
        } | Sort-Object Sequence, LineNumber)
        if ($matchingRejections.Count -eq 0) {
            continue
        }

        foreach ($candidate in $matchingRejections) {
            $rawCandidates.Add($candidate) | Out-Null
        }

        $authorityId = Get-FileTransferRegularV4RepairProjectionScopeField `
            -Event $invalidation `
            -Name 'authority_id' `
            -Default '(none)'
        $rangeText = Get-FileTransferEventField -Event $invalidation -Name 'projected_ranges' -Default '(none)'
        $tuple = (@(
                (Get-FileTransferEventField -Event $invalidation -Name 'session_id' -Default '(none)'),
                (Get-FileTransferEventField -Event $invalidation -Name 'transfer_id' -Default '(none)'),
                (Get-FileTransferEventField -Event $invalidation -Name 'direction' -Default '(none)'),
                $frontier,
                $authorityId,
                $rangeText,
                $currentBridgeDecisionGeneration,
                (Get-FileTransferEventField -Event $closure -Name 'regular_v4_liveness_generation' -Default '0'),
                (Get-FileTransferRegularV4RepairProjectionScopeKey -Event $invalidation -Frontier $frontier)
            ) -join '|').ToLowerInvariant()
        if ($seenTuples.ContainsKey($tuple)) {
            continue
        }
        $seenTuples[$tuple] = $true
        $firstCandidate = $matchingRejections[0]
        $distinctCandidates.Add($firstCandidate) | Out-Null
        $metadataBySequence[[string][int64]$firstCandidate.Sequence] = [pscustomobject]@{
            Invalidation = $invalidation
            BridgeAuthority = $bridgeAuthority
            Closure = $closure
            Frontier = $frontier
            Range = $range
            CurrentBridgeDecisionGeneration = $currentBridgeDecisionGeneration
        }
    }

    foreach ($candidate in $distinctCandidates.ToArray()) {
        $metadata = $metadataBySequence[[string][int64]$candidate.Sequence]
        $candidateSequence = [int64]$candidate.Sequence
        $frontier = [int64]$metadata.Frontier
        $scopeAnchor = $metadata.Invalidation

        $durableResolution = @($orderedEvents | Where-Object {
            [int64]$_.Sequence -gt $candidateSequence -and
            (Test-FileTransferRegularV4RepairProjectionReauthorizationBaseScopeMatch `
                -Anchor $scopeAnchor `
                -Candidate $_) -and
            (
                ($_.EventName -eq 'filetransfer_v4_state_sent' -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'contiguous_committed_chunk_index' -Default -1) -gt $frontier) -or
                ($_.EventName -eq 'filetransfer_regular_v4_frontier_repair_progress_observed' -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'committed_frontier_after' -Default -1) -gt $frontier) -or
                ($_.EventName -eq 'filetransfer_regular_v4_frontier_repair_projection_cleared' -and
                    (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -in @(
                        'frontier_advanced', 'frontier_advanced_gap_resolved', 'frontier_complete',
                        'range_filled', 'durable_fill', 'repair_filled'))
            )
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)

        $freshProjection = @($projectionRetainedEvents | Where-Object {
            [int64]$_.Sequence -gt $candidateSequence -and
            (Test-FileTransferRegularV4RepairProjectionReauthorizationBaseScopeMatch `
                -Anchor $scopeAnchor `
                -Candidate $_) -and
            (Get-FileTransferRegularV4RepairProjectionScopeField -Event $_ -Name 'bridge_decision_generation' -Default '0') -eq
                [string]$metadata.CurrentBridgeDecisionGeneration -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
                'coordinator_recovery_projection_reauthorized' -and
            @((Get-FileTransferRegularV4RepairProjectionRange -Event $_).Ranges | Where-Object {
                $_.Start -eq [int64]$metadata.Range.Start -and $_.End -eq [int64]$metadata.Range.End
            }).Count -gt 0
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)

        $dispatchResolution = @()
        if ($freshProjection.Count -gt 0) {
            $freshProjection = $freshProjection[0]
            $freshAuthorityId = Get-FileTransferRegularV4RepairProjectionScopeField `
                -Event $freshProjection `
                -Name 'authority_id'
            $published = @($projectionPublishedEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$freshProjection.Sequence -and
                (Get-FileTransferRegularV4RepairProjectionScopeField -Event $_ -Name 'authority_id') -eq $freshAuthorityId -and
                @((Get-FileTransferRegularV4RepairProjectionRange -Event $_).Ranges | Where-Object {
                    $_.Start -eq [int64]$metadata.Range.Start -and $_.End -eq [int64]$metadata.Range.End
                }).Count -gt 0
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            if ($published.Count -gt 0) {
                $stateSent = @($orderedEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$published[0].Sequence -and
                    $_.EventName -eq 'filetransfer_v4_state_sent' -and
                    (Get-FileTransferRegularV4RepairProjectionScopeField -Event $_ -Name 'authority_id') -eq $freshAuthorityId -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'missing_range_count' -Default 0) -gt 0
                } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                if ($stateSent.Count -gt 0) {
                    $stateEpoch = Get-FileTransferEventField -Event $stateSent[0] -Name 'epoch' -Default ''
                        $stateReceived = @($orderedEvents | Where-Object {
                            [int64]$_.Sequence -gt [int64]$stateSent[0].Sequence -and
                            $_.EventName -eq 'filetransfer_v4_state_received' -and
                        (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '') -eq
                            (Get-FileTransferEventField -Event $stateSent[0] -Name 'session_id' -Default '') -and
                        (Get-FileTransferEventField -Event $_ -Name 'transfer_id' -Default '') -eq
                            (Get-FileTransferEventField -Event $stateSent[0] -Name 'transfer_id' -Default '') -and
                            (Get-FileTransferEventField -Event $_ -Name 'epoch' -Default '') -eq $stateEpoch -and
                            (Get-FileTransferEventField -Event $_ -Name 'applied' -Default '0') -eq '1' -and
                            (Get-FileTransferEventInt64Field -Event $_ -Name 'missing_range_count' -Default 0) -gt 0 -and
                            @((Get-FileTransferRegularV4RepairProjectionRange -Event $_).Ranges | Where-Object {
                                $_.Start -eq [int64]$metadata.Range.Start -and $_.End -eq [int64]$metadata.Range.End
                            }).Count -gt 0
                    } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                    if ($stateReceived.Count -gt 0) {
                        $freshRepairKey = Get-FileTransferEventField `
                            -Event $freshProjection `
                            -Name 'projected_repair_request_key' `
                            -Default ''
                        $peerAuthority = @($orderedEvents | Where-Object {
                            [int64]$_.Sequence -gt [int64]$stateReceived[0].Sequence -and
                            $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_authority_granted' -and
                            (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
                            (Test-FileTransferRegularV4RepairProjectionScopeMatch `
                                -Anchor $stateReceived[0] `
                                -Candidate $_) -and
                            -not [string]::IsNullOrWhiteSpace($freshRepairKey) -and
                            (Get-FileTransferEventField -Event $_ -Name 'repair_request_key' -Default '') -eq
                                $freshRepairKey -and
                            @((Get-FileTransferRegularV4RepairProjectionRange -Event $_).Ranges | Where-Object {
                                $_.Start -eq [int64]$metadata.Range.Start -and $_.End -eq [int64]$metadata.Range.End
                            }).Count -gt 0
                        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                        if ($peerAuthority.Count -gt 0) {
                            $peerAuthorityId = Get-FileTransferRegularV4RepairProjectionScopeField `
                                -Event $peerAuthority[0] `
                                -Name 'authority_id'
                            $dispatchResolution = @($orderedEvents | Where-Object {
                                [int64]$_.Sequence -gt [int64]$peerAuthority[0].Sequence -and
                                $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_dispatched' -and
                                (Get-FileTransferRegularV4RepairProjectionScopeField -Event $_ -Name 'authority_id') -eq $peerAuthorityId -and
                                (Test-FileTransferRegularV4RepairProjectionScopeMatch `
                                    -Anchor $peerAuthority[0] `
                                    -Candidate $_) -and
                                (Get-FileTransferEventField -Event $_ -Name 'repair_request_key' -Default '') -eq
                                    $freshRepairKey -and
                                @((Get-FileTransferRegularV4RepairProjectionRange -Event $_).Ranges | Where-Object {
                                    $_.Start -eq [int64]$metadata.Range.Start -and $_.End -eq [int64]$metadata.Range.End
                                }).Count -gt 0
                            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                        }
                    }
                }
            }
        }

        if ($durableResolution.Count -gt 0 -or $dispatchResolution.Count -gt 0) {
            $recoveredCandidates.Add($candidate) | Out-Null
        }
        else {
            $unresolvedCandidates.Add($candidate) | Out-Null
        }
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = $recoveredCandidates.Count
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = if ($unresolvedCandidates.Count -gt 0) { 'fail' } elseif ($distinctCandidates.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @($recoveredCandidates.ToArray())
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
    }
}

function Get-FileTransferRegularV4MissingRangePreservationProof {
    param([AllowEmptyCollection()][object[]]$Events = @())

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    $authorityByFrontier = @{}
    $activeByScope = @{}
    $projectionEpochToScope = @{}
    $appliedProjectionScopes = @{}
    $peerAuthorityEvents = New-Object System.Collections.Generic.List[object]
    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $recoveredCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $recoveredCandidateSequences = @{}
    $seenCandidateLogicalTuples = @{}
    $candidateMetadataBySequence = @{}

    foreach ($event in $orderedEvents) {
        $eventName = [string]$event.EventName
        $sequence = [int64]$event.Sequence

        if ($eventName -in @(
                'transfer_terminal',
                'file_transfer_inbound_terminal',
                'file_transfer_outbound_terminal',
                'filetransfer_runtime_terminalized',
                'filetransfer_manifest_received',
                'filetransfer_manifest_replaced',
                'filetransfer_session_replaced',
                'filetransfer_data_session_recreated',
                'filetransfer_route_selected',
                'filetransfer_route_transitioned',
                'filetransfer_live_route_epoch_started',
                'filetransfer_runtime_started',
                'filetransfer_runtime_owner_changed')) {
            $isUnconditionalBoundary = $eventName -in @(
                'transfer_terminal',
                'file_transfer_inbound_terminal',
                'file_transfer_outbound_terminal',
                'filetransfer_runtime_terminalized',
                'filetransfer_manifest_received',
                'filetransfer_manifest_replaced',
                'filetransfer_session_replaced',
                'filetransfer_data_session_recreated')
            foreach ($scopeKey in @($activeByScope.Keys)) {
                $projection = $activeByScope[$scopeKey]
                if (-not (Test-FileTransferRegularV4RepairProjectionTransferMatch -Anchor $projection.Anchor -Candidate $event)) {
                    continue
                }
                if ($isUnconditionalBoundary -or
                    (Test-FileTransferRegularV4RepairProjectionScopeReplacement `
                        -Anchor $projection.ScopeAnchor `
                        -Candidate $event)) {
                    $activeByScope.Remove($scopeKey)
                }
            }
            continue
        }

        if ($eventName -eq 'filetransfer_regular_v4_frontier_repair_authority_granted') {
            $direction = Get-FileTransferEventField -Event $event -Name 'direction' -Default ''
            $route = Get-FileTransferEventField -Event $event -Name 'route' -Default 'regular_nkn_v4_fast'
            $protocol = Get-FileTransferEventField -Event $event -Name 'protocol_version' -Default '4'
            if ($direction -eq 'outbound' -and $route -eq 'regular_nkn_v4_fast' -and $protocol -eq '4') {
                $peerAuthorityEvents.Add($event) | Out-Null
            }
            elseif ($direction -eq 'inbound' -and $route -eq 'regular_nkn_v4_fast' -and $protocol -eq '4') {
                $rangeInfo = Get-FileTransferRegularV4RepairProjectionRange -Event $event
                foreach ($range in @($rangeInfo.Ranges)) {
                    $authorityKey = Get-FileTransferRegularV4RepairProjectionScopeKey -Event $event -Frontier $range.Start
                    $authorityByFrontier[$authorityKey] = $event
                }
            }
            continue
        }

        if ($eventName -in @(
                'filetransfer_v4_repair_requested',
                'filetransfer_v4_repair_suppressed',
                'filetransfer_regular_v4_frontier_repair_projection_retained',
                'filetransfer_regular_v4_frontier_repair_projection_published')) {
            $rangeInfo = Get-FileTransferRegularV4RepairProjectionRange -Event $event
            if (-not $rangeInfo.Valid) {
                continue
            }

            foreach ($range in @($rangeInfo.Ranges)) {
            $scopeKey = Get-FileTransferRegularV4RepairProjectionScopeKey -Event $event -Frontier $range.Start
            $existingScope = @($activeByScope.Values | Where-Object {
                [int64]$_.Start -eq $range.Start -and
                (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $_.ScopeAnchor -Candidate $event)
            } | Sort-Object @{ Expression = { [int64]$_.LastEvidence.Sequence } } | Select-Object -Last 1)
            if ($existingScope.Count -gt 0) {
                $scopeKey = [string]$existingScope[0].ScopeKey
            }
            $matchingAuthority = $null
            if ($authorityByFrontier.ContainsKey($scopeKey)) {
                $matchingAuthority = $authorityByFrontier[$scopeKey]
            }
            else {
                $matchingAuthority = @($authorityByFrontier.Values | Where-Object {
                    [int64]$_.Sequence -lt $sequence -and
                    (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $_ -Candidate $event) -and
                    @((Get-FileTransferRegularV4RepairProjectionRange -Event $_).Ranges | Where-Object {
                            $null -ne $_ -and $_.Start -eq $range.Start
                        }).Count -gt 0
                } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
                if ($matchingAuthority.Count -gt 0) {
                    $matchingAuthority = $matchingAuthority[0]
                }
                else {
                    $matchingAuthority = $null
                }
            }

            $sourceAuthorityId = Get-FileTransferEventField -Event $event -Name 'authority_id' -Default ''
            $hasEmbeddedAuthority = -not [string]::IsNullOrWhiteSpace($sourceAuthorityId) -and
                $sourceAuthorityId -notin @('(none)', 'none')
            if ($null -eq $matchingAuthority -and -not $hasEmbeddedAuthority) {
                continue
            }

            if ($activeByScope.ContainsKey($scopeKey)) {
                $projection = $activeByScope[$scopeKey]
                if ($range.Start -eq [int64]$projection.Start -and $range.End -le [int64]$projection.SourceEnd) {
                    $projection.End = $range.End
                    $projection.RepairKey = $range.RepairKey
                    $projection.LastEvidence = $event
                }
            }
            else {
                $matchingAuthorityRange = @(if ($null -ne $matchingAuthority) {
                    (Get-FileTransferRegularV4RepairProjectionRange -Event $matchingAuthority).Ranges | Where-Object {
                            $null -ne $_ -and $_.Start -eq $range.Start
                        } | Select-Object -First 1
                }
                else {
                    # Preserve an empty collection for embedded-authority projection
                    # events that do not need a separate authorization event.
                })
                $sourceEnd = if ($matchingAuthorityRange.Count -gt 0) {
                    [int64]$matchingAuthorityRange[0].End
                }
                else {
                    $range.End
                }
                $activeByScope[$scopeKey] = [pscustomobject]@{
                    ScopeKey = $scopeKey
                    Anchor = $event
                    Authority = $matchingAuthority
                    ScopeAnchor = if ($hasEmbeddedAuthority -or $eventName -like 'filetransfer_regular_v4_frontier_repair_projection_*') {
                        $event
                    }
                    elseif ($null -ne $matchingAuthority) {
                        $matchingAuthority
                    }
                    else {
                        $event
                    }
                    LastEvidence = $event
                    Start = $range.Start
                    End = $range.End
                    SourceEnd = $sourceEnd
                    RepairKey = $range.RepairKey
                    Candidate = $null
                    CandidateLogicalTuple = ''
                    Recovered = $false
                }
            }

            if ($eventName -eq 'filetransfer_regular_v4_frontier_repair_projection_published') {
                $epoch = Get-FileTransferEventField -Event $event -Name 'epoch' -Default ''
                if ($epoch -notmatch '^\d+$') {
                    $epoch = Get-FileTransferEventField -Event $event -Name 'state_epoch' -Default ''
                }
                if ($epoch -match '^\d+$') {
                    $epochKey = ('{0}|{1}|{2}' -f
                            (Get-FileTransferEventField -Event $event -Name 'session_id' -Default '(none)'),
                            (Get-FileTransferEventField -Event $event -Name 'transfer_id' -Default '(none)'),
                            $epoch)
                    if (-not $projectionEpochToScope.ContainsKey($epochKey)) {
                        $projectionEpochToScope[$epochKey] = New-Object System.Collections.Generic.List[string]
                    }
                    if (-not $projectionEpochToScope[$epochKey].Contains($scopeKey)) {
                        $projectionEpochToScope[$epochKey].Add($scopeKey) | Out-Null
                    }
                }
            }
            }
            continue
        }

        if ($eventName -eq 'filetransfer_v4_state_sent') {
            $frontier = Get-FileTransferEventInt64Field -Event $event -Name 'contiguous_committed_chunk_index' -Default -1
            $durableHighest = Get-FileTransferEventInt64Field -Event $event -Name 'durable_received_highest_chunk_index' -Default -1
            $missingCount = Get-FileTransferEventInt64Field -Event $event -Name 'missing_range_count' -Default 0
            $creditExclusive = Get-FileTransferEventInt64Field -Event $event -Name 'credit_until_chunk_index_exclusive' -Default -1
            $terminalReady = Get-FileTransferEventField -Event $event -Name 'terminal_ready' -Default '0'
            $epoch = Get-FileTransferEventField -Event $event -Name 'epoch' -Default ''
            $stateRangeInfo = Get-FileTransferRegularV4RepairProjectionRange -Event $event

            foreach ($scopeKey in @($activeByScope.Keys)) {
                $projection = $activeByScope[$scopeKey]
                if (-not (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $projection.ScopeAnchor -Candidate $event)) {
                    continue
                }

                if ($frontier -gt [int64]$projection.Start) {
                    if ($null -ne $projection.Candidate) {
                        $projection.Recovered = $true
                        $recoveredCandidateSequences[[string][int64]$projection.Candidate.Sequence] = $true
                        if (-not [string]::IsNullOrWhiteSpace([string]$projection.CandidateLogicalTuple) -and
                            $seenCandidateLogicalTuples.ContainsKey([string]$projection.CandidateLogicalTuple)) {
                            $earliestLogicalCandidate = $seenCandidateLogicalTuples[[string]$projection.CandidateLogicalTuple]
                            $recoveredCandidateSequences[[string][int64]$earliestLogicalCandidate.Sequence] = $true
                        }
                    }
                    $activeByScope.Remove($scopeKey)
                    continue
                }

                $stateCarriesExactProjection = $stateRangeInfo.Valid -and @($stateRangeInfo.Ranges | Where-Object {
                        $null -ne $_ -and
                        [int64]$_.Start -eq [int64]$projection.Start -and
                        [int64]$_.End -eq [int64]$projection.End
                    }).Count -gt 0
                if ($missingCount -gt 0 -and $stateCarriesExactProjection -and $epoch -match '^\d+$') {
                    $epochKey = ('{0}|{1}|{2}' -f
                            (Get-FileTransferEventField -Event $event -Name 'session_id' -Default '(none)'),
                            (Get-FileTransferEventField -Event $event -Name 'transfer_id' -Default '(none)'),
                            $epoch)
                    if (-not $projectionEpochToScope.ContainsKey($epochKey)) {
                        $projectionEpochToScope[$epochKey] = New-Object System.Collections.Generic.List[string]
                    }
                    if (-not $projectionEpochToScope[$epochKey].Contains($scopeKey)) {
                        $projectionEpochToScope[$epochKey].Add($scopeKey) | Out-Null
                    }
                }

                if ($null -eq $projection.Candidate -and
                    $frontier -eq [int64]$projection.Start -and
                    $durableHighest -gt $frontier -and
                    $missingCount -eq 0 -and
                    $terminalReady -ne '1' -and
                    $creditExclusive -gt [int64]$projection.End) {
                    $projection.Candidate = $event
                    $rawCandidates.Add($event) | Out-Null
                    $authorityId = Get-FileTransferEventField -Event $projection.ScopeAnchor -Name 'authority_id' -Default '(none)'
                    $decisionGeneration = Get-FileTransferEventField -Event $projection.ScopeAnchor -Name 'decision_generation' -Default '0'
                    $logicalTuple = ('{0}|{1}|{2}|{3}|{4}|{5}|{6}' -f
                        $projection.ScopeKey,
                        $projection.Start,
                        $projection.End,
                        $authorityId,
                        $decisionGeneration,
                        (Get-FileTransferEventField -Event $projection.LastEvidence -Name 'rebind_generation' -Default '0'),
                        $projection.RepairKey)
                    $projection.CandidateLogicalTuple = $logicalTuple
                    if (-not $seenCandidateLogicalTuples.ContainsKey($logicalTuple)) {
                        $seenCandidateLogicalTuples[$logicalTuple] = $event
                        $candidateMetadataBySequence[[string][int64]$event.Sequence] = [pscustomobject]@{
                            ScopeAnchor = $projection.ScopeAnchor
                            Start = [int64]$projection.Start
                            End = [int64]$projection.End
                            LogicalTuple = $logicalTuple
                        }
                        $distinctCandidates.Add($event) | Out-Null
                    }
                }
                elseif ($null -ne $projection.Candidate -and
                    $frontier -eq [int64]$projection.Start -and
                    $durableHighest -gt $frontier -and
                    $missingCount -eq 0 -and
                    $terminalReady -ne '1' -and
                    $creditExclusive -gt [int64]$projection.End -and
                    $epoch -match '^\d+$' -and
                    [string]::Equals(
                        $epoch,
                        (Get-FileTransferEventField -Event $projection.Candidate -Name 'epoch' -Default ''),
                        [System.StringComparison]::Ordinal)) {
                    # Retained-slice merging can preserve the same logical state
                    # more than once. Count the raw copy, but keep one distinct
                    # proof edge at its earliest retained sequence.
                    $rawCandidates.Add($event) | Out-Null
                }
            }
            continue
        }

        if ($eventName -eq 'filetransfer_v4_state_received' -and
            (Get-FileTransferEventField -Event $event -Name 'applied' -Default '0') -eq '1' -and
            (Get-FileTransferEventInt64Field -Event $event -Name 'missing_range_count' -Default 0) -gt 0) {
            $epoch = Get-FileTransferEventField -Event $event -Name 'epoch' -Default ''
            $epochKey = ('{0}|{1}|{2}' -f
                (Get-FileTransferEventField -Event $event -Name 'session_id' -Default '(none)'),
                (Get-FileTransferEventField -Event $event -Name 'transfer_id' -Default '(none)'),
                $epoch)
            if ($projectionEpochToScope.ContainsKey($epochKey)) {
                foreach ($scopeKey in @($projectionEpochToScope[$epochKey])) {
                    $appliedProjectionScopes[$scopeKey] = $event
                }
            }
            continue
        }

        if ($eventName -eq 'filetransfer_regular_v4_frontier_repair_dispatched') {
            $dispatchRange = Get-FileTransferRegularV4RepairProjectionRange -Event $event
            foreach ($scopeKey in @($activeByScope.Keys)) {
                $projection = $activeByScope[$scopeKey]
                if ($null -eq $projection.Candidate -or
                    -not $appliedProjectionScopes.ContainsKey($scopeKey) -or
                    -not (Test-FileTransferRegularV4RepairProjectionTransferMatch -Anchor $projection.Anchor -Candidate $event)) {
                    continue
                }
                $appliedState = $appliedProjectionScopes[$scopeKey]
                $matchingPeerAuthority = @($peerAuthorityEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$appliedState.Sequence -and
                    [int64]$_.Sequence -lt $sequence -and
                    (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $projection.ScopeAnchor -Candidate $_) -and
                    (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $appliedState -Candidate $_) -and
                    @((Get-FileTransferRegularV4RepairProjectionRange -Event $_).Ranges | Where-Object {
                            $null -ne $_ -and
                            [int64]$_.Start -eq [int64]$projection.Start -and
                            [int64]$_.End -eq [int64]$projection.End
                        }).Count -gt 0
                } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                if ($matchingPeerAuthority.Count -gt 0 -and
                    $dispatchRange.Valid -and
                    @($dispatchRange.Ranges | Where-Object {
                            $null -ne $_ -and
                            [int64]$_.Start -eq [int64]$projection.Start -and
                            [int64]$_.End -eq [int64]$projection.End
                        }).Count -gt 0 -and
                    (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $matchingPeerAuthority[0] -Candidate $event)) {
                    $projection.Recovered = $true
                    $recoveredCandidateSequences[[string][int64]$projection.Candidate.Sequence] = $true
                    if (-not [string]::IsNullOrWhiteSpace([string]$projection.CandidateLogicalTuple) -and
                        $seenCandidateLogicalTuples.ContainsKey([string]$projection.CandidateLogicalTuple)) {
                        $earliestLogicalCandidate = $seenCandidateLogicalTuples[[string]$projection.CandidateLogicalTuple]
                        $recoveredCandidateSequences[[string][int64]$earliestLogicalCandidate.Sequence] = $true
                    }
                }
            }
            continue
        }

        if ($eventName -in @(
                'filetransfer_v4_repair_filled',
                'filetransfer_v4_repair_cleared',
                'filetransfer_regular_v4_frontier_repair_progress_observed',
                'filetransfer_regular_v4_frontier_repair_projection_cleared')) {
            $frontierAfter = Get-FileTransferEventInt64Field -Event $event -Name 'committed_frontier_after' -Default -1
            if ($frontierAfter -lt 0) {
                $frontierAfter = Get-FileTransferEventInt64Field -Event $event -Name 'contiguous_committed_chunk_index' -Default -1
            }
            $range = Get-FileTransferRegularV4RepairProjectionRange -Event $event
            $clearReason = Get-FileTransferEventField -Event $event -Name 'decision_reason' -Default ''
            if ([string]::IsNullOrWhiteSpace($clearReason)) {
                $clearReason = Get-FileTransferEventField -Event $event -Name 'reason' -Default ''
            }
            foreach ($scopeKey in @($activeByScope.Keys)) {
                $projection = $activeByScope[$scopeKey]
                if (-not (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $projection.ScopeAnchor -Candidate $event)) {
                    continue
                }
                $durablyResolved = $frontierAfter -gt [int64]$projection.Start -or
                    ($eventName -eq 'filetransfer_v4_repair_filled' -and
                     $range.Valid -and
                     $range.Start -le [int64]$projection.Start -and
                     $range.End -ge [int64]$projection.End) -or
                    ($eventName -eq 'filetransfer_regular_v4_frontier_repair_projection_cleared' -and
                     $clearReason -in @(
                         'frontier_advanced',
                         'frontier_advanced_gap_resolved',
                         'frontier_complete',
                         'range_filled',
                         'durable_fill',
                         'repair_filled'))
                if ($durablyResolved) {
                    if ($null -ne $projection.Candidate) {
                        $projection.Recovered = $true
                        $recoveredCandidateSequences[[string][int64]$projection.Candidate.Sequence] = $true
                        if (-not [string]::IsNullOrWhiteSpace([string]$projection.CandidateLogicalTuple) -and
                            $seenCandidateLogicalTuples.ContainsKey([string]$projection.CandidateLogicalTuple)) {
                            $earliestLogicalCandidate = $seenCandidateLogicalTuples[[string]$projection.CandidateLogicalTuple]
                            $recoveredCandidateSequences[[string][int64]$earliestLogicalCandidate.Sequence] = $true
                        }
                    }
                }
                if ($durablyResolved -or $eventName -eq 'filetransfer_regular_v4_frontier_repair_projection_cleared') {
                    $activeByScope.Remove($scopeKey)
                }
            }
        }
    }

    foreach ($candidate in $distinctCandidates.ToArray()) {
        $matchingProjection = @($activeByScope.Values | Where-Object {
            $null -ne $_.Candidate -and [int64]$_.Candidate.Sequence -eq [int64]$candidate.Sequence
        } | Select-Object -First 1)
        if (($matchingProjection.Count -gt 0 -and $matchingProjection[0].Recovered) -or
            $recoveredCandidateSequences.ContainsKey([string][int64]$candidate.Sequence)) {
            $recoveredCandidates.Add($candidate) | Out-Null
        }
        else {
            $unresolvedCandidates.Add($candidate) | Out-Null
        }
    }

    # A resolved projection may have been removed from the active map. Re-scan
    # durable frontier/fill evidence only for those candidate objects so their
    # recovery status is retained without treating attempt settlement as proof.
    foreach ($candidate in @($unresolvedCandidates.ToArray())) {
        $candidateFrontier = Get-FileTransferEventInt64Field -Event $candidate -Name 'contiguous_committed_chunk_index' -Default -1
        $candidateMetadata = $candidateMetadataBySequence[[string][int64]$candidate.Sequence]
        $candidateScopeAnchor = if ($null -ne $candidateMetadata) { $candidateMetadata.ScopeAnchor } else { $candidate }
        $firstInvalidatingBoundary = @($orderedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$candidate.Sequence -and
            $_.EventName -in @(
                'transfer_terminal',
                'file_transfer_inbound_terminal',
                'file_transfer_outbound_terminal',
                'filetransfer_runtime_terminalized',
                'filetransfer_manifest_received',
                'filetransfer_manifest_replaced',
                'filetransfer_session_replaced',
                'filetransfer_data_session_recreated',
                'filetransfer_route_selected',
                'filetransfer_route_transitioned',
                'filetransfer_live_route_epoch_started',
                'filetransfer_runtime_started',
                'filetransfer_runtime_owner_changed') -and
            (Test-FileTransferRegularV4RepairProjectionTransferMatch -Anchor $candidate -Candidate $_) -and
            (
                $_.EventName -in @(
                    'transfer_terminal',
                    'file_transfer_inbound_terminal',
                    'file_transfer_outbound_terminal',
                    'filetransfer_runtime_terminalized',
                    'filetransfer_manifest_received',
                    'filetransfer_manifest_replaced',
                    'filetransfer_session_replaced',
                    'filetransfer_data_session_recreated') -or
                (Test-FileTransferRegularV4RepairProjectionScopeReplacement `
                    -Anchor $candidateScopeAnchor `
                    -Candidate $_)
            )
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $invalidationSequence = if ($firstInvalidatingBoundary.Count -gt 0) {
            [int64]$firstInvalidatingBoundary[0].Sequence
        }
        else {
            [int64]::MaxValue
        }
        $recovery = @($orderedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$candidate.Sequence -and
            [int64]$_.Sequence -lt $invalidationSequence -and
            (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $candidateScopeAnchor -Candidate $_) -and
            (
                ($_.EventName -eq 'filetransfer_v4_state_sent' -and
                 (Get-FileTransferEventInt64Field -Event $_ -Name 'contiguous_committed_chunk_index' -Default -1) -gt $candidateFrontier) -or
                ($_.EventName -eq 'filetransfer_regular_v4_frontier_repair_progress_observed' -and
                 (Get-FileTransferEventInt64Field -Event $_ -Name 'committed_frontier_after' -Default -1) -gt $candidateFrontier)
            )
        } | Select-Object -First 1)
        if ($recovery.Count -gt 0) {
            $unresolvedCandidates.Remove($candidate) | Out-Null
            $recoveredCandidates.Add($candidate) | Out-Null
        }
    }

    $verdict = if ($unresolvedCandidates.Count -gt 0) {
        'fail'
    }
    elseif ($distinctCandidates.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = $recoveredCandidates.Count
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = $verdict
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @($recoveredCandidates.ToArray())
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
    }
}

function Get-FileTransferRegularV4PeerSilenceReplayRange {
    param([Parameter(Mandatory = $true)]$Event)

    $repairKey = Get-FileTransferEventField -Event $Event -Name 'repair_request_key' -Default ''
    if ([string]::IsNullOrWhiteSpace($repairKey) -or $repairKey -in @('(none)', 'none')) {
        $repairKey = Get-FileTransferEventField -Event $Event -Name 'successor_repair_request_key' -Default ''
    }

    if ($repairKey -match '^regular_v4_peer_silence_safety_replay:(?<frontier>\d+):(?<start>\d+):(?<count>\d+):(?<ordinal>\d+)$') {
        $start = [int64]$Matches['start']
        $count = [int64]$Matches['count']
        return [pscustomobject]@{
            Valid = $count -gt 0
            RepairKey = $repairKey
            Frontier = [int64]$Matches['frontier']
            Start = $start
            End = $start + $count
            Ordinal = [int64]$Matches['ordinal']
        }
    }

    $frontier = Get-FileTransferEventInt64Field -Event $Event -Name 'remote_next_expected_chunk_index' -Default -1
    if ($frontier -lt 0) {
        $frontier = Get-FileTransferEventInt64Field -Event $Event -Name 'frontier_chunk_index' -Default -1
    }
    $start = Get-FileTransferEventInt64Field -Event $Event -Name 'replay_start_chunk_index' -Default -1
    if ($start -lt 0) {
        $start = Get-FileTransferEventInt64Field -Event $Event -Name 'start_chunk_index' -Default -1
    }
    $end = Get-FileTransferEventInt64Field -Event $Event -Name 'replay_end_chunk_exclusive' -Default -1
    if ($end -lt 0 -and $start -ge 0) {
        $count = Get-FileTransferEventInt64Field -Event $Event -Name 'scheduled_chunk_count' -Default 0
        if ($count -le 0) {
            $count = Get-FileTransferEventInt64Field -Event $Event -Name 'requested_chunk_count' -Default 0
        }
        if ($count -le 0) {
            $count = Get-FileTransferEventInt64Field -Event $Event -Name 'sent_chunk_count' -Default 0
        }
        if ($count -gt 0) {
            $end = $start + $count
        }
    }

    return [pscustomobject]@{
        Valid = $frontier -ge 0 -and $start -ge 0 -and $end -gt $start
        RepairKey = if ([string]::IsNullOrWhiteSpace($repairKey)) { '(none)' } else { $repairKey }
        Frontier = $frontier
        Start = $start
        End = $end
        Ordinal = Get-FileTransferEventInt64Field -Event $Event -Name 'replay_ordinal' -Default 0
    }
}

function Test-FileTransferRegularV4PeerSilenceReplayScopeMatch {
    param(
        [Parameter(Mandatory = $true)]$Anchor,
        [Parameter(Mandatory = $true)]$Candidate
    )

    if (-not (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $Anchor -Candidate $Candidate)) {
        return $false
    }

    $anchorDirection = Get-FileTransferEventField -Event $Anchor -Name 'direction' -Default ''
    $candidateDirection = Get-FileTransferEventField -Event $Candidate -Name 'direction' -Default ''
    return [string]::IsNullOrWhiteSpace($anchorDirection) -or
        [string]::IsNullOrWhiteSpace($candidateDirection) -or
        [string]::Equals($anchorDirection, $candidateDirection, [System.StringComparison]::OrdinalIgnoreCase)
}

function Get-FileTransferRegularV4PeerSilenceReplayMissingDispatchRangeProof {
    param([AllowEmptyCollection()][object[]]$Events = @())

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    $grantRecords = New-Object System.Collections.Generic.List[object]
    $grantByCorrelationKey = @{}
    $missingDispatchByCorrelationKey = @{}
    $activeUnresolvedRanges = New-Object System.Collections.Generic.List[object]
    $activeRangeByLogicalKey = @{}
    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidateRecords = New-Object System.Collections.Generic.List[object]
    $seenCandidateLogicalTuples = @{}

    foreach ($event in $orderedEvents) {
        $eventName = [string]$event.EventName
        $sequence = [int64]$event.Sequence

        if ($eventName -in @(
                'transfer_terminal',
                'file_transfer_inbound_terminal',
                'file_transfer_outbound_terminal',
                'filetransfer_runtime_terminalized',
                'filetransfer_manifest_received',
                'filetransfer_manifest_replaced',
                'filetransfer_session_replaced',
                'filetransfer_data_session_recreated',
                'filetransfer_route_selected',
                'filetransfer_route_transitioned',
                'filetransfer_live_route_epoch_started',
                'filetransfer_runtime_started',
                'filetransfer_runtime_owner_changed')) {
            $isUnconditionalBoundary = $eventName -in @(
                'transfer_terminal',
                'file_transfer_inbound_terminal',
                'file_transfer_outbound_terminal',
                'filetransfer_runtime_terminalized',
                'filetransfer_manifest_received',
                'filetransfer_manifest_replaced',
                'filetransfer_session_replaced',
                'filetransfer_data_session_recreated')
            foreach ($range in @($activeUnresolvedRanges.ToArray())) {
                if (-not (Test-FileTransferRegularV4RepairProjectionTransferMatch -Anchor $range.ScopeAnchor -Candidate $event)) {
                    continue
                }
                if ($isUnconditionalBoundary -or
                    (Test-FileTransferRegularV4RepairProjectionScopeReplacement -Anchor $range.ScopeAnchor -Candidate $event)) {
                    $activeUnresolvedRanges.Remove($range) | Out-Null
                    $activeRangeByLogicalKey.Remove([string]$range.LogicalKey)
                }
            }
            foreach ($candidate in $distinctCandidateRecords.ToArray()) {
                if ($sequence -le [int64]$candidate.Event.Sequence -or
                    [int64]$candidate.InvalidationSequence -ne [int64]::MaxValue -or
                    -not (Test-FileTransferRegularV4RepairProjectionTransferMatch -Anchor $candidate.ScopeAnchor -Candidate $event)) {
                    continue
                }
                if ($isUnconditionalBoundary -or
                    (Test-FileTransferRegularV4RepairProjectionScopeReplacement -Anchor $candidate.ScopeAnchor -Candidate $event)) {
                    $candidate.InvalidationSequence = $sequence
                }
            }
            continue
        }

        if ($eventName -eq 'filetransfer_regular_v4_frontier_repair_authority_granted') {
            $source = Get-FileTransferEventField -Event $event -Name 'source' -Default ''
            $direction = Get-FileTransferEventField -Event $event -Name 'direction' -Default ''
            $route = Get-FileTransferEventField -Event $event -Name 'route' -Default 'regular_nkn_v4_fast'
            $protocol = Get-FileTransferEventField -Event $event -Name 'protocol_version' -Default '4'
            $range = Get-FileTransferRegularV4PeerSilenceReplayRange -Event $event
            if ($source -ne 'regular_v4_peer_silence_safety_replay' -or
                $direction -ne 'outbound' -or
                $route -ne 'regular_nkn_v4_fast' -or
                $protocol -ne '4' -or
                -not $range.Valid) {
                continue
            }

            $scopeKey = Get-FileTransferRegularV4RepairProjectionScopeKey -Event $event -Frontier $range.Frontier
            $correlationKey = ('{0}|{1}' -f $scopeKey, $range.RepairKey)
            if (-not $grantByCorrelationKey.ContainsKey($correlationKey)) {
                $grantRecord = [pscustomobject]@{
                    CorrelationKey = $correlationKey
                    ScopeKey = $scopeKey
                    Event = $event
                    Range = $range
                }
                $grantByCorrelationKey[$correlationKey] = $grantRecord
                $grantRecords.Add($grantRecord) | Out-Null
            }

            foreach ($unresolved in @($activeUnresolvedRanges.ToArray())) {
                if ($range.Frontier -ne [int64]$unresolved.Frontier -or
                    $range.Start -le [int64]$unresolved.Start -or
                    -not (Test-FileTransferRegularV4PeerSilenceReplayScopeMatch -Anchor $unresolved.ScopeAnchor -Candidate $event)) {
                    continue
                }

                $rawCandidates.Add($event) | Out-Null
                $decisionGeneration = Get-FileTransferEventField -Event $event -Name 'decision_generation' -Default '0'
                $logicalTuple = ('{0}|{1}|{2}|{3}|{4}|{5}|{6}' -f
                    $unresolved.ScopeKey,
                    $unresolved.Frontier,
                    $unresolved.Start,
                    $unresolved.End,
                    $unresolved.RepairKey,
                    $range.RepairKey,
                    $decisionGeneration)
                if (-not $seenCandidateLogicalTuples.ContainsKey($logicalTuple)) {
                    $candidateRecord = [pscustomobject]@{
                        Event = $event
                        LogicalTuple = $logicalTuple
                        ScopeAnchor = $unresolved.ScopeAnchor
                        Frontier = [int64]$unresolved.Frontier
                        Start = [int64]$unresolved.Start
                        End = [int64]$unresolved.End
                        Recovered = $false
                        InvalidationSequence = [int64]::MaxValue
                    }
                    $seenCandidateLogicalTuples[$logicalTuple] = $candidateRecord
                    $distinctCandidateRecords.Add($candidateRecord) | Out-Null
                }
                break
            }
            continue
        }

        if ($eventName -eq 'filetransfer_regular_v4_frontier_repair_missing_dispatch') {
            $range = Get-FileTransferRegularV4PeerSilenceReplayRange -Event $event
            if ($range.Valid) {
                $matchingGrant = @($grantRecords.ToArray() | Where-Object {
                    $_.Range.RepairKey -eq $range.RepairKey -and
                    [int64]$_.Event.Sequence -lt $sequence -and
                    (Test-FileTransferRegularV4PeerSilenceReplayScopeMatch -Anchor $_.Event -Candidate $event)
                } | Sort-Object @{ Expression = { [int64]$_.Event.Sequence } } | Select-Object -Last 1)
                if ($matchingGrant.Count -gt 0) {
                    $missingDispatchByCorrelationKey[[string]$matchingGrant[0].CorrelationKey] = $event
                }
            }
            continue
        }

        if ($eventName -in @(
                'filetransfer_regular_v4_frontier_repair_contract_settled',
                'filetransfer_regular_v4_frontier_repair_settled_stalled',
                'filetransfer_regular_v4_frontier_repair_settlement_accepted') -and
            -not ($eventName -eq 'filetransfer_regular_v4_frontier_repair_contract_settled' -and
                (Get-FileTransferEventField -Event $event -Name 'dispatch_observed' -Default '0') -eq '1')) {
            $range = Get-FileTransferRegularV4PeerSilenceReplayRange -Event $event
            if (-not $range.Valid) {
                continue
            }

            [object[]]$matchingGrants = @($grantRecords.ToArray() | Where-Object {
                $_.Range.RepairKey -eq $range.RepairKey -and
                [int64]$_.Event.Sequence -lt $sequence -and
                $missingDispatchByCorrelationKey.ContainsKey([string]$_.CorrelationKey) -and
                (Test-FileTransferRegularV4PeerSilenceReplayScopeMatch -Anchor $_.Event -Candidate $event)
            } | Sort-Object @{ Expression = { [int64]$_.Event.Sequence } })
            if ($matchingGrants.Count -eq 0 -or
                ($eventName -eq 'filetransfer_regular_v4_frontier_repair_contract_settled' -and
                    $matchingGrants.Count -ne 1)) {
                continue
            }

            $outcome = Get-FileTransferEventField -Event $event -Name 'settlement_outcome' -Default ''
            if ([string]::IsNullOrWhiteSpace($outcome)) {
                $outcome = Get-FileTransferEventField -Event $event -Name 'outcome' -Default ''
            }
            if ([string]::IsNullOrWhiteSpace($outcome) -and
                $eventName -eq 'filetransfer_regular_v4_frontier_repair_settled_stalled') {
                $outcome = 'SettledStalled'
            }
            $dispatchObserved = Get-FileTransferEventField -Event $event -Name 'dispatch_observed' -Default '0'
            if ($outcome.ToLowerInvariant() -notin @('missingdispatch', 'missing_dispatch', 'settledstalled', 'settled_stalled') -or
                $dispatchObserved -eq '1') {
                continue
            }

            $grantRecord = $matchingGrants[-1]
            $scopeAnchor = $grantRecord.Event
            $range = $grantRecord.Range
            $scopeKey = [string]$grantRecord.ScopeKey
            $logicalKey = ('{0}|{1}|{2}|{3}' -f $scopeKey, $range.Frontier, $range.Start, $range.End)
            if (-not $activeRangeByLogicalKey.ContainsKey($logicalKey)) {
                $unresolved = [pscustomobject]@{
                    LogicalKey = $logicalKey
                    ScopeKey = $scopeKey
                    ScopeAnchor = $scopeAnchor
                    Frontier = $range.Frontier
                    Start = $range.Start
                    End = $range.End
                    RepairKey = $range.RepairKey
                    Settlement = $event
                }
                $activeRangeByLogicalKey[$logicalKey] = $unresolved
                $activeUnresolvedRanges.Add($unresolved) | Out-Null
            }
            else {
                $unresolved = $activeRangeByLogicalKey[$logicalKey]
                if ([int64]$event.Sequence -gt [int64]$unresolved.Settlement.Sequence) {
                    $unresolved.ScopeKey = $scopeKey
                    $unresolved.ScopeAnchor = $scopeAnchor
                    $unresolved.RepairKey = $range.RepairKey
                    $unresolved.Settlement = $event
                }
            }
            continue
        }

        if ($eventName -in @(
                'filetransfer_regular_v4_frontier_repair_dispatched',
                'filetransfer_regular_v4_frontier_repair_contract_settled')) {
            if ($eventName -eq 'filetransfer_regular_v4_frontier_repair_contract_settled' -and
                (Get-FileTransferEventField -Event $event -Name 'dispatch_observed' -Default '0') -ne '1') {
                continue
            }
            $range = Get-FileTransferRegularV4PeerSilenceReplayRange -Event $event
            if (-not $range.Valid) {
                continue
            }
            [object[]]$matchingGrants = @($grantRecords.ToArray() | Where-Object {
                $_.Range.RepairKey -eq $range.RepairKey -and
                [int64]$_.Event.Sequence -lt $sequence -and
                (Test-FileTransferRegularV4PeerSilenceReplayScopeMatch -Anchor $_.Event -Candidate $event)
            } | Sort-Object @{ Expression = { [int64]$_.Event.Sequence } })
            if ($eventName -eq 'filetransfer_regular_v4_frontier_repair_contract_settled' -and
                $matchingGrants.Count -ne 1) {
                continue
            }
            $scopeAnchor = if ($matchingGrants.Count -gt 0) { $matchingGrants[-1].Event } else { $event }
            foreach ($unresolved in @($activeUnresolvedRanges.ToArray())) {
                if ($range.Start -le [int64]$unresolved.Start -and
                    $range.End -ge [int64]$unresolved.End -and
                    (Test-FileTransferRegularV4PeerSilenceReplayScopeMatch -Anchor $unresolved.ScopeAnchor -Candidate $scopeAnchor)) {
                    $activeUnresolvedRanges.Remove($unresolved) | Out-Null
                    $activeRangeByLogicalKey.Remove([string]$unresolved.LogicalKey)
                }
            }
            foreach ($candidate in $distinctCandidateRecords.ToArray()) {
                if (-not $candidate.Recovered -and
                    $sequence -gt [int64]$candidate.Event.Sequence -and
                    $sequence -lt [int64]$candidate.InvalidationSequence -and
                    $range.Start -le [int64]$candidate.Start -and
                    $range.End -ge [int64]$candidate.End -and
                    (Test-FileTransferRegularV4PeerSilenceReplayScopeMatch -Anchor $candidate.ScopeAnchor -Candidate $scopeAnchor)) {
                    $candidate.Recovered = $true
                }
            }
            continue
        }

        if ($eventName -eq 'filetransfer_v4_state_received' -and
            (Get-FileTransferEventField -Event $event -Name 'applied' -Default '0') -eq '1') {
            $peerFrontier = Get-FileTransferEventInt64Field -Event $event -Name 'contiguous_committed_chunk_index' -Default -1
            foreach ($unresolved in @($activeUnresolvedRanges.ToArray())) {
                if ($peerFrontier -ge [int64]$unresolved.End -and
                    (Test-FileTransferRegularV4PeerSilenceReplayScopeMatch -Anchor $unresolved.ScopeAnchor -Candidate $event)) {
                    $activeUnresolvedRanges.Remove($unresolved) | Out-Null
                    $activeRangeByLogicalKey.Remove([string]$unresolved.LogicalKey)
                }
            }
            foreach ($candidate in $distinctCandidateRecords.ToArray()) {
                if (-not $candidate.Recovered -and
                    $sequence -gt [int64]$candidate.Event.Sequence -and
                    $sequence -lt [int64]$candidate.InvalidationSequence -and
                    $peerFrontier -ge [int64]$candidate.End -and
                    (Test-FileTransferRegularV4PeerSilenceReplayScopeMatch -Anchor $candidate.ScopeAnchor -Candidate $event)) {
                    $candidate.Recovered = $true
                }
            }
        }
    }

    [object[]]$recoveredCandidateEvents = @(
        $distinctCandidateRecords.ToArray() |
            Where-Object { $_.Recovered } |
            ForEach-Object { $_.Event }
    )
    [object[]]$unresolvedCandidateEvents = @(
        $distinctCandidateRecords.ToArray() |
            Where-Object { -not $_.Recovered } |
            ForEach-Object { $_.Event }
    )
    $verdict = if ($unresolvedCandidateEvents.Count -gt 0) {
        'fail'
    }
    elseif ($distinctCandidateRecords.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidateRecords.Count
        RecoveredCount = $recoveredCandidateEvents.Count
        UnresolvedCount = $unresolvedCandidateEvents.Count
        Verdict = $verdict
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidateRecords.ToArray() | ForEach-Object { $_.Event })
        RecoveredCandidateEvents = $recoveredCandidateEvents
        UnresolvedCandidateEvents = $unresolvedCandidateEvents
    }
}

function Get-FileTransferRuntimeUnlockRegularV4RecoverySettlementCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [AllowEmptyCollection()][object[]]$EffectiveGrantEvents = @(),
        [AllowEmptyCollection()][object[]]$ResolvedRepairSettlementEvents = @()
    )

    [object[]]$events = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$effectiveGrants = @($EffectiveGrantEvents | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$resolvedRepairSettlements = @(
        $ResolvedRepairSettlementEvents |
            Where-Object { $null -ne $_ } |
            Sort-Object Sequence, LineNumber)
    $requiredScopeFields = @(
        'session_id',
        'transfer_id',
        'route',
        'protocol_version',
        'live_route_epoch',
        'regular_v4_liveness_generation',
        'bridge_decision_generation')
    $semanticCandidateBaseFields = @(
        'session_id',
        'transfer_id',
        'route',
        'protocol_version',
        'live_route_epoch',
        'regular_v4_liveness_generation',
        'bridge_decision_generation')
    $completeRecoveryFields = @(
        'session_id',
        'transfer_id',
        'direction',
        'route',
        'protocol_version',
        'live_route_epoch',
        'runtime_generation',
        'terminal_generation',
        'leg_generation',
        'transport_epoch',
        'bridge_recovery_generation',
        'bridge_decision_generation',
        'regular_v4_liveness_generation')

    function Test-RecoveryValuePresent {
        param([AllowNull()][AllowEmptyString()][string]$Value)

        return -not [string]::IsNullOrWhiteSpace($Value) -and
            $Value -notin @('(none)', 'none', '(missing)', '__missing__')
    }

    function Get-RecoveryScopeFieldValue {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string]$Name
        )

        return Get-FileTransferEventField -Event $Event -Name $Name -Default ''
    }

    function Test-RecoveryCandidateComplete {
        param([Parameter(Mandatory = $true)]$Event)

        foreach ($field in $requiredScopeFields) {
            if (-not (Test-RecoveryValuePresent (
                        Get-RecoveryScopeFieldValue -Event $Event -Name $field))) {
                return $false
            }
        }
        return $true
    }

    function Get-RecoveryScopeKey {
        param([Parameter(Mandatory = $true)]$Event)

        return (@($requiredScopeFields + 'direction') | ForEach-Object {
                (Get-RecoveryScopeFieldValue -Event $Event -Name $_).ToLowerInvariant()
            }) -join '|'
    }

    function Test-RecoveryPartialScopeCompatible {
        param(
            [Parameter(Mandatory = $true)]$Partial,
            [Parameter(Mandatory = $true)]$Complete
        )

        if (-not (Test-RecoveryCandidateComplete $Complete)) {
            return $false
        }

        $observedFieldCount = 0
        foreach ($field in $requiredScopeFields) {
            $partialValue = Get-RecoveryScopeFieldValue -Event $Partial -Name $field
            if (-not (Test-RecoveryValuePresent $partialValue)) {
                continue
            }
            $observedFieldCount++
            $completeValue = Get-RecoveryScopeFieldValue -Event $Complete -Name $field
            if (-not (Test-RecoveryValuePresent $completeValue) -or
                -not [string]::Equals(
                    $partialValue,
                    $completeValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        $partialDirection = Get-RecoveryScopeFieldValue -Event $Partial -Name 'direction'
        if (Test-RecoveryValuePresent $partialDirection) {
            $completeDirection = Get-RecoveryScopeFieldValue -Event $Complete -Name 'direction'
            if (-not (Test-RecoveryValuePresent $completeDirection) -or
                -not [string]::Equals(
                    $partialDirection,
                    $completeDirection,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $observedFieldCount -gt 0
    }

    function New-RecoveryScopeEvent {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)]$ScopeEvidence
        )

        $fields = @{}
        if ($null -ne $Event.Fields) {
            foreach ($key in @($Event.Fields.Keys)) {
                $fields[$key] = $Event.Fields[$key]
            }
        }
        foreach ($field in $completeRecoveryFields) {
            $currentValue = Get-FileTransferEventField -Event $Event -Name $field -Default ''
            if (-not (Test-RecoveryValuePresent $currentValue)) {
                $fields[$field] = Get-RecoveryScopeFieldValue -Event $ScopeEvidence -Name $field
            }
        }

        return [pscustomobject]@{
            EventName = [string]$Event.EventName
            Sequence = [int64]$Event.Sequence
            LineNumber = [int]$Event.LineNumber
            FilePath = [string]$Event.FilePath
            FileName = [string]$Event.FileName
            Message = [string]$Event.Message
            RawLine = [string]$Event.RawLine
            TransferId = [string]$Event.TransferId
            Fields = $fields
        }
    }

    function Get-RecoveryChainKey {
        param([Parameter(Mandatory = $true)]$Event)

        return (Get-RecoveryScopeKey -Event $Event) + '|' +
            (@('contract_generation', 'retired_generation', 'offer_generation') | ForEach-Object {
                    (Get-FileTransferEventField -Event $Event -Name $_ -Default '(missing)').ToLowerInvariant()
                }) -join '|'
    }

    function Test-RecoveryScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Anchor,
            [Parameter(Mandatory = $true)]$Candidate
        )

        foreach ($field in $requiredScopeFields) {
            $left = Get-RecoveryScopeFieldValue -Event $Anchor -Name $field
            $right = Get-RecoveryScopeFieldValue -Event $Candidate -Name $field
            if (-not (Test-RecoveryValuePresent $left) -or
                -not (Test-RecoveryValuePresent $right) -or
                -not [string]::Equals($left, $right, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        $anchorDirection = Get-RecoveryScopeFieldValue -Event $Anchor -Name 'direction'
        $candidateDirection = Get-RecoveryScopeFieldValue -Event $Candidate -Name 'direction'
        if ((Test-RecoveryValuePresent $anchorDirection) -or
            (Test-RecoveryValuePresent $candidateDirection)) {
            if (-not (Test-RecoveryValuePresent $anchorDirection) -or
                -not (Test-RecoveryValuePresent $candidateDirection) -or
                -not [string]::Equals(
                    $anchorDirection,
                    $candidateDirection,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Test-CompleteRecoveryTupleMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        foreach ($field in $completeRecoveryFields) {
            $leftValue = Get-FileTransferEventField -Event $Left -Name $field -Default ''
            $rightValue = Get-FileTransferEventField -Event $Right -Name $field -Default ''
            if (-not (Test-RecoveryValuePresent $leftValue) -or
                -not (Test-RecoveryValuePresent $rightValue) -or
                -not [string]::Equals(
                    $leftValue,
                    $rightValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Test-RecoveryAuthorityValueRedacted {
        param([AllowNull()][AllowEmptyString()][string]$Value)

        return $Value -in @('[redacted]', 'redacted', '(redacted)')
    }

    function Test-RecoveryAuthorityEvidenceSetCompatible {
        param([AllowEmptyCollection()][object[]]$Values = @())

        $observedAuthorities = New-Object 'System.Collections.Generic.HashSet[string]' `
            ([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($valueObject in @($Values)) {
            $value = [string]$valueObject
            if (-not (Test-RecoveryValuePresent $value)) {
                return $false
            }
            if (-not (Test-RecoveryAuthorityValueRedacted $value)) {
                $observedAuthorities.Add($value) | Out-Null
            }
        }

        # A redacted structured value is absence, not equality.  It is
        # corroborated only by one concrete authority-bearing Phase-2 chain;
        # two different concrete identities are always a mismatch.
        return $observedAuthorities.Count -eq 1
    }

    function Test-RecoveryBoundaryMatch {
        param(
            [Parameter(Mandatory = $true)]$Blocked,
            [Parameter(Mandatory = $true)]$Boundary
        )

        return Test-FileTransferRuntimeUnlockRegularV4RecoveryBoundaryMatch `
            -Blocked $Blocked `
            -Boundary $Boundary
    }

    function Test-RecoveryRepairSettlementScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Blocked,
            [Parameter(Mandatory = $true)]$Settlement
        )

        $outcome = (Get-FileTransferEventField `
            -Event $Settlement `
            -Name 'outcome' `
            -Default (Get-FileTransferEventField -Event $Settlement -Name 'settlement_outcome' -Default '')).
            Replace('_', '').ToLowerInvariant()
        if ($outcome -notin @('progressobserved', 'missingdispatch', 'settledstalled')) {
            return $false
        }

        foreach ($field in @(
                'session_id',
                'transfer_id',
                'direction',
                'route',
                'protocol_version',
                'live_route_epoch',
                'runtime_generation',
                'terminal_generation',
                'leg_generation',
                'transport_epoch',
                'bridge_recovery_generation',
                'bridge_decision_generation')) {
            $blockedValue = Get-FileTransferEventField -Event $Blocked -Name $field -Default ''
            $settlementValue = Get-FileTransferEventField -Event $Settlement -Name $field -Default ''
            if (-not (Test-RecoveryValuePresent $blockedValue) -or
                -not (Test-RecoveryValuePresent $settlementValue) -or
                -not [string]::Equals(
                    $blockedValue,
                    $settlementValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Test-RecoveryRepairSettlementEvidenceMatch {
        param(
            [Parameter(Mandatory = $true)]$Settlement,
            [Parameter(Mandatory = $true)]$Evidence
        )

        foreach ($field in @(
                'session_id',
                'transfer_id',
                'direction',
                'route',
                'protocol_version',
                'live_route_epoch',
                'runtime_generation',
                'terminal_generation',
                'leg_generation',
                'transport_epoch',
                'bridge_recovery_generation',
                'bridge_decision_generation',
                'authority_id',
                'repair_request_key')) {
            $settlementValue = Get-FileTransferEventField -Event $Settlement -Name $field -Default ''
            $evidenceValue = Get-FileTransferEventField -Event $Evidence -Name $field -Default ''
            if (-not (Test-RecoveryValuePresent $settlementValue) -or
                -not (Test-RecoveryValuePresent $evidenceValue) -or
                -not [string]::Equals(
                    $settlementValue,
                    $evidenceValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        $settlementGeneration = Get-FileTransferEventField -Event $Settlement -Name 'decision_generation' -Default ''
        $evidenceGeneration = Get-FileTransferEventField -Event $Evidence -Name 'settlement_decision_generation' -Default ''
        if (-not (Test-RecoveryValuePresent $settlementGeneration) -or
            -not (Test-RecoveryValuePresent $evidenceGeneration) -or
            $settlementGeneration -ne $evidenceGeneration) {
            return $false
        }

        $settlementOutcome = (Get-FileTransferEventField -Event $Settlement -Name 'outcome' -Default '').
            Replace('_', '').ToLowerInvariant()
        $evidenceOutcome = (Get-FileTransferEventField -Event $Evidence -Name 'settlement_outcome' -Default '').
            Replace('_', '').ToLowerInvariant()
        return -not [string]::IsNullOrWhiteSpace($settlementOutcome) -and
            $settlementOutcome -eq $evidenceOutcome
    }

    function Test-RecoveryRepairSettlementHandoffMatch {
        param(
            [Parameter(Mandatory = $true)]$Blocked,
            [Parameter(Mandatory = $true)]$Settlement,
            [Parameter(Mandatory = $true)][int64]$BoundarySequence
        )

        if (-not (Test-RecoveryRepairSettlementScopeMatch -Blocked $Blocked -Settlement $Settlement)) {
            return $false
        }

        $blockedContractGeneration = Get-FileTransferEventField -Event $Blocked -Name 'contract_generation' -Default ''
        $blockedOfferGeneration = Get-FileTransferEventField -Event $Blocked -Name 'offer_generation' -Default ''
        $blockedLivenessGeneration = Get-FileTransferEventField `
            -Event $Blocked `
            -Name 'regular_v4_liveness_generation' `
            -Default ''
        $blockedBridgeDecisionGeneration = Get-FileTransferEventField `
            -Event $Blocked `
            -Name 'bridge_decision_generation' `
            -Default ''
        foreach ($value in @(
                $blockedContractGeneration,
                $blockedOfferGeneration,
                $blockedLivenessGeneration,
                $blockedBridgeDecisionGeneration)) {
            if (-not (Test-RecoveryValuePresent $value)) {
                return $false
            }
        }

        [object[]]$matchingEvidence = @($events | Where-Object {
            [int64]$_.Sequence -gt [int64]$Settlement.Sequence -and
            [int64]$_.Sequence -lt $BoundarySequence -and
            $_.EventName -in @(
                'runtime_unlock_regular_v4_frontier_repair_precontract_settlement_cached',
                'runtime_unlock_regular_v4_frontier_repair_settlement_handoff_adopted',
                'runtime_unlock_regular_v4_frontier_repair_settlement_held',
                'runtime_unlock_regular_v4_frontier_repair_settlement_handoff_held_for_bridge_lifecycle') -and
            (Test-RecoveryRepairSettlementEvidenceMatch -Settlement $Settlement -Evidence $_)
        })
        if ($matchingEvidence.Count -eq 0) {
            return $false
        }

        $recoveryScopeObserved = @($matchingEvidence | Where-Object {
            (Get-FileTransferEventField -Event $_ -Name 'adopted_recovery_liveness_generation' -Default '') -eq
                $blockedLivenessGeneration -and
            (Get-FileTransferEventField -Event $_ -Name 'adopted_bridge_decision_generation' -Default '') -eq
                $blockedBridgeDecisionGeneration
        }).Count -gt 0
        if (-not $recoveryScopeObserved) {
            return $false
        }

        return @($matchingEvidence | Where-Object {
            (Get-FileTransferEventField -Event $_ -Name 'contract_generation' -Default '') -eq
                $blockedContractGeneration -and
            (Get-FileTransferEventField -Event $_ -Name 'offer_generation' -Default '') -eq
                $blockedOfferGeneration
        }).Count -gt 0
    }

    function Test-ClosureGrantNonAuthorityTupleMatch {
        param(
            [Parameter(Mandatory = $true)]$Consumed,
            [Parameter(Mandatory = $true)]$Grant
        )

        if ((Get-FileTransferEventField -Event $Grant -Name 'release_kind' -Default '') -ne
            'ReceiveRecoveryLeaseClosure' -or
            (Get-FileTransferEventInt64Field -Event $Grant -Name 'install_generation' -Default 0) -le 0) {
            return $false
        }
        foreach ($field in @($completeRecoveryFields | Where-Object {
                    $_ -ne 'regular_v4_liveness_generation'
                })) {
            $consumedValue = Get-FileTransferEventField -Event $Consumed -Name $field -Default ''
            $grantValue = Get-FileTransferEventField -Event $Grant -Name $field -Default ''
            if (-not (Test-RecoveryValuePresent $consumedValue) -or
                -not (Test-RecoveryValuePresent $grantValue) -or
                -not [string]::Equals(
                    $consumedValue,
                    $grantValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        foreach ($pair in @(
                @('regular_v4_liveness_generation', 'request_regular_v4_liveness_generation'),
                @('bridge_decision_generation', 'request_bridge_decision_generation'),
                @('lease_generation', 'release_generation'),
                @('dispatch_attempt_generation', 'dispatch_attempt_generation'),
                @('missing_dispatch_successor_generation', 'missing_dispatch_successor_generation'))) {
            $leftValue = Get-FileTransferEventField -Event $Consumed -Name $pair[0] -Default ''
            $rightValue = Get-FileTransferEventField -Event $Grant -Name $pair[1] -Default ''
            if (-not (Test-RecoveryValuePresent $leftValue) -or
                -not (Test-RecoveryValuePresent $rightValue) -or
                -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Test-ClosureGrantBlockedRetryMatch {
        param(
            [Parameter(Mandatory = $true)]$Blocked,
            [Parameter(Mandatory = $true)]$Grant
        )

        # A recovery closure releases one blocked retry chain, not every
        # retry sharing the same recovery window.  Require every retry-lineage
        # field carried by the blocked anchor to agree with the committed
        # grant.  Older Held-only telemetry lacks these fields and remains
        # correlatable only through its otherwise unique recovery scope.
        foreach ($fieldPair in @(
                @('contract_generation', 'contract_generation'),
                @('retired_generation', 'retired_generation'),
                @('offer_generation', 'retired_generation'),
                @('dispatch_attempt_generation', 'dispatch_attempt_generation'),
                @('missing_dispatch_successor_generation', 'missing_dispatch_successor_generation'),
                @('predecessor_authority_id', 'predecessor_authority_id'),
                @('request_active_predecessor_supersession', 'request_active_predecessor_supersession'))) {
            $blockedValue = Get-FileTransferEventField -Event $Blocked -Name $fieldPair[0] -Default ''
            if (-not (Test-RecoveryValuePresent $blockedValue)) {
                continue
            }
            $grantValue = Get-FileTransferEventField -Event $Grant -Name $fieldPair[1] -Default ''
            if (-not (Test-RecoveryValuePresent $grantValue) -or
                -not [string]::Equals(
                    $blockedValue,
                    $grantValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Test-RecoveryPotentialGrantMatch {
        param(
            [Parameter(Mandatory = $true)]$Blocked,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if ($Candidate.EventName -notin @(
                'runtime_unlock_retry_dispatch_pending_request_rechecked',
                'runtime_unlock_retry_dispatch_authority_granted')) {
            return $false
        }
        foreach ($field in @('session_id', 'transfer_id')) {
            $blockedValue = Get-FileTransferEventField -Event $Blocked -Name $field -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $field -Default ''
            if (-not (Test-RecoveryValuePresent $blockedValue) -or
                -not (Test-RecoveryValuePresent $candidateValue) -or
                -not [string]::Equals($blockedValue, $candidateValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        $blockedDirection = Get-FileTransferEventField -Event $Blocked -Name 'direction' -Default ''
        $candidateDirection = Get-FileTransferEventField -Event $Candidate -Name 'direction' -Default ''
        if (-not (Test-RecoveryValuePresent $blockedDirection) -or
            -not (Test-RecoveryValuePresent $candidateDirection) -or
            -not [string]::Equals(
                $blockedDirection,
                $candidateDirection,
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
        foreach ($generationPair in @(
                @('regular_v4_liveness_generation', 'request_regular_v4_liveness_generation'),
                @('bridge_decision_generation', 'request_bridge_decision_generation'))) {
            $blockedValue = Get-FileTransferEventField -Event $Blocked -Name $generationPair[0] -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $generationPair[1] -Default ''
            if (-not (Test-RecoveryValuePresent $blockedValue) -or
                -not (Test-RecoveryValuePresent $candidateValue) -or
                ($candidateValue -ne '0' -and $candidateValue -ne $blockedValue)) {
                return $false
            }
        }

        $requiredCandidateFields = if ($Candidate.EventName -eq 'runtime_unlock_retry_dispatch_pending_request_rechecked') {
            @('route', 'protocol_version', 'live_route_epoch', 'contract_generation', 'retired_generation')
        }
        else {
            @(
                'authority_id',
                'route',
                'protocol_version',
                'live_route_epoch',
                'contract_generation',
                'retired_generation',
                'release_kind',
                'release_authority_id',
                'release_generation',
                'release_outcome')
        }
        foreach ($field in $requiredCandidateFields) {
            if (-not (Test-RecoveryValuePresent (
                        Get-FileTransferEventField -Event $Candidate -Name $field -Default ''))) {
                return $false
            }
        }
        foreach ($field in @('route', 'protocol_version', 'live_route_epoch')) {
            if (-not [string]::Equals(
                    (Get-FileTransferEventField -Event $Blocked -Name $field -Default ''),
                    (Get-FileTransferEventField -Event $Candidate -Name $field -Default ''),
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        if (-not (Test-ClosureGrantBlockedRetryMatch -Blocked $Blocked -Grant $Candidate)) {
            return $false
        }

        if ($Candidate.EventName -eq 'runtime_unlock_retry_dispatch_pending_request_rechecked') {
            return (Get-FileTransferEventField -Event $Candidate -Name 'decision_status' -Default '') -in @('Granted', 'Accepted')
        }
        if ((Get-FileTransferAuthoritySchema -Line ([string]$Candidate.RawLine)) -lt 2) {
            return $false
        }

        $installGeneration = Get-FileTransferEventInt64Field -Event $Candidate -Name 'install_generation' -Default 0
        if ($installGeneration -gt 0) {
            $authorityId = Get-FileTransferEventField -Event $Candidate -Name 'authority_id' -Default ''
            [object[]]$matchingEffectiveGrant = @($effectiveGrants | Where-Object {
                [int64]$_.Sequence -eq [int64]$Candidate.Sequence -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'install_generation' -Default 0) -eq $installGeneration -and
                [string]::Equals(
                    (Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default ''),
                    $authorityId,
                    [System.StringComparison]::OrdinalIgnoreCase)
            })
            if ($matchingEffectiveGrant.Count -eq 0) {
                return $false
            }
        }
        return $true
    }

    [object[]]$completeRecoveryWindowEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lifecycle_decided' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @('Accepted', 'Idempotent') -and
        (Get-FileTransferEventField -Event $_ -Name 'lifecycle_outcome' -Default '') -in @('Completed', 'ReceiveProofObserved') -and
        (Test-RecoveryCandidateComplete $_) -and
        (Test-RecoveryValuePresent (Get-RecoveryScopeFieldValue -Event $_ -Name 'direction'))
    })
    [object[]]$potentialGrantEvents = @($events | Where-Object {
        $_.EventName -in @(
            'runtime_unlock_retry_dispatch_pending_request_rechecked',
            'runtime_unlock_retry_dispatch_authority_granted')
    })

    function Get-UniqueRecoveryScopeEvidence {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [switch]$RequireSemanticCandidateBase
        )

        if ($RequireSemanticCandidateBase) {
            foreach ($field in $semanticCandidateBaseFields) {
                if (-not (Test-RecoveryValuePresent (
                            Get-RecoveryScopeFieldValue -Event $Event -Name $field))) {
                    return $null
                }
            }
        }

        $writerId = Get-FileTransferEventField -Event $Event -Name 'log_writer_id' -Default ''
        [object[]]$compatible = @($completeRecoveryWindowEvents | Where-Object {
            $candidateWriterId = Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default ''
            $sequenceEligible = if (Test-RecoveryValuePresent $writerId) {
                (Test-RecoveryValuePresent $candidateWriterId) -and
                [string]::Equals($writerId, $candidateWriterId, [System.StringComparison]::OrdinalIgnoreCase)
            }
            else {
                [int64]$_.Sequence -gt [int64]$Event.Sequence
            }
            $sequenceEligible -and
            (Test-RecoveryPartialScopeCompatible -Partial $Event -Complete $_)
        })
        [object[]]$scopeGroups = @($compatible | Group-Object { Get-RecoveryScopeKey -Event $_ })
        if ($scopeGroups.Count -ne 1) {
            return $null
        }
        return @($scopeGroups[0].Group | Sort-Object Sequence, LineNumber)[0]
    }

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $recordsByChain = @{}
    $chainKeysByScope = @{}
    foreach ($blocked in @($events | Where-Object {
                $_.EventName -eq 'runtime_unlock_retry_blocked_by_regular_v4_receive_recovery'
            })) {
        if (-not (Test-RecoveryCandidateComplete $blocked)) {
            continue
        }
        $scopeEvent = $blocked
        if (-not (Test-RecoveryValuePresent (
                    Get-RecoveryScopeFieldValue -Event $scopeEvent -Name 'direction'))) {
            $scopeEvidence = Get-UniqueRecoveryScopeEvidence `
                -Event $blocked `
                -RequireSemanticCandidateBase
            if ($null -ne $scopeEvidence) {
                $scopeEvent = New-RecoveryScopeEvent -Event $blocked -ScopeEvidence $scopeEvidence
            }
        }

        $scopeKey = Get-RecoveryScopeKey -Event $scopeEvent
        $chainKey = Get-RecoveryChainKey -Event $scopeEvent
        if (-not $recordsByChain.ContainsKey($chainKey)) {
            $rawCandidates.Add($blocked) | Out-Null
            $recordsByChain[$chainKey] = [pscustomobject]@{
                Event = $blocked
                ScopeEvent = $scopeEvent
                ScopeKey = $scopeKey
                ChainKey = $chainKey
            }
        }
        if (-not $chainKeysByScope.ContainsKey($scopeKey)) {
            $chainKeysByScope[$scopeKey] = New-Object System.Collections.Generic.List[string]
        }
        if (-not $chainKeysByScope[$scopeKey].Contains($chainKey)) {
            $chainKeysByScope[$scopeKey].Add($chainKey) | Out-Null
        }
    }

    # Complete Held telemetry is evidence for a blocked chain.  Incomplete Held
    # lines remain raw diagnostics and cannot manufacture another semantic
    # failure.  A complete Held line attaches only to one unambiguous chain.
    foreach ($held in @($events | Where-Object {
                $_.EventName -eq 'runtime_unlock_retry_dispatch_held_by_regular_v4_receive_recovery'
            })) {
        if (-not (Test-RecoveryCandidateComplete $held) -or
            -not (Test-RecoveryValuePresent (
                    Get-RecoveryScopeFieldValue -Event $held -Name 'direction'))) {
            [object[]]$matchingRecords = @($recordsByChain.Values | Where-Object {
                Test-RecoveryPartialScopeCompatible -Partial $held -Complete $_.ScopeEvent
            })
            # Incomplete Held telemetry is diagnostic only.  It can attach to
            # one existing semantic blocked window, but can never create one.
            if ($matchingRecords.Count -eq 1) {
                continue
            }
            continue
        }

        $scopeKey = Get-RecoveryScopeKey -Event $held
        [string[]]$matchingChainKeys = @(
            if ($chainKeysByScope.ContainsKey($scopeKey)) {
                @($chainKeysByScope[$scopeKey])
            }
        )
        if ($matchingChainKeys.Count -eq 1) {
            continue
        }
        if ($matchingChainKeys.Count -gt 1) {
            continue
        }

        $chainKey = $scopeKey + '|held'
        if (-not $recordsByChain.ContainsKey($chainKey)) {
            $rawCandidates.Add($held) | Out-Null
            $recordsByChain[$chainKey] = [pscustomobject]@{
                Event = $held
                ScopeEvent = $held
                ScopeKey = $scopeKey
                ChainKey = $chainKey
            }
        }
    }

    foreach ($explicitMissing in @($events | Where-Object {
                $_.EventName -eq 'runtime_unlock_retry_regular_v4_recovery_settlement_missing'
            })) {
        $baseKey = if (Test-RecoveryCandidateComplete $explicitMissing) {
            Get-RecoveryChainKey -Event $explicitMissing
        }
        else {
            $null
        }
        if ($null -ne $baseKey -and $recordsByChain.ContainsKey($baseKey)) {
            # The explicit runtime event is the authoritative disposition of
            # the already-canonicalized blocked chain.  Replace its anchor;
            # do not count the same semantic boundary a second time.
            $existing = $recordsByChain[$baseKey]
            $recordsByChain[$baseKey] = [pscustomobject]@{
                Event = $explicitMissing
                ScopeEvent = $explicitMissing
                ScopeKey = [string]$existing.ScopeKey
                ChainKey = $baseKey
            }
            continue
        }
        $explicitKey = if ($null -ne $baseKey) {
            $baseKey + '|explicit'
        }
        else {
            'explicit|' + [string]$explicitMissing.Sequence + '|' + [string]$explicitMissing.LineNumber
        }
        if (-not $recordsByChain.ContainsKey($explicitKey)) {
            $rawCandidates.Add($explicitMissing) | Out-Null
            $recordsByChain[$explicitKey] = [pscustomobject]@{
                Event = $explicitMissing
                ScopeEvent = $explicitMissing
                ScopeKey = if (Test-RecoveryCandidateComplete $explicitMissing) {
                    Get-RecoveryScopeKey -Event $explicitMissing
                } else { '(explicit)' }
                ChainKey = $explicitKey
            }
        }
    }

    [object[]]$distinctRecords = @($recordsByChain.Values | Sort-Object { [int64]$_.Event.Sequence })
    $recoveredCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $handoffBypassCandidates = New-Object System.Collections.Generic.List[object]
    [object[]]$boundaryEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_regular_v4_recovery_settlement_missing' -or
        ($_.EventName -eq 'session_liveness_timeout_filetransfer_recovery_state_not_deferred' -and
            (Get-FileTransferEventField -Event $_ -Name 'state' -Default '') -eq 'exhausted' -and
            (Get-FileTransferEventField -Event $_ -Name 'terminal_recommended' -Default '0') -eq '1' -and
            (Get-FileTransferEventField -Event $_ -Name 'receive_proof_observed' -Default '0') -eq '0') -or
        $_.EventName -in @(
            'file_transfer_outbound_terminal',
            'file_transfer_inbound_terminal',
            'transfer_terminal',
            'filetransfer_runtime_terminalized')
    })

    foreach ($record in $distinctRecords) {
        $blocked = $record.Event
        $blockedScope = $record.ScopeEvent
        $blockedSequence = [int64]$blocked.Sequence
        if ($blocked.EventName -eq 'runtime_unlock_retry_regular_v4_recovery_settlement_missing') {
            $unresolvedCandidates.Add($blocked) | Out-Null
            continue
        }

        [object[]]$boundaries = @($boundaryEvents | Where-Object {
            [int64]$_.Sequence -gt $blockedSequence -and
            (Test-RecoveryBoundaryMatch -Blocked $blockedScope -Boundary $_)
        } | Sort-Object Sequence, LineNumber)
        $boundarySequence = if ($boundaries.Count -gt 0) { [int64]$boundaries[0].Sequence } else { [int64]::MaxValue }

        $resolutionEvents = New-Object System.Collections.Generic.List[object]
        foreach ($repairSettlementHandoff in @($resolvedRepairSettlements | Where-Object {
                    [int64]$_.Sequence -gt $blockedSequence -and
                    [int64]$_.Sequence -lt $boundarySequence -and
                    (Test-RecoveryRepairSettlementHandoffMatch `
                        -Blocked $blockedScope `
                        -Settlement $_ `
                        -BoundarySequence $boundarySequence)
                })) {
            $resolutionEvents.Add($repairSettlementHandoff) | Out-Null
        }
        foreach ($legacyResolution in @($events | Where-Object {
                    [int64]$_.Sequence -gt $blockedSequence -and
                    [int64]$_.Sequence -lt $boundarySequence -and
                    $_.EventName -in @(
                        'runtime_unlock_retry_released_after_regular_v4_receive_recovery',
                        'runtime_unlock_retry_rejected_after_regular_v4_receive_recovery') -and
                    (Test-RecoveryScopeMatch -Anchor $blockedScope -Candidate $_)
                })) {
            if ($legacyResolution.EventName -eq 'runtime_unlock_retry_released_after_regular_v4_receive_recovery') {
                [object[]]$phase2ReportsBeforeLegacyRelease = @($events | Where-Object {
                    [int64]$_.Sequence -gt $blockedSequence -and
                    [int64]$_.Sequence -lt [int64]$legacyResolution.Sequence -and
                    $_.EventName -eq 'runtime_unlock_regular_v4_recovery_settlement_reported' -and
                    (Test-RecoveryScopeMatch -Anchor $blockedScope -Candidate $_)
                })
                if ($phase2ReportsBeforeLegacyRelease.Count -gt 0) {
                    continue
                }
            }
            $resolutionEvents.Add($legacyResolution) | Out-Null
        }

        foreach ($decision in @($events | Where-Object {
                    [int64]$_.Sequence -gt $blockedSequence -and
                    [int64]$_.Sequence -lt $boundarySequence -and
                    $_.EventName -eq 'runtime_unlock_regular_v4_recovery_settlement_decided' -and
                    (Get-FileTransferEventField -Event $_ -Name 'disposition' -Default '') -eq 'Consumed' -and
                    (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @('Accepted', 'Idempotent') -and
                    (Test-RecoveryScopeMatch -Anchor $blockedScope -Candidate $_)
                })) {
            [object[]]$reports = @($events | Where-Object {
                [int64]$_.Sequence -gt $blockedSequence -and
                [int64]$_.Sequence -lt [int64]$decision.Sequence -and
                (Test-FileTransferRuntimeUnlockRegularV4RecoveryReportDecisionMatch -Report $_ -Decision $decision)
            })
            if ($reports.Count -gt 0) {
                $resolutionEvents.Add($decision) | Out-Null
            }
        }

        $closureChains = New-Object System.Collections.Generic.List[object]
        foreach ($lifecycle in @($events | Where-Object {
                    [int64]$_.Sequence -lt $boundarySequence -and
                    $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lifecycle_decided' -and
                    (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @('Accepted', 'Idempotent') -and
                    (Get-FileTransferEventField -Event $_ -Name 'lifecycle_outcome' -Default '') -in @('Completed', 'ReceiveProofObserved') -and
                    (Test-RecoveryScopeMatch -Anchor $blockedScope -Candidate $_)
                })) {
            foreach ($retained in @($events | Where-Object {
                        [int64]$_.Sequence -gt [int64]$lifecycle.Sequence -and
                        [int64]$_.Sequence -lt $boundarySequence -and
                        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_retained' -and
                        (Get-FileTransferEventField -Event $_ -Name 'lifecycle_decision_status' -Default '') -in @('Accepted', 'Idempotent') -and
                        (Get-FileTransferEventField -Event $_ -Name 'lifecycle_outcome' -Default '') -in @('Completed', 'ReceiveProofObserved') -and
                        (Test-CompleteRecoveryTupleMatch -Left $lifecycle -Right $_)
                    })) {
                foreach ($adopted in @($events | Where-Object {
                            [int64]$_.Sequence -gt [int64]$retained.Sequence -and
                            [int64]$_.Sequence -gt $blockedSequence -and
                            [int64]$_.Sequence -lt $boundarySequence -and
                        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_adopted' -and
                        (Test-CompleteRecoveryTupleMatch -Left $retained -Right $_) -and
                            (Get-FileTransferEventField -Event $retained -Name 'lease_generation' -Default '') -eq
                                (Get-FileTransferEventField -Event $_ -Name 'lease_generation' -Default '')
                        })) {
                    foreach ($consumed in @($events | Where-Object {
                                [int64]$_.Sequence -gt [int64]$adopted.Sequence -and
                                [int64]$_.Sequence -lt $boundarySequence -and
                                $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_consumed' -and
                                (Test-CompleteRecoveryTupleMatch -Left $adopted -Right $_) -and
                                (Get-FileTransferEventField -Event $adopted -Name 'lease_generation' -Default '') -eq
                                    (Get-FileTransferEventField -Event $_ -Name 'lease_generation' -Default '')
                            })) {
                        foreach ($grant in @($effectiveGrants | Where-Object {
                                    [int64]$_.Sequence -gt [int64]$consumed.Sequence -and
                                    [int64]$_.Sequence -lt $boundarySequence -and
                                    (Test-ClosureGrantNonAuthorityTupleMatch -Consumed $consumed -Grant $_) -and
                                    (Test-RecoveryAuthorityEvidenceSetCompatible -Values @(
                                        (Get-FileTransferEventField -Event $retained -Name 'lease_authority_id' -Default ''),
                                        (Get-FileTransferEventField -Event $adopted -Name 'lease_authority_id' -Default ''),
                                        (Get-FileTransferEventField -Event $consumed -Name 'lease_authority_id' -Default ''),
                                        (Get-FileTransferEventField -Event $_ -Name 'release_authority_id' -Default ''))) -and
                                    (Test-RecoveryAuthorityEvidenceSetCompatible -Values @(
                                        (Get-FileTransferEventField -Event $consumed -Name 'retry_authority_id' -Default ''),
                                        (Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default ''))) -and
                                    (Test-ClosureGrantBlockedRetryMatch -Blocked $blocked -Grant $_)
                                })) {
                            $closureChains.Add([pscustomobject]@{
                                Lifecycle = $lifecycle
                                Retained = $retained
                                Adopted = $adopted
                                Consumed = $consumed
                                Grant = $grant
                                Key = (@(
                                        (Get-FileTransferEventField -Event $grant -Name 'authority_id' -Default '(missing)'),
                                        (Get-FileTransferEventField -Event $grant -Name 'install_generation' -Default '(missing)'),
                                        (Get-FileTransferEventField -Event $grant -Name 'direction' -Default '(missing)'),
                                        (Get-FileTransferEventField -Event $grant -Name 'release_generation' -Default '(missing)'),
                                        (Get-FileTransferEventField -Event $retained -Name 'lease_authority_id' -Default '(missing)'),
                                        (Get-FileTransferEventField -Event $adopted -Name 'lease_authority_id' -Default '(missing)'),
                                        (Get-FileTransferEventField -Event $consumed -Name 'lease_authority_id' -Default '(missing)'),
                                        (Get-FileTransferEventField -Event $consumed -Name 'retry_authority_id' -Default '(missing)')) -join '|')
                            }) | Out-Null
                        }
                    }
                }
            }
        }
        [object[]]$distinctClosureChains = @($closureChains.ToArray() | Group-Object Key | ForEach-Object { $_.Group[0] })
        if ($distinctClosureChains.Count -eq 1) {
            $resolutionEvents.Add($distinctClosureChains[0].Grant) | Out-Null
        }

        [object[]]$orderedResolutions = @($resolutionEvents.ToArray() | Sort-Object Sequence, LineNumber)
        $firstResolutionSequence = if ($orderedResolutions.Count -gt 0) {
            [int64]$orderedResolutions[0].Sequence
        }
        else {
            [int64]::MaxValue
        }
        [object[]]$prematureGrants = @($potentialGrantEvents | Where-Object {
            [int64]$_.Sequence -gt $blockedSequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            [int64]$_.Sequence -lt $firstResolutionSequence -and
            (Test-RecoveryPotentialGrantMatch -Blocked $blockedScope -Candidate $_)
        } | Sort-Object Sequence, LineNumber)
        if ($prematureGrants.Count -gt 0) {
            $handoffBypassCandidates.Add($prematureGrants[0]) | Out-Null
        }
        elseif ($orderedResolutions.Count -gt 0) {
            $recoveredCandidates.Add($blocked) | Out-Null
        }
        elseif ($boundaries.Count -gt 0) {
            $unresolvedCandidates.Add($boundaries[0]) | Out-Null
        }
    }

    # A more precise retained-closure liveness failure owns the same terminal
    # boundary.  Do not report that terminal again as settlement missing.
    [object[]]$closureLivenessFailureEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_liveness_deferral_rejected' -or
        ($_.EventName -eq 'filetransfer_recovery_authority_rejected' -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default (
                Get-FileTransferEventField -Event $_ -Name 'reason' -Default '')) -eq
                'recovery_liveness_lease_missing')
    })
    if ($closureLivenessFailureEvents.Count -gt 0 -and $unresolvedCandidates.Count -gt 0) {
        [object[]]$authoritativeExplicit = @($unresolvedCandidates.ToArray() | Where-Object {
            $_.EventName -eq 'runtime_unlock_retry_regular_v4_recovery_settlement_missing'
        })
        [object[]]$inferredSettlementMissing = @($unresolvedCandidates.ToArray() | Where-Object {
            $_.EventName -ne 'runtime_unlock_retry_regular_v4_recovery_settlement_missing'
        })
        [object[]]$uncovered = @(
            Get-FileTransferUncoveredRuntimeUnlockRegularV4RecoverySettlementMissingEvents `
                -SettlementMissingEvents $inferredSettlementMissing `
                -ClosureLivenessFailureEvents $closureLivenessFailureEvents
        )
        $unresolvedCandidates.Clear()
        foreach ($candidate in @($authoritativeExplicit + $uncovered | Sort-Object Sequence, LineNumber)) {
            $unresolvedCandidates.Add($candidate) | Out-Null
        }
    }

    $verdict = if ($unresolvedCandidates.Count -gt 0) {
        'fail'
    }
    elseif ($distinctRecords.Count -gt 0 -and $recoveredCandidates.Count -eq $distinctRecords.Count) {
        'pass'
    }
    elseif ($distinctRecords.Count -gt 0) {
        'pending'
    }
    else {
        'none'
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctRecords.Count
        RecoveredCount = $recoveredCandidates.Count
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = $verdict
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctRecords | ForEach-Object { $_.Event })
        RecoveredCandidateEvents = @($recoveredCandidates.ToArray())
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
        HandoffBypassCount = $handoffBypassCandidates.Count
        HandoffBypassCandidateEvents = @($handoffBypassCandidates.ToArray())
    }
}

function Get-FileTransferRuntimeUnlockPostTunaFallbackTransportProofHandoffCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [AllowEmptyCollection()][object[]]$EffectiveGrantEvents = @()
    )

    [object[]]$events = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$heldEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_runtime_unlock_precommit_probe_pending_held' -and
        (Get-FileTransferEventField -Event $_ -Name 'hold_reason' -Default '') -eq 'transport_proof_missing' -and
        (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'post_tuna_fallback_v6'
    })
    [object[]]$retryEvents = @($events | Where-Object {
        $_.EventName -eq 'tuna_acceleration_retry_fired' -and
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq
            'runtime_unlock_after_fallback_tail_quiescent'
    })
    [object[]]$proofReplayHeldEvents = @($events | Where-Object {
        (($_.EventName -eq 'filetransfer_runtime_unlock_admission_denied' -and
            (Get-FileTransferEventField -Event $_ -Name 'admission_reason' -Default '') -eq 'fallback_proof_replay_pending') -or
        ($_.EventName -eq 'filetransfer_runtime_unlock_fallback_survival_resume_held' -and
            (Get-FileTransferEventField -Event $_ -Name 'admission_reason' -Default '') -eq 'fallback_proof_replay_pending'))
    })
    [object[]]$activationIntentEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_post_tuna_fallback_activation_intent_retained'
    })
    [object[]]$scheduledEvents = @($events | Where-Object {
        $_.EventName -eq 'tuna_acceleration_timeline' -and
        (Get-FileTransferEventField -Event $_ -Name 'status' -Default '') -like
            'negotiation_scheduled_runtime_unlock*'
    })

    function Test-HandoffSessionMatch {
        param(
            [Parameter(Mandatory = $true)]$Anchor,
            [Parameter(Mandatory = $true)]$Candidate
        )

        $anchorSession = Get-FileTransferEventField -Event $Anchor -Name 'session_id' -Default ''
        $candidateSession = Get-FileTransferEventField -Event $Candidate -Name 'session_id' -Default ''
        return -not [string]::IsNullOrWhiteSpace($anchorSession) -and
            -not [string]::IsNullOrWhiteSpace($candidateSession) -and
            [string]::Equals($anchorSession, $candidateSession, [System.StringComparison]::OrdinalIgnoreCase)
    }

    function Test-HandoffScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Scope,
            [Parameter(Mandatory = $true)]$Candidate
        )

        foreach ($field in @('session_id', 'transfer_id')) {
            $scopeValue = Get-FileTransferEventField -Event $Scope -Name $field -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($scopeValue) -or
                $scopeValue -in @('(none)', 'none') -or
                [string]::IsNullOrWhiteSpace($candidateValue) -or
                $candidateValue -in @('(none)', 'none') -or
                -not [string]::Equals(
                    $scopeValue,
                    $candidateValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        $scopeDirection = Get-FileTransferEventField -Event $Scope -Name 'direction' -Default ''
        $candidateDirection = Get-FileTransferEventField -Event $Candidate -Name 'direction' -Default ''
        if ([string]::IsNullOrWhiteSpace($candidateDirection)) {
            if ($Candidate.EventName -eq 'file_transfer_outbound_terminal') {
                $candidateDirection = 'outbound'
            }
            elseif ($Candidate.EventName -eq 'file_transfer_inbound_terminal') {
                $candidateDirection = 'inbound'
            }
        }
        if ([string]::IsNullOrWhiteSpace($scopeDirection) -or
            [string]::IsNullOrWhiteSpace($candidateDirection) -or
            -not [string]::Equals(
                $scopeDirection,
                $candidateDirection,
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }

        foreach ($field in @(
                'route',
                'protocol_version',
                'live_route_epoch',
                'runtime_generation',
                'terminal_generation',
                'leg_generation')) {
            $scopeValue = Get-FileTransferEventField -Event $Scope -Name $field -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $field -Default ''
            if (-not [string]::IsNullOrWhiteSpace($candidateValue) -and
                $candidateValue -notin @('(none)', 'none') -and
                ([string]::IsNullOrWhiteSpace($scopeValue) -or
                    $scopeValue -in @('(none)', 'none') -or
                    -not [string]::Equals(
                        $scopeValue,
                        $candidateValue,
                        [System.StringComparison]::OrdinalIgnoreCase))) {
                return $false
            }
        }
        return $true
    }

    function Test-HandoffScopeComplete {
        param([Parameter(Mandatory = $true)]$Event)

        foreach ($field in @(
                'session_id',
                'transfer_id',
                'direction',
                'route',
                'protocol_version',
                'live_route_epoch',
                'runtime_generation',
                'terminal_generation',
                'leg_generation')) {
            $value = Get-FileTransferEventField -Event $Event -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($value) -or $value -in @('(none)', 'none')) {
                return $false
            }
        }
        return $true
    }

    function Test-HandoffPositiveGeneration {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string]$Name
        )

        [int64]$generation = 0
        $value = Get-FileTransferEventField -Event $Event -Name $Name -Default ''
        return [int64]::TryParse($value, [ref]$generation) -and $generation -gt 0
    }

    function Test-HandoffExactFieldMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right,
            [Parameter(Mandatory = $true)][string[]]$Fields
        )

        foreach ($field in $Fields) {
            $leftValue = Get-FileTransferEventField -Event $Left -Name $field -Default ''
            $rightValue = Get-FileTransferEventField -Event $Right -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                $leftValue -in @('(none)', 'none') -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                $rightValue -in @('(none)', 'none') -or
                -not [string]::Equals(
                    $leftValue,
                    $rightValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    [string[]]$exactIntentScopeFields = @(
        'session_id',
        'transfer_id',
        'direction',
        'route',
        'protocol_version',
        'live_route_epoch',
        'runtime_generation',
        'terminal_generation',
        'leg_generation',
        'route_publication_generation',
        'route_commit_generation',
        'target_route',
        'target_protocol_version',
        'target_transport',
        'fallback_leg_generation',
        'fallback_transport_epoch',
        'fallback_bridge_recovery_generation',
        'data_session_generation',
        'admission_granted',
        'admission_reason',
        'intent_generation')
    [string[]]$exactOperationScopeFields = @(
        $exactIntentScopeFields + @(
            'operation_generation',
            'payer_decision_id',
            'retry_authority_id',
            'install_generation'))

    function Test-HandoffExactIntentScopeComplete {
        param([Parameter(Mandatory = $true)]$Event)

        if (-not (Test-HandoffExactFieldMatch `
                -Left $Event `
                -Right $Event `
                -Fields $exactIntentScopeFields)) {
            return $false
        }
        return (Test-HandoffPositiveGeneration -Event $Event -Name 'intent_generation')
    }

    function Test-HandoffExactOperationScopeComplete {
        param([Parameter(Mandatory = $true)]$Event)

        if (-not (Test-HandoffExactFieldMatch `
                -Left $Event `
                -Right $Event `
                -Fields $exactOperationScopeFields)) {
            return $false
        }
        return (Test-HandoffPositiveGeneration -Event $Event -Name 'intent_generation') -and
            (Test-HandoffPositiveGeneration -Event $Event -Name 'operation_generation')
    }

    function Test-HandoffEffectiveGrantMatch {
        param(
            [Parameter(Mandatory = $true)]$Scheduled,
            [Parameter(Mandatory = $true)]$Grant
        )

        if ([int64]$Grant.Sequence -ge [int64]$Scheduled.Sequence -or
            -not (Test-HandoffExactFieldMatch `
                -Left $Scheduled `
                -Right $Grant `
                -Fields @('session_id', 'transfer_id', 'direction'))) {
            return $false
        }

        $retryAuthorityId = Get-FileTransferEventField `
            -Event $Scheduled `
            -Name 'retry_authority_id' `
            -Default ''
        $grantAuthorityId = Get-FileTransferEventField -Event $Grant -Name 'authority_id' -Default ''
        $scheduledInstallGeneration = Get-FileTransferEventField `
            -Event $Scheduled `
            -Name 'install_generation' `
            -Default ''
        $grantInstallGeneration = Get-FileTransferEventField `
            -Event $Grant `
            -Name 'install_generation' `
            -Default ''
        if ([string]::IsNullOrWhiteSpace($retryAuthorityId) -or
            $retryAuthorityId -in @('(none)', 'none') -or
            -not [string]::Equals($retryAuthorityId, $grantAuthorityId, [System.StringComparison]::Ordinal) -or
            [string]::IsNullOrWhiteSpace($scheduledInstallGeneration) -or
            -not [string]::Equals(
                $scheduledInstallGeneration,
                $grantInstallGeneration,
                [System.StringComparison]::Ordinal)) {
            return $false
        }

        $predecessor = Get-FileTransferEventField -Event $Grant -Name 'predecessor_authority_id' -Default ''
        return (Get-FileTransferEventField -Event $Grant -Name 'release_kind' -Default '') -eq
                'FallbackPairedTailYield' -and
            (Get-FileTransferEventField -Event $Grant -Name 'dispatch_attempt_generation' -Default '') -eq '1' -and
            (Get-FileTransferEventField -Event $Grant -Name 'missing_dispatch_successor_generation' -Default '') -eq '0' -and
            $predecessor -in @('(none)', 'none') -and
            (Get-FileTransferEventField `
                -Event $Grant `
                -Name 'request_active_predecessor_supersession' `
                -Default '') -eq '0'
    }

    function Get-HandoffScopeKey {
        param([Parameter(Mandatory = $true)]$Event)

        return (@(
                'session_id',
                'transfer_id',
                'direction',
                'route',
                'protocol_version',
                'live_route_epoch',
                'runtime_generation',
                'terminal_generation',
                'leg_generation',
                'route_publication_generation',
                'route_commit_generation',
                'transport_epoch',
                'bridge_recovery_generation',
                'data_session_generation',
                'admission_generation') | ForEach-Object {
                    (Get-FileTransferEventField -Event $Event -Name $_ -Default '(missing)').ToLowerInvariant()
                }) -join '|'
    }

    function New-HandoffScopeEvent {
        param(
            [Parameter(Mandatory = $true)]$Held,
            [Parameter(Mandatory = $true)]$Publication
        )

        $fields = @{}
        if ($null -ne $Publication.Fields) {
            foreach ($name in @($Publication.Fields.Keys)) {
                $fields[$name] = $Publication.Fields[$name]
            }
        }
        if ($null -ne $Held.Fields) {
            foreach ($name in @($Held.Fields.Keys)) {
                $fields[$name] = $Held.Fields[$name]
            }
        }
        return [pscustomobject]@{
            EventName = [string]$Held.EventName
            Sequence = [int64]$Held.Sequence
            LineNumber = [int]$Held.LineNumber
            FilePath = [string]$Held.FilePath
            FileName = [string]$Held.FileName
            Message = [string]$Held.Message
            RawLine = [string]$Held.RawLine
            TransferId = [string]$Held.TransferId
            Fields = $fields
        }
    }

    function Test-HandoffSharedTransferScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Scope,
            [Parameter(Mandatory = $true)]$Candidate
        )

        foreach ($field in @(
                'session_id',
                'transfer_id',
                'route',
                'protocol_version',
                'live_route_epoch',
                'runtime_generation',
                'terminal_generation',
                'leg_generation')) {
            $scopeValue = Get-FileTransferEventField -Event $Scope -Name $field -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($scopeValue) -or
                $scopeValue -in @('(none)', 'none') -or
                [string]::IsNullOrWhiteSpace($candidateValue) -or
                $candidateValue -in @('(none)', 'none') -or
                -not [string]::Equals(
                    $scopeValue,
                    $candidateValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Test-HandoffDisposition {
        param([Parameter(Mandatory = $true)]$Event)

        if ($Event.EventName -in @(
                'runtime_unlock_post_tuna_fallback_activation_disposition',
                'runtime_unlock_filetransfer_owner_accepted_before_path_lease',
                'runtime_unlock_filetransfer_owner_rejected_before_path_lease',
                'runtime_unlock_filetransfer_owner_missing_before_path_lease',
                'runtime_unlock_filetransfer_owner_stale_before_offer_dispatch',
                'tuna_path_lease_started',
                'tuna_acceleration_activation_offer_sent',
                'tuna_acceleration_activation_offer_queued',
                'filetransfer_runtime_unlock_precommit_probe_waiting_for_transport_proof',
                'filetransfer_runtime_unlock_precommit_probe_pending_held',
                'filetransfer_runtime_unlock_precommit_probe_pending_rejected',
                'runtime_unlock_precommit_probe_started',
                'runtime_unlock_precommit_probe_sent',
                'tuna_acceleration_runtime_unlock_dispatch_deferred_for_regular_v4_receive_recovery',
                'tuna_acceleration_runtime_unlock_retry_suppressed',
                'tuna_acceleration_negotiation_scheduling_started',
                'tuna_acceleration_negotiation_scheduling_held',
                'tuna_acceleration_negotiation_scheduling_rejected',
                'tuna_acceleration_negotiation_scheduling_invalidated',
                'tuna_acceleration_negotiation_scheduling_completed')) {
            if ($Event.EventName -eq 'runtime_unlock_post_tuna_fallback_activation_disposition') {
                return (Get-FileTransferEventField -Event $Event -Name 'disposition' -Default '') -in @(
                    'started', 'held', 'rejected', 'invalidated', 'completed')
            }
            return $true
        }
        if ($Event.EventName -eq 'tuna_acceleration_timeline') {
            $status = Get-FileTransferEventField -Event $Event -Name 'status' -Default ''
            return $status -in @(
                'negotiation_started_runtime_unlock',
                'negotiation_held_runtime_unlock',
                'negotiation_rejected_runtime_unlock',
                'negotiation_invalidated_runtime_unlock',
                'negotiation_completed_runtime_unlock')
        }
        return $false
    }

    function Get-HandoffNewDisposition {
        param([Parameter(Mandatory = $true)]$Event)

        if ($Event.EventName -eq 'runtime_unlock_post_tuna_fallback_activation_disposition') {
            return Get-FileTransferEventField -Event $Event -Name 'disposition' -Default ''
        }
        if ($Event.EventName -like 'tuna_acceleration_negotiation_scheduling_*') {
            return $Event.EventName.Substring('tuna_acceleration_negotiation_scheduling_'.Length)
        }
        return ''
    }

    function Test-HandoffLegacyDispositionIdentityMatch {
        param(
            [Parameter(Mandatory = $true)]$Scheduled,
            [Parameter(Mandatory = $true)]$Scope,
            [Parameter(Mandatory = $true)]$Candidate
        )

        $scheduledPayerDecisionId = Get-FileTransferEventField -Event $Scheduled -Name 'payer_decision_id' -Default ''
        $candidatePayerDecisionId = Get-FileTransferEventField -Event $Candidate -Name 'payer_decision_id' -Default ''
        if (-not [string]::IsNullOrWhiteSpace($candidatePayerDecisionId) -and
            $candidatePayerDecisionId -notin @('(none)', 'none')) {
            return (Test-HandoffSessionMatch -Anchor $Scheduled -Candidate $Candidate) -and
                -not [string]::IsNullOrWhiteSpace($scheduledPayerDecisionId) -and
                [string]::Equals(
                    $scheduledPayerDecisionId,
                    $candidatePayerDecisionId,
                    [System.StringComparison]::OrdinalIgnoreCase)
        }
        return Test-HandoffScopeMatch -Scope $Scope -Candidate $Candidate
    }

    function Test-HandoffExactStartedEvidence {
        param(
            [Parameter(Mandatory = $true)]$Scheduled,
            [Parameter(Mandatory = $true)]$Scope,
            [Parameter(Mandatory = $true)]$Started
        )

        if ((Get-HandoffNewDisposition -Event $Started) -ne 'started' -or
            -not (Test-HandoffExactOperationScopeComplete -Event $Started) -or
            -not (Test-HandoffLegacyDispositionIdentityMatch `
                -Scheduled $Scheduled `
                -Scope $Scope `
                -Candidate $Started)) {
            return $false
        }

        [object[]]$matchingIntents = @($activationIntentEvents | Where-Object {
            [int64]$_.Sequence -lt [int64]$Started.Sequence -and
            (Test-HandoffExactIntentScopeComplete -Event $_) -and
            (Test-HandoffExactFieldMatch `
                -Left $Started `
                -Right $_ `
                -Fields $exactIntentScopeFields)
        })
        [object[]]$matchingGrants = @($EffectiveGrantEvents | Where-Object {
            Test-HandoffEffectiveGrantMatch -Scheduled $Started -Grant $_
        })
        return $matchingIntents.Count -gt 0 -and $matchingGrants.Count -gt 0
    }

    function Test-HandoffDispositionMatch {
        param(
            [Parameter(Mandatory = $true)]$Scheduled,
            [Parameter(Mandatory = $true)]$Scope,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if (-not (Test-HandoffDisposition $Candidate)) {
            return $false
        }

        $newDisposition = Get-HandoffNewDisposition -Event $Candidate
        if ($newDisposition -eq 'started') {
            return $false
        }

        [object[]]$matchingStarted = @($events | Where-Object {
            [int64]$_.Sequence -gt [int64]$Scheduled.Sequence -and
            [int64]$_.Sequence -lt [int64]$Candidate.Sequence -and
            (Test-HandoffExactStartedEvidence `
                -Scheduled $Scheduled `
                -Scope $Scope `
                -Started $_)
        })

        if (-not [string]::IsNullOrWhiteSpace($newDisposition)) {
            if ($newDisposition -notin @('held', 'rejected', 'invalidated', 'completed') -or
                -not (Test-HandoffExactOperationScopeComplete -Event $Candidate)) {
                return $false
            }
            return @($matchingStarted | Where-Object {
                Test-HandoffExactFieldMatch `
                    -Left $_ `
                    -Right $Candidate `
                    -Fields $exactOperationScopeFields
            }).Count -gt 0
        }

        if (-not (Test-HandoffLegacyDispositionIdentityMatch `
                -Scheduled $Scheduled `
                -Scope $Scope `
                -Candidate $Candidate)) {
            return $false
        }

        [object[]]$matchingNewIntents = @($activationIntentEvents | Where-Object {
            [int64]$_.Sequence -lt [int64]$Candidate.Sequence -and
            (Test-HandoffExactIntentScopeComplete -Event $_) -and
            (Test-HandoffScopeMatch -Scope $Scope -Candidate $_)
        })
        return $matchingNewIntents.Count -eq 0 -or $matchingStarted.Count -gt 0
    }

    function Test-HandoffReplacement {
        param(
            [Parameter(Mandatory = $true)]$Scope,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if ($Candidate.EventName -notin @(
                'filetransfer_route_selected',
                'filetransfer_runtime_started',
                'filetransfer_route_hint_authorized_publication_accepted')) {
            return $false
        }
        foreach ($field in @('session_id', 'transfer_id')) {
            $scopeValue = Get-FileTransferEventField -Event $Scope -Name $field -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($scopeValue) -or
                [string]::IsNullOrWhiteSpace($candidateValue) -or
                -not [string]::Equals($scopeValue, $candidateValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        $scopeDirection = Get-FileTransferEventField -Event $Scope -Name 'direction' -Default ''
        $candidateDirection = Get-FileTransferEventField -Event $Candidate -Name 'direction' -Default ''
        if ([string]::IsNullOrWhiteSpace($scopeDirection) -or
            [string]::IsNullOrWhiteSpace($candidateDirection) -or
            -not [string]::Equals($scopeDirection, $candidateDirection, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }

        foreach ($field in @('route', 'protocol_version', 'live_route_epoch', 'runtime_generation', 'terminal_generation', 'leg_generation')) {
            $scopeValue = Get-FileTransferEventField -Event $Scope -Name $field -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $field -Default ''
            if (-not [string]::IsNullOrWhiteSpace($candidateValue) -and
                $candidateValue -notin @('(none)', 'none') -and
                -not [string]::Equals($scopeValue, $candidateValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $true
            }
        }

        # Same-route replacement is still an invalidation when a scoped
        # publication, admission, transport, bridge, or data-session
        # generation moves.  Compare only fields present on both sides; an
        # incomplete diagnostic cannot manufacture a replacement boundary.
        foreach ($fieldAliases in @(
                @('route_publication_generation', 'route_publication_generation', 'publication_generation'),
                @('route_commit_generation', 'route_commit_generation'),
                @('transport_epoch', 'transport_epoch'),
                @('bridge_recovery_generation', 'bridge_recovery_generation'),
                @('data_session_generation', 'data_session_generation'),
                @('admission_generation', 'admission_generation'))) {
            $scopeValue = Get-FileTransferEventField -Event $Scope -Name $fieldAliases[0] -Default ''
            if ([string]::IsNullOrWhiteSpace($scopeValue) -or $scopeValue -in @('(none)', 'none')) {
                continue
            }
            $candidateValue = ''
            foreach ($candidateName in @($fieldAliases | Select-Object -Skip 1)) {
                $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $candidateName -Default ''
                if (-not [string]::IsNullOrWhiteSpace($candidateValue) -and
                    $candidateValue -notin @('(none)', 'none')) {
                    break
                }
            }
            if (-not [string]::IsNullOrWhiteSpace($candidateValue) -and
                $candidateValue -notin @('(none)', 'none') -and
                -not [string]::Equals(
                    $scopeValue,
                    $candidateValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $true
            }
        }
        return $false
    }

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctByKey = @{}
    foreach ($scheduled in $scheduledEvents) {
        $scheduledSequence = [int64]$scheduled.Sequence
        [object[]]$matchingHeld = @($heldEvents | Where-Object {
            [int64]$_.Sequence -lt $scheduledSequence -and
            (Test-HandoffScopeComplete $_) -and
            (Test-HandoffSessionMatch -Anchor $scheduled -Candidate $_)
        })
        [object[]]$matchingHeldScopeGroups = @($matchingHeld | Group-Object { Get-HandoffScopeKey -Event $_ })
        if ($matchingHeldScopeGroups.Count -ne 1) {
            continue
        }
        $held = @($matchingHeldScopeGroups[0].Group | Sort-Object Sequence -Descending)[0]
        $scope = $held
        [object[]]$publicationScopeEvidence = @($events | Where-Object {
            [int64]$_.Sequence -lt [int64]$held.Sequence -and
            $_.EventName -in @(
                'filetransfer_route_selected',
                'filetransfer_runtime_started',
                'filetransfer_route_hint_authorized_publication_accepted') -and
            (Test-HandoffScopeMatch -Scope $held -Candidate $_)
        } | Sort-Object Sequence, LineNumber)
        if ($publicationScopeEvidence.Count -gt 0) {
            $scope = New-HandoffScopeEvent `
                -Held $held `
                -Publication $publicationScopeEvidence[-1]
        }
        $scheduledWriterId = Get-FileTransferEventField -Event $scheduled -Name 'log_writer_id' -Default ''
        $heldWriterId = Get-FileTransferEventField -Event $held -Name 'log_writer_id' -Default ''
        [object[]]$matchingRetry = @($retryEvents | Where-Object {
            $retryWriterId = Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default ''
            $writerMatches = if (-not [string]::IsNullOrWhiteSpace($scheduledWriterId)) {
                -not [string]::IsNullOrWhiteSpace($retryWriterId) -and
                [string]::Equals($retryWriterId, $scheduledWriterId, [System.StringComparison]::OrdinalIgnoreCase) -and
                ([string]::IsNullOrWhiteSpace($heldWriterId) -or
                    [string]::Equals($retryWriterId, $heldWriterId, [System.StringComparison]::OrdinalIgnoreCase))
            }
            else {
                [string]::IsNullOrWhiteSpace($retryWriterId)
            }
            return [int64]$_.Sequence -gt [int64]$held.Sequence -and
            [int64]$_.Sequence -lt $scheduledSequence -and
            $writerMatches
        } | Group-Object {
            $retryWriterId = Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default ''
            if ([string]::IsNullOrWhiteSpace($retryWriterId)) {
                return ('legacy|' + [string]$_.RawLine).ToLowerInvariant()
            }
            return (@(
                        $retryWriterId,
                        (Get-FileTransferEventField -Event $_ -Name 'log_writer_sequence' -Default '(missing)'),
                        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '(missing)')) -join '|').ToLowerInvariant()
        } | ForEach-Object { $_.Group[0] })
        [object[]]$matchingReplayHold = @($proofReplayHeldEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$held.Sequence -and
            [int64]$_.Sequence -lt $scheduledSequence -and
            (Test-HandoffSharedTransferScopeMatch -Scope $held -Candidate $_)
        })
        if ($matchingRetry.Count -eq 0 -or $matchingReplayHold.Count -eq 0) {
            continue
        }

        # Multiple legitimate retries may occur while proof replay remains
        # active.  The latest eligible retry is the trigger owned by this
        # scheduled operation; earlier retries are diagnostics, not
        # ambiguity.
        $matchingRetry = @($matchingRetry | Sort-Object Sequence, LineNumber)
        $retry = $matchingRetry[-1]
        $hasExactIntent = @($activationIntentEvents | Where-Object {
            [int64]$_.Sequence -lt $scheduledSequence -and
            (Test-HandoffExactIntentScopeComplete -Event $_) -and
            (Test-HandoffScopeMatch -Scope $scope -Candidate $_)
        }).Count -gt 0

        $rawCandidates.Add($scheduled) | Out-Null
        $key = (@(
                (Get-FileTransferEventField -Event $scheduled -Name 'session_id' -Default '(missing)'),
                (Get-FileTransferEventField -Event $scope -Name 'transfer_id' -Default '(missing)'),
                (Get-FileTransferEventField -Event $scope -Name 'direction' -Default '(missing)'),
                (Get-FileTransferEventField -Event $scope -Name 'route' -Default '(missing)'),
                (Get-FileTransferEventField -Event $scope -Name 'live_route_epoch' -Default '(missing)'),
                (Get-FileTransferEventField -Event $scope -Name 'runtime_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $scope -Name 'route_publication_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $scope -Name 'admission_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $retry -Name 'log_writer_id' -Default '(legacy)'),
                (Get-FileTransferEventField -Event $retry -Name 'log_writer_sequence' -Default ([string]$retry.Sequence)),
                (Get-FileTransferEventField -Event $scheduled -Name 'payer_decision_id' -Default '(missing)')) -join '|').ToLowerInvariant()
        if (-not $distinctByKey.ContainsKey($key)) {
            $distinctByKey[$key] = [pscustomobject]@{
                Event = $scheduled
                Held = $held
                Scope = $scope
                Key = $key
                HasExactIntent = $hasExactIntent
            }
        }
    }

    [object[]]$distinctRecords = @($distinctByKey.Values | Sort-Object { [int64]$_.Event.Sequence })
    $recovered = New-Object System.Collections.Generic.List[object]
    $unresolved = New-Object System.Collections.Generic.List[object]
    foreach ($record in $distinctRecords) {
        $scheduled = $record.Event
        $held = $record.Held
        $scope = $record.Scope
        $scheduledSequence = [int64]$scheduled.Sequence
        [object[]]$terminalEvents = @($events | Where-Object {
            [int64]$_.Sequence -gt $scheduledSequence -and
            $_.EventName -in @(
                'file_transfer_outbound_terminal',
                'file_transfer_inbound_terminal',
                'transfer_terminal',
                'filetransfer_runtime_terminalized') -and
            (Test-HandoffScopeMatch -Scope $scope -Candidate $_)
        } | Sort-Object Sequence, LineNumber)
        $terminalSequence = if ($terminalEvents.Count -gt 0) { [int64]$terminalEvents[0].Sequence } else { [int64]::MaxValue }
        [object[]]$replacementEvents = @($events | Where-Object {
            [int64]$_.Sequence -gt $scheduledSequence -and
            [int64]$_.Sequence -lt $terminalSequence -and
            (Test-HandoffReplacement -Scope $scope -Candidate $_)
        } | Sort-Object Sequence, LineNumber)
        $replacementSequence = if ($replacementEvents.Count -gt 0) { [int64]$replacementEvents[0].Sequence } else { [int64]::MaxValue }
        $boundarySequence = [Math]::Min($terminalSequence, $replacementSequence)
        [object[]]$dispositions = @($events | Where-Object {
            [int64]$_.Sequence -gt $scheduledSequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-HandoffDispositionMatch -Scheduled $scheduled -Scope $scope -Candidate $_)
        } | Sort-Object Sequence, LineNumber)
        if ($dispositions.Count -gt 0) {
            $recovered.Add($scheduled) | Out-Null
        }
        elseif (-not $record.HasExactIntent -and $replacementEvents.Count -gt 0) {
            $recovered.Add($scheduled) | Out-Null
        }
        elseif ($terminalEvents.Count -gt 0 -or
            ($record.HasExactIntent -and $replacementEvents.Count -gt 0)) {
            $unresolved.Add($scheduled) | Out-Null
        }
    }

    $verdict = if ($unresolved.Count -gt 0) {
        'fail'
    }
    elseif ($distinctRecords.Count -gt 0 -and $recovered.Count -eq $distinctRecords.Count) {
        'pass'
    }
    elseif ($distinctRecords.Count -gt 0) {
        'pending'
    }
    else {
        'none'
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctRecords.Count
        RecoveredCount = $recovered.Count
        UnresolvedCount = $unresolved.Count
        Verdict = $verdict
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctRecords | ForEach-Object { $_.Event })
        RecoveredCandidateEvents = @($recovered.ToArray())
        UnresolvedCandidateEvents = @($unresolved.ToArray())
    }
}

function Get-FileTransferRuntimeUnlockUncommittedTunaFallbackProofAuthorityCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @()
    )

    [object[]]$events = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$proofEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_post_tuna_fallback_nkn_proved'
    })
    [object[]]$bindingEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_uncommitted_tuna_fallback_peer_proof_binding_decided'
    })

    function Get-ProofAuthorityField {
        param([Parameter(Mandatory = $true)]$Event, [Parameter(Mandatory = $true)][string]$Name)
        $value = Get-FileTransferEventField -Event $Event -Name $Name -Default ''
        if ([string]::IsNullOrWhiteSpace($value) -or $value -in @('(none)', 'none', '(missing)', '__missing__')) {
            return ''
        }
        return $value
    }

    function Test-ProofAuthoritySameWriter {
        param([Parameter(Mandatory = $true)]$Left, [Parameter(Mandatory = $true)]$Right)
        $leftWriter = Get-ProofAuthorityField -Event $Left -Name 'log_writer_id'
        $rightWriter = Get-ProofAuthorityField -Event $Right -Name 'log_writer_id'
        return -not [string]::IsNullOrWhiteSpace($leftWriter) -and
            [string]::Equals($leftWriter, $rightWriter, [System.StringComparison]::OrdinalIgnoreCase)
    }

    $raw = New-Object System.Collections.Generic.List[object]
    $distinct = New-Object System.Collections.Generic.List[object]
    $recovered = New-Object System.Collections.Generic.List[object]
    $unresolved = New-Object System.Collections.Generic.List[object]
    $downstream = New-Object System.Collections.Generic.List[object]
    $seen = @{}

    foreach ($proof in $proofEvents) {
        $missingFields = @(@(
            'transfer_id',
            'direction',
            'proof_generation',
            'proof_transport_epoch',
            'proof_frame_identity',
            'transaction_generation',
            'offer_generation',
            'tuna_path_lease_generation',
            'probe_id'
        ) | Where-Object { [string]::IsNullOrWhiteSpace((Get-ProofAuthorityField -Event $proof -Name $_)) })
        if ($missingFields.Count -eq 0) {
            continue
        }

        $proofSequence = [int64]$proof.Sequence
        $proofWriterSequence = Get-FileTransferEventInt64Field -Event $proof -Name 'log_writer_sequence' -Default 0
        [object[]]$matchingSuppression = @($events | Where-Object {
            $_.EventName -eq 'filetransfer_post_tuna_fallback_route_hint_suppressed_uncommitted_runtime_unlock' -and
            [int64]$_.Sequence -gt $proofSequence -and
            (Test-ProofAuthoritySameWriter -Left $proof -Right $_) -and
            ($proofWriterSequence -le 0 -or
                (Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0) -le ($proofWriterSequence + 2)) -and
            (Get-ProofAuthorityField -Event $_ -Name 'source') -eq 'availability_broadcast' -and
            (Get-ProofAuthorityField -Event $_ -Name 'reason') -eq 'transport_recovered' -and
            (Get-ProofAuthorityField -Event $_ -Name 'current_route') -eq 'regular_nkn_v4_fast'
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($matchingSuppression.Count -eq 0) {
            continue
        }

        $suppression = $matchingSuppression[0]
        $raw.Add($proof) | Out-Null
        $key = [string]::Join('|', @(
                (Get-ProofAuthorityField -Event $proof -Name 'log_writer_id'),
                (Get-ProofAuthorityField -Event $proof -Name 'log_writer_sequence'),
                (Get-ProofAuthorityField -Event $proof -Name 'session_id'),
                (Get-ProofAuthorityField -Event $proof -Name 'reason'),
                (Get-ProofAuthorityField -Event $proof -Name 'proof'))).ToLowerInvariant()
        if ($seen.ContainsKey($key)) {
            continue
        }
        $seen[$key] = $true
        $distinct.Add($proof) | Out-Null

        [object[]]$matchingBinding = @($bindingEvents | Where-Object {
            [int64]$_.Sequence -ge $proofSequence -and
            [int64]$_.Sequence -le [int64]$suppression.Sequence -and
            (Test-ProofAuthoritySameWriter -Left $proof -Right $_) -and
            (Get-ProofAuthorityField -Event $_ -Name 'binding_status') -in @('Bound', 'Idempotent') -and
            -not [string]::IsNullOrWhiteSpace((Get-ProofAuthorityField -Event $_ -Name 'transfer_id')) -and
            -not [string]::IsNullOrWhiteSpace((Get-ProofAuthorityField -Event $_ -Name 'proof_frame_identity'))
        } | Select-Object -First 1)
        if ($matchingBinding.Count -gt 0) {
            $recovered.Add($proof) | Out-Null
            continue
        }

        $proof | Add-Member -NotePropertyName FailureReason -NotePropertyValue 'post_tuna_fallback_proof_completed_without_authority_scope' -Force
        $unresolved.Add($proof) | Out-Null
        foreach ($ignored in @($events | Where-Object {
                [int64]$_.Sequence -gt [int64]$suppression.Sequence -and
                $_.EventName -eq 'filetransfer_data_frame_ignored' -and
                (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq 'protocol_not_v4' -and
                (Get-FileTransferEventField -Event $_ -Name 'frame_type' -Default '') -like '*.v6'
            })) {
            $downstream.Add($ignored) | Out-Null
        }
    }

    return [pscustomobject]@{
        RawCount = $raw.Count
        DistinctCount = $distinct.Count
        RecoveredCount = $recovered.Count
        UnresolvedCount = $unresolved.Count
        Verdict = if ($unresolved.Count -gt 0) { 'fail' } elseif ($distinct.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = @($raw.ToArray())
        DistinctCandidateEvents = @($distinct.ToArray())
        RecoveredCandidateEvents = @($recovered.ToArray())
        UnresolvedCandidateEvents = @($unresolved.ToArray())
        DownstreamProtocolMismatchEvents = @($downstream.ToArray())
        DownstreamProtocolMismatchSequences = @($downstream.ToArray() | ForEach-Object { [int64]$_.Sequence })
    }
}

function Get-FileTransferRuntimeUnlockUncommittedTunaFallbackHandoffSuppressionCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @()
    )

    [object[]]$events = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$availabilityEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_data_session_availability_broadcast' -and
        (Get-FileTransferEventField -Event $_ -Name 'is_available' -Default '0') -eq '1' -and
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq 'transport_recovered' -and
        (Get-FileTransferEventField -Event $_ -Name 'requires_resume_request' -Default '0') -eq '1' -and
        (Get-FileTransferEventField -Event $_ -Name 'handoff_kind' -Default '') -eq 'tuna_to_normal_fallback' -and
        (Get-FileTransferEventField -Event $_ -Name 'target_transport' -Default '') -eq 'regular_nkn'
    })
    [object[]]$suppressionEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_post_tuna_fallback_route_hint_suppressed_uncommitted_runtime_unlock' -and
        (Get-FileTransferEventField -Event $_ -Name 'source' -Default '') -eq 'availability_broadcast' -and
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq 'transport_recovered' -and
        (Get-FileTransferEventField -Event $_ -Name 'handoff_kind' -Default '') -eq 'tuna_to_normal_fallback' -and
        (Get-FileTransferEventField -Event $_ -Name 'target_transport' -Default '') -eq 'regular_nkn' -and
        (Get-FileTransferEventField -Event $_ -Name 'current_route' -Default '') -eq 'regular_nkn_v4_fast' -and
        (Get-FileTransferEventField -Event $_ -Name 'current_protocol_version' -Default '') -eq '4'
    })
    [object[]]$proofEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_post_tuna_fallback_nkn_proved'
    })
    [object[]]$scopedAvailabilityEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_data_session_availability_invoking' -and
        (Get-FileTransferEventField -Event $_ -Name 'is_available' -Default '0') -eq '1' -and
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq 'transport_recovered' -and
        (Get-FileTransferEventField -Event $_ -Name 'proof_scoped_fallback_boundary' -Default '0') -eq '1'
    })
    [object[]]$retainedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_uncommitted_tuna_fallback_handoff_retained'
    })
    [object[]]$dispositionEvents = @($events | Where-Object {
        $_.EventName -in @(
            'runtime_unlock_uncommitted_tuna_fallback_handoff_decided',
            'runtime_unlock_uncommitted_tuna_fallback_handoff_committed',
            'runtime_unlock_uncommitted_tuna_fallback_handoff_invalidated')
    })
    [object[]]$legacyRouteTransitions = @($events | Where-Object {
        $_.EventName -in @(
            'filetransfer_route_selected',
            'filetransfer_route_transitioned',
            'filetransfer_runtime_started',
            'filetransfer_route_hint_authorized_publication_accepted') -and
        ((Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'post_tuna_fallback_v6' -or
            (Get-FileTransferEventField -Event $_ -Name 'new_route' -Default '') -eq 'post_tuna_fallback_v6') -and
        ((Get-FileTransferEventField -Event $_ -Name 'protocol_version' -Default '') -eq '6' -or
            (Get-FileTransferEventField -Event $_ -Name 'new_protocol_version' -Default '') -eq '6')
    })
    [object[]]$terminalEvents = @($events | Where-Object {
        $_.EventName -in @(
            'file_transfer_outbound_terminal',
            'file_transfer_inbound_terminal',
            'transfer_terminal',
            'filetransfer_runtime_terminalized')
    })

    function Get-UncommittedFallbackField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Names
        )

        foreach ($name in $Names) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and
                $value -notin @('(none)', 'none', '(missing)', '__missing__')) {
                return $value
            }
        }
        return ''
    }

    function Test-UncommittedFallbackSameWriter {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        $leftWriter = Get-UncommittedFallbackField -Event $Left -Names @('log_writer_id')
        $rightWriter = Get-UncommittedFallbackField -Event $Right -Names @('log_writer_id')
        if ([string]::IsNullOrWhiteSpace($leftWriter) -or
            [string]::IsNullOrWhiteSpace($rightWriter)) {
            return $false
        }
        return [string]::Equals($leftWriter, $rightWriter, [System.StringComparison]::OrdinalIgnoreCase)
    }

    function Test-UncommittedFallbackIdentityMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right,
            [string[]]$RequiredFields = @('session_id', 'transfer_id')
        )

        foreach ($field in $RequiredFields) {
            $leftValue = Get-UncommittedFallbackField -Event $Left -Names @($field)
            $rightValue = Get-UncommittedFallbackField -Event $Right -Names @($field)
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Test-UncommittedFallbackDispositionMatch {
        param(
            [Parameter(Mandatory = $true)]$Retained,
            [Parameter(Mandatory = $true)]$Disposition
        )

        if (-not (Test-UncommittedFallbackIdentityMatch -Left $Retained -Right $Disposition)) {
            return $false
        }

        $retainedGeneration = Get-UncommittedFallbackField -Event $Retained -Names @('handoff_generation')
        $dispositionGeneration = Get-UncommittedFallbackField -Event $Disposition -Names @('handoff_generation')
        if ([string]::IsNullOrWhiteSpace($retainedGeneration) -or
            [string]::IsNullOrWhiteSpace($dispositionGeneration) -or
            $retainedGeneration -ne $dispositionGeneration) {
            return $false
        }

        foreach ($aliases in @(
                @('direction'),
                @('source_route', 'current_route'),
                @('source_protocol_version', 'current_protocol_version'),
                @('live_route_epoch'),
                @('runtime_generation'),
                @('terminal_generation'),
                @('leg_generation'),
                @('transport_epoch'),
                @('bridge_recovery_generation'),
                @('route_publication_generation'),
                @('route_commit_generation'),
                @('data_session_generation'),
                @('transaction_generation'),
                @('offer_generation'),
                @('tuna_path_lease_generation'),
                @('launch_generation'),
                @('probe_id'),
                @('drain_generation'),
                @('proof_transport_epoch'),
                @('handoff_kind'),
                @('target_route'),
                @('target_protocol_version'),
                @('target_transport'))) {
            $leftValue = Get-UncommittedFallbackField -Event $Retained -Names $aliases
            $rightValue = Get-UncommittedFallbackField -Event $Disposition -Names $aliases
            if (-not [string]::IsNullOrWhiteSpace($leftValue) -and
                -not [string]::IsNullOrWhiteSpace($rightValue) -and
                -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        if ($Disposition.EventName -eq 'runtime_unlock_uncommitted_tuna_fallback_handoff_decided') {
            $status = Get-UncommittedFallbackField -Event $Disposition -Names @('decision_status', 'status', 'disposition')
            return -not [string]::IsNullOrWhiteSpace($status)
        }
        return $true
    }

    $raw = New-Object System.Collections.Generic.List[object]
    $distinct = New-Object System.Collections.Generic.List[object]
    $recovered = New-Object System.Collections.Generic.List[object]
    $unresolved = New-Object System.Collections.Generic.List[object]
    $downstream = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($suppression in $suppressionEvents) {
        $suppressionSequence = [int64]$suppression.Sequence
        $suppressionWriterSequence = Get-FileTransferEventInt64Field `
            -Event $suppression `
            -Name 'log_writer_sequence' `
            -Default 0
        [object[]]$matchingBroadcasts = @($availabilityEvents | Where-Object {
            [int64]$_.Sequence -lt $suppressionSequence -and
            (Test-UncommittedFallbackSameWriter -Left $suppression -Right $_) -and
            ($suppressionWriterSequence -le 0 -or
                (Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default -2) -eq
                    ($suppressionWriterSequence - 1))
        } | Sort-Object Sequence, LineNumber)
        if ($matchingBroadcasts.Count -eq 0) {
            continue
        }
        $broadcast = $matchingBroadcasts[-1]

        [object[]]$matchingProofs = @($proofEvents | Where-Object {
            [int64]$_.Sequence -lt [int64]$broadcast.Sequence -and
            (Test-UncommittedFallbackSameWriter -Left $suppression -Right $_) -and
            ((Get-UncommittedFallbackField -Event $_ -Names @('session_id')) -eq
                (Get-UncommittedFallbackField -Event $suppression -Names @('session_id'))) -and
            -not [string]::IsNullOrWhiteSpace((Get-UncommittedFallbackField -Event $_ -Names @('transfer_id'))) -and
            -not [string]::IsNullOrWhiteSpace((Get-UncommittedFallbackField -Event $_ -Names @('direction'))) -and
            -not [string]::IsNullOrWhiteSpace((Get-UncommittedFallbackField -Event $_ -Names @('proof_generation'))) -and
            -not [string]::IsNullOrWhiteSpace((Get-UncommittedFallbackField -Event $_ -Names @('proof_transport_epoch'))) -and
            -not [string]::IsNullOrWhiteSpace((Get-UncommittedFallbackField -Event $_ -Names @('proof_frame_identity')))
        } | Sort-Object Sequence, LineNumber)
        if ($matchingProofs.Count -eq 0) {
            continue
        }

        $raw.Add($suppression) | Out-Null
        $key = [string]::Join('|', @(
                (Get-UncommittedFallbackField -Event $suppression -Names @('log_writer_id')),
                (Get-UncommittedFallbackField -Event $suppression -Names @('log_writer_sequence')),
                (Get-UncommittedFallbackField -Event $suppression -Names @('session_id')),
                (Get-UncommittedFallbackField -Event $suppression -Names @('transfer_id')),
                (Get-UncommittedFallbackField -Event $suppression -Names @('handoff_kind')),
                (Get-UncommittedFallbackField -Event $suppression -Names @('target_transport')),
                (Get-UncommittedFallbackField -Event $suppression -Names @('current_route')),
                (Get-UncommittedFallbackField -Event $suppression -Names @('current_protocol_version')))).ToLowerInvariant()
        if ($seen.ContainsKey($key)) {
            continue
        }
        $seen[$key] = $true
        $distinct.Add($suppression) | Out-Null

        [object[]]$matchingTerminals = @($terminalEvents | Where-Object {
            [int64]$_.Sequence -gt $suppressionSequence -and
            (Test-UncommittedFallbackIdentityMatch -Left $suppression -Right $_)
        } | Sort-Object Sequence, LineNumber)
        $boundarySequence = if ($matchingTerminals.Count -gt 0) {
            [int64]$matchingTerminals[0].Sequence
        }
        else {
            [int64]::MaxValue
        }

        [object[]]$matchingRetained = @($retainedEvents | Where-Object {
            [int64]$_.Sequence -gt $suppressionSequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-UncommittedFallbackIdentityMatch -Left $suppression -Right $_) -and
            (Get-UncommittedFallbackField -Event $_ -Names @('handoff_kind')) -eq 'tuna_to_normal_fallback' -and
            (Get-UncommittedFallbackField -Event $_ -Names @('target_route')) -eq 'post_tuna_fallback_v6' -and
            (Get-UncommittedFallbackField -Event $_ -Names @('target_transport')) -eq 'regular_nkn'
        } | Sort-Object Sequence, LineNumber)
        $newResolution = @()
        foreach ($retained in $matchingRetained) {
            $newResolution = @($dispositionEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$retained.Sequence -and
                [int64]$_.Sequence -lt $boundarySequence -and
                (Test-UncommittedFallbackDispositionMatch -Retained $retained -Disposition $_)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            if ($newResolution.Count -gt 0) {
                break
            }
        }

        [object[]]$legacyResolution = @($legacyRouteTransitions | Where-Object {
            [int64]$_.Sequence -gt $suppressionSequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-UncommittedFallbackIdentityMatch -Left $suppression -Right $_) -and
            (Test-UncommittedFallbackSameWriter -Left $suppression -Right $_) -and
            (Get-UncommittedFallbackField -Event $_ -Names @('direction')) -eq 'outbound'
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)

        [object[]]$deliveredLifecycleResolution = @($scopedAvailabilityEvents | Where-Object {
            [int64]$_.Sequence -gt $suppressionSequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-UncommittedFallbackIdentityMatch -Left $suppression -Right $_) -and
            (Test-UncommittedFallbackSameWriter -Left $suppression -Right $_)
        } | Sort-Object Sequence, LineNumber)
        if ($deliveredLifecycleResolution.Count -gt 0) {
            $availability = $deliveredLifecycleResolution[0]
            $deliveredLifecycleResolution = @($dispositionEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$availability.Sequence -and
                [int64]$_.Sequence -lt $boundarySequence -and
                (Test-UncommittedFallbackIdentityMatch -Left $suppression -Right $_)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        }

        if ($newResolution.Count -gt 0 -or
            $legacyResolution.Count -gt 0 -or
            $deliveredLifecycleResolution.Count -gt 0) {
            $recovered.Add($suppression) | Out-Null
        }
        else {
            $unresolved.Add($suppression) | Out-Null
            foreach ($ignored in @($events | Where-Object {
                    [int64]$_.Sequence -gt $suppressionSequence -and
                    [int64]$_.Sequence -lt $boundarySequence -and
                    $_.EventName -eq 'filetransfer_data_frame_ignored' -and
                    (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq 'protocol_not_v4' -and
                    (Get-FileTransferEventField -Event $_ -Name 'frame_type' -Default '') -like '*.v6' -and
                    (Test-UncommittedFallbackIdentityMatch -Left $suppression -Right $_)
                })) {
                $downstream.Add($ignored) | Out-Null
            }
        }
    }

    return [pscustomobject]@{
        RawCount = $raw.Count
        DistinctCount = $distinct.Count
        RecoveredCount = $recovered.Count
        UnresolvedCount = $unresolved.Count
        Verdict = if ($unresolved.Count -gt 0) { 'fail' } elseif ($distinct.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = @($raw.ToArray())
        DistinctCandidateEvents = @($distinct.ToArray())
        RecoveredCandidateEvents = @($recovered.ToArray())
        UnresolvedCandidateEvents = @($unresolved.ToArray())
        DownstreamProtocolMismatchEvents = @($downstream.ToArray())
        DownstreamProtocolMismatchSequences = @($downstream.ToArray() | ForEach-Object { [int64]$_.Sequence })
    }
}

function Get-FileTransferRuntimeUnlockUncommittedTunaFallbackPrecommitAuthorityCorrelation {
    param([AllowEmptyCollection()][object[]]$Events = @())

    [object[]]$events = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)

    function Get-PrecommitField {
        param([Parameter(Mandatory = $true)]$Event, [Parameter(Mandatory = $true)][string]$Name)
        $value = Get-FileTransferEventField -Event $Event -Name $Name -Default ''
        if ($value -in @('(none)', 'none', '(missing)', '__missing__')) { return '' }
        return $value
    }

    function Test-PrecommitFieldsMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right,
            [Parameter(Mandatory = $true)][string[]]$Fields)
        foreach ($field in $Fields) {
            $leftValue = Get-PrecommitField -Event $Left -Name $field
            $rightValue = Get-PrecommitField -Event $Right -Name $field
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Test-PrecommitSameWriter {
        param([Parameter(Mandatory = $true)]$Left, [Parameter(Mandatory = $true)]$Right)
        return Test-PrecommitFieldsMatch -Left $Left -Right $Right -Fields @('log_writer_id')
    }

    [object[]]$rejections = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_uncommitted_tuna_fallback_handoff_decided' -and
        (Get-PrecommitField -Event $_ -Name 'direction') -eq 'outbound' -and
        (Get-PrecommitField -Event $_ -Name 'decision_status') -eq 'Rejected' -and
        (Get-PrecommitField -Event $_ -Name 'decision_reason') -eq 'proof_boundary_not_current'
    })
    [object[]]$admissions = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_runtime_unlock_admission_granted' -and
        (Get-PrecommitField -Event $_ -Name 'direction') -eq 'outbound' -and
        (Get-PrecommitField -Event $_ -Name 'route') -eq 'regular_nkn_v4_fast' -and
        (Get-PrecommitField -Event $_ -Name 'protocol_version') -eq '4' -and
        (Get-FileTransferEventInt64Field -Event $_ -Name 'admission_generation' -Default 0) -gt 0
    })
    [object[]]$drains = @($events | Where-Object {
        $_.EventName -in @(
            'runtime_unlock_regular_v4_route_commit_send_drain_deferred',
            'runtime_unlock_regular_v4_route_commit_send_drain_completed') -and
        (Get-PrecommitField -Event $_ -Name 'direction') -eq 'outbound' -and
        (Get-PrecommitField -Event $_ -Name 'source_route') -eq 'regular_nkn_v4_fast' -and
        (Get-PrecommitField -Event $_ -Name 'source_protocol_version') -eq '4' -and
        (Get-PrecommitField -Event $_ -Name 'probe_state') -eq 'Acked'
    })
    [object[]]$bindings = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_uncommitted_tuna_fallback_peer_proof_binding_decided' -and
        (Get-PrecommitField -Event $_ -Name 'binding_status') -in @('Bound', 'Idempotent')
    })
    [object[]]$proofs = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_post_tuna_fallback_nkn_proved' -and
        (Get-PrecommitField -Event $_ -Name 'binding_status') -in @('bound', 'idempotent')
    })
    [object[]]$suppressions = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_post_tuna_fallback_route_hint_suppressed_uncommitted_runtime_unlock' -and
        (Get-PrecommitField -Event $_ -Name 'reason') -eq 'transport_recovered'
    })
    [object[]]$availability = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_data_session_availability_invoking' -and
        (Get-PrecommitField -Event $_ -Name 'is_available') -eq '1' -and
        (Get-PrecommitField -Event $_ -Name 'proof_scoped_fallback_boundary') -eq '1' -and
        (Get-PrecommitField -Event $_ -Name 'handoff_kind') -eq 'tuna_to_normal_fallback'
    })
    [object[]]$retained = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_uncommitted_tuna_fallback_handoff_retained'
    })
    [object[]]$committed = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_uncommitted_tuna_fallback_handoff_committed'
    })
    [object[]]$applied = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_uncommitted_tuna_fallback_peer_proof_observed' -and
        (Get-PrecommitField -Event $_ -Name 'decision_status') -in @('Applied', 'Idempotent')
    })
    [object[]]$terminals = @($events | Where-Object {
        $_.EventName -in @('file_transfer_outbound_terminal', 'transfer_terminal', 'filetransfer_runtime_terminalized')
    })

    $raw = New-Object System.Collections.Generic.List[object]
    $distinct = New-Object System.Collections.Generic.List[object]
    $recovered = New-Object System.Collections.Generic.List[object]
    $unresolved = New-Object System.Collections.Generic.List[object]
    $downstream = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    $identityFields = @('session_id', 'transfer_id', 'direction')
    $precommitFields = @('transaction_generation', 'offer_generation', 'tuna_path_lease_generation', 'launch_generation')
    $proofFields = @('proof_generation', 'proof_transport_epoch')

    foreach ($rejection in $rejections) {
        $sequence = [int64]$rejection.Sequence
        [object[]]$matchingProofs = @($proofs | Where-Object {
            [int64]$_.Sequence -lt $sequence -and
            (Test-PrecommitFieldsMatch -Left $rejection -Right $_ -Fields ($identityFields + $precommitFields + $proofFields))
        } | Sort-Object Sequence, LineNumber)
        if ($matchingProofs.Count -eq 0) { continue }
        $proof = $matchingProofs[-1]
        [object[]]$matchingBindings = @($bindings | Where-Object {
            [int64]$_.Sequence -lt [int64]$proof.Sequence -and
            (Test-PrecommitFieldsMatch -Left $proof -Right $_ -Fields ($identityFields + $proofFields))
        })
        [object[]]$matchingAvailability = @($availability | Where-Object {
            [int64]$_.Sequence -gt [int64]$proof.Sequence -and [int64]$_.Sequence -lt $sequence -and
            (Test-PrecommitFieldsMatch -Left $proof -Right $_ -Fields (@('session_id', 'transfer_id') + $precommitFields + @('proof_transport_epoch'))) -and
            (Test-PrecommitSameWriter -Left $proof -Right $_)
        })
        [object[]]$matchingSuppression = @($suppressions | Where-Object {
            [int64]$_.Sequence -gt [int64]$proof.Sequence -and [int64]$_.Sequence -lt $sequence -and
            (Test-PrecommitFieldsMatch -Left $proof -Right $_ -Fields @('session_id', 'transfer_id')) -and
            (Test-PrecommitSameWriter -Left $proof -Right $_)
        })
        [object[]]$matchingDrains = @($drains | Where-Object {
            [int64]$_.Sequence -lt [int64]$proof.Sequence -and
            (Test-PrecommitFieldsMatch -Left $proof -Right $_ -Fields ($identityFields + $precommitFields))
        } | Sort-Object Sequence, LineNumber)
        if ($matchingBindings.Count -eq 0 -or $matchingAvailability.Count -eq 0 -or
            $matchingSuppression.Count -eq 0 -or $matchingDrains.Count -eq 0) { continue }
        $drain = $matchingDrains[-1]
        [object[]]$matchingAdmissions = @($admissions | Where-Object {
            [int64]$_.Sequence -lt [int64]$drain.Sequence -and
            (Test-PrecommitFieldsMatch -Left $rejection -Right $_ -Fields $identityFields)
        } | Sort-Object Sequence, LineNumber)
        if ($matchingAdmissions.Count -eq 0) { continue }

        $raw.Add($rejection) | Out-Null
        $key = (@($identityFields + $precommitFields + $proofFields) | ForEach-Object {
            (Get-PrecommitField -Event $rejection -Name $_).ToLowerInvariant()
        }) -join '|'
        if ($seen.ContainsKey($key)) { continue }
        $seen[$key] = $true
        $distinct.Add($rejection) | Out-Null

        [object[]]$matchingTerminals = @($terminals | Where-Object {
            [int64]$_.Sequence -gt $sequence -and
            (Test-PrecommitFieldsMatch -Left $rejection -Right $_ -Fields @('session_id', 'transfer_id'))
        } | Sort-Object Sequence, LineNumber)
        $boundary = if ($matchingTerminals.Count -gt 0) { [int64]$matchingTerminals[0].Sequence } else { [int64]::MaxValue }
        [object[]]$matchingRetained = @($retained | Where-Object {
            [int64]$_.Sequence -gt $sequence -and [int64]$_.Sequence -lt $boundary -and
            (Test-PrecommitFieldsMatch -Left $rejection -Right $_ -Fields ($identityFields + $precommitFields + $proofFields))
        } | Sort-Object Sequence, LineNumber)
        $resolved = $false
        foreach ($intent in $matchingRetained) {
            [object[]]$matchingCommit = @($committed | Where-Object {
                [int64]$_.Sequence -gt [int64]$intent.Sequence -and [int64]$_.Sequence -lt $boundary -and
                (Test-PrecommitFieldsMatch -Left $intent -Right $_ -Fields @('session_id', 'transfer_id', 'direction', 'handoff_generation'))
            })
            [object[]]$matchingApplied = @($applied | Where-Object {
                [int64]$_.Sequence -gt [int64]$intent.Sequence -and [int64]$_.Sequence -lt $boundary -and
                (Test-PrecommitFieldsMatch -Left $intent -Right $_ -Fields @('session_id', 'transfer_id', 'direction', 'handoff_generation', 'proof_transport_epoch'))
            })
            if ($matchingCommit.Count -gt 0 -and $matchingApplied.Count -gt 0) { $resolved = $true; break }
        }
        if ($resolved) { $recovered.Add($rejection) | Out-Null } else { $unresolved.Add($rejection) | Out-Null }

        if (-not $resolved) {
            foreach ($ignored in @($events | Where-Object {
                    [int64]$_.Sequence -gt $sequence -and [int64]$_.Sequence -lt $boundary -and
                    $_.EventName -eq 'filetransfer_data_frame_ignored' -and
                    (Get-PrecommitField -Event $_ -Name 'reason') -eq 'protocol_not_v4' -and
                    (Get-PrecommitField -Event $_ -Name 'frame_type') -like '*.v6' -and
                    (Test-PrecommitFieldsMatch -Left $rejection -Right $_ -Fields @('session_id', 'transfer_id'))
                })) { $downstream.Add($ignored) | Out-Null }
        }
    }

    return [pscustomobject]@{
        RawCount = $raw.Count
        DistinctCount = $distinct.Count
        RecoveredCount = $recovered.Count
        UnresolvedCount = $unresolved.Count
        Verdict = if ($unresolved.Count -gt 0) { 'fail' } elseif ($distinct.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = @($raw.ToArray())
        DistinctCandidateEvents = @($distinct.ToArray())
        RecoveredCandidateEvents = @($recovered.ToArray())
        UnresolvedCandidateEvents = @($unresolved.ToArray())
        DownstreamProtocolMismatchSequences = @($downstream.ToArray() | ForEach-Object { [int64]$_.Sequence })
    }
}

function Test-FileTransferRuntimeUnlockRegularV4RecoverySettlementMatch {
    param(
        [Parameter(Mandatory = $true)]$Blocked,
        [Parameter(Mandatory = $true)]$Candidate
    )

    if ((Get-FileTransferAuthoritySchema -Line ([string]$Candidate.RawLine)) -lt 2) {
        return $false
    }

    foreach ($requiredCandidateField in @(
            'authority_id', 'session_id', 'transfer_id', 'direction', 'route',
            'protocol_version', 'live_route_epoch', 'runtime_generation', 'terminal_generation',
            'leg_generation', 'transport_epoch', 'bridge_recovery_generation',
            'settlement_bridge_decision_generation', 'route_publication_generation',
            'route_commit_generation', 'target_transport', 'repair_request_key',
            'frontier_chunk_index', 'durable_received_highest_chunk_index',
            'requested_chunk_count', 'settlement_decision_generation', 'settlement_outcome',
            'regular_v4_liveness_generation', 'bridge_decision_generation', 'disposition',
            'settlement_reason', 'decision_status')) {
        $requiredValue = Get-FileTransferEventField -Event $Candidate -Name $requiredCandidateField -Default ''
        if ([string]::IsNullOrWhiteSpace($requiredValue) -or $requiredValue -in @('(none)', 'none')) {
            return $false
        }
    }

    foreach ($identityField in @(
            'session_id', 'transfer_id', 'direction', 'route', 'protocol_version',
            'live_route_epoch', 'regular_v4_liveness_generation', 'bridge_decision_generation')) {
        $blockedValue = Get-FileTransferEventField -Event $Blocked -Name $identityField -Default ''
        $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $identityField -Default ''
        if ([string]::IsNullOrWhiteSpace($blockedValue) -or
            $blockedValue -in @('(none)', 'none') -or
            [string]::IsNullOrWhiteSpace($candidateValue) -or
            $candidateValue -in @('(none)', 'none') -or
            -not [string]::Equals(
                $blockedValue,
                $candidateValue,
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    return (Get-FileTransferEventField -Event $Candidate -Name 'disposition' -Default '') -eq 'Consumed' -and
        (Get-FileTransferEventField -Event $Candidate -Name 'decision_status' -Default '') -in @('Accepted', 'Idempotent')
}

function Test-FileTransferRuntimeUnlockRegularV4RecoveryReportDecisionMatch {
    param(
        [Parameter(Mandatory = $true)]$Report,
        [Parameter(Mandatory = $true)]$Decision
    )

    if ([int64]$Report.Sequence -ge [int64]$Decision.Sequence -or
        $Report.EventName -ne 'runtime_unlock_regular_v4_recovery_settlement_reported' -or
        $Decision.EventName -ne 'runtime_unlock_regular_v4_recovery_settlement_decided') {
        return $false
    }

    $baseReportMatches = Test-FileTransferAuthorityFieldsEqual `
        -LeftLine ([string]$Report.RawLine) `
        -RightLine ([string]$Decision.RawLine) `
        -Fields @(
            'authority_id', 'session_id', 'transfer_id', 'direction', 'route',
            'protocol_version', 'live_route_epoch', 'runtime_generation', 'terminal_generation',
            'leg_generation', 'transport_epoch', 'bridge_recovery_generation',
            'settlement_bridge_decision_generation', 'route_publication_generation',
            'route_commit_generation', 'target_transport', 'repair_request_key',
            'frontier_chunk_index', 'durable_received_highest_chunk_index',
            'requested_chunk_count', 'settlement_decision_generation', 'settlement_outcome',
            'regular_v4_liveness_generation', 'bridge_decision_generation', 'disposition',
            'settlement_reason')
    if (-not $baseReportMatches) {
        return $false
    }

    $reportReason = Get-FileTransferEventField -Event $Report -Name 'report_reason' -Default ''
    $decisionReportReason = Get-FileTransferEventField -Event $Decision -Name 'report_reason' -Default ''
    if ([string]::IsNullOrWhiteSpace($reportReason) -and
        [string]::IsNullOrWhiteSpace($decisionReportReason)) {
        return $true
    }

    return -not [string]::IsNullOrWhiteSpace($reportReason) -and
        -not [string]::IsNullOrWhiteSpace($decisionReportReason) -and
        [string]::Equals(
            $reportReason,
            $decisionReportReason,
            [System.StringComparison]::OrdinalIgnoreCase)
}

function Test-FileTransferRuntimeUnlockRegularV4RecoveryLifecycleReportDecisionMatch {
    param(
        [Parameter(Mandatory = $true)]$Report,
        [Parameter(Mandatory = $true)]$Decision
    )

    return [int64]$Report.Sequence -lt [int64]$Decision.Sequence -and
        $Report.EventName -eq 'runtime_unlock_regular_v4_recovery_lifecycle_reported' -and
        $Decision.EventName -eq 'runtime_unlock_regular_v4_recovery_lifecycle_decided' -and
        (Test-FileTransferAuthorityFieldsEqual `
            -LeftLine ([string]$Report.RawLine) `
            -RightLine ([string]$Decision.RawLine) `
            -Fields @(
                'session_id', 'transfer_id', 'direction', 'route', 'protocol_version',
                'live_route_epoch', 'runtime_generation', 'terminal_generation', 'leg_generation',
                'transport_epoch', 'bridge_recovery_generation', 'bridge_decision_generation',
                'regular_v4_liveness_generation', 'lifecycle_outcome', 'lifecycle_reason'))
}

function Test-FileTransferRuntimeUnlockRegularV4RecoveryLifecycleMatchesBlocked {
    param(
        [Parameter(Mandatory = $true)]$Blocked,
        [Parameter(Mandatory = $true)]$Lifecycle
    )

    foreach ($fieldName in @(
            'session_id', 'transfer_id', 'direction', 'route', 'protocol_version',
            'live_route_epoch', 'regular_v4_liveness_generation', 'bridge_decision_generation')) {
        $blockedValue = Get-FileTransferEventField -Event $Blocked -Name $fieldName -Default ''
        $lifecycleValue = Get-FileTransferEventField -Event $Lifecycle -Name $fieldName -Default ''
        if ([string]::IsNullOrWhiteSpace($blockedValue) -or
            [string]::IsNullOrWhiteSpace($lifecycleValue) -or
            -not [string]::Equals(
                $blockedValue,
                $lifecycleValue,
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    return $true
}

function Test-FileTransferRuntimeUnlockRegularV4RecoveryBoundaryMatch {
    param(
        [Parameter(Mandatory = $true)]$Blocked,
        [Parameter(Mandatory = $true)]$Boundary
    )

    $blockedSession = Get-FileTransferEventField -Event $Blocked -Name 'session_id' -Default ''
    $boundarySession = Get-FileTransferEventField -Event $Boundary -Name 'session_id' -Default ''
    if ([string]::IsNullOrWhiteSpace($blockedSession) -or
        [string]::IsNullOrWhiteSpace($boundarySession) -or
        -not [string]::Equals(
            $blockedSession,
            $boundarySession,
            [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }

    $blockedTransfer = Get-FileTransferEventField -Event $Blocked -Name 'transfer_id' -Default ''
    $boundaryTransfer = Get-FileTransferEventField -Event $Boundary -Name 'transfer_id' -Default ''
    if ([string]::IsNullOrWhiteSpace($blockedTransfer) -or
        $blockedTransfer -in @('(none)', 'none') -or
        [string]::IsNullOrWhiteSpace($boundaryTransfer) -or
        $boundaryTransfer -in @('(none)', 'none') -or
        -not [string]::Equals(
            $blockedTransfer,
            $boundaryTransfer,
            [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }

    foreach ($identityField in @('route', 'protocol_version', 'live_route_epoch')) {
        $blockedValue = Get-FileTransferEventField -Event $Blocked -Name $identityField -Default ''
        $boundaryValue = Get-FileTransferEventField -Event $Boundary -Name $identityField -Default ''
        if (-not [string]::IsNullOrWhiteSpace($blockedValue) -and
            $blockedValue -notin @('(none)', 'none') -and
            -not [string]::IsNullOrWhiteSpace($boundaryValue) -and
            $boundaryValue -notin @('(none)', 'none') -and
            -not [string]::Equals(
                $blockedValue,
                $boundaryValue,
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    $blockedDirection = Get-FileTransferEventField -Event $Blocked -Name 'direction' -Default ''
    $boundaryDirection = Get-FileTransferEventField -Event $Boundary -Name 'direction' -Default ''
    if ([string]::IsNullOrWhiteSpace($boundaryDirection)) {
        if ($Boundary.EventName -eq 'file_transfer_outbound_terminal') {
            $boundaryDirection = 'outbound'
        }
        elseif ($Boundary.EventName -eq 'file_transfer_inbound_terminal') {
            $boundaryDirection = 'inbound'
        }
    }

    return -not [string]::IsNullOrWhiteSpace($blockedDirection) -and
        $blockedDirection -notin @('(none)', 'none') -and
        -not [string]::IsNullOrWhiteSpace($boundaryDirection) -and
        $boundaryDirection -notin @('(none)', 'none') -and
        [string]::Equals(
            $blockedDirection,
            $boundaryDirection,
            [System.StringComparison]::OrdinalIgnoreCase)
}

function Test-FileTransferRuntimeUnlockRegularV4RecoveryCandidateBlockedByUnverifiableSettlement {
    param(
        [Parameter(Mandatory = $true)]$Candidate,
        [AllowEmptyCollection()][object[]]$AcceptedSettlementEvents = @(),
        [AllowEmptyCollection()][object[]]$UnresolvedSettlementEvents = @()
    )

    function Get-SettlementField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Names,
            [string]$Default = ''
        )

        foreach ($name in $Names) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and $value -notin @('(none)', 'none')) {
                return $value
            }
        }
        return $Default
    }

    function Get-SettlementIdentityKey {
        param([Parameter(Mandatory = $true)]$Event)

        return (@(
                'authority_id', 'successor_authority_id', 'session_id', 'transfer_id',
                'direction', 'route', 'protocol_version', 'live_route_epoch',
                'runtime_generation', 'terminal_generation', 'leg_generation', 'transport_epoch',
                'bridge_recovery_generation', 'bridge_decision_generation',
                'route_publication_generation', 'route_commit_generation', 'target_transport',
                'repair_request_key', 'frontier_chunk_index', 'durable_received_highest_chunk_index',
                'requested_chunk_count', 'decision_generation|settlement_decision_generation',
                'outcome|settlement_outcome', 'settlement_reason') |
            ForEach-Object {
                Get-SettlementField -Event $Event -Names ($_ -split '\|') -Default '(missing)'
            }) -join '|'
    }

    [object[]]$scopeSettlements = @($AcceptedSettlementEvents | Where-Object {
        $outcome = (Get-SettlementField `
            -Event $_ `
            -Names @('outcome', 'settlement_outcome')).Replace('_', '').ToLowerInvariant()
        if ($outcome -eq 'superseded') {
            return $false
        }

        foreach ($field in @(
                'session_id', 'transfer_id', 'route', 'protocol_version',
                'live_route_epoch', 'bridge_decision_generation')) {
            $acceptedValue = Get-FileTransferEventField -Event $_ -Name $field -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($acceptedValue) -or
                [string]::IsNullOrWhiteSpace($candidateValue) -or
                -not [string]::Equals(
                    $acceptedValue,
                    $candidateValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    })

    $candidateAuthority = Get-SettlementField `
        -Event $Candidate `
        -Names @(
            'frontier_repair_authority_id',
            'settlement_authority_id',
            'regular_v4_frontier_repair_authority_id')
    $candidateRepairKey = Get-SettlementField `
        -Event $Candidate `
        -Names @(
            'frontier_repair_request_key',
            'settlement_repair_request_key',
            'repair_request_key')
    if (-not [string]::IsNullOrWhiteSpace($candidateAuthority)) {
        $scopeSettlements = @($scopeSettlements | Where-Object {
            [string]::Equals(
                (Get-SettlementField -Event $_ -Names @('authority_id')),
                $candidateAuthority,
                [System.StringComparison]::OrdinalIgnoreCase)
        })
    }
    if (-not [string]::IsNullOrWhiteSpace($candidateRepairKey)) {
        $scopeSettlements = @($scopeSettlements | Where-Object {
            [string]::Equals(
                (Get-SettlementField -Event $_ -Names @('repair_request_key')),
                $candidateRepairKey,
                [System.StringComparison]::OrdinalIgnoreCase)
        })
    }

    $settlementsByIdentity = @{}
    foreach ($acceptedSettlement in $scopeSettlements) {
        $identityKey = Get-SettlementIdentityKey -Event $acceptedSettlement
        if (-not $settlementsByIdentity.ContainsKey($identityKey)) {
            $settlementsByIdentity[$identityKey] = $acceptedSettlement
        }
    }
    if ($settlementsByIdentity.Count -ne 1) {
        return $false
    }

    $onlyIdentityKey = @($settlementsByIdentity.Keys)[0]
    foreach ($unresolvedSettlement in $UnresolvedSettlementEvents) {
        if ((Get-SettlementIdentityKey -Event $unresolvedSettlement) -eq $onlyIdentityKey) {
            return $true
        }
    }

    return $false
}

function Get-FileTransferRegularV4FrontierRepairSettlementDispositionProof {
    param(
        [AllowEmptyCollection()][object[]]$Events = @()
    )

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$acceptedEvents = @($orderedEvents | Where-Object {
        if ($_.EventName -ne 'filetransfer_regular_v4_frontier_repair_settlement_accepted') {
            return $false
        }

        $outcome = (Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $_ `
            -Names @('outcome', 'settlement_outcome')).Replace('_', '').ToLowerInvariant()
        return -not [string]::IsNullOrWhiteSpace($outcome) -and $outcome -ne 'superseded'
    })
    [object[]]$dispositionEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'runtime_unlock_regular_v4_frontier_repair_precontract_settlement_cached',
            'runtime_unlock_regular_v4_frontier_repair_settlement_released',
            'runtime_unlock_regular_v4_frontier_repair_settlement_held',
            'runtime_unlock_regular_v4_frontier_repair_settlement_rejected',
            'runtime_unlock_regular_v4_frontier_repair_settlement_handoff_rejected',
            'runtime_unlock_regular_v4_frontier_repair_settlement_handoff_adopted',
            'runtime_unlock_regular_v4_frontier_repair_settlement_handoff_consumed',
            'runtime_unlock_regular_v4_frontier_repair_settlement_handoff_discarded',
            'runtime_unlock_regular_v4_frontier_repair_settlement_handoff_duplicate_ignored',
            'runtime_unlock_regular_v4_frontier_repair_settlement_handoff_held_for_bridge_lifecycle',
            'runtime_unlock_regular_v4_frontier_repair_precontract_settlement_consumed',
            'runtime_unlock_regular_v4_frontier_repair_settlement_held_for_lease_closure_window',
            'runtime_unlock_regular_v4_recovery_settlement_reported')
    })
    [object[]]$pressureSettlementApplyEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_pressure_settlement_apply_decided'
    })
    [object[]]$pressureBindingRetiredEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_pressure_binding_retired'
    })
    [object[]]$legacyRecoveryOwnershipEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'runtime_unlock_retry_blocked_by_regular_v4_receive_recovery',
            'runtime_unlock_retry_dispatch_held_by_regular_v4_receive_recovery',
            'runtime_unlock_retry_regular_v4_recovery_settlement_missing')
    })

    function Get-RegularV4SettlementField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Names
        )

        foreach ($name in $Names) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and $value -notin @('(none)', 'none')) {
                return $value
            }
        }
        return ''
    }

    function Test-RegularV4SettlementDispositionMatch {
        param(
            [Parameter(Mandatory = $true)]$Accepted,
            [Parameter(Mandatory = $true)]$Disposition
        )

        $acceptedAuthority = Get-RegularV4SettlementField -Event $Accepted -Names @('authority_id')
        $dispositionAuthority = Get-RegularV4SettlementField -Event $Disposition -Names @('authority_id')
        $acceptedHasExactAuthority = -not [string]::IsNullOrWhiteSpace($acceptedAuthority) -and
            $acceptedAuthority -notin @('[redacted]', 'redacted')
        if ($acceptedHasExactAuthority -and
            ([string]::IsNullOrWhiteSpace($dispositionAuthority) -or
                -not [string]::Equals(
                    $acceptedAuthority,
                    $dispositionAuthority,
                    [System.StringComparison]::OrdinalIgnoreCase))) {
            return $false
        }

        $acceptedSuccessorAuthority = Get-FileTransferEventField `
            -Event $Accepted `
            -Name 'successor_authority_id' `
            -Default ''
        $dispositionSuccessorAuthority = Get-FileTransferEventField `
            -Event $Disposition `
            -Name 'successor_authority_id' `
            -Default ''
        if ($acceptedHasExactAuthority -and
            ([string]::IsNullOrWhiteSpace($acceptedSuccessorAuthority) -or
                [string]::IsNullOrWhiteSpace($dispositionSuccessorAuthority))) {
            return $false
        }
        if (-not [string]::IsNullOrWhiteSpace($acceptedSuccessorAuthority) -and
            -not [string]::IsNullOrWhiteSpace($dispositionSuccessorAuthority) -and
            -not [string]::Equals(
                $acceptedSuccessorAuthority,
                $dispositionSuccessorAuthority,
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }

        $fieldAliases = @(
                [pscustomobject]@{ Accepted = @('session_id'); Disposition = @('session_id') },
                [pscustomobject]@{ Accepted = @('transfer_id'); Disposition = @('transfer_id') },
                [pscustomobject]@{ Accepted = @('direction'); Disposition = @('direction') },
                [pscustomobject]@{ Accepted = @('route'); Disposition = @('route') },
                [pscustomobject]@{ Accepted = @('protocol_version'); Disposition = @('protocol_version') },
                [pscustomobject]@{ Accepted = @('live_route_epoch'); Disposition = @('live_route_epoch') },
                [pscustomobject]@{ Accepted = @('runtime_generation'); Disposition = @('runtime_generation') },
                [pscustomobject]@{ Accepted = @('terminal_generation'); Disposition = @('terminal_generation') },
                [pscustomobject]@{ Accepted = @('leg_generation'); Disposition = @('leg_generation') },
                [pscustomobject]@{ Accepted = @('transport_epoch'); Disposition = @('transport_epoch') },
                [pscustomobject]@{ Accepted = @('bridge_recovery_generation'); Disposition = @('bridge_recovery_generation') },
                [pscustomobject]@{ Accepted = @('bridge_decision_generation'); Disposition = @('settlement_bridge_decision_generation', 'bridge_decision_generation') },
                [pscustomobject]@{ Accepted = @('route_publication_generation'); Disposition = @('route_publication_generation') },
                [pscustomobject]@{ Accepted = @('route_commit_generation'); Disposition = @('route_commit_generation') },
                [pscustomobject]@{ Accepted = @('target_transport'); Disposition = @('target_transport') },
                [pscustomobject]@{ Accepted = @('repair_request_key'); Disposition = @('repair_request_key') },
                [pscustomobject]@{ Accepted = @('frontier_chunk_index'); Disposition = @('frontier_chunk_index') },
                [pscustomobject]@{ Accepted = @('requested_chunk_count'); Disposition = @('requested_chunk_count') },
                [pscustomobject]@{ Accepted = @('decision_generation'); Disposition = @('settlement_decision_generation', 'decision_generation') },
                [pscustomobject]@{ Accepted = @('outcome', 'settlement_outcome'); Disposition = @('settlement_outcome', 'outcome') },
                [pscustomobject]@{ Accepted = @('settlement_reason'); Disposition = @('settlement_reason') })
        for ($index = 0; $index -lt $fieldAliases.Count; $index++) {
            $aliases = $fieldAliases[$index]
            $left = Get-RegularV4SettlementField -Event $Accepted -Names $aliases.Accepted
            $right = Get-RegularV4SettlementField -Event $Disposition -Names $aliases.Disposition
            $requiredField = $acceptedHasExactAuthority -or
                $aliases.Accepted[0] -in @('session_id', 'transfer_id', 'direction', 'repair_request_key')
            if ($aliases.Accepted[0] -eq 'settlement_reason') {
                $requiredField = $acceptedHasExactAuthority -and
                    -not [string]::IsNullOrWhiteSpace($left)
            }
            if ($requiredField -and
                ([string]::IsNullOrWhiteSpace($left) -or [string]::IsNullOrWhiteSpace($right))) {
                return $false
            }
            $normalizeOutcome = $aliases.Accepted[0] -in @('outcome', 'settlement_outcome')
            $leftComparison = if ($normalizeOutcome) { $left.Replace('_', '') } else { $left }
            $rightComparison = if ($normalizeOutcome) { $right.Replace('_', '') } else { $right }
            if (-not [string]::IsNullOrWhiteSpace($left) -and
                -not [string]::IsNullOrWhiteSpace($right) -and
                -not [string]::Equals($leftComparison, $rightComparison, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Get-RegularV4SettlementTupleKey {
        param([Parameter(Mandatory = $true)]$Event)

        $parts = foreach ($aliases in @(
                @('authority_id'),
                @('session_id'), @('transfer_id'), @('direction'), @('route'), @('protocol_version'),
                @('live_route_epoch'), @('runtime_generation'), @('terminal_generation'), @('leg_generation'),
                @('transport_epoch'), @('bridge_recovery_generation'), @('bridge_decision_generation'),
                @('route_publication_generation'), @('route_commit_generation'), @('target_transport'),
                @('repair_request_key'), @('successor_authority_id'), @('frontier_chunk_index'),
                @('requested_chunk_count'), @('decision_generation', 'settlement_decision_generation'),
                @('outcome', 'settlement_outcome'), @('settlement_reason'))) {
            if ($aliases[0] -eq 'successor_authority_id') {
                Get-FileTransferEventField -Event $Event -Name 'successor_authority_id' -Default '(missing)'
            }
            else {
                Get-RegularV4SettlementField -Event $Event -Names $aliases
            }
        }
        return [string]::Join('|', $parts)
    }

    function Test-RegularV4LegacyRecoveryOwnershipMatch {
        param(
            [Parameter(Mandatory = $true)]$Accepted,
            [Parameter(Mandatory = $true)]$Ownership
        )

        foreach ($aliases in @(
                @('session_id'),
                @('transfer_id'))) {
            $acceptedValue = Get-RegularV4SettlementField -Event $Accepted -Names $aliases
            $ownershipValue = Get-RegularV4SettlementField -Event $Ownership -Names $aliases
            if ([string]::IsNullOrWhiteSpace($acceptedValue) -or
                [string]::IsNullOrWhiteSpace($ownershipValue) -or
                -not [string]::Equals($acceptedValue, $ownershipValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        foreach ($aliases in @(
                @('direction'),
                @('route'),
                @('protocol_version'),
                @('live_route_epoch'),
                @('bridge_decision_generation'))) {
            $acceptedValue = Get-RegularV4SettlementField -Event $Accepted -Names $aliases
            $ownershipValue = Get-RegularV4SettlementField -Event $Ownership -Names $aliases
            if (-not [string]::IsNullOrWhiteSpace($acceptedValue) -and
                -not [string]::IsNullOrWhiteSpace($ownershipValue) -and
                -not [string]::Equals($acceptedValue, $ownershipValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Get-RegularV4TerminalPressureApplyTupleKey {
        param([Parameter(Mandatory = $true)]$Event)

        return [string]::Join('|', @(
                'pressure_apply',
                (Get-FileTransferEventField -Event $Event -Name 'session_id' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'transfer_id' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'direction' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'authority_id' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'successor_authority_id' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'current_authority_id' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'retained_predecessor_authority_id' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'install_generation' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'settlement_outcome' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'apply_status' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'current_authority_cleared' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'retained_predecessor_cleared' -Default ''))).
            ToLowerInvariant()
    }

    function Get-RegularV4TerminalPressureRetirementTupleKey {
        param([Parameter(Mandatory = $true)]$Event)

        return [string]::Join('|', @(
                'pressure_retirement',
                (Get-FileTransferEventField -Event $Event -Name 'session_id' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'transfer_id' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'direction' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'authority_id' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'predecessor_authority_id' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'repair_request_key' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'install_generation' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'install_boundary' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'route' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'protocol_version' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'live_route_epoch' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'runtime_generation' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'terminal_generation' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'leg_generation' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'transport_epoch' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'bridge_recovery_generation' -Default ''),
                (Get-FileTransferEventField -Event $Event -Name 'bridge_decision_generation' -Default ''))).
            ToLowerInvariant()
    }

    function Test-RegularV4TerminalPressureDisposition {
        param(
            [Parameter(Mandatory = $true)]$Accepted
        )

        $acceptedOutcome = (Get-RegularV4SettlementField `
            -Event $Accepted `
            -Names @('outcome', 'settlement_outcome')).Replace('_', '').ToLowerInvariant()
        if ($acceptedOutcome -notin @('transferterminal', 'stalerejected')) {
            # ProgressObserved, MissingDispatch, and SettledStalled still require
            # their runtime-unlock recovery handoff. Pressure retirement alone is
            # only complete disposition evidence for diagnostic final outcomes.
            return $false
        }

        $acceptedAuthority = Get-RegularV4SettlementField -Event $Accepted -Names @('authority_id')
        $acceptedInstallGeneration = Get-RegularV4SettlementField `
            -Event $Accepted `
            -Names @('successor_install_generation', 'install_generation')
        if ([string]::IsNullOrWhiteSpace($acceptedAuthority) -or
            $acceptedAuthority -in @('[redacted]', 'redacted') -or
            [string]::IsNullOrWhiteSpace($acceptedInstallGeneration)) {
            return $false
        }

        [object[]]$matchingRetirements = @($pressureBindingRetiredEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$Accepted.Sequence -and
            (Get-RegularV4SettlementField -Event $_ -Names @('authority_id')) -eq $acceptedAuthority -and
            (Get-RegularV4SettlementField -Event $_ -Names @('install_generation')) -eq $acceptedInstallGeneration -and
            (Get-FileTransferEventField -Event $_ -Name 'install_boundary' -Default '') -eq 'settlement' -and
            (Test-FileTransferRegularV4FrontierRepairLifecycleMatch -Source $Accepted -Candidate $_)
        } | Group-Object { Get-RegularV4TerminalPressureRetirementTupleKey -Event $_ } | ForEach-Object {
            @($_.Group | Sort-Object Sequence, LineNumber)[0]
        } | Sort-Object Sequence, LineNumber)
        if ($matchingRetirements.Count -ne 1) {
            return $false
        }

        $retirement = $matchingRetirements[0]
        [object[]]$matchingApplies = @($pressureSettlementApplyEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$Accepted.Sequence -and
            [int64]$_.Sequence -lt [int64]$retirement.Sequence -and
            (Get-RegularV4SettlementField -Event $_ -Names @('install_generation')) -eq $acceptedInstallGeneration -and
            (Get-RegularV4SettlementField -Event $_ -Names @('settlement_outcome')).Replace('_', '').ToLowerInvariant() -eq
                $acceptedOutcome -and
            (Get-FileTransferEventField -Event $_ -Name 'apply_status' -Default '').ToLowerInvariant() -in @('applied', 'idempotent') -and
            (Get-FileTransferEventField -Event $_ -Name 'current_authority_cleared' -Default '0') -eq '1' -and
            (Get-FileTransferEventField -Event $_ -Name 'retained_predecessor_cleared' -Default '1') -eq '0' -and
            (Get-RegularV4SettlementField -Event $_ -Names @('session_id')) -eq
                (Get-RegularV4SettlementField -Event $Accepted -Names @('session_id')) -and
            (Get-RegularV4SettlementField -Event $_ -Names @('transfer_id')) -eq
                (Get-RegularV4SettlementField -Event $Accepted -Names @('transfer_id')) -and
            (Get-RegularV4SettlementField -Event $_ -Names @('direction')) -eq
                (Get-RegularV4SettlementField -Event $Accepted -Names @('direction'))
        } | Group-Object { Get-RegularV4TerminalPressureApplyTupleKey -Event $_ } | ForEach-Object {
            @($_.Group | Sort-Object Sequence, LineNumber)[0]
        } | Sort-Object Sequence, LineNumber)
        if ($matchingApplies.Count -ne 1) {
            # Authority IDs are intentionally redacted on the Infra apply event.
            # Requiring one exact scope/outcome/install-generation match between
            # acceptance and retirement is the redaction-safe correlation.
            return $false
        }

        $applyAuthority = Get-RegularV4SettlementField -Event $matchingApplies[0] -Names @('authority_id')
        if (-not [string]::IsNullOrWhiteSpace($applyAuthority) -and
            $applyAuthority -notin @('[redacted]', 'redacted') -and
            -not [string]::Equals(
                $applyAuthority,
                $acceptedAuthority,
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }

        return $true
    }

    $distinctAccepted = New-Object System.Collections.Generic.List[object]
    $resolvedAccepted = New-Object System.Collections.Generic.List[object]
    $unresolvedAccepted = New-Object System.Collections.Generic.List[object]
    $unresolvedTupleKeys = @{}
    $seen = @{}
    foreach ($accepted in $acceptedEvents) {
        $tupleKey = Get-RegularV4SettlementTupleKey -Event $accepted
        if ($seen.ContainsKey($tupleKey)) {
            continue
        }
        $seen[$tupleKey] = $true
        $distinctAccepted.Add($accepted) | Out-Null

        $disposition = @($dispositionEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$accepted.Sequence -and
            (Test-RegularV4SettlementDispositionMatch -Accepted $accepted -Disposition $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($disposition.Count -gt 0) {
            $resolvedAccepted.Add($accepted) | Out-Null
        }
        elseif (Test-RegularV4TerminalPressureDisposition -Accepted $accepted) {
            $resolvedAccepted.Add($accepted) | Out-Null
        }
        else {
            $acceptedAuthority = Get-RegularV4SettlementField -Event $accepted -Names @('authority_id')
            [object[]]$legacyOwnership = @()
            if ([string]::IsNullOrWhiteSpace($acceptedAuthority) -or
                $acceptedAuthority -in @('[redacted]', 'redacted')) {
                $legacyOwnership = @($legacyRecoveryOwnershipEvents | Where-Object {
                    [int64]$_.Sequence -lt [int64]$accepted.Sequence -and
                    (Test-RegularV4LegacyRecoveryOwnershipMatch -Accepted $accepted -Ownership $_)
                } | Select-Object -Last 1)
            }
            if ($legacyOwnership.Count -gt 0) {
                $resolvedAccepted.Add($accepted) | Out-Null
            }
            else {
                $unresolvedAccepted.Add($accepted) | Out-Null
                $unresolvedTupleKeys[$tupleKey] = $true
            }
        }
    }

    [object[]]$rawUnresolvedAccepted = @($acceptedEvents | Where-Object {
        $unresolvedTupleKeys.ContainsKey((Get-RegularV4SettlementTupleKey -Event $_))
    })

    return [pscustomobject]@{
        RawCount = $rawUnresolvedAccepted.Count
        DistinctCount = $unresolvedAccepted.Count
        RecoveredCount = 0
        UnresolvedCount = $unresolvedAccepted.Count
        Verdict = if ($unresolvedAccepted.Count -gt 0) { 'fail' } elseif ($distinctAccepted.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = $rawUnresolvedAccepted
        DistinctCandidateEvents = @($unresolvedAccepted.ToArray())
        RecoveredCandidateEvents = @()
        UnresolvedCandidateEvents = @($unresolvedAccepted.ToArray())
        DistinctAcceptedEvents = @($distinctAccepted.ToArray())
        ResolvedAcceptedEvents = @($resolvedAccepted.ToArray())
    }
}

function Get-FileTransferRegularV4FrontierRepairIdentityField {
    param(
        [Parameter(Mandatory = $true)]$Event,
        [Parameter(Mandatory = $true)][string[]]$Names
    )

    foreach ($name in $Names) {
        $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
        if (-not [string]::IsNullOrWhiteSpace($value) -and
            $value -notin @('(none)', 'none', '(missing)', '__missing__', '[redacted]', 'redacted')) {
            return $value
        }
    }
    return ''
}

function Test-FileTransferRegularV4FrontierRepairLifecycleMatch {
    param(
        [Parameter(Mandatory = $true)]$Source,
        [Parameter(Mandatory = $true)]$Candidate
    )

    $sourceAuthority = Get-FileTransferRegularV4FrontierRepairIdentityField `
        -Event $Source `
        -Names @('authority_id', 'frontier_repair_authority_id', 'settlement_authority_id')
    $candidateAuthority = Get-FileTransferRegularV4FrontierRepairIdentityField `
        -Event $Candidate `
        -Names @('authority_id', 'frontier_repair_authority_id', 'settlement_authority_id')
    if (-not [string]::IsNullOrWhiteSpace($sourceAuthority) -and
        -not [string]::IsNullOrWhiteSpace($candidateAuthority) -and
        -not [string]::Equals($sourceAuthority, $candidateAuthority, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }

    $sourceRepairKey = Get-FileTransferRegularV4FrontierRepairIdentityField `
        -Event $Source `
        -Names @('repair_request_key', 'frontier_repair_request_key', 'settlement_repair_request_key')
    $candidateRepairKey = Get-FileTransferRegularV4FrontierRepairIdentityField `
        -Event $Candidate `
        -Names @('repair_request_key', 'frontier_repair_request_key', 'settlement_repair_request_key')
    if ([string]::IsNullOrWhiteSpace($sourceRepairKey) -or
        [string]::IsNullOrWhiteSpace($candidateRepairKey) -or
        -not [string]::Equals($sourceRepairKey, $candidateRepairKey, [System.StringComparison]::Ordinal)) {
        return $false
    }

    foreach ($aliases in @(
            @('session_id'),
            @('transfer_id'),
            @('direction'))) {
        $sourceValue = Get-FileTransferEventField -Event $Source -Name $aliases[0] -Default ''
        $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $aliases[0] -Default ''
        if ([string]::IsNullOrWhiteSpace($sourceValue) -or
            [string]::IsNullOrWhiteSpace($candidateValue) -or
            $sourceValue -in @('(none)', 'none', '(missing)', '__missing__') -or
            $candidateValue -in @('(none)', 'none', '(missing)', '__missing__') -or
            -not [string]::Equals($sourceValue, $candidateValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    # Durable-highest is deliberately excluded: it is a mutable observation,
    # not part of the immutable repair-contract identity.
    foreach ($fieldAliases in @(
            [pscustomobject]@{ Source = @('route'); Candidate = @('route') },
            [pscustomobject]@{ Source = @('protocol_version'); Candidate = @('protocol_version') },
            [pscustomobject]@{ Source = @('live_route_epoch'); Candidate = @('live_route_epoch') },
            [pscustomobject]@{ Source = @('runtime_generation'); Candidate = @('runtime_generation') },
            [pscustomobject]@{ Source = @('terminal_generation'); Candidate = @('terminal_generation') },
            [pscustomobject]@{ Source = @('leg_generation'); Candidate = @('leg_generation') },
            [pscustomobject]@{ Source = @('transport_epoch'); Candidate = @('transport_epoch') },
            [pscustomobject]@{ Source = @('bridge_recovery_generation'); Candidate = @('bridge_recovery_generation') },
            [pscustomobject]@{ Source = @('bridge_decision_generation', 'settlement_bridge_decision_generation'); Candidate = @('bridge_decision_generation', 'settlement_bridge_decision_generation') },
            [pscustomobject]@{ Source = @('route_publication_generation'); Candidate = @('route_publication_generation') },
            [pscustomobject]@{ Source = @('route_commit_generation'); Candidate = @('route_commit_generation') },
            [pscustomobject]@{ Source = @('target_transport'); Candidate = @('target_transport') },
            [pscustomobject]@{ Source = @('frontier_chunk_index'); Candidate = @('frontier_chunk_index') },
            [pscustomobject]@{ Source = @('requested_chunk_count', 'pending_repair_count'); Candidate = @('requested_chunk_count', 'pending_repair_count') },
            [pscustomobject]@{ Source = @('decision_generation', 'settlement_decision_generation'); Candidate = @('decision_generation', 'settlement_decision_generation') })) {
        $sourceValue = Get-FileTransferRegularV4FrontierRepairIdentityField -Event $Source -Names $fieldAliases.Source
        $candidateValue = Get-FileTransferRegularV4FrontierRepairIdentityField -Event $Candidate -Names $fieldAliases.Candidate
        if (-not [string]::IsNullOrWhiteSpace($sourceValue) -and
            -not [string]::IsNullOrWhiteSpace($candidateValue) -and
            -not [string]::Equals($sourceValue, $candidateValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    return $true
}

function Get-FileTransferRegularV4FrontierRepairLifecycleProof {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        $SettlementDispositionProof = $null
    )

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$stalledEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_stalled'
    })
    [object[]]$progressEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_progress_observed'
    })
    if ($null -eq $SettlementDispositionProof) {
        $SettlementDispositionProof =
            Get-FileTransferRegularV4FrontierRepairSettlementDispositionProof -Events $orderedEvents
    }
    [object[]]$acceptedSettledStalledEvents = @(
        @($SettlementDispositionProof.DistinctAcceptedEvents) | Where-Object {
            (Get-FileTransferRegularV4FrontierRepairIdentityField `
                -Event $_ `
                -Names @('outcome', 'settlement_outcome')).Replace('_', '').ToLowerInvariant() -eq 'settledstalled'
        }
    )
    [object[]]$adoptionEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_frontier_repair_settlement_handoff_adopted'
    })
    [object[]]$closureWonDiscardEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_frontier_repair_settlement_handoff_discarded' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'receive_recovery_lease_closure_won'
    })
    [object[]]$retainedProjectionEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_projection_retained' -and
        (Get-FileTransferEventField -Event $_ -Name 'source_authority_lifecycle' -Default '') -eq 'retired' -and
        (Get-FileTransferEventField -Event $_ -Name 'source_authority_settlement' -Default '').Replace('_', '').ToLowerInvariant() -eq
            'settledstalled'
    })
    [object[]]$publishedProjectionEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_projection_published'
    })
    [object[]]$appliedPeerStateEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_v4_state_received' -and
        (Get-FileTransferEventField -Event $_ -Name 'applied' -Default '0') -eq '1' -and
        (Get-FileTransferEventInt64Field -Event $_ -Name 'missing_range_count' -Default 0) -gt 0
    })
    [object[]]$peerPressureBindingStagedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_pressure_binding_staged'
    })
    [object[]]$peerPressureBindingCommittedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_pressure_binding_committed'
    })

    function Test-RegularV4RepairPeerProjectionIdentityMatch {
        param(
            [Parameter(Mandatory = $true)]$Projection,
            [Parameter(Mandatory = $true)]$Candidate
        )

        foreach ($field in @('session_id', 'transfer_id')) {
            # Retained artifacts may redact transfer identifiers consistently.
            # Redaction is still a usable scope value here because the peer
            # projection chain also requires the complete immutable route and
            # repair tuple below.
            $projectionValue = Get-FileTransferEventField -Event $Projection -Name $field -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($projectionValue) -or
                [string]::IsNullOrWhiteSpace($candidateValue) -or
                -not [string]::Equals(
                    $projectionValue,
                    $candidateValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        $projectionDirection = Get-FileTransferEventField -Event $Projection -Name 'direction' -Default ''
        $candidateDirection = Get-FileTransferEventField -Event $Candidate -Name 'direction' -Default ''
        if ([string]::IsNullOrWhiteSpace($projectionDirection) -or
            [string]::IsNullOrWhiteSpace($candidateDirection) -or
            [string]::Equals(
                $projectionDirection,
                $candidateDirection,
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }

        foreach ($field in @(
                'route',
                'protocol_version',
                'live_route_epoch',
                'runtime_generation',
                'terminal_generation',
                'leg_generation',
                'transport_epoch',
                'route_publication_generation',
                'route_commit_generation')) {
            $projectionValue = Get-FileTransferRegularV4FrontierRepairIdentityField `
                -Event $Projection `
                -Names @($field)
            $candidateValue = Get-FileTransferRegularV4FrontierRepairIdentityField `
                -Event $Candidate `
                -Names @($field)
            if (-not [string]::IsNullOrWhiteSpace($projectionValue) -and
                -not [string]::IsNullOrWhiteSpace($candidateValue) -and
                -not [string]::Equals(
                    $projectionValue,
                    $candidateValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        $projectedRepairKey = Get-FileTransferRegularV4FrontierRepairIdentityField `
            -Event $Projection `
            -Names @('projected_repair_request_key', 'source_repair_request_key')
        $candidateRepairKey = Get-FileTransferRegularV4FrontierRepairIdentityField `
            -Event $Candidate `
            -Names @('repair_request_key')
        if (-not [string]::IsNullOrWhiteSpace($candidateRepairKey) -and
            -not [string]::Equals(
                $projectedRepairKey,
                $candidateRepairKey,
                [System.StringComparison]::Ordinal)) {
            return $false
        }

        $projectedRanges = Get-FileTransferRegularV4FrontierRepairIdentityField `
            -Event $Projection `
            -Names @('projected_ranges')
        $candidateRanges = Get-FileTransferRegularV4FrontierRepairIdentityField `
            -Event $Candidate `
            -Names @('projected_ranges')
        if (-not [string]::IsNullOrWhiteSpace($candidateRanges) -and
            -not [string]::Equals(
                $projectedRanges,
                $candidateRanges,
                [System.StringComparison]::Ordinal)) {
            return $false
        }
        return $true
    }
    [object[]]$resolvedSettledStalledEvents = @(
        foreach ($accepted in $acceptedSettledStalledEvents) {
            $adoption = @($adoptionEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$accepted.Sequence -and
                (Test-FileTransferRegularV4FrontierRepairLifecycleMatch -Source $accepted -Candidate $_)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            if ($adoption.Count -gt 0) {
                $adoption[0]
                continue
            }

            $acceptedAuthority = Get-FileTransferRegularV4FrontierRepairIdentityField -Event $accepted -Names @('authority_id')
            $acceptedRepairKey = Get-FileTransferRegularV4FrontierRepairIdentityField -Event $accepted -Names @('repair_request_key')
            $projection = @($retainedProjectionEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$accepted.Sequence -and
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $_ -Names @('authority_id')) -eq $acceptedAuthority -and
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $_ -Names @('source_repair_request_key')) -eq $acceptedRepairKey -and
                (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $accepted -Candidate $_)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            if ($projection.Count -eq 0) {
                continue
            }

            $closureWon = @($closureWonDiscardEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$projection[0].Sequence -and
                (Test-FileTransferRegularV4FrontierRepairLifecycleMatch -Source $accepted -Candidate $_)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            if ($closureWon.Count -gt 0) {
                $closureWon[0]
                continue
            }

            $published = @($publishedProjectionEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$projection[0].Sequence -and
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $_ -Names @('authority_id')) -eq
                    $acceptedAuthority -and
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $_ -Names @('source_repair_request_key')) -eq
                    $acceptedRepairKey -and
                (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $projection[0] -Candidate $_)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            if ($published.Count -eq 0) {
                continue
            }

            $peerState = @($appliedPeerStateEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$published[0].Sequence -and
                (Test-RegularV4RepairPeerProjectionIdentityMatch `
                    -Projection $published[0] `
                    -Candidate $_)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            if ($peerState.Count -eq 0) {
                continue
            }

            [object[]]$stagedPeerBindings = @($peerPressureBindingStagedEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$peerState[0].Sequence -and
                (Test-RegularV4RepairPeerProjectionIdentityMatch `
                    -Projection $published[0] `
                    -Candidate $_)
            } | Sort-Object Sequence, LineNumber)
            foreach ($stagedPeerBinding in $stagedPeerBindings) {
                $peerAuthorityId = Get-FileTransferRegularV4FrontierRepairIdentityField `
                    -Event $stagedPeerBinding `
                    -Names @('authority_id')
                $peerInstallGeneration = Get-FileTransferRegularV4FrontierRepairIdentityField `
                    -Event $stagedPeerBinding `
                    -Names @('install_generation')
                $committedPeerBinding = @($peerPressureBindingCommittedEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$stagedPeerBinding.Sequence -and
                    (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $_ -Names @('authority_id')) -eq
                        $peerAuthorityId -and
                    (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $_ -Names @('install_generation')) -eq
                        $peerInstallGeneration -and
                    (Test-RegularV4RepairPeerProjectionIdentityMatch `
                        -Projection $published[0] `
                        -Candidate $_)
                } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                if ($committedPeerBinding.Count -gt 0) {
                    # The peer-local binding proves that the accepted receiver
                    # settlement completed its projection handoff.  Preserve
                    # the original same-direction authority as the resolution
                    # anchor so the stalled attempt can be matched exactly.
                    $accepted
                    break
                }
            }
        }
    )

    $distinct = New-Object System.Collections.Generic.List[object]
    $recovered = New-Object System.Collections.Generic.List[object]
    $unresolved = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($stalled in $stalledEvents) {
        $key = [string]::Join('|', @(
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $stalled -Names @('session_id')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $stalled -Names @('transfer_id')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $stalled -Names @('direction')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $stalled -Names @('repair_request_key')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $stalled -Names @('route')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $stalled -Names @('live_route_epoch')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $stalled -Names @('runtime_generation')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $stalled -Names @('terminal_generation')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $stalled -Names @('leg_generation')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $stalled -Names @('transport_epoch')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $stalled -Names @('bridge_decision_generation'))))
        if ($seen.ContainsKey($key)) {
            continue
        }
        $seen[$key] = $true
        $distinct.Add($stalled) | Out-Null

        $resolution = @(
            # A later authority rejection is not proof that an earlier stalled
            # repair lifecycle completed.  Only progress or the exact accepted
            # settlement/projection handoff may resolve the stalled attempt.
            @($progressEvents + $resolvedSettledStalledEvents) | Where-Object {
                [int64]$_.Sequence -gt [int64]$stalled.Sequence -and
                (Test-FileTransferRegularV4FrontierRepairLifecycleMatch -Source $stalled -Candidate $_)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1
        )
        if ($resolution.Count -gt 0) {
            $recovered.Add($stalled) | Out-Null
        }
        else {
            $unresolved.Add($stalled) | Out-Null
        }
    }

    return [pscustomobject]@{
        RawCount = $stalledEvents.Count
        DistinctCount = $distinct.Count
        RecoveredCount = $recovered.Count
        UnresolvedCount = $unresolved.Count
        Verdict = if ($unresolved.Count -gt 0) { 'fail' } elseif ($distinct.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = $stalledEvents
        DistinctCandidateEvents = @($distinct.ToArray())
        RecoveredCandidateEvents = @($recovered.ToArray())
        UnresolvedCandidateEvents = @($unresolved.ToArray())
        ResolvedSettledStalledEvents = $resolvedSettledStalledEvents
    }
}

function Get-FileTransferRegularV4FrontierRepairPressureAuthorityLifecycleSplitProof {
    param(
        [AllowEmptyCollection()][object[]]$Events = @()
    )

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$installEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'filetransfer_regular_v4_frontier_repair_initial_pressure_install_accepted',
            'filetransfer_regular_v4_frontier_repair_successor_pressure_install_accepted',
            'filetransfer_regular_v4_frontier_repair_successor_pressure_install_idempotent')
    })
    [object[]]$livenessEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_v4_receive_liveness_summary'
    })
    [object[]]$currentAuthorityEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_v4_repair_suppressed' -and
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq 'current_authority_work_outstanding'
    })
    [object[]]$settlementRejectedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_settlement_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'pressure_reason' -Default '') -in @('', '(none)', 'none') -and
        (Get-FileTransferEventField -Event $_ -Name 'current_successor_authority_id' -Default '') -in @('', '(none)', 'none')
    })

    function Test-RegularV4PressureWriterMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        $leftWriter = Get-FileTransferEventField -Event $Left -Name 'log_writer_id' -Default ''
        $rightWriter = Get-FileTransferEventField -Event $Right -Name 'log_writer_id' -Default ''
        return -not [string]::IsNullOrWhiteSpace($leftWriter) -and
            -not [string]::IsNullOrWhiteSpace($rightWriter) -and
            [string]::Equals($leftWriter, $rightWriter, [System.StringComparison]::OrdinalIgnoreCase)
    }

    function Test-RegularV4PressureCoreScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Install,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if (-not (Test-RegularV4PressureWriterMatch -Left $Install -Right $Candidate)) {
            return $false
        }

        $installAuthority = Get-FileTransferRegularV4FrontierRepairIdentityField `
            -Event $Install `
            -Names @('authority_id', 'current_successor_authority_id')
        $candidateAuthority = Get-FileTransferRegularV4FrontierRepairIdentityField `
            -Event $Candidate `
            -Names @('authority_id', 'current_successor_authority_id')
        if (-not [string]::IsNullOrWhiteSpace($installAuthority) -and
            -not [string]::IsNullOrWhiteSpace($candidateAuthority) -and
            -not [string]::Equals($installAuthority, $candidateAuthority, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }

        foreach ($aliases in @(
                @('session_id'),
                @('transfer_id'),
                @('repair_request_key'))) {
            $left = Get-FileTransferEventField -Event $Install -Name $aliases[0] -Default ''
            $right = Get-FileTransferEventField -Event $Candidate -Name $aliases[0] -Default ''
            if ([string]::IsNullOrWhiteSpace($left) -or
                [string]::IsNullOrWhiteSpace($right) -or
                $left -in @('(none)', 'none', '(missing)', '__missing__') -or
                $right -in @('(none)', 'none', '(missing)', '__missing__') -or
                -not [string]::Equals($left, $right, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        $installDecisionGeneration = Get-FileTransferRegularV4FrontierRepairIdentityField `
            -Event $Install `
            -Names @('decision_generation', 'settlement_decision_generation')
        $candidateDecisionGeneration = Get-FileTransferRegularV4FrontierRepairIdentityField `
            -Event $Candidate `
            -Names @('repair_generation', 'decision_generation', 'settlement_decision_generation')
        if (-not [string]::IsNullOrWhiteSpace($installDecisionGeneration) -and
            -not [string]::IsNullOrWhiteSpace($candidateDecisionGeneration) -and
            -not [string]::Equals($installDecisionGeneration, $candidateDecisionGeneration, [System.StringComparison]::Ordinal)) {
            return $false
        }
        return $true
    }

    $raw = New-Object System.Collections.Generic.List[object]
    $distinct = New-Object System.Collections.Generic.List[object]
    $recovered = New-Object System.Collections.Generic.List[object]
    $unresolved = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($install in $installEvents) {
        $installSequence = [int64]$install.Sequence
        $nextWriterInstall = @($installEvents | Where-Object {
            [int64]$_.Sequence -gt $installSequence -and
            (Test-RegularV4PressureWriterMatch -Left $install -Right $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $installEndSequence = if ($nextWriterInstall.Count -gt 0) {
            [int64]$nextWriterInstall[0].Sequence
        }
        else {
            [int64]::MaxValue
        }

        $active = @($livenessEvents | Where-Object {
            [int64]$_.Sequence -gt $installSequence -and
            [int64]$_.Sequence -lt $installEndSequence -and
            (Get-FileTransferEventField -Event $_ -Name 'regular_v4_control_feedback_pressure' -Default '0') -eq '1' -and
            (Test-RegularV4PressureWriterMatch -Left $install -Right $_) -and
            (Test-FileTransferRegularV4FrontierRepairLifecycleMatch -Source $install -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($active.Count -eq 0) {
            continue
        }

        $pressureLost = @($livenessEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$active[0].Sequence -and
            [int64]$_.Sequence -lt $installEndSequence -and
            (Get-FileTransferEventField -Event $_ -Name 'regular_v4_control_feedback_pressure' -Default '1') -eq '0' -and
            (Get-FileTransferRegularV4FrontierRepairIdentityField `
                -Event $_ `
                -Names @('regular_v4_frontier_repair_coordinator_binding_state', 'regular_v4_frontier_repair_binding_state')) -eq '' -and
            (Test-RegularV4PressureWriterMatch -Left $install -Right $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($pressureLost.Count -eq 0) {
            continue
        }

        $coreStillCurrent = @($currentAuthorityEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$pressureLost[0].Sequence -and
            [int64]$_.Sequence -lt $installEndSequence -and
            (Test-RegularV4PressureCoreScopeMatch -Install $install -Candidate $_) -and
            ((Get-FileTransferEventField -Event $_ -Name 'queued' -Default '0') -eq '1' -or
                (Get-FileTransferEventField -Event $_ -Name 'in_flight' -Default '0') -eq '1')
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($coreStillCurrent.Count -eq 0) {
            continue
        }

        $rejectedSettlement = @($settlementRejectedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$coreStillCurrent[0].Sequence -and
            (Test-RegularV4PressureWriterMatch -Left $install -Right $_) -and
            (Test-FileTransferRegularV4FrontierRepairLifecycleMatch -Source $install -Candidate $_) -and
            (Test-RegularV4PressureCoreScopeMatch -Install $_ -Candidate $coreStillCurrent[0])
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($rejectedSettlement.Count -eq 0) {
            continue
        }

        $candidate = $pressureLost[0]
        $raw.Add($candidate) | Out-Null
        $identity = [string]::Join('|', @(
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $install -Names @('session_id')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $install -Names @('transfer_id')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $install -Names @('direction')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $install -Names @('repair_request_key')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $install -Names @('route')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $install -Names @('runtime_generation')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $install -Names @('leg_generation')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $install -Names @('bridge_decision_generation')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $install -Names @('decision_generation')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $install -Names @('install_generation'))))
        if ($seen.ContainsKey($identity)) {
            continue
        }
        $seen[$identity] = $true
        $distinct.Add($candidate) | Out-Null

        $reinstall = @($installEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$candidate.Sequence -and
            [int64]$_.Sequence -lt [int64]$rejectedSettlement[0].Sequence -and
            (Test-RegularV4PressureWriterMatch -Left $install -Right $_) -and
            (Test-FileTransferRegularV4FrontierRepairLifecycleMatch -Source $install -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($reinstall.Count -gt 0) {
            $recovered.Add($candidate) | Out-Null
        }
        else {
            $unresolved.Add($candidate) | Out-Null
        }
    }

    return [pscustomobject]@{
        RawCount = $raw.Count
        DistinctCount = $distinct.Count
        RecoveredCount = $recovered.Count
        UnresolvedCount = $unresolved.Count
        Verdict = if ($unresolved.Count -gt 0) { 'fail' } elseif ($distinct.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = @($raw.ToArray())
        DistinctCandidateEvents = @($distinct.ToArray())
        RecoveredCandidateEvents = @($recovered.ToArray())
        UnresolvedCandidateEvents = @($unresolved.ToArray())
    }
}

function Get-FileTransferRegularV4FrontierRepairPressureRecoveryHandoffProof {
    param(
        [AllowEmptyCollection()][object[]]$Events = @()
    )

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$bindingCommittedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_pressure_binding_committed'
    })
    [object[]]$bindingClearedEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'filetransfer_regular_v4_frontier_repair_pressure_binding_retired',
            'filetransfer_regular_v4_frontier_repair_pressure_binding_invalidated')
    })
    [object[]]$recoveryRejectedEvents = @($orderedEvents | Where-Object {
        ($_.EventName -eq 'filetransfer_recovery_authority_rejected' -and
            (Get-FileTransferEventField -Event $_ -Name 'action_kind' -Default '') -eq 'BridgeReceiveStallRecovery') -or
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_pressure_recovery_handoff_rejected'
    })
    [object[]]$handoffCommittedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_pressure_recovery_handoff_committed'
    })
    [object[]]$bridgeRecoveryGrantedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_bridge_recovery_authority_granted' -and
        (Get-FileTransferEventField -Event $_ -Name 'action_kind' -Default '') -eq 'BridgeReceiveStallRecovery'
    })
    [object[]]$recoveryLeaseGrantedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_recovery_liveness_lease_granted' -and
        (Get-FileTransferEventField -Event $_ -Name 'action_kind' -Default '') -eq 'BridgeReceiveStallRecovery'
    })
    [object[]]$withoutAuthorityEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'session_liveness_timeout_active_filetransfer_progress_observed_without_recovery_authority'
    })
    [object[]]$timeoutEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'session_liveness_timeout'
    })

    function Test-PressureRecoveryTransferMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        foreach ($name in @('session_id', 'transfer_id', 'direction')) {
            # Run artifacts redact session/transfer values consistently.  They
            # remain valid correlation evidence only inside the unique
            # direction/runtime/install scope enforced by the caller.
            $leftValue = Get-FileTransferEventField -Event $Left -Name $name -Default ''
            $rightValue = Get-FileTransferEventField -Event $Right -Name $name -Default ''
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                $leftValue -in @('(none)', 'none', '(missing)', '__missing__') -or
                $rightValue -in @('(none)', 'none', '(missing)', '__missing__') -or
                -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Test-PressureRecoveryCurrentScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Binding,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if (-not (Test-PressureRecoveryTransferMatch -Left $Binding -Right $Candidate)) {
            return $false
        }

        foreach ($aliases in @(
                [pscustomobject]@{ Binding = @('route'); Candidate = @('route', 'current_route') },
                [pscustomobject]@{ Binding = @('protocol_version'); Candidate = @('protocol_version', 'current_protocol_version') },
                [pscustomobject]@{ Binding = @('live_route_epoch'); Candidate = @('live_route_epoch', 'current_live_route_epoch') },
                [pscustomobject]@{ Binding = @('runtime_generation'); Candidate = @('runtime_generation', 'current_runtime_generation') },
                [pscustomobject]@{ Binding = @('terminal_generation'); Candidate = @('terminal_generation', 'current_terminal_generation') },
                [pscustomobject]@{ Binding = @('leg_generation'); Candidate = @('leg_generation', 'attempted_leg_generation') },
                [pscustomobject]@{ Binding = @('transport_epoch'); Candidate = @('transport_epoch', 'attempted_transport_epoch') },
                [pscustomobject]@{ Binding = @('bridge_recovery_generation'); Candidate = @('bridge_recovery_generation', 'attempted_bridge_recovery_generation') })) {
            $leftValue = Get-FileTransferRegularV4FrontierRepairIdentityField -Event $Binding -Names $aliases.Binding
            $rightValue = Get-FileTransferRegularV4FrontierRepairIdentityField -Event $Candidate -Names $aliases.Candidate
            if (-not [string]::IsNullOrWhiteSpace($leftValue) -and
                -not [string]::IsNullOrWhiteSpace($rightValue) -and
                -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Test-PressureRecoveryCompleteRuntimeScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        if (-not (Test-PressureRecoveryTransferMatch -Left $Left -Right $Right)) {
            return $false
        }

        foreach ($name in @(
                'route',
                'protocol_version',
                'live_route_epoch',
                'runtime_generation',
                'terminal_generation',
                'leg_generation',
                'transport_epoch',
                'bridge_recovery_generation')) {
            $leftValue = Get-FileTransferEventField -Event $Left -Name $name -Default ''
            $rightValue = Get-FileTransferEventField -Event $Right -Name $name -Default ''
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                $leftValue -in @('(none)', 'none', '(missing)', '__missing__') -or
                $rightValue -in @('(none)', 'none', '(missing)', '__missing__') -or
                -not [string]::Equals(
                    $leftValue,
                    $rightValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Get-CurrentPressureBindingAtBoundary {
        param(
            [Parameter(Mandatory = $true)]$Boundary
        )

        $byAuthority = @{}
        foreach ($binding in @($bindingCommittedEvents | Where-Object {
                    [int64]$_.Sequence -lt [int64]$Boundary.Sequence -and
                    (Test-PressureRecoveryCurrentScopeMatch -Binding $_ -Candidate $Boundary)
                } | Sort-Object Sequence, LineNumber)) {
            $authority = Get-FileTransferRegularV4FrontierRepairIdentityField -Event $binding -Names @('authority_id')
            if (-not [string]::IsNullOrWhiteSpace($authority)) {
                $byAuthority[$authority.ToLowerInvariant()] = $binding
            }
        }

        [object[]]$current = @(foreach ($authorityKey in @($byAuthority.Keys)) {
            $binding = $byAuthority[$authorityKey]
            $cleared = @($bindingClearedEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$binding.Sequence -and
                [int64]$_.Sequence -lt [int64]$Boundary.Sequence -and
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $_ -Names @('authority_id')).ToLowerInvariant() -eq
                    $authorityKey
            } | Select-Object -First 1)
            if ($cleared.Count -eq 0) {
                $binding
            }
        })
        if ($current.Count -eq 1) {
            return $current[0]
        }
        return $null
    }

    function Test-PressureRecoveryExplicitRejection {
        param([Parameter(Mandatory = $true)]$Event)

        foreach ($name in @('mismatch_kind', 'rejection_reason', 'decision_reason', 'reason')) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if ($value -in @(
                    'installed_repair_pressure_not_retired_before_receive_recovery',
                    'regular_v4_frontier_repair_pressure_retirement_required')) {
                return $true
            }
        }
        return $false
    }

    function Test-PressureRecoveryLegacyTimeoutChain {
        param([Parameter(Mandatory = $true)]$Rejection)

        $withoutAuthority = @($withoutAuthorityEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$Rejection.Sequence -and
            [int64]$_.Sequence -le ([int64]$Rejection.Sequence + 20L) -and
            (Test-PressureRecoveryTransferMatch -Left $Rejection -Right $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($withoutAuthority.Count -eq 0) {
            return $false
        }

        # Session identifiers are redacted consistently in retained artifacts.
        # Compare that raw value exactly; the identity helper intentionally
        # removes redaction markers and would turn a missing identity into a
        # wildcard here.  The caller has already required one unique current
        # pressure binding for this rejection boundary.
        $session = Get-FileTransferEventField -Event $Rejection -Name 'session_id' -Default ''
        if ([string]::IsNullOrWhiteSpace($session) -or
            $session -in @('(none)', 'none', '(missing)', '__missing__')) {
            return $false
        }
        return @($timeoutEvents | Where-Object {
            $timeoutSession = Get-FileTransferEventField -Event $_ -Name 'session_id' -Default ''
            [int64]$_.Sequence -gt [int64]$withoutAuthority[0].Sequence -and
            [int64]$_.Sequence -le ([int64]$Rejection.Sequence + 20L) -and
            -not [string]::IsNullOrWhiteSpace($timeoutSession) -and
            $timeoutSession -notin @('(none)', 'none', '(missing)', '__missing__') -and
            [string]::Equals($timeoutSession, $session, [System.StringComparison]::OrdinalIgnoreCase)
        } | Select-Object -First 1).Count -gt 0
    }

    function Test-PressureRecoveryHandoffCompleted {
        param(
            [Parameter(Mandatory = $true)]$Binding,
            [Parameter(Mandatory = $true)]$Candidate
        )

        $authority = Get-FileTransferRegularV4FrontierRepairIdentityField -Event $Binding -Names @('authority_id')
        $installGeneration = Get-FileTransferRegularV4FrontierRepairIdentityField -Event $Binding -Names @('install_generation')
        $sourceBridgeDecisionGeneration = Get-FileTransferEventField `
            -Event $Binding `
            -Name 'bridge_decision_generation' `
            -Default ''
        if ([string]::IsNullOrWhiteSpace($authority) -or
            [string]::IsNullOrWhiteSpace($installGeneration) -or
            [string]::IsNullOrWhiteSpace($sourceBridgeDecisionGeneration)) {
            return $false
        }
        $commit = @($handoffCommittedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$Candidate.Sequence -and
            (Test-PressureRecoveryCurrentScopeMatch -Binding $Binding -Candidate $_) -and
            (Test-PressureRecoveryCompleteRuntimeScopeMatch -Left $Binding -Right $_) -and
            (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $_ -Names @('authority_id')) -eq $authority -and
            (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $_ -Names @('install_generation')) -eq $installGeneration -and
            (Get-FileTransferEventField -Event $_ -Name 'source_bridge_decision_generation' -Default '') -eq
                $sourceBridgeDecisionGeneration -and
            (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $_ -Names @('settlement_outcome')).Replace('_', '').ToLowerInvariant() -eq 'stalerejected' -and
            (Get-FileTransferEventField -Event $_ -Name 'settlement_reason' -Default '') -eq
                'bridge_receive_stall_recovery_pressure_handoff' -and
            (Get-FileTransferEventField -Event $_ -Name 'recovery_action' -Default '') -eq
                'BridgeReceiveStallRecovery' -and
            (Get-FileTransferEventField -Event $_ -Name 'apply_status' -Default '').ToLowerInvariant() -in @('applied', 'idempotent') -and
            (Get-FileTransferEventField -Event $_ -Name 'current_authority_cleared' -Default '0') -eq '1' -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'bridge_decision_generation' -Default 0) -gt 0 -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'recovery_liveness_lease_generation' -Default 0) -gt 0
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($commit.Count -eq 0) {
            return $false
        }

        $decisionGeneration = Get-FileTransferEventField -Event $commit[0] -Name 'bridge_decision_generation' -Default ''
        $leaseGeneration = Get-FileTransferEventField -Event $commit[0] -Name 'recovery_liveness_lease_generation' -Default ''
        $leaseAuthorityId = Get-FileTransferEventField `
            -Event $commit[0] `
            -Name 'recovery_liveness_lease_authority_id' `
            -Default ''
        if ([string]::IsNullOrWhiteSpace($leaseAuthorityId) -or
            $leaseAuthorityId -in @('(none)', 'none', '(missing)', '__missing__')) {
            return $false
        }

        [object[]]$bridgeGrant = @($bridgeRecoveryGrantedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$commit[0].Sequence -and
            (Test-PressureRecoveryTransferMatch -Left $commit[0] -Right $_) -and
            (Test-PressureRecoveryCompleteRuntimeScopeMatch -Left $commit[0] -Right $_) -and
            (Get-FileTransferEventField -Event $_ -Name 'bridge_decision_generation' -Default '') -eq $decisionGeneration -and
            (Get-FileTransferEventField -Event $_ -Name 'recovery_liveness_lease_generation' -Default '') -eq $leaseGeneration -and
            (Get-FileTransferEventField -Event $_ -Name 'recovery_liveness_lease_authority_id' -Default '') -eq $leaseAuthorityId -and
            (Get-FileTransferEventField -Event $_ -Name 'recovery_liveness_lease_state' -Default '') -eq 'Active'
        } | Sort-Object Sequence, LineNumber)
        if ($bridgeGrant.Count -eq 0) {
            return $false
        }

        [object[]]$leaseGrant = @($recoveryLeaseGrantedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$commit[0].Sequence -and
            (Test-PressureRecoveryTransferMatch -Left $commit[0] -Right $_) -and
            (Test-PressureRecoveryCompleteRuntimeScopeMatch -Left $commit[0] -Right $_) -and
            (Get-FileTransferEventField -Event $_ -Name 'recovery_liveness_lease_generation' -Default '') -eq $leaseGeneration -and
            (Get-FileTransferEventField -Event $_ -Name 'recovery_liveness_lease_authority_id' -Default '') -eq $leaseAuthorityId -and
            (Get-FileTransferEventField -Event $_ -Name 'recovery_liveness_lease_state' -Default '') -eq 'Active'
        } | Sort-Object Sequence, LineNumber)
        return $leaseGrant.Count -gt 0
    }

    $raw = New-Object System.Collections.Generic.List[object]
    $distinct = New-Object System.Collections.Generic.List[object]
    $recovered = New-Object System.Collections.Generic.List[object]
    $unresolved = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($rejection in $recoveryRejectedEvents) {
        $binding = Get-CurrentPressureBindingAtBoundary -Boundary $rejection
        if ($null -eq $binding) {
            continue
        }

        $explicit = Test-PressureRecoveryExplicitRejection -Event $rejection
        $legacy = -not $explicit -and
            $rejection.EventName -eq 'filetransfer_recovery_authority_rejected' -and
            (Get-FileTransferEventInt64Field -Event $rejection -Name 'recovery_decision_generation' -Default 0) -eq 0 -and
            (Get-FileTransferEventInt64Field -Event $rejection -Name 'recovery_liveness_lease_generation' -Default 0) -eq 0 -and
            (Test-PressureRecoveryLegacyTimeoutChain -Rejection $rejection)
        if (-not $explicit -and -not $legacy) {
            continue
        }

        $raw.Add($rejection) | Out-Null
        $authority = Get-FileTransferRegularV4FrontierRepairIdentityField -Event $binding -Names @('authority_id')
        $identity = [string]::Join('|', @(
                (Get-FileTransferEventField -Event $binding -Name 'session_id' -Default ''),
                (Get-FileTransferEventField -Event $binding -Name 'transfer_id' -Default ''),
                (Get-FileTransferEventField -Event $binding -Name 'direction' -Default ''),
                $authority,
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $binding -Names @('install_generation')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $binding -Names @('repair_request_key')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $binding -Names @('runtime_generation')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $binding -Names @('terminal_generation')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $binding -Names @('leg_generation')),
                (Get-FileTransferRegularV4FrontierRepairIdentityField -Event $binding -Names @('transport_epoch')),
                'BridgeReceiveStallRecovery')).ToLowerInvariant()
        if ($seen.ContainsKey($identity)) {
            continue
        }
        $seen[$identity] = $true
        $distinct.Add($rejection) | Out-Null

        if (Test-PressureRecoveryHandoffCompleted -Binding $binding -Candidate $rejection) {
            $recovered.Add($rejection) | Out-Null
        }
        else {
            $unresolved.Add($rejection) | Out-Null
        }
    }

    return [pscustomobject]@{
        RawCount = $raw.Count
        DistinctCount = $distinct.Count
        RecoveredCount = $recovered.Count
        UnresolvedCount = $unresolved.Count
        Verdict = if ($unresolved.Count -gt 0) { 'fail' } elseif ($distinct.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = @($raw.ToArray())
        DistinctCandidateEvents = @($distinct.ToArray())
        RecoveredCandidateEvents = @($recovered.ToArray())
        UnresolvedCandidateEvents = @($unresolved.ToArray())
    }
}

function Test-FileTransferRuntimeUnlockRecoverySettlementMissingFirstEdgeEligible {
    param(
        [Parameter(Mandatory = $true)]$MissingEvent,
        [AllowEmptyCollection()][object[]]$SettlementEvents = @(),
        [AllowEmptyCollection()][object[]]$DispositionGapEvents = @()
    )

    $direction = Get-FileTransferEventField -Event $MissingEvent -Name 'direction' -Default ''
    if (-not [string]::IsNullOrWhiteSpace($direction) -and
        $direction -notin @('(none)', 'none', '(missing)', '__missing__')) {
        return $true
    }

    $scopeFields = @(
        'session_id',
        'transfer_id',
        'route',
        'protocol_version',
        'live_route_epoch',
        'bridge_decision_generation')
    $matchingAcceptedByIdentity = @{}
    foreach ($accepted in @($SettlementEvents | Where-Object {
                $null -ne $_ -and
                $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_settlement_accepted'
            })) {
        $matches = $true
        foreach ($field in $scopeFields) {
            $left = Get-FileTransferEventField -Event $MissingEvent -Name $field -Default ''
            $right = Get-FileTransferEventField -Event $accepted -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($left) -or
                [string]::IsNullOrWhiteSpace($right) -or
                $left -in @('(none)', 'none', '(missing)', '__missing__') -or
                $right -in @('(none)', 'none', '(missing)', '__missing__') -or
                -not [string]::Equals($left, $right, [System.StringComparison]::OrdinalIgnoreCase)) {
                $matches = $false
                break
            }
        }
        if ($matches) {
            $outcome = Get-FileTransferRegularV4RecoveryLeaseField `
                -Event $accepted `
                -Names @('outcome', 'settlement_outcome')
            if ($outcome.Replace('_', '').ToLowerInvariant() -eq 'superseded') {
                continue
            }
            $identity = @(
                'session_id',
                'transfer_id',
                'direction',
                'authority_id',
                'repair_request_key',
                'decision_generation') | ForEach-Object {
                    (Get-FileTransferEventField -Event $accepted -Name $_ -Default '(missing)').ToLowerInvariant()
                }
            $identity += $outcome.Replace('_', '').ToLowerInvariant()
            $matchingAcceptedByIdentity[[string]::Join('|', $identity)] = $accepted
        }
    }

    if ($matchingAcceptedByIdentity.Count -ne 1) {
        return $true
    }

    $onlyAccepted = @($matchingAcceptedByIdentity.Values)[0]
    $hasExactDispositionGap = @($DispositionGapEvents | Where-Object {
        $null -ne $_ -and
        [int64]$_.Sequence -eq [int64]$onlyAccepted.Sequence -and
        [int]$_.LineNumber -eq [int]$onlyAccepted.LineNumber
    }).Count -gt 0
    if ($hasExactDispositionGap) {
        # Keep the explicit runtime event in semantic counts, but do not let
        # incomplete direction scope outrank the sole exact accepted
        # settlement whose disposition cannot be verified.
        return $false
    }

    return $true
}

function Get-FileTransferRegularV4FrontierRepairSuccessorPressureInstallProof {
    param(
        [AllowEmptyCollection()][object[]]$Events = @()
    )

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$contractSettlements = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_contract_settled'
    })
    [object[]]$acceptedSettlements = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_settlement_accepted'
    })
    [object[]]$rejectedSettlements = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_settlement_rejected'
    })
    [object[]]$projectionEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'filetransfer_regular_v4_frontier_repair_projection_retained',
            'filetransfer_regular_v4_frontier_repair_successor_pressure_install_staged',
            'filetransfer_regular_v4_frontier_repair_pressure_install_requested')
    })
    [object[]]$installDecisionEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'filetransfer_regular_v4_frontier_repair_successor_pressure_install_decided',
            'filetransfer_regular_v4_frontier_repair_successor_pressure_install_accepted',
            'filetransfer_regular_v4_frontier_repair_successor_pressure_install_idempotent',
            'filetransfer_regular_v4_frontier_repair_successor_pressure_install_rejected',
            'filetransfer_regular_v4_frontier_repair_pressure_install_decided')
    })
    [object[]]$dispatchEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_dispatched'
    })

    function Get-RegularV4PressureField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Names
        )
        foreach ($name in $Names) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and $value -notin @('(none)', 'none')) {
                return $value
            }
        }
        return ''
    }

    function Test-RegularV4PressureScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Projection,
            [Parameter(Mandatory = $true)]$Candidate
        )
        foreach ($fieldAliases in @(
                [pscustomobject]@{ Projection = @('session_id'); Candidate = @('session_id') },
                [pscustomobject]@{ Projection = @('transfer_id'); Candidate = @('transfer_id') },
                [pscustomobject]@{ Projection = @('direction'); Candidate = @('direction') },
                [pscustomobject]@{ Projection = @('route'); Candidate = @('route') },
                [pscustomobject]@{ Projection = @('protocol_version'); Candidate = @('protocol_version') },
                [pscustomobject]@{ Projection = @('live_route_epoch'); Candidate = @('live_route_epoch') },
                [pscustomobject]@{ Projection = @('runtime_generation'); Candidate = @('runtime_generation') },
                [pscustomobject]@{ Projection = @('terminal_generation'); Candidate = @('terminal_generation') },
                [pscustomobject]@{ Projection = @('leg_generation'); Candidate = @('leg_generation') },
                [pscustomobject]@{ Projection = @('transport_epoch'); Candidate = @('transport_epoch') },
                [pscustomobject]@{ Projection = @('bridge_recovery_generation'); Candidate = @('bridge_recovery_generation') },
                [pscustomobject]@{ Projection = @('bridge_decision_generation'); Candidate = @('bridge_decision_generation') },
                [pscustomobject]@{ Projection = @('route_publication_generation'); Candidate = @('route_publication_generation') },
                [pscustomobject]@{ Projection = @('route_commit_generation'); Candidate = @('route_commit_generation') },
                [pscustomobject]@{ Projection = @('target_transport'); Candidate = @('target_transport') },
                [pscustomobject]@{ Projection = @('projected_repair_request_key', 'source_repair_request_key', 'repair_request_key'); Candidate = @('repair_request_key') },
                [pscustomobject]@{ Projection = @('frontier_chunk_index'); Candidate = @('frontier_chunk_index') })) {
            $left = Get-RegularV4PressureField -Event $Projection -Names $fieldAliases.Projection
            $right = Get-RegularV4PressureField -Event $Candidate -Names $fieldAliases.Candidate
            if ([string]::IsNullOrWhiteSpace($left) -or
                [string]::IsNullOrWhiteSpace($right) -or
                -not [string]::Equals($left, $right, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        $projectionGeneration = Get-RegularV4PressureField -Event $Projection -Names @('decision_generation', 'repair_generation')
        $candidateGeneration = Get-RegularV4PressureField -Event $Candidate -Names @('decision_generation', 'repair_generation')
        return -not [string]::IsNullOrWhiteSpace($projectionGeneration) -and
            $projectionGeneration -eq $candidateGeneration
    }

    function Test-RegularV4PressureInstallAccepted {
        param(
            [Parameter(Mandatory = $true)]$Projection,
            [Parameter(Mandatory = $true)]$Decision,
            [Parameter(Mandatory = $true)][string]$PredecessorAuthorityId
        )
        $status = (Get-RegularV4PressureField -Event $Decision -Names @('install_status', 'decision_status', 'status')).ToLowerInvariant()
        $projectionAuthority = Get-RegularV4PressureField -Event $Projection -Names @('authority_id')
        $decisionAuthority = Get-RegularV4PressureField -Event $Decision -Names @('authority_id')
        $receiptAuthority = Get-RegularV4PressureField -Event $Decision -Names @('receipt_authority_id')
        $decisionPredecessor = Get-RegularV4PressureField -Event $Decision -Names @('predecessor_authority_id')
        $retainedPredecessor = Get-RegularV4PressureField -Event $Decision -Names @('retained_predecessor_authority_id')
        $currentSuccessor = Get-RegularV4PressureField -Event $Decision -Names @('current_successor_authority_id')
        if ($status -notin @('installed', 'idempotent') -or
            [string]::IsNullOrWhiteSpace($projectionAuthority) -or
            $projectionAuthority -ne $decisionAuthority -or
            [string]::IsNullOrWhiteSpace($decisionPredecessor) -or
            $decisionPredecessor -ne $PredecessorAuthorityId -or
            (-not [string]::IsNullOrWhiteSpace($retainedPredecessor) -and $retainedPredecessor -ne $PredecessorAuthorityId) -or
            (-not [string]::IsNullOrWhiteSpace($receiptAuthority) -and $receiptAuthority -ne $projectionAuthority) -or
            (-not [string]::IsNullOrWhiteSpace($currentSuccessor) -and $currentSuccessor -ne $projectionAuthority)) {
            return $false
        }
        return Test-RegularV4PressureScopeMatch -Projection $Projection -Candidate $Decision
    }

    function Test-RegularV4PressureOptionalIdentityMatch {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Names,
            [Parameter(Mandatory = $true)][string]$Expected
        )
        $actual = Get-RegularV4PressureField -Event $Event -Names $Names
        return [string]::IsNullOrWhiteSpace($actual) -or $actual -eq $Expected
    }

    function Test-RegularV4PressureSharedScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Projection,
            [Parameter(Mandatory = $true)]$Candidate
        )
        foreach ($names in @(
                @('session_id'), @('transfer_id'), @('direction'), @('route'), @('protocol_version'),
                @('live_route_epoch'), @('runtime_generation'), @('terminal_generation'), @('leg_generation'),
                @('transport_epoch'), @('bridge_recovery_generation'), @('route_publication_generation'),
                @('route_commit_generation'), @('target_transport'))) {
            $left = Get-RegularV4PressureField -Event $Projection -Names $names
            $right = Get-RegularV4PressureField -Event $Candidate -Names $names
            if ([string]::IsNullOrWhiteSpace($left) -or
                [string]::IsNullOrWhiteSpace($right) -or
                -not [string]::Equals($left, $right, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctRecords = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($rejection in $rejectedSettlements) {
        $outcome = (Get-RegularV4PressureField -Event $rejection -Names @('outcome', 'settlement_outcome')).ToLowerInvariant()
        if ($outcome -notin @('missing_dispatch', 'missingdispatch', 'settled_stalled', 'settledstalled')) {
            continue
        }
        $reason = Get-RegularV4PressureField -Event $rejection -Names @('mismatch_kind', 'rejection_reason', 'decision_reason', 'reason')
        $legacyPressureMissing =
            (Get-FileTransferEventField -Event $rejection -Name 'pressure_pending_repair_count' -Default '-1') -eq '0' -and
            (Get-FileTransferEventField -Event $rejection -Name 'cleared_pressure' -Default '-1') -eq '0'
        if ($reason -ne 'regular_v4_frontier_repair_pressure_missing' -and -not $legacyPressureMissing) {
            continue
        }

        $rejectionAuthorityId = Get-RegularV4PressureField -Event $rejection -Names @('authority_id')
        $rejectionPredecessorAuthorityId = Get-RegularV4PressureField -Event $rejection -Names @('predecessor_authority_id', 'retained_predecessor_authority_id')
        $successorSettlements = @($contractSettlements | Where-Object {
            [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
            (Get-RegularV4PressureField -Event $_ -Names @('repair_request_key')) -eq
                (Get-RegularV4PressureField -Event $rejection -Names @('repair_request_key')) -and
            (Get-RegularV4PressureField -Event $_ -Names @('settlement_outcome', 'outcome')).Replace('_', '').ToLowerInvariant() -eq
                $outcome.Replace('_', '') -and
            ([string]::IsNullOrWhiteSpace($rejectionAuthorityId) -or
                (Get-RegularV4PressureField -Event $_ -Names @('authority_id')) -eq $rejectionAuthorityId)
        } | Sort-Object Sequence, LineNumber -Descending)

        $chain = $null
        foreach ($candidateSuccessorSettlement in $successorSettlements) {
            $candidateSuccessorAuthorityId = Get-RegularV4PressureField -Event $candidateSuccessorSettlement -Names @('authority_id')
            if ([string]::IsNullOrWhiteSpace($candidateSuccessorAuthorityId) -or
                (Get-FileTransferEventField -Event $candidateSuccessorSettlement -Name 'dispatch_observed' -Default '0') -eq '1') {
                continue
            }
            $candidateProjections = @($projectionEvents | Where-Object {
                [int64]$_.Sequence -lt [int64]$candidateSuccessorSettlement.Sequence -and
                (Get-RegularV4PressureField -Event $_ -Names @('authority_id')) -eq $candidateSuccessorAuthorityId -and
                (Test-RegularV4PressureScopeMatch -Projection $_ -Candidate $rejection)
            } | Sort-Object Sequence, LineNumber -Descending)
            foreach ($candidateProjection in $candidateProjections) {
                $candidatePredecessorAuthorityId = Get-RegularV4PressureField -Event $candidateProjection -Names @('predecessor_authority_id', 'retained_predecessor_authority_id')
                if ([string]::IsNullOrWhiteSpace($candidatePredecessorAuthorityId) -or
                    (-not [string]::IsNullOrWhiteSpace($rejectionPredecessorAuthorityId) -and
                        $rejectionPredecessorAuthorityId -ne $candidatePredecessorAuthorityId)) {
                    continue
                }
                $candidatePredecessorSettlements = @($contractSettlements | Where-Object {
                    [int64]$_.Sequence -gt [int64]$candidateProjection.Sequence -and
                    [int64]$_.Sequence -lt [int64]$candidateSuccessorSettlement.Sequence -and
                    (Get-RegularV4PressureField -Event $_ -Names @('settlement_outcome', 'outcome')).ToLowerInvariant() -eq 'superseded' -and
                    (Get-RegularV4PressureField -Event $_ -Names @('authority_id')) -eq $candidatePredecessorAuthorityId -and
                    (Get-RegularV4PressureField -Event $_ -Names @('successor_authority_id')) -eq $candidateSuccessorAuthorityId
                } | Sort-Object Sequence, LineNumber -Descending)
                if ($candidatePredecessorSettlements.Count -eq 0) {
                    continue
                }
                $candidatePredecessorSettlement = $candidatePredecessorSettlements[0]
                $candidatePredecessorAccepted = @($acceptedSettlements | Where-Object {
                    [int64]$_.Sequence -gt [int64]$candidatePredecessorSettlement.Sequence -and
                    [int64]$_.Sequence -lt [int64]$candidateSuccessorSettlement.Sequence -and
                    (Get-RegularV4PressureField -Event $_ -Names @('outcome', 'settlement_outcome')).ToLowerInvariant() -eq 'superseded' -and
                    (Get-RegularV4PressureField -Event $_ -Names @('repair_request_key')) -eq
                        (Get-RegularV4PressureField -Event $candidatePredecessorSettlement -Names @('repair_request_key')) -and
                    (Test-RegularV4PressureOptionalIdentityMatch -Event $_ -Names @('authority_id') -Expected $candidatePredecessorAuthorityId) -and
                    (Test-RegularV4PressureOptionalIdentityMatch -Event $_ -Names @('successor_authority_id', 'current_successor_authority_id') -Expected $candidateSuccessorAuthorityId) -and
                    (Test-RegularV4PressureSharedScopeMatch -Projection $candidateProjection -Candidate $_)
                } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                if ($candidatePredecessorAccepted.Count -eq 0) {
                    continue
                }
                $chain = [pscustomobject]@{
                    SuccessorSettlement = $candidateSuccessorSettlement
                    SuccessorAuthorityId = $candidateSuccessorAuthorityId
                    Projection = $candidateProjection
                    PredecessorSettlement = $candidatePredecessorSettlement
                    PredecessorAuthorityId = $candidatePredecessorAuthorityId
                }
                break
            }
            if ($null -ne $chain) {
                break
            }
        }
        if ($null -eq $chain) {
            continue
        }

        $successorSettlement = $chain.SuccessorSettlement
        $successorAuthorityId = $chain.SuccessorAuthorityId
        $successorProjection = $chain.Projection
        $predecessorSettlement = $chain.PredecessorSettlement
        $predecessorAuthorityId = $chain.PredecessorAuthorityId
        $installAccepted = @($installDecisionEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$successorProjection.Sequence -and
            [int64]$_.Sequence -lt [int64]$predecessorSettlement.Sequence -and
            (Test-RegularV4PressureInstallAccepted -Projection $successorProjection -Decision $_ -PredecessorAuthorityId $predecessorAuthorityId)
        })
        $successorAcceptedBeforeRejection = @($acceptedSettlements | Where-Object {
            [int64]$_.Sequence -gt [int64]$successorSettlement.Sequence -and
            [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
            (Get-RegularV4PressureField -Event $_ -Names @('repair_request_key')) -eq
                (Get-RegularV4PressureField -Event $successorSettlement -Names @('repair_request_key')) -and
            (Get-RegularV4PressureField -Event $_ -Names @('outcome', 'settlement_outcome')).Replace('_', '').ToLowerInvariant() -eq
                $outcome.Replace('_', '') -and
            (Test-RegularV4PressureOptionalIdentityMatch -Event $_ -Names @('authority_id') -Expected $successorAuthorityId) -and
            (Test-RegularV4PressureScopeMatch -Projection $successorProjection -Candidate $_)
        })
        $successorDispatchedBeforeRejection = @($dispatchEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$successorProjection.Sequence -and
            [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
            (Get-RegularV4PressureField -Event $_ -Names @('repair_request_key')) -eq
                (Get-RegularV4PressureField -Event $successorSettlement -Names @('repair_request_key')) -and
            (Test-RegularV4PressureOptionalIdentityMatch -Event $_ -Names @('authority_id') -Expected $successorAuthorityId) -and
            (Test-RegularV4PressureScopeMatch -Projection $successorProjection -Candidate $_)
        })
        if ($installAccepted.Count -gt 0 -and
            ($successorAcceptedBeforeRejection.Count -gt 0 -or $successorDispatchedBeforeRejection.Count -gt 0)) {
            continue
        }

        $rawCandidates.Add($rejection) | Out-Null
        $logicalKey = [string]::Join('|', @(
            (Get-RegularV4PressureField -Event $successorProjection -Names @('session_id')),
            (Get-RegularV4PressureField -Event $successorProjection -Names @('transfer_id')),
            (Get-RegularV4PressureField -Event $successorProjection -Names @('direction')),
            (Get-RegularV4PressureField -Event $successorProjection -Names @('route')),
            (Get-RegularV4PressureField -Event $successorProjection -Names @('protocol_version')),
            (Get-RegularV4PressureField -Event $successorProjection -Names @('live_route_epoch')),
            (Get-RegularV4PressureField -Event $successorProjection -Names @('runtime_generation')),
            (Get-RegularV4PressureField -Event $successorProjection -Names @('terminal_generation')),
            (Get-RegularV4PressureField -Event $successorProjection -Names @('leg_generation')),
            (Get-RegularV4PressureField -Event $successorProjection -Names @('transport_epoch')),
            (Get-RegularV4PressureField -Event $successorProjection -Names @('bridge_recovery_generation')),
            (Get-RegularV4PressureField -Event $successorProjection -Names @('bridge_decision_generation')),
            (Get-RegularV4PressureField -Event $successorProjection -Names @('route_publication_generation')),
            (Get-RegularV4PressureField -Event $successorProjection -Names @('route_commit_generation')),
            $predecessorAuthorityId,
            $successorAuthorityId,
            (Get-RegularV4PressureField -Event $successorProjection -Names @('projected_repair_request_key', 'source_repair_request_key', 'repair_request_key')),
            (Get-RegularV4PressureField -Event $successorProjection -Names @('decision_generation', 'repair_generation'))))
        if (-not $seen.ContainsKey($logicalKey)) {
            $seen[$logicalKey] = $true
            $distinctRecords.Add([pscustomobject]@{
                Event = $rejection
                Projection = $successorProjection
                Recovered = $false
            }) | Out-Null
        }
    }

    [object[]]$recovered = @()
    [object[]]$unresolved = @($distinctRecords.ToArray() | ForEach-Object { $_.Event })

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctRecords.Count
        RecoveredCount = $recovered.Count
        UnresolvedCount = $unresolved.Count
        Verdict = if ($unresolved.Count -gt 0) { 'fail' } elseif ($distinctRecords.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctRecords.ToArray() | ForEach-Object { $_.Event })
        RecoveredCandidateEvents = $recovered
        UnresolvedCandidateEvents = $unresolved
    }
}

function Get-FileTransferRegularV4FrontierRepairInitialPressureInstallProof {
    param(
        [AllowEmptyCollection()][object[]]$Events = @()
    )

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$contractSettlements = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_contract_settled'
    })
    [object[]]$installEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'filetransfer_regular_v4_frontier_repair_initial_pressure_install_staged',
            'filetransfer_regular_v4_frontier_repair_initial_pressure_install_decided')
    })
    [object[]]$successorInstallEvents = @($orderedEvents | Where-Object {
        $_.EventName -like 'filetransfer_regular_v4_frontier_repair_successor_pressure_install_*'
    })
    [object[]]$rejections = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_settlement_rejected'
    })

    function Get-InitialPressureField {
        param($Event, [string[]]$Names)
        foreach ($name in $Names) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and $value -notin @('(none)', 'none')) {
                return $value
            }
        }
        return ''
    }

    function Test-InitialPressureIdentityMatch {
        param($Left, $Right)
        foreach ($names in @(
                @('authority_id'), @('repair_request_key'), @('session_id'), @('transfer_id'), @('direction'),
                @('route'), @('protocol_version'), @('live_route_epoch'), @('runtime_generation'),
                @('terminal_generation'), @('leg_generation'), @('transport_epoch'),
                @('bridge_recovery_generation'), @('bridge_decision_generation'),
                @('route_publication_generation'), @('route_commit_generation'),
                @('decision_generation', 'repair_generation'))) {
            $leftValue = Get-InitialPressureField -Event $Left -Names $names
            $rightValue = Get-InitialPressureField -Event $Right -Names $names
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($rejection in $rejections) {
        $outcome = (Get-InitialPressureField -Event $rejection -Names @('outcome', 'settlement_outcome')).Replace('_', '').ToLowerInvariant()
        if ($outcome -notin @('progressobserved', 'missingdispatch', 'settledstalled')) {
            continue
        }
        $reason = Get-InitialPressureField -Event $rejection -Names @('mismatch_kind', 'rejection_reason', 'decision_reason', 'reason')
        $legacyPressureMissing =
            (Get-FileTransferEventField -Event $rejection -Name 'pressure_pending_repair_count' -Default '-1') -eq '0' -and
            (Get-FileTransferEventField -Event $rejection -Name 'cleared_pressure' -Default '-1') -eq '0'
        if ($reason -ne 'regular_v4_frontier_repair_pressure_missing' -and -not $legacyPressureMissing) {
            continue
        }

        $authorityId = Get-InitialPressureField -Event $rejection -Names @('authority_id')
        $repairKey = Get-InitialPressureField -Event $rejection -Names @('repair_request_key')
        if ([string]::IsNullOrWhiteSpace($authorityId) -or [string]::IsNullOrWhiteSpace($repairKey)) {
            continue
        }
        $hasSuccessorLineage = @($successorInstallEvents | Where-Object {
            (Get-InitialPressureField -Event $_ -Names @('authority_id')) -eq $authorityId
        }).Count -gt 0
        if ($hasSuccessorLineage) {
            continue
        }

        $settlement = @($contractSettlements | Where-Object {
            [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
            (Get-InitialPressureField -Event $_ -Names @('authority_id')) -eq $authorityId -and
            (Get-InitialPressureField -Event $_ -Names @('repair_request_key')) -eq $repairKey -and
            (Get-InitialPressureField -Event $_ -Names @('settlement_outcome', 'outcome')).Replace('_', '').ToLowerInvariant() -eq $outcome
        } | Sort-Object Sequence, LineNumber -Descending | Select-Object -First 1)
        if ($settlement.Count -eq 0) {
            continue
        }

        $acceptedInstall = @($installEvents | Where-Object {
            [int64]$_.Sequence -lt [int64]$settlement[0].Sequence -and
            $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_initial_pressure_install_decided' -and
            (Get-InitialPressureField -Event $_ -Names @('install_status', 'status')).ToLowerInvariant() -in @('installed', 'idempotent') -and
            (Test-InitialPressureIdentityMatch -Left $_ -Right $rejection)
        }).Count -gt 0
        if ($acceptedInstall) {
            continue
        }

        $rawCandidates.Add($rejection) | Out-Null
        $logicalKey = [string]::Join('|', @(
            (Get-InitialPressureField -Event $rejection -Names @('session_id')),
            (Get-InitialPressureField -Event $rejection -Names @('transfer_id')),
            (Get-InitialPressureField -Event $rejection -Names @('direction')),
            (Get-InitialPressureField -Event $rejection -Names @('route')),
            (Get-InitialPressureField -Event $rejection -Names @('protocol_version')),
            (Get-InitialPressureField -Event $rejection -Names @('live_route_epoch')),
            (Get-InitialPressureField -Event $rejection -Names @('runtime_generation')),
            (Get-InitialPressureField -Event $rejection -Names @('terminal_generation')),
            (Get-InitialPressureField -Event $rejection -Names @('leg_generation')),
            (Get-InitialPressureField -Event $rejection -Names @('transport_epoch')),
            (Get-InitialPressureField -Event $rejection -Names @('bridge_recovery_generation')),
            (Get-InitialPressureField -Event $rejection -Names @('bridge_decision_generation')),
            $authorityId,
            $repairKey))
        if (-not $seen.ContainsKey($logicalKey)) {
            $seen[$logicalKey] = $true
            $distinctCandidates.Add($rejection) | Out-Null
        }
    }

    [object[]]$unresolved = @($distinctCandidates.ToArray())
    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = 0
        UnresolvedCount = $unresolved.Count
        Verdict = if ($unresolved.Count -gt 0) { 'fail' } elseif ($rawCandidates.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @()
        UnresolvedCandidateEvents = $unresolved
    }
}

function Test-FileTransferRuntimeUnlockRetryDispatchTupleMatch {
    param(
        [Parameter(Mandatory = $true)]$Left,
        [Parameter(Mandatory = $true)]$Right
    )

    $leftSchema = Get-FileTransferAuthoritySchema -Line ([string]$Left.RawLine)
    $rightSchema = Get-FileTransferAuthoritySchema -Line ([string]$Right.RawLine)
    if ($leftSchema -ge 2 -or $rightSchema -ge 2) {
        if ($leftSchema -lt 2 -or $rightSchema -lt 2) {
            return $false
        }

        return Test-FileTransferAuthorityFieldsEqual `
            -LeftLine ([string]$Left.RawLine) `
            -RightLine ([string]$Right.RawLine) `
            -Fields @(
                'authority_id',
                'predecessor_authority_id',
                'session_id',
                'transfer_id',
                'direction',
                'route',
                'protocol_version',
                'live_route_epoch',
                'runtime_generation',
                'terminal_generation',
                'leg_generation',
                'transport_epoch',
                'bridge_recovery_generation',
                'bridge_decision_generation',
                'route_publication_generation',
                'route_commit_generation',
                'contract_generation',
                'retired_generation',
                'dispatch_attempt_generation',
                'missing_dispatch_successor_generation',
                'retry_reason',
                'recovery_reason',
                'release_kind',
                'release_authority_id',
                'release_generation',
                'release_outcome',
                'target_route',
                'target_protocol_version',
                'target_transport')
    }

    $leftSession = Get-FileTransferEventField -Event $Left -Name 'session_id' -Default ''
    $rightSession = Get-FileTransferEventField -Event $Right -Name 'session_id' -Default ''
    if ([string]::IsNullOrWhiteSpace($leftSession) -or
        [string]::IsNullOrWhiteSpace($rightSession) -or
        $leftSession -ne $rightSession) {
        return $false
    }

    $leftTransfer = Get-FileTransferEventField -Event $Left -Name 'transfer_id' -Default ''
    $rightTransfer = Get-FileTransferEventField -Event $Right -Name 'transfer_id' -Default ''
    if (-not [string]::IsNullOrWhiteSpace($leftTransfer) -and
        $leftTransfer -ne '(none)' -and
        -not [string]::IsNullOrWhiteSpace($rightTransfer) -and
        $rightTransfer -ne '(none)' -and
        $leftTransfer -ne $rightTransfer) {
        return $false
    }

    $leftContract = Get-FileTransferEventField -Event $Left -Name 'contract_generation' -Default ''
    $rightContract = Get-FileTransferEventField -Event $Right -Name 'contract_generation' -Default ''
    if (-not [string]::IsNullOrWhiteSpace($leftContract) -and
        -not [string]::IsNullOrWhiteSpace($rightContract) -and
        $leftContract -ne $rightContract) {
        return $false
    }

    return $true
}

function Get-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleFields {
    return [string[]]@(
        'authority_schema', 'authority_id', 'authority_generation', 'predecessor_authority_id',
        'session_id', 'transfer_id', 'direction', 'route', 'route_kind', 'protocol_version',
        'live_route_epoch', 'runtime_generation', 'terminal_generation', 'leg_generation',
        'transport_epoch', 'bridge_recovery_generation', 'bridge_decision_generation',
        'route_publication_generation', 'route_commit_generation', 'contract_generation',
        'retired_generation', 'dispatch_attempt_generation', 'missing_dispatch_successor_generation',
        'missing_dispatch_successor_limit', 'retry_reason', 'recovery_reason', 'release_kind',
        'release_authority_id', 'release_generation', 'release_outcome', 'target_route',
        'target_route_kind', 'target_protocol_version', 'target_transport',
        'runtime_owner_session_id', 'runtime_owner_transfer_id', 'runtime_owner_direction',
        'runtime_owner_route', 'runtime_owner_route_kind', 'runtime_owner_protocol_version',
        'runtime_owner_live_route_epoch', 'runtime_owner_runtime_generation',
        'runtime_owner_terminal_generation', 'runtime_owner_family', 'runtime_owner_created_reason',
        'source_publication_session_id', 'source_publication_transfer_id',
        'source_publication_direction', 'source_publication_route', 'source_publication_route_kind',
        'source_publication_protocol_version', 'source_publication_live_route_epoch',
        'source_publication_runtime_generation', 'source_publication_terminal_generation',
        'source_publication_leg_generation', 'source_publication_route_commit_generation',
        'source_publication_target_route', 'source_publication_target_route_kind',
        'source_publication_target_protocol_version', 'source_publication_target_transport',
        'source_publication_generation', 'source_publication_action_kind', 'source_publication_reason',
        'source_publication_runtime_owner_session_id',
        'source_publication_runtime_owner_transfer_id',
        'source_publication_runtime_owner_direction', 'source_publication_runtime_owner_route',
        'source_publication_runtime_owner_route_kind',
        'source_publication_runtime_owner_protocol_version',
        'source_publication_runtime_owner_live_route_epoch',
        'source_publication_runtime_owner_runtime_generation',
        'source_publication_runtime_owner_terminal_generation',
        'source_publication_runtime_owner_family',
        'source_publication_runtime_owner_created_reason'
    )
}

function Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch {
    param(
        [Parameter(Mandatory = $true)]$Left,
        [Parameter(Mandatory = $true)]$Right
    )

    foreach ($field in @(Get-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleFields)) {
        $leftValue = Get-FileTransferEventField -Event $Left -Name $field -Default ''
        $rightValue = Get-FileTransferEventField -Event $Right -Name $field -Default ''
        if ([string]::IsNullOrWhiteSpace($leftValue) -or
            [string]::IsNullOrWhiteSpace($rightValue) -or
            -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::Ordinal)) {
            return $false
        }
    }

    return $true
}

function Get-FileTransferRuntimeUnlockRetryDispatchInstallProof {
    param([object[]]$Events)

    [string[]]$authorityTupleFields = @(
        Get-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleFields
    )
    [string[]]$requestTupleFields = @(
        'request_regular_v4_liveness_generation',
        'request_bridge_decision_generation',
        'request_active_predecessor_supersession'
    )

    $allEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    $stageEvents = @($allEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_decision_staged' -and
        (Get-FileTransferEventField -Event $_ -Name 'stage_status' -Default 'Staged') -in @('Staged', 'Idempotent')
    })
    $receiptEvents = @($allEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_install_receipt_issued'
    })
    $committedEvents = @($allEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_install_committed' -and
        (Get-FileTransferEventField -Event $_ -Name 'install_status' -Default 'Installed') -in @('Installed', 'Idempotent')
    })
    $rejectedEvents = @($allEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_install_rejected'
    })
    $grantEvents = @($allEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_authority_granted'
    })
    $phase2Events = @($stageEvents + $receiptEvents + $committedEvents + $rejectedEvents)
    [object[]]$phase2DeclaredGrantEvents = @($grantEvents | Where-Object {
        [int64]$installGeneration = 0
        $installGenerationText = Get-FileTransferEventField `
            -Event $_ `
            -Name 'install_generation' `
            -Default ''
        [int64]::TryParse($installGenerationText, [ref]$installGeneration) -and
            $installGeneration -gt 0
    })
    $phase2ProtocolObserved = $phase2Events.Count -gt 0 -or
        $phase2DeclaredGrantEvents.Count -gt 0

    function Get-InstallIdentityKey {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [switch]$IgnoreInstallGeneration
        )

        $parts = @($authorityTupleFields | ForEach-Object {
            Get-FileTransferEventField -Event $Event -Name $_ -Default '(missing)'
        })
        if ($Event.EventName -in @(
                'runtime_unlock_retry_dispatch_decision_staged',
                'runtime_unlock_retry_dispatch_install_receipt_issued',
                'runtime_unlock_retry_dispatch_install_committed',
                'runtime_unlock_retry_dispatch_install_rejected',
                'runtime_unlock_retry_dispatch_authority_granted')) {
            $parts += @($requestTupleFields | ForEach-Object {
                Get-FileTransferEventField -Event $Event -Name $_ -Default '(missing)'
            })
        }
        if (-not $IgnoreInstallGeneration) {
            $parts += Get-FileTransferEventField -Event $Event -Name 'install_generation' -Default '(missing)'
        }
        if ($Event.EventName -eq 'runtime_unlock_retry_dispatch_install_rejected') {
            $parts += Get-FileTransferEventField -Event $Event -Name 'install_status' -Default '(missing)'
            $parts += Get-FileTransferEventField -Event $Event -Name 'stage_cleared' -Default '(missing)'
            $parts += Get-FileTransferEventField -Event $Event -Name 'stage_disposition' -Default '(missing)'
        }
        return $parts -join '|'
    }

    function Get-DistinctInstallEvents {
        param(
            [object[]]$Candidates,
            [switch]$IgnoreInstallGeneration
        )

        $seen = @{}
        $result = New-Object System.Collections.Generic.List[object]
        foreach ($candidate in @($Candidates | Sort-Object Sequence, LineNumber)) {
            $key = Get-InstallIdentityKey -Event $candidate -IgnoreInstallGeneration:$IgnoreInstallGeneration
            if ($seen.ContainsKey($key)) {
                continue
            }
            $seen[$key] = $true
            $result.Add($candidate) | Out-Null
        }
        return @($result.ToArray())
    }

    function Test-InstallPrimaryIdentityMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        foreach ($field in @('session_id', 'transfer_id', 'direction', 'authority_id')) {
            $leftValue = Get-FileTransferEventField -Event $Left -Name $field -Default ''
            $rightValue = Get-FileTransferEventField -Event $Right -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        return $true
    }

    function Test-InstallEventBefore {
        param(
            [Parameter(Mandatory = $true)]$Earlier,
            [Parameter(Mandatory = $true)]$Later
        )

        $earlierSequence = [int64]$Earlier.Sequence
        $laterSequence = [int64]$Later.Sequence
        if ($earlierSequence -lt $laterSequence) {
            return $true
        }
        if ($earlierSequence -gt $laterSequence) {
            return $false
        }

        return [int64]$Earlier.LineNumber -lt [int64]$Later.LineNumber
    }

    function Test-InstallScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right,
            [switch]$RequireInstallGeneration,
            [switch]$RequireRequestTuple
        )

        foreach ($field in $authorityTupleFields) {
            $leftValue = Get-FileTransferEventField -Event $Left -Name $field -Default ''
            $rightValue = Get-FileTransferEventField -Event $Right -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        if ($RequireRequestTuple) {
            foreach ($field in $requestTupleFields) {
                $leftValue = Get-FileTransferEventField -Event $Left -Name $field -Default ''
                $rightValue = Get-FileTransferEventField -Event $Right -Name $field -Default ''
                if ([string]::IsNullOrWhiteSpace($leftValue) -or
                    [string]::IsNullOrWhiteSpace($rightValue) -or
                    -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::Ordinal)) {
                    return $false
                }
            }
        }

        if ($RequireInstallGeneration) {
            $leftGeneration = Get-FileTransferEventField -Event $Left -Name 'install_generation' -Default ''
            $rightGeneration = Get-FileTransferEventField -Event $Right -Name 'install_generation' -Default ''
            if ([string]::IsNullOrWhiteSpace($leftGeneration) -or
                [string]::IsNullOrWhiteSpace($rightGeneration) -or
                $leftGeneration -ne $rightGeneration) {
                return $false
            }
        }

        return $true
    }

    function Test-InstallGenerationPositive {
        param([Parameter(Mandatory = $true)]$Event)

        [int64]$generation = 0
        $generationText = Get-FileTransferEventField `
            -Event $Event `
            -Name 'install_generation' `
            -Default ''
        return [int64]::TryParse($generationText, [ref]$generation) -and
            $generation -gt 0
    }

    function Get-InstallGrantBoundaryKey {
        param([Parameter(Mandatory = $true)]$Event)

        return (@(
                'session_id',
                'transfer_id',
                'direction',
                'authority_id',
                'install_generation') | ForEach-Object {
                Get-FileTransferEventField -Event $Event -Name $_ -Default '(missing)'
            }) -join '|'
    }

    function Test-InstallGrantBoundaryMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        return (Get-InstallGrantBoundaryKey -Event $Left) -eq
            (Get-InstallGrantBoundaryKey -Event $Right)
    }

    function Get-InstallGrantEvidenceFailureReason {
        param([Parameter(Mandatory = $true)]$Grant)

        foreach ($field in $requestTupleFields) {
            $value = Get-FileTransferEventField -Event $Grant -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($value) -or $value -in @('(none)', 'none')) {
                return "retry_dispatch_grant_${field}_missing"
            }
        }

        [object[]]$referenceEvents = @(
            @($distinctCommitted + $distinctReceipts + $distinctStages) | Where-Object {
                (Test-InstallGrantBoundaryMatch -Left $Grant -Right $_) -and
                (Test-InstallEventBefore -Earlier $_ -Later $Grant)
            } | Sort-Object Sequence, LineNumber -Descending
        )
        if ($referenceEvents.Count -eq 0) {
            return 'retry_dispatch_grant_install_chain_missing'
        }

        $reference = $referenceEvents[0]
        foreach ($field in $requestTupleFields) {
            $grantValue = Get-FileTransferEventField -Event $Grant -Name $field -Default ''
            $referenceValue = Get-FileTransferEventField -Event $reference -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($referenceValue) -or
                -not [string]::Equals($grantValue, $referenceValue, [System.StringComparison]::Ordinal)) {
                return "retry_dispatch_grant_${field}_mismatch"
            }
        }

        foreach ($field in $authorityTupleFields) {
            $grantValue = Get-FileTransferEventField -Event $Grant -Name $field -Default ''
            $referenceValue = Get-FileTransferEventField -Event $reference -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($grantValue) -or
                [string]::IsNullOrWhiteSpace($referenceValue) -or
                -not [string]::Equals($grantValue, $referenceValue, [System.StringComparison]::Ordinal)) {
                return 'retry_dispatch_grant_authority_tuple_mismatch'
            }
        }

        return 'retry_dispatch_grant_install_chain_incomplete'
    }

    function New-InstallGrantEvidenceCandidateEvent {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string]$Reason
        )

        $fields = @{}
        if ($null -ne $Event.Fields) {
            foreach ($key in @($Event.Fields.Keys)) {
                $fields[$key] = $Event.Fields[$key]
            }
        }
        $fields['decision_reason'] = $Reason

        return [pscustomobject]@{
            EventName = [string]$Event.EventName
            Sequence = [int64]$Event.Sequence
            LineNumber = [int]$Event.LineNumber
            FilePath = [string]$Event.FilePath
            FileName = [string]$Event.FileName
            Message = [string]$Event.Message
            RawLine = [string]$Event.RawLine
            TransferId = [string]$Event.TransferId
            Fields = $fields
        }
    }

    function Test-InstallRejectionDisposition {
        param(
            [Parameter(Mandatory = $true)]$Rejection,
            [switch]$RequireStageCleared
        )

        if ($Rejection.EventName -ne 'runtime_unlock_retry_dispatch_install_rejected' -or
            (Get-FileTransferEventField -Event $Rejection -Name 'install_status' -Default '') -ne 'Rejected') {
            return $false
        }

        if (-not $RequireStageCleared) {
            return $true
        }

        if ((Get-FileTransferEventField -Event $Rejection -Name 'stage_cleared' -Default '0') -ne '1') {
            return $false
        }

        $disposition = Get-FileTransferEventField `
            -Event $Rejection `
            -Name 'stage_disposition' `
            -Default ''
        return -not [string]::IsNullOrWhiteSpace($disposition) -and
            $disposition -notin @('(none)', 'none', 'unknown')
    }

    function Test-InstallStageClearedByDirectRejection {
        param(
            [Parameter(Mandatory = $true)]$Stage,
            [Parameter(Mandatory = $true)]$Rejection
        )

        [int64]$rejectionGeneration = -1
        $rejectionGenerationText = Get-FileTransferEventField `
            -Event $Rejection `
            -Name 'install_generation' `
            -Default ''
        return (Test-InstallRejectionDisposition -Rejection $Rejection -RequireStageCleared) -and
            [int64]::TryParse($rejectionGenerationText, [ref]$rejectionGeneration) -and
            $rejectionGeneration -eq 0 -and
            (Test-InstallScopeMatch -Left $Stage -Right $Rejection -RequireRequestTuple)
    }

    function Test-InstallReceiptClearedByExactRejection {
        param(
            [Parameter(Mandatory = $true)]$Receipt,
            [Parameter(Mandatory = $true)]$Rejection
        )

        return (Test-InstallRejectionDisposition -Rejection $Rejection -RequireStageCleared) -and
            (Test-InstallGenerationPositive -Event $Receipt) -and
            (Test-InstallScopeMatch `
                -Left $Receipt `
                -Right $Rejection `
                -RequireInstallGeneration `
                -RequireRequestTuple)
    }

    $distinctStages = @(Get-DistinctInstallEvents -Candidates $stageEvents -IgnoreInstallGeneration)
    $distinctReceipts = @(Get-DistinctInstallEvents -Candidates $receiptEvents)
    $distinctCommitted = @(Get-DistinctInstallEvents -Candidates $committedEvents)
    $distinctRejected = @(Get-DistinctInstallEvents -Candidates $rejectedEvents)
    $distinctGrants = @(Get-DistinctInstallEvents -Candidates $grantEvents)
    $effectiveGrants = New-Object System.Collections.Generic.List[object]
    $uncommittedGrants = New-Object System.Collections.Generic.List[object]

    foreach ($grant in $distinctGrants) {
        $phase2ForGrant = @($phase2Events | Where-Object {
            Test-InstallPrimaryIdentityMatch -Left $grant -Right $_
        })
        if ($phase2ForGrant.Count -eq 0) {
            [int64]$grantInstallGeneration = 0
            $grantInstallGenerationText = Get-FileTransferEventField `
                -Event $grant `
                -Name 'install_generation' `
                -Default ''
            if ([int64]::TryParse($grantInstallGenerationText, [ref]$grantInstallGeneration) -and
                $grantInstallGeneration -gt 0) {
                # A positive install generation declares the Phase-2 protocol.
                # Missing stage/receipt/commit evidence must fail closed rather
                # than being accepted through the legacy artifact path.
                $uncommittedGrants.Add($grant) | Out-Null
            }
            elseif (-not $phase2ProtocolObserved) {
                # Legacy artifacts predate the two-phase protocol. Once any
                # Phase-2 evidence exists in an artifact, a grant without its
                # install generation cannot borrow the legacy path.
                $effectiveGrants.Add($grant) | Out-Null
            }
            else {
                $uncommittedGrants.Add($grant) | Out-Null
            }
            continue
        }

        [object[]]$commit = @($distinctCommitted | Where-Object {
            (Test-InstallEventBefore -Earlier $_ -Later $grant) -and
            (Test-InstallScopeMatch `
                -Left $grant `
                -Right $_ `
                -RequireInstallGeneration `
                -RequireRequestTuple)
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        [object[]]$receipt = @()
        if ($commit.Count -gt 0) {
            $receipt = @($distinctReceipts | Where-Object {
                (Test-InstallEventBefore -Earlier $_ -Later $commit[0]) -and
                (Test-InstallScopeMatch `
                    -Left $commit[0] `
                    -Right $_ `
                    -RequireInstallGeneration `
                    -RequireRequestTuple)
            } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        }
        [object[]]$stage = @()
        if ($receipt.Count -gt 0) {
            $stage = @($distinctStages | Where-Object {
                (Test-InstallEventBefore -Earlier $_ -Later $receipt[0]) -and
                (Test-InstallScopeMatch -Left $grant -Right $_ -RequireRequestTuple) -and
                (Test-InstallScopeMatch -Left $receipt[0] -Right $_ -RequireRequestTuple)
            } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        }
        $chainInvalidated = $false
        if ($commit.Count -gt 0 -and $receipt.Count -gt 0 -and $stage.Count -gt 0) {
            $stageClearedBeforeReceipt = @($distinctRejected | Where-Object {
                (Test-InstallEventBefore -Earlier $stage[0] -Later $_) -and
                (Test-InstallEventBefore -Earlier $_ -Later $receipt[0]) -and
                (Test-InstallStageClearedByDirectRejection `
                    -Stage $stage[0] `
                    -Rejection $_)
            }).Count -gt 0
            $receiptClearedBeforeCommit = @($distinctRejected | Where-Object {
                (Test-InstallEventBefore -Earlier $receipt[0] -Later $_) -and
                (Test-InstallEventBefore -Earlier $_ -Later $commit[0]) -and
                (Test-InstallReceiptClearedByExactRejection `
                    -Receipt $receipt[0] `
                    -Rejection $_)
            }).Count -gt 0
            $receiptRejectedAfterCommit = @($distinctRejected | Where-Object {
                (Test-InstallEventBefore -Earlier $commit[0] -Later $_) -and
                (Test-InstallEventBefore -Earlier $_ -Later $grant) -and
                (Test-InstallRejectionDisposition -Rejection $_) -and
                (Test-InstallScopeMatch `
                    -Left $commit[0] `
                    -Right $_ `
                    -RequireInstallGeneration `
                    -RequireRequestTuple)
            }).Count -gt 0
            $chainInvalidated = $stageClearedBeforeReceipt -or
                $receiptClearedBeforeCommit -or
                $receiptRejectedAfterCommit
        }
        if ($commit.Count -gt 0 -and
            $receipt.Count -gt 0 -and
            $stage.Count -gt 0 -and
            -not $chainInvalidated) {
            $effectiveGrants.Add($grant) | Out-Null
        }
        else {
            $uncommittedGrants.Add($grant) | Out-Null
        }
    }

    $pendingReceipts = @($distinctReceipts | Where-Object {
        $receipt = $_
        $resolvedByCommit = @($distinctCommitted | Where-Object {
            (Test-InstallEventBefore -Earlier $receipt -Later $_) -and
            (Test-InstallScopeMatch `
                -Left $receipt `
                -Right $_ `
                -RequireInstallGeneration `
                -RequireRequestTuple)
        })
        $resolvedByRejection = @($distinctRejected | Where-Object {
            (Test-InstallEventBefore -Earlier $receipt -Later $_) -and
            (Test-InstallReceiptClearedByExactRejection `
                -Receipt $receipt `
                -Rejection $_)
        })
        $resolvedByCommit.Count -eq 0 -and $resolvedByRejection.Count -eq 0
    })
    $pendingStages = @($distinctStages | Where-Object {
        $stage = $_
        $resolvedByReceipt = @($distinctReceipts | Where-Object {
            (Test-InstallEventBefore -Earlier $stage -Later $_) -and
            (Test-InstallGenerationPositive -Event $_) -and
            (Test-InstallScopeMatch -Left $stage -Right $_ -RequireRequestTuple)
        })
        $resolvedByRejection = @($distinctRejected | Where-Object {
            (Test-InstallEventBefore -Earlier $stage -Later $_) -and
            (Test-InstallStageClearedByDirectRejection `
                -Stage $stage `
                -Rejection $_)
        })
        $resolvedByReceipt.Count -eq 0 -and $resolvedByRejection.Count -eq 0
    })

    # A commit is proof only when the exact complete authority tuple first
    # passed through stage and receipt issuance in chronological order.  Do
    # this independently from authority_granted correlation so a commit-only
    # artifact cannot be accepted merely because no grant line survived.
    $orphanCommitted = @($distinctCommitted | Where-Object {
        $commit = $_
        $validChain = $false
        [object[]]$matchingReceipts = @($distinctReceipts | Where-Object {
            (Test-InstallEventBefore -Earlier $_ -Later $commit) -and
            (Test-InstallScopeMatch `
                -Left $commit `
                -Right $_ `
                -RequireInstallGeneration `
                -RequireRequestTuple)
        } | Sort-Object Sequence, LineNumber -Descending)
        foreach ($receipt in $matchingReceipts) {
            [object[]]$matchingStages = @($distinctStages | Where-Object {
                (Test-InstallEventBefore -Earlier $_ -Later $receipt) -and
                (Test-InstallScopeMatch -Left $receipt -Right $_ -RequireRequestTuple)
            } | Sort-Object Sequence, LineNumber -Descending)
            foreach ($stage in $matchingStages) {
                $interveningStageRejection = @($distinctRejected | Where-Object {
                    (Test-InstallEventBefore -Earlier $stage -Later $_) -and
                    (Test-InstallEventBefore -Earlier $_ -Later $receipt) -and
                    (Test-InstallStageClearedByDirectRejection `
                        -Stage $stage `
                        -Rejection $_)
                }).Count -gt 0
                $interveningReceiptRejection = @($distinctRejected | Where-Object {
                    (Test-InstallEventBefore -Earlier $receipt -Later $_) -and
                    (Test-InstallEventBefore -Earlier $_ -Later $commit) -and
                    (Test-InstallReceiptClearedByExactRejection `
                        -Receipt $receipt `
                        -Rejection $_)
                }).Count -gt 0
                if (-not $interveningStageRejection -and
                    -not $interveningReceiptRejection) {
                    $validChain = $true
                    break
                }
            }
            if ($validChain) {
                break
            }
        }
        -not $validChain
    })

    # A Phase-2 authority grant is effective only when its own complete tuple
    # correlates to stage, receipt, and commit.  Keep malformed retained copies
    # as evidence, but group them by the stable install boundary so a later
    # exact duplicate can recover the boundary without inflating grant count.
    $incompleteGrantRawCandidates = New-Object System.Collections.Generic.List[object]
    foreach ($grant in $grantEvents) {
        if (-not (Test-InstallGenerationPositive -Event $grant)) {
            continue
        }

        $exactEffectiveGrant = @($effectiveGrants.ToArray() | Where-Object {
            Test-InstallScopeMatch `
                -Left $grant `
                -Right $_ `
                -RequireInstallGeneration `
                -RequireRequestTuple
        }).Count -gt 0
        if ($exactEffectiveGrant) {
            continue
        }

        $reason = Get-InstallGrantEvidenceFailureReason -Grant $grant
        $incompleteGrantRawCandidates.Add(
            (New-InstallGrantEvidenceCandidateEvent -Event $grant -Reason $reason)) | Out-Null
    }

    $incompleteGrantDistinctCandidates = New-Object System.Collections.Generic.List[object]
    $incompleteGrantRecoveredCandidates = New-Object System.Collections.Generic.List[object]
    $incompleteGrantUnresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $seenIncompleteGrantBoundaries = @{}
    foreach ($candidate in @($incompleteGrantRawCandidates.ToArray() | Sort-Object Sequence, LineNumber)) {
        $boundaryKey = Get-InstallGrantBoundaryKey -Event $candidate
        if ($seenIncompleteGrantBoundaries.ContainsKey($boundaryKey)) {
            continue
        }
        $seenIncompleteGrantBoundaries[$boundaryKey] = $true
        $incompleteGrantDistinctCandidates.Add($candidate) | Out-Null

        $recovered = @($effectiveGrants.ToArray() | Where-Object {
            Test-InstallGrantBoundaryMatch -Left $candidate -Right $_
        }).Count -gt 0
        if ($recovered) {
            $incompleteGrantRecoveredCandidates.Add($candidate) | Out-Null
        }
        else {
            $incompleteGrantUnresolvedCandidates.Add($candidate) | Out-Null
        }
    }

    $grantEvidenceVerdict = if ($phase2DeclaredGrantEvents.Count -eq 0) {
        'none'
    }
    elseif ($incompleteGrantUnresolvedCandidates.Count -gt 0) {
        'fail'
    }
    else {
        'pass'
    }

    [object[]]$otherUncommittedGrantEvents = @($uncommittedGrants.ToArray() | Where-Object {
        -not (Test-InstallGenerationPositive -Event $_)
    })

    $verdict = if ($pendingStages.Count -gt 0 -or
        $pendingReceipts.Count -gt 0 -or
        $orphanCommitted.Count -gt 0 -or
        $otherUncommittedGrantEvents.Count -gt 0 -or
        $incompleteGrantUnresolvedCandidates.Count -gt 0) {
        'incomplete'
    }
    elseif ($phase2Events.Count -eq 0) {
        'none'
    }
    else {
        'pass'
    }

    return [pscustomobject]@{
        DecisionStagedCount = $distinctStages.Count
        ReceiptIssuedCount = $distinctReceipts.Count
        CommittedCount = $distinctCommitted.Count
        RejectedCount = $distinctRejected.Count
        Verdict = $verdict
        ProtocolObserved = $phase2ProtocolObserved
        AuthorityGrantedRawCount = $grantEvents.Count
        EffectiveGrantEvents = @($effectiveGrants.ToArray())
        UncommittedGrantEvents = @($otherUncommittedGrantEvents + $incompleteGrantUnresolvedCandidates.ToArray())
        OrphanCommittedEvents = @($orphanCommitted)
        GrantEvidenceIncompleteRawCount = $incompleteGrantRawCandidates.Count
        GrantEvidenceIncompleteDistinctCount = $incompleteGrantDistinctCandidates.Count
        GrantEvidenceIncompleteRecoveredCount = $incompleteGrantRecoveredCandidates.Count
        GrantEvidenceIncompleteUnresolvedCount = $incompleteGrantUnresolvedCandidates.Count
        GrantEvidenceVerdict = $grantEvidenceVerdict
        GrantEvidenceRawCandidateEvents = @($incompleteGrantRawCandidates.ToArray())
        GrantEvidenceDistinctCandidateEvents = @($incompleteGrantDistinctCandidates.ToArray())
        GrantEvidenceRecoveredCandidateEvents = @($incompleteGrantRecoveredCandidates.ToArray())
        GrantEvidenceUnresolvedCandidateEvents = @($incompleteGrantUnresolvedCandidates.ToArray())
    }
}

function Get-FileTransferRuntimeUnlockRetryDispatchPostGrantHoldCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [AllowEmptyCollection()][object[]]$EffectiveGrantEvents = @()
    )

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$heldEvents = @($orderedEvents | Where-Object {
        $_.EventName -like 'runtime_unlock_retry_dispatch_held_*'
    })
    [object[]]$dispatchObservedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_observed'
    })
    [object[]]$settledEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_contract_settled'
    })
    [object[]]$settlementDecisions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_settlement_decided'
    })

    function Test-PostGrantExactMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        if (-not (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch `
                -Left $Left `
                -Right $Right)) {
            return $false
        }

        $leftInstallGeneration = Get-FileTransferEventField -Event $Left -Name 'install_generation' -Default ''
        $rightInstallGeneration = Get-FileTransferEventField -Event $Right -Name 'install_generation' -Default ''
        [int64]$rightPositiveGeneration = 0
        if ([int64]::TryParse($rightInstallGeneration, [ref]$rightPositiveGeneration) -and
            $rightPositiveGeneration -gt 0) {
            return -not [string]::IsNullOrWhiteSpace($leftInstallGeneration) -and
                [string]::Equals($leftInstallGeneration, $rightInstallGeneration, [System.StringComparison]::Ordinal)
        }

        return $true
    }

    function Get-PostGrantHoldKey {
        param([Parameter(Mandatory = $true)]$Event)

        $parts = @(Get-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleFields | ForEach-Object {
            Get-FileTransferEventField -Event $Event -Name $_ -Default '(missing)'
        })
        $parts += Get-FileTransferEventField -Event $Event -Name 'install_generation' -Default '(legacy)'
        return $parts -join '|'
    }

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctRecords = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($grant in @($EffectiveGrantEvents | Sort-Object Sequence, LineNumber)) {
        if ((Get-FileTransferAuthoritySchema -Line ([string]$grant.RawLine)) -lt 2) {
            continue
        }

        [object[]]$matchingSettlements = @($settledEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$grant.Sequence -and
            (Test-PostGrantExactMatch -Left $grant -Right $_)
        } | Sort-Object Sequence, LineNumber)
        $settlementBoundary = if ($matchingSettlements.Count -gt 0) {
            [int64]$matchingSettlements[0].Sequence
        }
        else {
            [int64]::MaxValue
        }

        foreach ($held in @($heldEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$grant.Sequence -and
            [int64]$_.Sequence -lt $settlementBoundary -and
            (Get-FileTransferAuthoritySchema -Line ([string]$_.RawLine)) -ge 2 -and
            (Test-PostGrantExactMatch -Left $grant -Right $_)
        } | Sort-Object Sequence, LineNumber)) {
            $rawCandidates.Add($held) | Out-Null
            $key = Get-PostGrantHoldKey -Event $grant
            if ($seen.ContainsKey($key)) {
                continue
            }
            $seen[$key] = $true

            $recovered = $false
            if ($held.EventName -eq 'runtime_unlock_retry_dispatch_held_by_active_negotiation') {
                [object[]]$observed = @($dispatchObservedEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$held.Sequence -and
                    (Test-PostGrantExactMatch -Left $grant -Right $_)
                } | Sort-Object Sequence, LineNumber)
                [object[]]$dispatchSettlements = @($matchingSettlements | Where-Object {
                    [int64]$_.Sequence -gt [int64]$held.Sequence -and
                    (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'DispatchObserved' -and
                    (Get-FileTransferEventField -Event $_ -Name 'dispatch_observed' -Default '0') -eq '1'
                } | Sort-Object Sequence, LineNumber)
                if ($observed.Count -gt 0 -and $dispatchSettlements.Count -gt 0) {
                    $settlement = $dispatchSettlements[0]
                    $recovered = @($settlementDecisions | Where-Object {
                        [int64]$_.Sequence -gt [int64]$settlement.Sequence -and
                        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'DispatchObserved' -and
                        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @('Accepted', 'Idempotent') -and
                        (Test-PostGrantExactMatch -Left $grant -Right $_)
                    }).Count -gt 0
                }
            }

            $distinctRecords.Add([pscustomobject]@{
                Event = $held
                Recovered = $recovered
            }) | Out-Null
        }
    }

    [object[]]$distinct = @($distinctRecords.ToArray() | ForEach-Object { $_.Event })
    [object[]]$recovered = @($distinctRecords.ToArray() | Where-Object { $_.Recovered } | ForEach-Object { $_.Event })
    [object[]]$unresolved = @($distinctRecords.ToArray() | Where-Object { -not $_.Recovered } | ForEach-Object { $_.Event })
    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinct.Count
        RecoveredCount = $recovered.Count
        UnresolvedCount = $unresolved.Count
        Verdict = if ($unresolved.Count -gt 0) { 'fail' } elseif ($distinct.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = $distinct
        RecoveredCandidateEvents = $recovered
        UnresolvedCandidateEvents = $unresolved
    }
}

function Get-FileTransferRuntimeUnlockPreCommitProbeStartHandoffCorrelation {
    param([AllowEmptyCollection()][object[]]$Events = @())

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$launchRequests = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_precommit_probe_launch_requested' -and
        (Get-FileTransferEventField -Event $_ -Name 'duplicate' -Default '0') -eq '0' -and
        (Get-FileTransferEventField -Event $_ -Name 'responder_waiting_for_peer_probe' -Default '0') -eq '0'
    })
    [object[]]$timeouts = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_precommit_probe_start_timeout' -and
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default (
            Get-FileTransferEventField -Event $_ -Name 'failure_reason' -Default '')) -eq
            'runtime_unlock_probe_start_timeout'
    })
    [object[]]$startedEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'runtime_unlock_precommit_probe_started',
            'runtime_unlock_precommit_probe_launch_started')
    })
    [object[]]$dispositionEvents = @($orderedEvents | Where-Object {
        ($_.EventName -eq 'filetransfer_runtime_unlock_precommit_probe_launch_handoff_decided' -and
            (Get-FileTransferEventField -Event $_ -Name 'status' -Default (
                Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '')) -in
                @('Accepted', 'Idempotent', 'Held', 'Rejected', 'Invalidated')) -or
        $_.EventName -in @(
            'runtime_unlock_precommit_probe_launch_held_by_coordinator_denial',
            'runtime_unlock_precommit_probe_start_timeout_suppressed_by_coordinator_denial',
            'filetransfer_runtime_unlock_precommit_probe_pending_held',
            'filetransfer_runtime_unlock_precommit_probe_pending_rejected')
    })

    function Get-ProbeField {
        param($Event, [string[]]$Names)
        foreach ($name in $Names) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and $value -notin @('(none)', 'none')) {
                return $value
            }
        }
        return ''
    }

    function Test-ProbeCoreMatch {
        param($Launch, $Candidate)
        foreach ($aliases in @(
                @('session_id'),
                @('transaction_generation'),
                @('offer_generation'))) {
            $left = Get-ProbeField -Event $Launch -Names $aliases
            $right = Get-ProbeField -Event $Candidate -Names $aliases
            if ([string]::IsNullOrWhiteSpace($left) -or
                [string]::IsNullOrWhiteSpace($right) -or
                -not [string]::Equals($left, $right, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        foreach ($aliases in @(
                @('direction'),
                @('transfer_id'),
                @('tuna_path_lease_generation', 'path_lease_generation'),
                @('launch_generation'))) {
            $left = Get-ProbeField -Event $Launch -Names $aliases
            $right = Get-ProbeField -Event $Candidate -Names $aliases
            if (-not [string]::IsNullOrWhiteSpace($right) -and
                ([string]::IsNullOrWhiteSpace($left) -or
                    -not [string]::Equals($left, $right, [System.StringComparison]::OrdinalIgnoreCase))) {
                return $false
            }
        }
        return $true
    }

    function Test-ProbeExactMatch {
        param($Launch, $Candidate)
        if (-not (Test-ProbeCoreMatch -Launch $Launch -Candidate $Candidate)) {
            return $false
        }
        foreach ($aliases in @(
                @('transfer_id'),
                @('tuna_path_lease_generation', 'path_lease_generation'),
                @('launch_generation'))) {
            $left = Get-ProbeField -Event $Launch -Names $aliases
            $right = Get-ProbeField -Event $Candidate -Names $aliases
            if ([string]::IsNullOrWhiteSpace($left) -or
                [string]::IsNullOrWhiteSpace($right) -or
                -not [string]::Equals($left, $right, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Test-ProbeCandidateHasExactTuple {
        param($Event)
        return -not [string]::IsNullOrWhiteSpace((Get-ProbeField -Event $Event -Names @('transfer_id'))) -and
            -not [string]::IsNullOrWhiteSpace((Get-ProbeField -Event $Event -Names @('tuna_path_lease_generation', 'path_lease_generation'))) -and
            -not [string]::IsNullOrWhiteSpace((Get-ProbeField -Event $Event -Names @('launch_generation')))
    }

    function Get-ProbeKey {
        param($Launch)
        return (@(
            (Get-ProbeField -Event $Launch -Names @('session_id')),
            (Get-ProbeField -Event $Launch -Names @('direction')),
            (Get-ProbeField -Event $Launch -Names @('transfer_id')),
            (Get-ProbeField -Event $Launch -Names @('transaction_generation')),
            (Get-ProbeField -Event $Launch -Names @('offer_generation')),
            (Get-ProbeField -Event $Launch -Names @('tuna_path_lease_generation', 'path_lease_generation')),
            (Get-ProbeField -Event $Launch -Names @('launch_generation'))
        )) -join '|'
    }

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctRecords = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    $matchedLaunchSequences = New-Object System.Collections.Generic.HashSet[long]
    foreach ($timeout in $timeouts) {
        [object[]]$possible = @($launchRequests | Where-Object {
            [int64]$_.Sequence -lt [int64]$timeout.Sequence -and
            (Test-ProbeCoreMatch -Launch $_ -Candidate $timeout)
        } | Sort-Object Sequence, LineNumber -Descending)
        if (Test-ProbeCandidateHasExactTuple -Event $timeout) {
            $possible = @($possible | Where-Object {
                Test-ProbeExactMatch -Launch $_ -Candidate $timeout
            })
        }
        else {
            $possible = @($possible | Where-Object {
                -not $matchedLaunchSequences.Contains([int64]$_.Sequence)
            })
            if ($possible.Count -ne 1) {
                continue
            }
        }
        if ($possible.Count -ne 1) {
            continue
        }

        $launch = $possible[0]
        $matchedLaunchSequences.Add([int64]$launch.Sequence) | Out-Null
        $rawCandidates.Add($timeout) | Out-Null
        $key = Get-ProbeKey -Launch $launch
        if ($seen.ContainsKey($key)) {
            continue
        }
        $seen[$key] = $true

        [object[]]$resolutions = @($startedEvents + $dispositionEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$launch.Sequence -and
            [int64]$_.Sequence -lt [int64]$timeout.Sequence -and
            $(if (Test-ProbeCandidateHasExactTuple -Event $_) {
                Test-ProbeExactMatch -Launch $launch -Candidate $_
            }
            else {
                Test-ProbeCoreMatch -Launch $launch -Candidate $_
            })
        })
        $distinctRecords.Add([pscustomobject]@{
            Event = $timeout
            Recovered = $resolutions.Count -gt 0
        }) | Out-Null
    }

    [object[]]$distinct = @($distinctRecords.ToArray() | ForEach-Object { $_.Event })
    [object[]]$recovered = @($distinctRecords.ToArray() | Where-Object { $_.Recovered } | ForEach-Object { $_.Event })
    [object[]]$unresolved = @($distinctRecords.ToArray() | Where-Object { -not $_.Recovered } | ForEach-Object { $_.Event })
    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinct.Count
        RecoveredCount = $recovered.Count
        UnresolvedCount = $unresolved.Count
        Verdict = if ($unresolved.Count -gt 0) { 'fail' } elseif ($distinct.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = $distinct
        RecoveredCandidateEvents = $recovered
        UnresolvedCandidateEvents = $unresolved
    }
}

function Get-FileTransferRuntimeUnlockRetryDispatchAuthorityTupleMismatchCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [AllowEmptyCollection()][object[]]$EffectiveGrantEvents = @(),
        [AllowEmptyCollection()][object[]]$AdditionalDiagnosticEvents = @()
    )

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$decisionTupleRejections = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_decision_tuple_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'runtime_unlock_retry_dispatch_authority_tuple_mismatch'
    })
    [object[]]$currentAuthorityRejections = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_current_authority_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'runtime_unlock_retry_dispatch_authority_tuple_mismatch'
    })
    [object[]]$dispatchObservedSettlements = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_contract_settled' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'DispatchObserved' -and
        (Get-FileTransferEventField -Event $_ -Name 'dispatch_observed' -Default '') -eq '1'
    })
    [object[]]$dispatchObservedReports = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_settlement_reported' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'DispatchObserved' -and
        -not [string]::IsNullOrWhiteSpace(
            (Get-FileTransferEventField -Event $_ -Name 'settlement_reason' -Default ''))
    })
    [object[]]$acceptedSettlementDecisions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_settlement_decided' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'DispatchObserved' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @('Accepted', 'Idempotent')
    })
    [int64[]]$additionalDiagnosticSequences = @(
        $AdditionalDiagnosticEvents |
            Where-Object { $null -ne $_ } |
            ForEach-Object { [int64]$_.Sequence }
    )

    $recoveredCurrentAuthorityRejections = New-Object System.Collections.Generic.List[object]
    $unresolvedCurrentAuthorityRejections = New-Object System.Collections.Generic.List[object]
    foreach ($rejection in $currentAuthorityRejections) {
        if ([int64]$rejection.Sequence -in $additionalDiagnosticSequences) {
            $recoveredCurrentAuthorityRejections.Add($rejection) | Out-Null
            continue
        }

        [object[]]$matchingGrants = @($EffectiveGrantEvents | Where-Object {
            [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
            (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $_ -Right $rejection)
        } | Sort-Object Sequence, LineNumber -Descending)
        $finalSettlementAccepted = $false
        foreach ($grant in $matchingGrants) {
            [object[]]$matchingSettlements = @($dispatchObservedSettlements | Where-Object {
                [int64]$_.Sequence -gt [int64]$grant.Sequence -and
                [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
                (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $_ -Right $rejection)
            } | Sort-Object Sequence, LineNumber)
            foreach ($settlement in $matchingSettlements) {
                $settlementReason = Get-FileTransferEventField -Event $settlement -Name 'decision_reason' -Default ''
                [object[]]$matchingReports = @($dispatchObservedReports | Where-Object {
                    [int64]$_.Sequence -gt [int64]$settlement.Sequence -and
                    [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
                    (Get-FileTransferEventField -Event $_ -Name 'settlement_reason' -Default '') -eq $settlementReason -and
                    (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $_ -Right $rejection)
                } | Sort-Object Sequence, LineNumber)
                foreach ($report in $matchingReports) {
                    $reportReason = Get-FileTransferEventField -Event $report -Name 'settlement_reason' -Default ''
                    $matchingDecision = @($acceptedSettlementDecisions | Where-Object {
                        [int64]$_.Sequence -gt [int64]$report.Sequence -and
                        [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
                        (Get-FileTransferEventField -Event $_ -Name 'settlement_reason' -Default '') -eq $reportReason -and
                        (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $_ -Right $rejection)
                    } | Select-Object -First 1)
                    if ($matchingDecision.Count -gt 0) {
                        $finalSettlementAccepted = $true
                        break
                    }
                }
                if ($finalSettlementAccepted) {
                    break
                }
            }
            if ($finalSettlementAccepted) {
                break
            }
        }

        if ($finalSettlementAccepted) {
            # The authority was installed, dispatched, and terminally accepted.
            # A later current-binding check is stale diagnostic evidence, not a
            # failure of the already completed authority tuple.
            $recoveredCurrentAuthorityRejections.Add($rejection) | Out-Null
        }
        else {
            $unresolvedCurrentAuthorityRejections.Add($rejection) | Out-Null
        }
    }

    [object[]]$unresolved = @($decisionTupleRejections + $unresolvedCurrentAuthorityRejections.ToArray())
    return [pscustomobject]@{
        RawCount = $decisionTupleRejections.Count + $currentAuthorityRejections.Count
        RecoveredCount = $recoveredCurrentAuthorityRejections.Count
        UnresolvedCount = $unresolved.Count
        RecoveredCandidateEvents = @($recoveredCurrentAuthorityRejections.ToArray())
        UnresolvedCandidateEvents = $unresolved
    }
}

function Get-FileTransferRecoveryFailureClassification {
    param(
        [Parameter(Mandatory = $true)]$Summary
    )

    [object[]]$events = @()
    if ($null -ne $Summary.PSObject.Properties['AllEvents']) {
        $events = @($Summary.AllEvents)
    }

    if ($events.Count -eq 0) {
        $events = @($Summary.GlobalEvents + $Summary.TransferEvents)
    }

    $runtimeUnlockOfferNotObservedEvents = @($events | Where-Object {
        $_.EventName -eq 'tuna_acceleration_activation_offer_not_observed' -and
        (
            (Get-FileTransferEventField -Event $_ -Name 'trigger' -Default '') -eq 'runtime_unlock' -or
            (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -like '*runtime_unlock*' -or
            (Get-FileTransferEventField -Event $_ -Name 'retry_reason' -Default '') -like '*runtime_unlock*'
        )
    })
    $runtimeUnlockRetryScheduledEvents = @($events | Where-Object {
        $_.EventName -eq 'tuna_acceleration_runtime_unlock_retry_after_recovery_scheduled'
    })
    $runtimeUnlockRetryReleasedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_released_after_regular_v4_receive_recovery'
    })
    $runtimeUnlockRetryBlockedByRegularV4RecoveryEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_blocked_by_regular_v4_receive_recovery'
    })
    $runtimeUnlockRetryHeldByRegularV4RecoveryEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_held_by_regular_v4_receive_recovery'
    })
    $runtimeUnlockRetryRejectedAfterRegularV4RecoveryEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_rejected_after_regular_v4_receive_recovery'
    })
    $runtimeUnlockRetryRegularV4RecoverySettlementMissingEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_regular_v4_recovery_settlement_missing'
    })
    $runtimeUnlockRegularV4RecoverySettlementReportedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_settlement_reported'
    })
    $runtimeUnlockRegularV4RecoverySettlementDecidedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_settlement_decided'
    })
    $runtimeUnlockRegularV4RecoverySettlementAcceptedEvents = @($runtimeUnlockRegularV4RecoverySettlementDecidedEvents | Where-Object {
        (Get-FileTransferEventField -Event $_ -Name 'disposition' -Default '') -eq 'Consumed' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -eq 'Accepted'
    })
    $runtimeUnlockRegularV4RecoverySettlementIdempotentEvents = @($runtimeUnlockRegularV4RecoverySettlementDecidedEvents | Where-Object {
        (Get-FileTransferEventField -Event $_ -Name 'disposition' -Default '') -eq 'Consumed' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -eq 'Idempotent'
    })
    $runtimeUnlockRegularV4RecoverySettlementRejectedEvents = @($runtimeUnlockRegularV4RecoverySettlementDecidedEvents | Where-Object {
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -eq 'Rejected'
    })
    $runtimeUnlockRegularV4RecoveryLifecycleReportedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lifecycle_reported'
    })
    $runtimeUnlockRegularV4RecoveryLifecycleDecidedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lifecycle_decided'
    })
    $runtimeUnlockRegularV4RecoveryLifecycleAcceptedEvents = @($runtimeUnlockRegularV4RecoveryLifecycleDecidedEvents | Where-Object {
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @('Accepted', 'Idempotent')
    })
    $runtimeUnlockRegularV4RecoveryLeaseClosureRetainedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_retained'
    })
    $runtimeUnlockRegularV4RecoveryLeaseClosureAdoptedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_adopted'
    })
    $runtimeUnlockRegularV4RecoveryLeaseClosureRejectedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_rejected'
    })
    $runtimeUnlockRegularV4RecoveryLeaseClosureConsumedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_consumed'
    })
    $runtimeUnlockRetryDispatchInstallProof =
        Get-FileTransferRuntimeUnlockRetryDispatchInstallProof -Events $events
    [object[]]$runtimeUnlockRetryDispatchEffectiveGrantEvents = @(
        $runtimeUnlockRetryDispatchInstallProof.EffectiveGrantEvents
    )
    $runtimeUnlockRetryDispatchPostGrantHoldProof =
        Get-FileTransferRuntimeUnlockRetryDispatchPostGrantHoldCorrelation `
            -Events $events `
            -EffectiveGrantEvents $runtimeUnlockRetryDispatchEffectiveGrantEvents
    $runtimeUnlockPreCommitProbeStartHandoffProof =
        Get-FileTransferRuntimeUnlockPreCommitProbeStartHandoffCorrelation -Events $events
    $runtimeUnlockRegularV4RecoveryLeaseIssuanceProof =
        Get-FileTransferRuntimeUnlockRegularV4RecoveryLeaseCorrelation `
            -Events $events `
            -EffectiveGrantEvents $runtimeUnlockRetryDispatchEffectiveGrantEvents
    $runtimeUnlockRegularV4RecoveryClosureOfferTimeoutHandoffProof =
        Get-FileTransferRuntimeUnlockRegularV4RecoveryClosureOfferTimeoutCorrelation `
            -Events $events `
            -EffectiveGrantEvents $runtimeUnlockRetryDispatchEffectiveGrantEvents
    $runtimeUnlockRetryDispatchAuthorityTupleMismatchProof =
        Get-FileTransferRuntimeUnlockRetryDispatchAuthorityTupleMismatchCorrelation `
            -Events $events `
            -EffectiveGrantEvents $runtimeUnlockRetryDispatchEffectiveGrantEvents `
            -AdditionalDiagnosticEvents $runtimeUnlockRegularV4RecoveryClosureOfferTimeoutHandoffProof.CorrelatedStaleAuthorityEvents
    $regularV4FrontierRepairSettlementDispositionProof =
        Get-FileTransferRegularV4FrontierRepairSettlementDispositionProof -Events $events
    $runtimeUnlockRegularV4RecoverySettlementProof =
        Get-FileTransferRuntimeUnlockRegularV4RecoverySettlementCorrelation `
            -Events $events `
            -EffectiveGrantEvents $runtimeUnlockRetryDispatchEffectiveGrantEvents `
            -ResolvedRepairSettlementEvents $regularV4FrontierRepairSettlementDispositionProof.ResolvedAcceptedEvents
    $runtimeUnlockPostTunaFallbackTransportProofHandoffProof =
        Get-FileTransferRuntimeUnlockPostTunaFallbackTransportProofHandoffCorrelation `
            -Events $events `
            -EffectiveGrantEvents $runtimeUnlockRetryDispatchEffectiveGrantEvents
    $runtimeUnlockUncommittedTunaFallbackProofAuthorityProof =
        Get-FileTransferRuntimeUnlockUncommittedTunaFallbackProofAuthorityCorrelation `
            -Events $events
    $runtimeUnlockUncommittedTunaFallbackHandoffSuppressionProof =
        Get-FileTransferRuntimeUnlockUncommittedTunaFallbackHandoffSuppressionCorrelation `
            -Events $events
    $runtimeUnlockUncommittedTunaFallbackPrecommitAuthorityProof =
        Get-FileTransferRuntimeUnlockUncommittedTunaFallbackPrecommitAuthorityCorrelation `
            -Events $events
    $runtimeUnlockRetryFallbackTailUnblockRecheckProof =
        Get-FileTransferRuntimeUnlockRetryFallbackTailUnblockRecheckCorrelation `
            -Events $events `
            -EffectiveGrantEvents $runtimeUnlockRetryDispatchEffectiveGrantEvents `
