        )
    }

    function Test-PostTunaFallbackOutboundWorkerInstallDescriptorComplete {
        param([Parameter(Mandatory = $true)]$Event)

        if (-not (Test-PostTunaFallbackOutboundWorkerPublicationTupleComplete -Event $Event)) {
            return $false
        }

        $installGenerationText = Get-FileTransferEventField -Event $Event -Name 'install_generation' -Default ''
        $predecessorGenerationText = Get-FileTransferEventField -Event $Event -Name 'predecessor_install_generation' -Default ''
        $dataSessionGenerationText = Get-FileTransferEventField -Event $Event -Name 'data_session_generation' -Default ''
        $runtimeFamily = Get-FileTransferEventField -Event $Event -Name 'runtime_family' -Default ''
        if ($installGenerationText -notmatch '^\d+$' -or
            $predecessorGenerationText -notmatch '^\d+$' -or
            $dataSessionGenerationText -notmatch '^\d+$' -or
            [string]::IsNullOrWhiteSpace($runtimeFamily) -or
            $runtimeFamily -in @('(none)', 'none')) {
            return $false
        }

        foreach ($fieldName in Get-PostTunaFallbackOutboundWorkerInstallDescriptorFieldNames) {
            $value = Get-FileTransferEventField -Event $Event -Name $fieldName -Default ''
            if ([string]::IsNullOrWhiteSpace($value) -or $value -in @('(none)', 'none')) {
                return $false
            }
        }

        foreach ($fieldName in @(
                'descriptor_terminal_generation',
                'descriptor_leg_generation',
                'runtime_owner_protocol_version',
                'runtime_owner_live_route_epoch',
                'runtime_owner_runtime_generation',
                'runtime_owner_terminal_generation',
                'route_publication_protocol_version',
                'route_publication_live_route_epoch',
                'route_publication_runtime_generation',
                'route_publication_terminal_generation',
                'route_publication_leg_generation',
                'route_publication_route_commit_generation',
                'route_publication_target_protocol_version',
                'route_publication_token_generation',
                'route_publication_owner_protocol_version',
                'route_publication_owner_live_route_epoch',
                'route_publication_owner_runtime_generation',
                'route_publication_owner_terminal_generation')) {
            if ((Get-FileTransferEventField -Event $Event -Name $fieldName -Default '') -notmatch '^\d+$') {
                return $false
            }
        }

        foreach ($fieldName in @('runtime_owner_direction', 'route_publication_direction', 'route_publication_owner_direction')) {
            if ((Get-FileTransferEventField -Event $Event -Name $fieldName -Default '') -ne 'outbound') {
                return $false
            }
        }

        $installGeneration = [int64]$installGenerationText
        $predecessorGeneration = [int64]$predecessorGenerationText
        $dataSessionGeneration = [int64]$dataSessionGenerationText
        return $installGeneration -gt 0 -and
            $predecessorGeneration -ge 0 -and
            $predecessorGeneration -lt $installGeneration -and
            $dataSessionGeneration -gt 0
    }

    function Test-PostTunaFallbackOutboundWorkerInstallDescriptorMatch {
        param(
            [Parameter(Mandatory = $true)]$Anchor,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if (-not (Test-PostTunaFallbackOutboundWorkerInstallDescriptorComplete -Event $Anchor) -or
            -not (Test-PostTunaFallbackOutboundWorkerInstallDescriptorComplete -Event $Candidate) -or
            -not (Test-PostTunaFallbackOutboundWorkerPublicationTupleMatch -Publication $Anchor -Candidate $Candidate)) {
            return $false
        }

        foreach ($fieldName in @(
                'install_generation',
                'predecessor_install_generation',
                'data_session_generation',
                'runtime_family') + @(Get-PostTunaFallbackOutboundWorkerInstallDescriptorFieldNames)) {
            $anchorValue = Get-FileTransferEventField -Event $Anchor -Name $fieldName -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $fieldName -Default ''
            if (-not [string]::Equals($anchorValue, $candidateValue, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        return $true
    }

    function Test-PostTunaFallbackOutboundWorkerDispatchTupleMatch {
        param(
            [Parameter(Mandatory = $true)]$Install,
            [Parameter(Mandatory = $true)]$Candidate
        )

        return Test-PostTunaFallbackOutboundWorkerInstallDescriptorMatch -Anchor $Install -Candidate $Candidate
    }

    function Test-PostTunaFallbackOutboundWorkerProgressMatch {
        param(
            [Parameter(Mandatory = $true)]$Install,
            [Parameter(Mandatory = $true)]$Progress,
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][object[]]$Dispatches
        )

        if ($Progress.EventName -ne 'filetransfer_fallback_frontier_repair_progress_observed' -or
            (Get-FileTransferEventField -Event $Progress -Name 'direction' -Default '') -ne 'inbound' -or
            -not (Test-PostTunaFallbackOutboundWorkerScopeMatch -Anchor $Install -Candidate $Progress)) {
            return $false
        }

        $repairRequestKey = Get-FileTransferEventField -Event $Progress -Name 'repair_request_key' -Default ''
        $frontierBeforeText = Get-FileTransferEventField -Event $Progress -Name 'committed_frontier_before' -Default ''
        $frontierAfterText = Get-FileTransferEventField -Event $Progress -Name 'committed_frontier_after' -Default ''
        $requestedChunkCountText = Get-FileTransferEventField -Event $Progress -Name 'requested_chunk_count' -Default ''
        if ([string]::IsNullOrWhiteSpace($repairRequestKey) -or
            $repairRequestKey -in @('(none)', 'none') -or
            $frontierBeforeText -notmatch '^\d+$' -or
            $frontierAfterText -notmatch '^\d+$' -or
            $requestedChunkCountText -notmatch '^\d+$' -or
            [int64]$frontierAfterText -le [int64]$frontierBeforeText -or
            [int64]$requestedChunkCountText -le 0) {
            return $false
        }

        return @($Dispatches | Where-Object {
            [int64]$_.Sequence -lt [int64]$Progress.Sequence -and
            (Test-PostTunaFallbackOutboundWorkerInstallDescriptorMatch -Anchor $Install -Candidate $_) -and
            [string]::Equals(
                (Get-FileTransferEventField -Event $_ -Name 'repair_request_id' -Default ''),
                $repairRequestKey,
                [System.StringComparison]::Ordinal)
        } | Select-Object -First 1).Count -gt 0
    }

    # A stale V4 sender failure is normally harmless after route supersession. It
    # becomes a proof-chain failure only when the accepted post-Tuna publication
    # is left without a consuming outbound worker: a later peer-visible frontier
    # request reaches the transport, but no exact handoff installation followed
    # by Core dispatch (or terminal resolution) remains current. A matching
    # nonterminal supervisor stop invalidates that proof until a fresh complete
    # required/install/dispatch interval is retained.
    $postTunaFallbackOutboundReceiveWorkerHandoffMissingCandidateEvents =
        New-Object System.Collections.Generic.List[object]
    $postTunaFallbackOutboundReceiveWorkerStaleFailureEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_runtime_owner_stale_update_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
        (Get-FileTransferEventField -Event $_ -Name 'source' -Default '') -eq 'v4_sender_failed' -and
        (Get-FileTransferEventField -Event $_ -Name 'attempted_action' -Default '') -eq 'read_failed' -and
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq 'runtime_generation_mismatch' -and
        (Get-FileTransferEventField -Event $_ -Name 'current_route' -Default '') -eq 'post_tuna_fallback_v6' -and
        (Get-FileTransferEventField -Event $_ -Name 'current_protocol_version' -Default '') -eq '6'
    } | Sort-Object Sequence)
    $postTunaFallbackOutboundWorkerRequiredEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_outbound_sparse_worker_handoff_required'
    } | Sort-Object Sequence)
    foreach ($staleFailure in $postTunaFallbackOutboundReceiveWorkerStaleFailureEvents) {
        $staleSequence = [int64]$staleFailure.Sequence
        $currentRuntimeGeneration = Get-FileTransferEventField -Event $staleFailure -Name 'current_runtime_generation' -Default ''
        $currentTerminalGeneration = Get-FileTransferEventField -Event $staleFailure -Name 'current_terminal_generation' -Default ''
        $currentLiveRouteEpoch = Get-FileTransferEventField -Event $staleFailure -Name 'current_live_route_epoch' -Default ''
        if ([string]::IsNullOrWhiteSpace($currentRuntimeGeneration) -or
            [string]::IsNullOrWhiteSpace($currentTerminalGeneration) -or
            [string]::IsNullOrWhiteSpace($currentLiveRouteEpoch)) {
            continue
        }

        $matchingPublications = @($events | Where-Object {
            [int64]$_.Sequence -lt $staleSequence -and
            $_.EventName -in @(
                'filetransfer_route_transitioned',
                'filetransfer_route_selected',
                'filetransfer_live_route_epoch_started',
                'filetransfer_live_route_epoch_recovered',
                'filetransfer_runtime_started') -and
            (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
            (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'post_tuna_fallback_v6' -and
            (Get-FileTransferEventField -Event $_ -Name 'protocol_version' -Default '') -eq '6' -and
            (Get-FileTransferEventField -Event $_ -Name 'runtime_generation' -Default '') -eq $currentRuntimeGeneration -and
            (Get-FileTransferEventField -Event $_ -Name 'terminal_generation' -Default '') -eq $currentTerminalGeneration -and
            (Get-FileTransferEventField -Event $_ -Name 'live_route_epoch' -Default '') -eq $currentLiveRouteEpoch -and
            (Get-FileTransferEventField -Event $_ -Name 'route_publication_action_kind' -Default '') -eq 'RoutePublication' -and
            (Get-FileTransferEventField -Event $_ -Name 'coordinator_decision_reason' -Default '') -eq 'accepted' -and
            (Test-PostTunaFallbackOutboundWorkerScopeMatch -Anchor $staleFailure -Candidate $_) -and
            (Test-PostTunaFallbackOutboundWorkerPublicationTupleComplete -Event $_)
        } | Sort-Object Sequence -Descending | Select-Object -First 1)
        if ($matchingPublications.Count -eq 0) {
            continue
        }

        $publication = $matchingPublications[0]
        $supersedingPublication = @($events | Where-Object {
            [int64]$_.Sequence -gt $staleSequence -and
            $_.EventName -in @(
                'filetransfer_route_transitioned',
                'filetransfer_route_selected',
                'filetransfer_live_route_epoch_started',
                'filetransfer_live_route_epoch_recovered',
                'filetransfer_runtime_started') -and
            (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
            (Get-FileTransferEventField -Event $_ -Name 'route_publication_action_kind' -Default '') -eq 'RoutePublication' -and
            (Get-FileTransferEventField -Event $_ -Name 'coordinator_decision_reason' -Default '') -eq 'accepted' -and
            (Test-PostTunaFallbackOutboundWorkerScopeMatch -Anchor $staleFailure -Candidate $_) -and
            (Test-PostTunaFallbackOutboundWorkerPublicationTupleComplete -Event $_) -and
            -not (Test-PostTunaFallbackOutboundWorkerPublicationTupleMatch -Publication $publication -Candidate $_)
        } | Sort-Object Sequence | Select-Object -First 1)
        if ($supersedingPublication.Count -gt 0) {
            # Route/publication replacement invalidates the old worker stage.
            # Later frontier traffic belongs to the successor tuple and cannot
            # prove a missing handoff for this stale predecessor.
            continue
        }

        $frontierEvidenceObserved = $false
        $terminalResolutionObserved = $false
        $publicationSuperseded = $false
        $currentInstall = $null
        $currentConsumerProven = $false
        $descriptorDispatchEvents = New-Object System.Collections.Generic.List[object]
        $matchedFrontierCorrelationKeys = [System.Collections.Generic.HashSet[string]]::new(
            [System.StringComparer]::OrdinalIgnoreCase)
        foreach ($event in @($events | Sort-Object Sequence)) {
            $eventSequence = [int64]$event.Sequence
            if ($eventSequence -le [int64]$publication.Sequence -or
                -not (Test-PostTunaFallbackOutboundWorkerScopeMatch -Anchor $staleFailure -Candidate $event)) {
                continue
            }

            if ($eventSequence -gt $staleSequence -and
                $event.EventName -in @(
                    'filetransfer_route_transitioned',
                    'filetransfer_route_selected',
                    'filetransfer_live_route_epoch_started',
                    'filetransfer_live_route_epoch_recovered',
                    'filetransfer_runtime_started') -and
                (Get-FileTransferEventField -Event $event -Name 'direction' -Default '') -eq 'outbound' -and
                (Get-FileTransferEventField -Event $event -Name 'route_publication_action_kind' -Default '') -eq 'RoutePublication' -and
                (Get-FileTransferEventField -Event $event -Name 'coordinator_decision_reason' -Default '') -eq 'accepted' -and
                (Test-PostTunaFallbackOutboundWorkerPublicationTupleComplete -Event $event) -and
                -not (Test-PostTunaFallbackOutboundWorkerPublicationTupleMatch -Publication $publication -Candidate $event)) {
                $publicationSuperseded = $true
                break
            }

            if ($eventSequence -gt $staleSequence -and
                $event.EventName -in @('file_transfer_outbound_terminal', 'transfer_terminal') -and
                ($event.EventName -ne 'transfer_terminal' -or
                    (Get-FileTransferEventField -Event $event -Name 'direction' -Default '') -eq 'outbound')) {
                $terminalResolutionObserved = $true
                break
            }

            if ($event.EventName -eq 'filetransfer_outbound_sparse_worker_handoff_installed' -and
                (Test-PostTunaFallbackOutboundWorkerInstallDescriptorComplete -Event $event) -and
                (Test-PostTunaFallbackOutboundWorkerPublicationTupleMatch -Publication $publication -Candidate $event)) {
                $matchingRequired = @($postTunaFallbackOutboundWorkerRequiredEvents | Where-Object {
                    [int64]$_.Sequence -lt $eventSequence -and
                    (Test-PostTunaFallbackOutboundWorkerInstallDescriptorMatch -Anchor $_ -Candidate $event)
                } | Sort-Object Sequence -Descending | Select-Object -First 1)
                if ($matchingRequired.Count -gt 0) {
                    if ($null -eq $currentInstall -or
                        -not (Test-PostTunaFallbackOutboundWorkerInstallDescriptorMatch -Anchor $currentInstall -Candidate $event)) {
                        $currentConsumerProven = $false
                    }
                    $currentInstall = $event
                }
                continue
            }

            if ($event.EventName -eq 'filetransfer_outbound_sparse_receive_supervisor_stopped' -and
                $null -ne $currentInstall -and
                (Test-PostTunaFallbackOutboundWorkerInstallDescriptorMatch -Anchor $currentInstall -Candidate $event)) {
                $stopTerminal = Get-FileTransferEventField -Event $event -Name 'terminal' -Default ''
                if ($eventSequence -gt $staleSequence -and $stopTerminal -eq '1') {
                    $terminalResolutionObserved = $true
                    break
                }
                if ($stopTerminal -eq '0') {
                    $currentInstall = $null
                    $currentConsumerProven = $false
                }
                continue
            }

            if ($eventSequence -gt $staleSequence -and
                $event.EventName -eq 'filetransfer_v6_frontier_request_receive_dispatched' -and
                (Test-PostTunaFallbackOutboundWorkerInstallDescriptorComplete -Event $event) -and
                (Test-PostTunaFallbackOutboundWorkerPublicationTupleMatch -Publication $publication -Candidate $event)) {
                $descriptorDispatchEvents.Add($event) | Out-Null
                if ($null -ne $currentInstall -and
                    (Test-PostTunaFallbackOutboundWorkerDispatchTupleMatch -Install $currentInstall -Candidate $event)) {
                    $currentConsumerProven = $true
                }
                continue
            }

            if ($eventSequence -gt $staleSequence -and
                $null -ne $currentInstall -and
                (Test-PostTunaFallbackOutboundWorkerProgressMatch `
                    -Install $currentInstall `
                    -Progress $event `
                    -Dispatches $descriptorDispatchEvents.ToArray())) {
                $currentConsumerProven = $true
                continue
            }

            if ($eventSequence -le $staleSequence) {
                continue
            }

            if ($event.EventName -in @(
                    'filetransfer_v6_frontier_request_transport_queued',
                    'filetransfer_v6_frontier_request_transport_rejected') -and
                (Get-FileTransferEventField -Event $event -Name 'frame_type' -Default '') -eq 'filetransfer.frontier_request.v6') {
                $correlationKey = Get-PostTunaFallbackOutboundWorkerFrontierCorrelationKey -Event $event
                if (-not [string]::IsNullOrWhiteSpace($correlationKey) -and
                    $matchedFrontierCorrelationKeys.Contains($correlationKey)) {
                    $frontierEvidenceObserved = $true
                }
                continue
            }

            if ($event.EventName -in @(
                    'filetransfer_control_plane_delivery_result',
                    'filetransfer_control_plane_delivery_observed') -and
                (Get-FileTransferEventField -Event $event -Name 'frame_type' -Default '') -eq 'filetransfer.frontier_request.v6' -and
                (Test-PostTunaFallbackOutboundWorkerFrontierTupleMatch -Publication $publication -Candidate $event) -and
                (Get-FileTransferEventField -Event $event -Name 'peer_visible_any' -Default '0') -eq '1' -and
                (Get-FileTransferEventField -Event $event -Name 'accepted_any' -Default '0') -eq '1') {
                $correlationKey = Get-PostTunaFallbackOutboundWorkerFrontierCorrelationKey -Event $event
                if (-not [string]::IsNullOrWhiteSpace($correlationKey)) {
                    $matchedFrontierCorrelationKeys.Add($correlationKey) | Out-Null
                    $frontierEvidenceObserved = $true
                }
            }
        }

        if (-not $publicationSuperseded -and
            -not $terminalResolutionObserved -and
            $frontierEvidenceObserved -and
            -not $currentConsumerProven) {
            $postTunaFallbackOutboundReceiveWorkerHandoffMissingCandidateEvents.Add($staleFailure) | Out-Null
        }
    }
    $postTunaFallbackOutboundReceiveWorkerHandoffMissingCount =
        $postTunaFallbackOutboundReceiveWorkerHandoffMissingCandidateEvents.Count

    function Test-RegularV4FrontierRepairMatch {
        param(
            [Parameter(Mandatory = $true)]$Source,
            [Parameter(Mandatory = $true)]$Candidate
        )
        return Test-FileTransferRegularV4FrontierRepairLifecycleMatch `
            -Source $Source `
            -Candidate $Candidate
    }

    function Test-RegularV4FrontierRepairSuccessorMatch {
        param(
            [Parameter(Mandatory = $true)]$Source,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if ($Candidate.EventName -ne 'filetransfer_regular_v4_frontier_repair_successor_authorized') {
            return $false
        }

        $sourceKey = Get-FileTransferEventField -Event $Source -Name 'repair_request_key' -Default ''
        $predecessorKey = Get-FileTransferEventField -Event $Candidate -Name 'predecessor_repair_request_key' -Default ''
        if ([string]::IsNullOrWhiteSpace($sourceKey) -or
            [string]::IsNullOrWhiteSpace($predecessorKey) -or
            -not [string]::Equals($sourceKey, $predecessorKey, [System.StringComparison]::Ordinal)) {
            return $false
        }

        foreach ($fieldName in @('transfer_id', 'session_id', 'route', 'protocol_version')) {
            $sourceValue = Get-FileTransferEventField -Event $Source -Name $fieldName -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $fieldName -Default ''
            if (-not [string]::IsNullOrWhiteSpace($sourceValue) -and
                -not [string]::IsNullOrWhiteSpace($candidateValue) -and
                -not [string]::Equals($sourceValue, $candidateValue, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        return $true
    }

    $regularV4FrontierRepairSettlementDispositionUnverifiableEvents =
        @($regularV4FrontierRepairSettlementDispositionProof.UnresolvedCandidateEvents)

    $regularV4FrontierRepairAcceptedResolvedSettledStalledEvents =
        @($regularV4FrontierRepairLifecycleProof.ResolvedSettledStalledEvents)

    $regularV4RecoveryPredecessorSettlementClosedSuccessorEvents = @(
        $consumedCandidates = @(
            $runtimeUnlockRegularV4FrontierRepairSettlementHandoffConsumedEvents +
            $runtimeUnlockRegularV4FrontierRepairPrecontractSettlementConsumedEvents
        )
        foreach ($consumed in $consumedCandidates) {
            if ((Get-FileTransferEventField -Event $consumed -Name 'decision_reason' -Default '') -eq 'no_retry_contract') {
                continue
            }

            $consumedSequence = [int64]$consumed.Sequence
            $sessionId = Get-FileTransferEventField -Event $consumed -Name 'session_id' -Default ''
            $transferId = Get-FileTransferEventField -Event $consumed -Name 'transfer_id' -Default ''
            $adoptedLivenessGeneration = Get-FileTransferEventField -Event $consumed -Name 'adopted_recovery_liveness_generation' -Default '0'
            $adoptedBridgeDecisionGeneration = Get-FileTransferEventField -Event $consumed -Name 'adopted_bridge_decision_generation' -Default '0'
            if ($adoptedLivenessGeneration -eq '0') {
                $adoption = @($runtimeUnlockRegularV4FrontierRepairSettlementHandoffAdoptedEvents | Where-Object {
                    [int64]$_.Sequence -lt $consumedSequence -and
                    (Test-RegularV4FrontierRepairMatch -Source $consumed -Candidate $_)
                } | Select-Object -Last 1)
                if ($adoption.Count -gt 0) {
                    $adoptedLivenessGeneration = Get-FileTransferEventField -Event $adoption[0] -Name 'adopted_recovery_liveness_generation' -Default '0'
                    $adoptedBridgeDecisionGeneration = Get-FileTransferEventField -Event $adoption[0] -Name 'adopted_bridge_decision_generation' -Default '0'
                }
            }

            $terminalBoundary = @($regularV4RecoveryBridgeLifecycleEvents | Where-Object {
                [int64]$_.Sequence -lt $consumedSequence -and
                (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '') -eq $sessionId -and
                (Get-FileTransferEventField -Event $_ -Name 'transfer_id' -Default '') -eq $transferId -and
                (Get-FileTransferEventField -Event $_ -Name 'lifecycle' -Default '') -in @('completed', 'exhausted', 'receive_resumed') -and
                ($adoptedLivenessGeneration -eq '0' -or
                    (Get-FileTransferEventField -Event $_ -Name 'generation' -Default '0') -eq $adoptedLivenessGeneration) -and
                ($adoptedBridgeDecisionGeneration -eq '0' -or
                    (Get-FileTransferEventField -Event $_ -Name 'bridge_decision_generation' -Default '0') -eq $adoptedBridgeDecisionGeneration)
            })
            if ($terminalBoundary.Count -eq 0) {
                $consumed
            }
        }
    )

    $regularV4FrontierRepairUnresolvedStalledEvents =
        @($regularV4FrontierRepairLifecycleProof.UnresolvedCandidateEvents)

    $regularV4FrontierRepairUnresolvedDispatchEvents = @(
        foreach ($dispatched in $regularV4FrontierRepairDispatchedEvents) {
            $dispatchSequence = [int64]$dispatched.Sequence
            $settled = @(
                @($regularV4FrontierRepairProgressObservedEvents + $regularV4FrontierRepairAuthorityRejectedEvents + $regularV4FrontierRepairAcceptedResolvedSettledStalledEvents) | Where-Object {
                    [int64]$_.Sequence -gt $dispatchSequence -and
                    (Test-RegularV4FrontierRepairMatch -Source $dispatched -Candidate $_)
                }
            )
            if ($settled.Count -eq 0) {
                $dispatched
            }
        }
    )

    $regularV4FrontierRepairUnresolvedSendDeferredEvents = @(
        foreach ($deferred in $regularV4FrontierRepairSendDeferredEvents) {
            $deferredSequence = [int64]$deferred.Sequence
            $settled = @(
                @($regularV4FrontierRepairDispatchedEvents + $regularV4FrontierRepairProgressObservedEvents + $regularV4FrontierRepairAuthorityRejectedEvents + $regularV4FrontierRepairSuccessorAuthorizedEvents + $regularV4FrontierRepairAcceptedResolvedSettledStalledEvents) | Where-Object {
                    [int64]$_.Sequence -gt $deferredSequence -and
                    ((Test-RegularV4FrontierRepairMatch -Source $deferred -Candidate $_) -or
                        (Test-RegularV4FrontierRepairSuccessorMatch -Source $deferred -Candidate $_))
                }
            )
            if ($settled.Count -eq 0) {
                $deferred
            }
        }
    )
    $regularV4FrontierRepairUnresolvedMissingDispatchEvents = @(
        foreach ($missingDispatch in $regularV4FrontierRepairMissingDispatchEvents) {
            $missingDispatchSequence = [int64]$missingDispatch.Sequence
            $settled = @(
                @($regularV4FrontierRepairDispatchedEvents + $regularV4FrontierRepairProgressObservedEvents + $regularV4FrontierRepairAuthorityRejectedEvents + $regularV4FrontierRepairSuccessorAuthorizedEvents + $regularV4FrontierRepairAcceptedResolvedSettledStalledEvents) | Where-Object {
                    [int64]$_.Sequence -gt $missingDispatchSequence -and
                    ((Test-RegularV4FrontierRepairMatch -Source $missingDispatch -Candidate $_) -or
                        (Test-RegularV4FrontierRepairSuccessorMatch -Source $missingDispatch -Candidate $_))
                }
            )
            if ($settled.Count -eq 0) {
                $missingDispatch
            }
        }
    )

    $regularV4RepairLivenessAuthorityMissing =
        $hasRegularOnlyRouteEvidence -and
        $regularV4FrontierStallMissingRangeEvents.Count -gt 0 -and
        $regularV4RepairRequestedEvents.Count -gt 0 -and
        $regularV4FrontierRepairAuthorityGrantedEvents.Count -eq 0 -and
        ($sessionLivenessTimeoutEvents.Count -gt 0 -or $peerDisconnectedTerminalEvents.Count -gt 0)
    $regularV4FrontierRepairStalled =
        $hasRegularOnlyRouteEvidence -and
        (
            $regularV4FrontierRepairSettlementDispositionUnverifiableEvents.Count -gt 0 -or
            $regularV4FrontierRepairUnresolvedStalledEvents.Count -gt 0 -or
            (
                $regularV4FrontierRepairUnresolvedDispatchEvents.Count -gt 0 -and
                ($sessionLivenessTimeoutEvents.Count -gt 0 -or $peerDisconnectedTerminalEvents.Count -gt 0)
            )
        )
    $regularV4FrontierRepairSendDeferred =
        $hasRegularOnlyRouteEvidence -and
        ($regularV4FrontierRepairUnresolvedSendDeferredEvents.Count -gt 0 -or
            $regularV4FrontierRepairUnresolvedMissingDispatchEvents.Count -gt 0) -and
        ($sessionLivenessTimeoutEvents.Count -gt 0 -or $peerDisconnectedTerminalEvents.Count -gt 0)
    $runtimeUnlockFallbackProofReplayPendingAfterPairedYieldUnresolvedEvents = @(
        foreach ($pending in $runtimeUnlockFallbackProofReplayPendingAfterPairedYieldEvents) {
            $pendingSequence = [int64]$pending.Sequence
            $pendingTransferId = Get-FileTransferEventField -Event $pending -Name 'transfer_id' -Default ''
            $pendingSessionId = Get-FileTransferEventField -Event $pending -Name 'session_id' -Default ''
            $pendingDirection = Get-FileTransferEventField -Event $pending -Name 'direction' -Default ''
            $settled = @(
                @(
                    $runtimeUnlockFallbackQuiescentAdmissionGrantedEvents +
                    $runtimeUnlockPreCommitProbeStartedEvents +
                    $runtimeUnlockPreCommitProbePendingRejectedEvents +
                    $runtimeUnlockPreCommitProbePendingHeldEvents +
                    $runtimeUnlockTransactionCommittedEvents
                ) | Where-Object {
                    if ([int64]$_.Sequence -le $pendingSequence) {
                        return $false
                    }

                    $candidateTransferId = Get-FileTransferEventField -Event $_ -Name 'transfer_id' -Default ''
                    if (-not [string]::IsNullOrWhiteSpace($pendingTransferId) -and
                        -not [string]::Equals($candidateTransferId, $pendingTransferId, [System.StringComparison]::Ordinal)) {
                        return $false
                    }

                    $candidateSessionId = Get-FileTransferEventField -Event $_ -Name 'session_id' -Default ''
                    if (-not [string]::IsNullOrWhiteSpace($pendingSessionId) -and
                        -not [string]::IsNullOrWhiteSpace($candidateSessionId) -and
                        -not [string]::Equals($candidateSessionId, $pendingSessionId, [System.StringComparison]::Ordinal)) {
                        return $false
                    }

                    $candidateDirection = Get-FileTransferEventField -Event $_ -Name 'direction' -Default ''
                    if (-not [string]::IsNullOrWhiteSpace($pendingDirection) -and
                        -not [string]::IsNullOrWhiteSpace($candidateDirection) -and
                        -not [string]::Equals($candidateDirection, $pendingDirection, [System.StringComparison]::OrdinalIgnoreCase)) {
                        return $false
                    }

                    return $true
                }
            )
            if ($settled.Count -eq 0) {
                $pending
            }
        }
    )
    $runtimeUnlockPostFallbackResumeBlockedEvents = @(
        foreach ($blocked in @($runtimeUnlockPreCommitProbeWaitingForTransportProofEvents + $runtimeUnlockPreCommitProbePendingHeldEvents)) {
            $blockedSequence = [int64]$blocked.Sequence
            $matchingAdmission = @(
                $runtimeUnlockFallbackQuiescentAdmissionGrantedEvents | Where-Object {
                    [int64]$_.Sequence -le $blockedSequence -and
                    (Test-FileTransferStaleRejectedProofScopeMatches -Rejection $blocked -Effect $_)
                }
            )
            if ($matchingAdmission.Count -eq 0) {
                continue
            }

            $settled = @(
                @(
                    $runtimeUnlockPreCommitProbeStartedEvents +
                    $runtimeUnlockPreCommitProbeAckedEvents +
                    $runtimeUnlockPreCommitProbePendingRejectedEvents +
                    $runtimeUnlockPreCommitProbeFailedEvents +
                    $runtimeUnlockTransactionCommittedEvents
                ) | Where-Object {
                    Test-FileTransferRuntimeUnlockResumeSettlementMatches -Blocked $blocked -Settlement $_
                }
            )

            if ($settled.Count -eq 0) {
                $blocked
            }
        }
    )
    $postFallbackRuntimeUnlockResumeBlocked =
        $hasPostTunaFallbackEvidence -and
        (
            $runtimeUnlockFallbackProofReplayPendingAfterPairedYieldUnresolvedEvents.Count -gt 0 -or
            $runtimeUnlockPostFallbackResumeBlockedEvents.Count -gt 0
        )
    $regularV4ReceiveRecoveryRejectedBeforeRuntimeUnlock =
        $runtimeUnlockRetryRejectedAfterRegularV4RecoveryEvents.Count -gt 0 -and
        $runtimeUnlockTransactionStartedEvents.Count -eq 0 -and
        @($events | Where-Object {
            $_.EventName -eq 'session_recovery_contract_failed' -and
            (
                (Get-FileTransferEventField -Event $_ -Name 'retry_reason' -Default '') -like '*runtime_unlock*' -or
                (Get-FileTransferEventField -Event $_ -Name 'kind' -Default '') -eq 'runtime_unlock_activation'
            )
        }).Count -gt 0 -and
        (
            $regularV4ReceiveRecoveryClosedNoDeferralEvents.Count -gt 0 -or
            @($runtimeUnlockRetryRejectedAfterRegularV4RecoveryEvents | Where-Object {
                (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -in @(
                    'regular_v4_recovery_no_current_settlement_proof',
                    'receive_recovery_contract_rejected',
                    'v4_repair_missing_dispatch',
                    'v4_repair_settled_stalled')
            }).Count -gt 0
        )

    $runtimeUnlockHasPreCommitAckProof =
        $runtimeUnlockProbeAckedEvents.Count -gt 0 -or
        $runtimeUnlockTunaProbeAckReceivedEvents.Count -gt 0 -or
        $runtimeUnlockPreCommitProbeAckedEvents.Count -gt 0 -or
        $runtimeUnlockPreCommitRouteEpochRecoveredEvents.Count -gt 0

    $terminalShaOk = Get-FileTransferInvariantShaOk -TerminalEvents @($Summary.TerminalEvents) -GateVerdict ''
    $terminalWinner = Get-FileTransferInvariantTerminalWinner -TerminalEvents @($Summary.TerminalEvents) -ShaOk $terminalShaOk
    $lateFrameProof = Get-FileTransferInvariantLateFrameClassification `
        -Summary $Summary `
        -TerminalWinner $terminalWinner `
        -ShaOk $terminalShaOk `
        -ExcludedEventSequences @(
            $runtimeUnlockUncommittedTunaFallbackProofAuthorityProof.DownstreamProtocolMismatchSequences
            $runtimeUnlockUncommittedTunaFallbackHandoffSuppressionProof.DownstreamProtocolMismatchSequences
            $runtimeUnlockUncommittedTunaFallbackPrecommitAuthorityProof.DownstreamProtocolMismatchSequences)
    $terminalLifecycleInvariant = Get-FileTransferInvariantTerminalLifecycleResult -Summary $Summary -LateFrameClassification $lateFrameProof.Classification
    $fallbackAuthorityProof = Get-FileTransferFallbackLegAuthorityProof -TransferEvents $Summary.TransferEvents
    $hasFallbackRouteOrOwnerEvidence = $hasPostTunaFallbackEvidence -or $fallbackAuthorityProof.StartedCount -gt 0

    $proofChainFailureCandidates = New-Object System.Collections.Generic.List[object]
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_retry_dispatch_install_grant_evidence_incomplete' `
        -Events @($runtimeUnlockRetryDispatchInstallProof.GrantEvidenceUnresolvedCandidateEvents)
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_uncommitted_tuna_fallback_proof_authority_missing' `
        -Events @($runtimeUnlockUncommittedTunaFallbackProofAuthorityProof.UnresolvedCandidateEvents) `
        -DefaultReason 'post_tuna_fallback_proof_completed_without_authority_scope' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_precommit_fallback_recovery_handoff_suppressed' `
        -Events @($runtimeUnlockUncommittedTunaFallbackHandoffSuppressionProof.UnresolvedCandidateEvents) `
        -DefaultReason 'transport_recovered_availability_suppressed_with_uncommitted_runtime_unlock' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_uncommitted_tuna_fallback_handoff_precommit_authority_misbound' `
        -Events @($runtimeUnlockUncommittedTunaFallbackPrecommitAuthorityProof.UnresolvedCandidateEvents) `
        -DefaultReason 'proof_boundary_not_current' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_post_tuna_fallback_transport_proof_handoff_missing' `
        -Events @($runtimeUnlockPostTunaFallbackTransportProofHandoffProof.UnresolvedCandidateEvents) `
        -DefaultReason 'scheduled_runtime_unlock_handoff_not_started' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_filetransfer_owner_missing_before_path_lease' `
        -Events $runtimeUnlockFileTransferOwnerMissingBeforePathLeaseUnresolvedEvents
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_filetransfer_owner_stale_before_offer_dispatch' `
        -Events $runtimeUnlockFileTransferOwnerStaleBeforeOfferDispatchUnresolvedEvents
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_retry_source_publication_mismatch' `
        -Events $runtimeUnlockRetrySourcePublicationMismatchEvents
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_tuna_probe_recovery_authority_lost' `
        -Events @($runtimeUnlockProbeRecoveryAuthorityLostUnresolvedEvents.ToArray())
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_retry_dispatch_successor_attempt_mismatch' `
        -Events $runtimeUnlockRetryDispatchSuccessorAttemptMismatchEvents
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_retry_dispatch_zero_offer_successor_rejected' `
        -Events @($runtimeUnlockRetryZeroOfferSuccessorProof.UnresolvedCandidateEvents) `
        -DefaultReason 'retry_dispatch_successor_retired_offer_mismatch' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_retry_dispatch_fallback_paired_yield_successor_release_invalid' `
        -Events @($runtimeUnlockRetryFallbackPairedYieldSuccessorReleaseProof.UnresolvedCandidateEvents) `
        -DefaultReason 'retry_dispatch_predecessor_release_invalid' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_retry_dispatch_settlement_unaccepted' `
        -Events @($runtimeUnlockRetryDispatchSettlementAcceptanceMissingEvents.ToArray()) `
        -DefaultReason 'runtime_unlock_retry_dispatch_settlement_unaccepted' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_retry_dispatch_chain_closure_incomplete' `
        -Events @($runtimeUnlockRetryDispatchIncompleteBoundedClosureEvents.ToArray()) `
        -DefaultReason 'runtime_unlock_retry_dispatch_chain_closure_incomplete' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_retry_dispatch_fresh_chain_invalid_after_closure' `
        -Events @($runtimeUnlockRetryDispatchInvalidFreshGrantEvents.ToArray()) `
        -DefaultReason 'runtime_unlock_retry_dispatch_fresh_chain_invalid_after_closure' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'post_tuna_fallback_outbound_receive_worker_handoff_missing' `
        -Events @($postTunaFallbackOutboundReceiveWorkerHandoffMissingCandidateEvents.ToArray())
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_retry_dispatch_fallback_tail_unblock_recheck_missing' `
        -Events @($runtimeUnlockRetryFallbackTailUnblockRecheckProof.UnresolvedCandidateEvents) `
        -DefaultReason 'fallback_tail_unblock_retry_recheck_missing' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'regular_v4_peer_silence_replay_missing_dispatch_range_not_preserved' `
        -Events @($regularV4PeerSilenceReplayMissingDispatchRangeProof.UnresolvedCandidateEvents) `
        -DefaultReason 'peer_silence_replay_range_rotated_after_missing_dispatch' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'regular_v4_frontier_repair_initial_pressure_install_missing' `
        -Events @($regularV4FrontierRepairInitialPressureInstallProof.UnresolvedCandidateEvents) `
        -DefaultReason 'regular_v4_frontier_repair_pressure_missing' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'regular_v4_frontier_repair_successor_pressure_install_missing' `
        -Events @($regularV4FrontierRepairSuccessorPressureInstallProof.UnresolvedCandidateEvents) `
        -DefaultReason 'regular_v4_frontier_repair_pressure_missing' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'regular_v4_frontier_repair_missing_range_not_preserved' `
        -Events @($regularV4FrontierRepairMissingRangePreservationProof.UnresolvedCandidateEvents) `
        -DefaultReason 'unresolved_frontier_repair_missing_range_omitted' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'regular_v4_frontier_repair_projection_reauthorization_missing_after_recovery' `
        -Events @($regularV4FrontierRepairProjectionReauthorizationProof.UnresolvedCandidateEvents) `
        -DefaultReason 'fresh_projection_required_before_unrestricted_state' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'post_tuna_fallback_paired_yield_bridge_recovery_generation_mismatch' `
        -Events @($fallbackTailProof.BridgeRecoveryGenerationMismatchCandidateEvents) `
        -DefaultReason 'bridge_recovery_generation_mismatch' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'post_tuna_fallback_paired_yield_transport_epoch_reauthorization_missing' `
        -Events @($fallbackTailProof.TransportEpochReauthorizationCandidateEvents | Where-Object {
            $_.EventName -ne 'filetransfer_fallback_tail_local_yield_blocked'
        }) `
        -DefaultReason 'retired_owner_cross_transport_epoch_suppression' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'post_tuna_fallback_paired_yield_transport_epoch_reauthorization_missing' `
        -Events @($fallbackTailProof.TransportEpochReauthorizationCandidateEvents | Where-Object {
            $_.EventName -eq 'filetransfer_fallback_tail_local_yield_blocked'
        }) `
        -DefaultReason 'local_yield_transport_epoch_reauthorization_missing' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_regular_v4_recovery_lease_not_issued' `
        -Events @($runtimeUnlockRegularV4RecoveryLeaseIssuanceProof.UnresolvedCandidateEvents) `
        -DefaultReason 'coordinator_recovery_liveness_lease_missing' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_regular_v4_recovery_lease_closure_not_adopted' `
        -Events @($runtimeUnlockRecoveryLeaseClosureNotAdoptedUnresolvedEvents) `
        -DefaultReason 'regular_v4_receive_recovery_pending' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_regular_v4_recovery_lease_closure_liveness_not_preserved' `
        -Events @($runtimeUnlockRegularV4RecoveryLeaseIssuanceProof.ClosureLivenessUnresolvedCandidateEvents) `
        -DefaultReason 'recovery_liveness_lease_missing' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_retry_regular_v4_recovery_lease_closure_hold_not_preserved' `
        -Events @($runtimeUnlockRegularV4RecoveryLeaseIssuanceProof.ClosureHoldNotPreservedUnresolvedCandidateEvents)
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_regular_v4_recovery_lease_closure_offer_timeout_handoff_missing' `
        -Events @($runtimeUnlockRegularV4RecoveryClosureOfferTimeoutHandoffProof.UnresolvedCandidateEvents) `
        -DefaultReason 'regular_v4_recovery_closure_window_join_missing' `
        -UseDefaultReason

    $grantBypassSequences = @(
        @($runtimeUnlockRetryDispatchGrantBypassedByRetryBudgetEvents) +
        @($runtimeUnlockRetryRegularV4SettlementHandoffBypassedCandidateEvents.ToArray()) |
            ForEach-Object { [int64]$_.Sequence }
    )
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_retry_dispatch_grant_bypassed_by_retry_budget' `
        -Events $runtimeUnlockRetryDispatchGrantBypassedByRetryBudgetEvents `
        -DefaultReason 'retry_dispatch_grant_bypassed_by_retry_budget' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_retry_dispatch_contract_unsettled' `
        -Events @($runtimeUnlockRetryDispatchUnsettledAuthorityEvents | Where-Object { [int64]$_.Sequence -notin $grantBypassSequences }) `
        -DefaultReason 'retry_dispatch_contract_unsettled' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_retry_dispatch_successor_missing_after_missing_dispatch' `
        -Events @($runtimeUnlockRetryDispatchSuccessorMissingAfterMissingDispatchEvents.ToArray()) `
        -DefaultReason 'retry_dispatch_successor_missing_after_missing_dispatch' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_retry_dispatch_authority_tuple_mismatch' `
        -Events $runtimeUnlockRetryDispatchAuthorityTupleMismatchClassificationEvents
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_retry_dispatch_held_after_authority_granted' `
        -Events @($runtimeUnlockRetryDispatchPostGrantHoldEvents) `
        -DefaultReason 'retry_dispatch_held_after_authority_granted' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_precommit_probe_start_handoff_missing' `
        -Events @($runtimeUnlockPreCommitProbeStartHandoffProof.UnresolvedCandidateEvents) `
        -DefaultReason 'runtime_unlock_probe_start_timeout' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'runtime_unlock_retry_dispatch_missing_after_authority_granted' `
        -Events $runtimeUnlockRetryDispatchUnsettledMissingAfterAuthorityGrantedEvents

    if ($runtimeUnlockRetryRegularV4SettlementHandoffBypassedCount -gt 0) {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class 'runtime_unlock_retry_regular_v4_settlement_handoff_bypassed' `
            -Events @($runtimeUnlockRetryRegularV4SettlementHandoffBypassedCandidateEvents.ToArray()) `
            -DefaultReason 'regular_v4_recovery_settlement_handoff_bypassed' `
            -UseDefaultReason
    }

    if ($runtimeUnlockRetryRegularV4RecoverySettlementMissingCount -gt 0) {
        [object[]]$runtimeUnlockRetryRegularV4RecoverySettlementMissingFirstEdgeEvents = @(
            $runtimeUnlockRetryRegularV4RecoverySettlementMissingCandidateEvents.ToArray() |
                Where-Object {
                    Test-FileTransferRuntimeUnlockRecoverySettlementMissingFirstEdgeEligible `
                        -MissingEvent $_ `
                        -SettlementEvents $events `
                        -DispositionGapEvents $regularV4FrontierRepairSettlementDispositionUnverifiableEvents
                })
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class 'runtime_unlock_retry_regular_v4_recovery_settlement_missing' `
            -Events $runtimeUnlockRetryRegularV4RecoverySettlementMissingFirstEdgeEvents `
            -DefaultReason 'regular_v4_recovery_settlement_handoff_unconsumed_at_exhaustion' `
            -UseDefaultReason
    }
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'regular_v4_recovery_predecessor_settlement_closed_successor' `
        -Events $regularV4RecoveryPredecessorSettlementClosedSuccessorEvents `
        -DefaultReason 'predecessor_settlement_closed_successor' `
        -UseDefaultReason
    if ($regularV4ReceiveRecoveryRejectedBeforeRuntimeUnlock) {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class 'regular_v4_receive_recovery_rejected_before_runtime_unlock' `
            -Events $runtimeUnlockRetryRejectedAfterRegularV4RecoveryEvents
    }
    if ($regularV4FrontierRepairSettlementDispositionUnverifiableEvents.Count -gt 0) {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class 'regular_v4_frontier_repair_settlement_disposition_unverifiable' `
            -Events $regularV4FrontierRepairSettlementDispositionUnverifiableEvents `
            -DefaultReason 'accepted_settlement_disposition_evidence_missing' `
            -UseDefaultReason
    }
    if ($regularV4FrontierRepairPressureAuthorityLifecycleSplitProof.UnresolvedCount -gt 0) {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class 'regular_v4_frontier_repair_pressure_authority_lifecycle_split' `
            -Events $regularV4FrontierRepairPressureAuthorityLifecycleSplitProof.UnresolvedCandidateEvents `
            -DefaultReason 'coordinator_repair_authority_outlived_legacy_pressure_ttl' `
            -UseDefaultReason
    }
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'regular_v4_frontier_repair_pressure_recovery_handoff_missing' `
        -Events @($regularV4FrontierRepairPressureRecoveryHandoffProof.UnresolvedCandidateEvents) `
        -DefaultReason 'installed_repair_pressure_not_retired_before_receive_recovery' `
        -UseDefaultReason
    if (-not $regularV4ReceiveRecoveryRejectedBeforeRuntimeUnlock -and
        $regularV4FrontierRepairSendDeferred) {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class 'regular_v4_frontier_repair_send_deferred_or_stalled' `
            -Events @($regularV4FrontierRepairUnresolvedSendDeferredEvents + $regularV4FrontierRepairUnresolvedMissingDispatchEvents)
    }
    elseif (-not $regularV4ReceiveRecoveryRejectedBeforeRuntimeUnlock -and
        $regularV4FrontierRepairStalled) {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class 'regular_v4_frontier_repair_stalled' `
            -Events @($regularV4FrontierRepairUnresolvedStalledEvents + $regularV4FrontierRepairSettlementDispositionUnverifiableEvents)
    }

    if ($publicationAuthorityFieldCoverageProof.Verdict -eq 'fail') {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class 'publication_authority_missing' `
            -Events $publicationAuthorityFieldCoverageProof.EvidenceEvents `
            -DefaultReason 'publication_authority_missing' `
            -UseDefaultReason
    }
    foreach ($candidateRecord in @($runtimeUnlockRegularV4RouteCommitSendDrainProof.UnresolvedCandidateRecords)) {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class 'runtime_unlock_regular_v4_route_commit_send_drain_missing' `
            -Events @($candidateRecord.Event) `
            -DefaultReason ([string]$candidateRecord.Reason) `
            -UseDefaultReason
    }
    if ($fileTunaV4DataPathProof.Verdict -eq 'fail') {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class 'file_tuna_data_path_mismatch' `
            -Events $fileTunaV4DataPathProof.EvidenceEvents `
            -DefaultReason 'file_tuna_data_path_mismatch' `
            -UseDefaultReason
    }
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'active_file_tuna_v6_evidence' `
        -Events $fileTunaV6Events `
        -DefaultReason 'active_file_tuna_v6_evidence' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'tuna_path_lease_unavailable_at_answer' `
        -Events @($runtimeUnlockAnswerRejectedTunaPathLeaseUnavailableEvents + $runtimeUnlockTunaPathLeaseRouteCommitRejectedEvents)

    $runtimeOwnerInvariant = Get-FileTransferInvariantRuntimeOwnerResult -Summary $Summary
    if ($runtimeOwnerInvariant.Verdict -eq 'fail') {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class $runtimeOwnerInvariant.FailureClass `
            -Events $runtimeOwnerInvariant.EvidenceEvents `
            -DefaultReason $runtimeOwnerInvariant.FailureClass `
            -UseDefaultReason
    }
    $routeLawInvariant = Get-FileTransferInvariantRouteLawResult -Summary $Summary
    if ($routeLawInvariant.Verdict -eq 'fail') {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class $routeLawInvariant.FailureClass `
            -Events $routeLawInvariant.EvidenceEvents `
            -DefaultReason $routeLawInvariant.FailureClass `
            -UseDefaultReason
    }
    $controlPriorityInvariant = Get-FileTransferInvariantControlPriorityResult -Summary $Summary
    if ($controlPriorityInvariant.Verdict -eq 'fail') {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class $controlPriorityInvariant.FailureClass `
            -Events $controlPriorityInvariant.EvidenceEvents `
            -DefaultReason $controlPriorityInvariant.FailureClass `
            -UseDefaultReason
    }
    if ($terminalLifecycleInvariant.Verdict -eq 'fail') {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class $terminalLifecycleInvariant.FailureClass `
            -Events $terminalLifecycleInvariant.EvidenceEvents `
            -DefaultReason $terminalLifecycleInvariant.FailureClass `
            -UseDefaultReason
    }
    if ($staleRejectedActionEffectProof.Verdict -eq 'fail') {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class $staleRejectedActionEffectProof.FailureClass `
            -Events $staleRejectedActionEffectProof.FailureEvents `
            -DefaultReason $staleRejectedActionEffectProof.FailureClass `
            -UseDefaultReason
    }
    if ($fallbackRuntimeUnlockSeparationProof.Verdict -eq 'fail' -and $hasFallbackRouteOrOwnerEvidence) {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class $fallbackRuntimeUnlockSeparationProof.FailureClass `
            -Events $fallbackRuntimeUnlockSeparationProof.FailureEvents `
            -DefaultReason $fallbackRuntimeUnlockSeparationProof.FailureClass `
            -UseDefaultReason
    }

    # Fallback symptoms are proof-chain candidates only after the retained slice
    # contains an actual fallback route or fallback-owner tuple. This prevents a
    # route-less downstream diagnostic from manufacturing fallback authority.
    if ($hasFallbackRouteOrOwnerEvidence) {
        $fallbackFailureClass = if ($fallbackTailProof.TransportEpochReauthorizationUnresolvedCount -gt 0) {
            # The cross-epoch suppression is the precise authority edge. One-sided
            # yield/quiescence symptoms in the retired scope are downstream.
            ''
        }
        elseif ($fallbackTailProof.YieldAuthorityRejectedCount -gt 0) {
            'fallback_tail_yield_authority_invalid'
        }
        elseif ($fallbackTailProof.OtherOwnerGenerationMismatchCount -gt 0) {
            'fallback_tail_owner_generation_mismatch'
        }
        elseif ($fallbackTailProof.FrontierRequestDispatchVerdict -eq 'fail') {
            'fallback_frontier_request_dispatch_missing'
        }
        elseif ($fallbackTailProof.FrontierRepairVerdict -eq 'fail') {
            'fallback_frontier_repair_stalled'
        }
        elseif ($fallbackTailProof.ProofReplayLocalYieldBlockedCount -gt 0 -and $fallbackTailProof.PairedYieldVerdict -eq 'fail') {
            'post_fallback_frontier_replay_unsettled'
        }
        elseif ($fallbackTailProof.LocalYieldBlockedCount -gt 0 -and $fallbackTailProof.PairedYieldVerdict -eq 'fail') {
            'fallback_tail_local_yield_missing'
        }
        elseif ($fallbackTailProof.QuiescenceVerdict -eq 'fail' -and
            $fallbackTailProof.BridgeRecoveryGenerationMismatchUnresolvedCount -eq 0) {
            'fallback_tail_quiescence_missing'
        }
        elseif ($fallbackTailProof.Verdict -eq 'fail') {
            'fallback_tail_reconciliation'
        }
        else {
            ''
        }
        if (-not [string]::IsNullOrWhiteSpace($fallbackFailureClass)) {
            [object[]]$fallbackFailureEvents = @(
                switch ($fallbackFailureClass) {
                    'fallback_tail_yield_authority_invalid' {
                        @($fallbackTailProof.YieldAuthorityRejectedEvents)
                        break
                    }
                    'fallback_tail_owner_generation_mismatch' {
                        @($fallbackTailProof.OtherOwnerGenerationMismatchEvents)
                        break
                    }
                    'fallback_frontier_request_dispatch_missing' {
                        @($fallbackTailProof.FrontierRequestDispatchMissingEvents)
                        break
                    }
                    'fallback_frontier_repair_stalled' {
                        @($fallbackTailProof.FrontierRepairUnresolvedStalledEvents)
                        break
                    }
                    default {
                        @(
                            $fallbackTailProof.QuiescenceEvidenceEvents |
                                Where-Object {
                                    $_.EventName -ne 'filetransfer_route_selected' -and
                                    $_.EventName -notlike 'filetransfer_fallback_leg_authority_started'
                                }
                        )
                    }
                }
            )
            if ($fallbackFailureEvents.Count -eq 0) {
                $fallbackFailureEvents = @($fallbackTailProof.EvidenceEvents | Where-Object { $_.EventName -ne 'filetransfer_route_selected' })
            }
            Add-FileTransferProofChainFailureCandidates `
                -Candidates $proofChainFailureCandidates `
                -Class $fallbackFailureClass `
                -Events $fallbackFailureEvents `
                -DefaultReason $fallbackFailureClass `
                -UseDefaultReason
        }
    }

    $firstProofChainFailure = @(
        $proofChainFailureCandidates |
            Sort-Object Sequence, LineNumber, Class, Event |
            Select-Object -First 1
    )
    if ($firstProofChainFailure.Count -eq 0) {
        $firstProofChainFailure = $null
    }
    else {
        $firstProofChainFailure = $firstProofChainFailure[0]
    }

    $class = '(none)'
    if ($null -ne $firstProofChainFailure) {
        # A retained, explicit proof-chain rejection owns classification before
        # aggregate symptoms (for example, later fallback or liveness failures).
        $class = $firstProofChainFailure.Class
    }
    elseif ($runtimeUnlockFileTransferOwnerMissingBeforePathLeaseUnresolvedEvents.Count -gt 0) {
        $class = 'runtime_unlock_filetransfer_owner_missing_before_path_lease'
    }
    elseif ($runtimeUnlockFileTransferOwnerStaleBeforeOfferDispatchUnresolvedEvents.Count -gt 0) {
        $class = 'runtime_unlock_filetransfer_owner_stale_before_offer_dispatch'
    }
    elseif ($runtimeUnlockRetrySourcePublicationMismatchEvents.Count -gt 0) {
        $class = 'runtime_unlock_retry_source_publication_mismatch'
    }
    elseif ($runtimeUnlockRetryDispatchSettlementAcceptanceMissingEvents.Count -gt 0) {
        $class = 'runtime_unlock_retry_dispatch_settlement_unaccepted'
    }
    elseif ($runtimeUnlockRetryDispatchIncompleteBoundedClosureEvents.Count -gt 0) {
        $class = 'runtime_unlock_retry_dispatch_chain_closure_incomplete'
    }
    elseif ($runtimeUnlockRetryDispatchInvalidFreshGrantEvents.Count -gt 0) {
        $class = 'runtime_unlock_retry_dispatch_fresh_chain_invalid_after_closure'
    }
    elseif ($runtimeUnlockRetryDispatchGrantBypassedByRetryBudgetEvents.Count -gt 0) {
        $class = 'runtime_unlock_retry_dispatch_grant_bypassed_by_retry_budget'
    }
    elseif ($runtimeUnlockRetryDispatchUnsettledAuthorityEvents.Count -gt 0) {
        $class = 'runtime_unlock_retry_dispatch_contract_unsettled'
    }
    elseif ($runtimeUnlockRetryDispatchSuccessorMissingAfterMissingDispatchCount -gt 0) {
        $class = 'runtime_unlock_retry_dispatch_successor_missing_after_missing_dispatch'
    }
    elseif ($runtimeUnlockRegularV4RecoveryClosureOfferTimeoutHandoffProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_regular_v4_recovery_lease_closure_offer_timeout_handoff_missing'
    }
    elseif ($regularV4PeerSilenceReplayMissingDispatchRangeProof.UnresolvedCount -gt 0) {
        $class = 'regular_v4_peer_silence_replay_missing_dispatch_range_not_preserved'
    }
    elseif ($regularV4FrontierRepairInitialPressureInstallProof.UnresolvedCount -gt 0) {
        $class = 'regular_v4_frontier_repair_initial_pressure_install_missing'
    }
    elseif ($regularV4FrontierRepairSuccessorPressureInstallProof.UnresolvedCount -gt 0) {
        $class = 'regular_v4_frontier_repair_successor_pressure_install_missing'
    }
    elseif ($runtimeUnlockRetryDispatchAuthorityTupleMismatchClassificationEvents.Count -gt 0) {
        $class = 'runtime_unlock_retry_dispatch_authority_tuple_mismatch'
    }
    elseif ($publicationAuthorityFieldCoverageProof.Verdict -eq 'fail') {
        $class = 'publication_authority_missing'
    }
    elseif ($runtimeUnlockRegularV4RouteCommitSendDrainProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_regular_v4_route_commit_send_drain_missing'
    }
    elseif ($fileTunaV4DataPathProof.Verdict -eq 'fail') {
        $class = 'file_tuna_data_path_mismatch'
    }
    elseif ($runtimeUnlockRetryDispatchPostGrantHoldProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_retry_dispatch_held_after_authority_granted'
    }
    elseif ($runtimeUnlockPreCommitProbeStartHandoffProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_precommit_probe_start_handoff_missing'
    }
    elseif ($runtimeUnlockRetryDispatchMissingAfterAuthorityGrantedCount -gt 0) {
        $class = 'runtime_unlock_retry_dispatch_missing_after_authority_granted'
    }
    elseif ($runtimeUnlockRecoveryLeaseClosureNotAdoptedUnresolvedCount -gt 0) {
        $class = 'runtime_unlock_regular_v4_recovery_lease_closure_not_adopted'
    }
    elseif ($runtimeUnlockRegularV4RecoveryLeaseIssuanceProof.ClosureLivenessUnresolvedCount -gt 0) {
        $class = 'runtime_unlock_regular_v4_recovery_lease_closure_liveness_not_preserved'
    }
    elseif ($runtimeUnlockRegularV4RecoveryLeaseIssuanceProof.ClosureHoldNotPreservedUnresolvedCount -gt 0) {
        $class = 'runtime_unlock_retry_regular_v4_recovery_lease_closure_hold_not_preserved'
    }
    elseif ($runtimeUnlockRetryRegularV4SettlementHandoffBypassedCount -gt 0) {
        $class = 'runtime_unlock_retry_regular_v4_settlement_handoff_bypassed'
    }
    elseif ($runtimeUnlockRetryDispatchProofVerdict -eq 'fail') {
        $class = 'runtime_unlock_retry_dispatch_missing'
    }
    elseif ($regularV4RecoveryPredecessorSettlementClosedSuccessorEvents.Count -gt 0) {
        $class = 'regular_v4_recovery_predecessor_settlement_closed_successor'
    }
    elseif ($regularV4ReceiveRecoveryRejectedBeforeRuntimeUnlock) {
        $class = 'regular_v4_receive_recovery_rejected_before_runtime_unlock'
    }
    elseif ($regularV4FrontierRepairSettlementDispositionUnverifiableEvents.Count -gt 0) {
        $class = 'regular_v4_frontier_repair_settlement_disposition_unverifiable'
    }
    elseif ($runtimeUnlockRetryRegularV4RecoverySettlementMissingCount -gt 0) {
        $class = 'runtime_unlock_retry_regular_v4_recovery_settlement_missing'
    }
    elseif ($runtimeUnlockUncommittedTunaFallbackProofAuthorityProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_uncommitted_tuna_fallback_proof_authority_missing'
    }
    elseif ($runtimeUnlockUncommittedTunaFallbackHandoffSuppressionProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_precommit_fallback_recovery_handoff_suppressed'
    }
    elseif ($runtimeUnlockUncommittedTunaFallbackPrecommitAuthorityProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_uncommitted_tuna_fallback_handoff_precommit_authority_misbound'
    }
    elseif ($runtimeUnlockPostTunaFallbackTransportProofHandoffProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_post_tuna_fallback_transport_proof_handoff_missing'
    }
    elseif ($regularV4FrontierRepairSendDeferred) {
        $class = 'regular_v4_frontier_repair_send_deferred_or_stalled'
    }
    elseif ($regularV4FrontierRepairStalled) {
        $class = 'regular_v4_frontier_repair_stalled'
    }
    elseif ($regularV4RepairLivenessAuthorityMissing) {
        $class = 'regular_v4_repair_liveness_authority_missing'
    }
    elseif ($staleRejectedActionEffectProof.Verdict -eq 'fail') {
        $class = 'stale_rejected_action_effect'
    }
    elseif ($fallbackRuntimeUnlockSeparationProof.FallbackUnavailableWithoutCoordinatorDenialCount -gt 0) {
        $class = 'stale_rejected_action_effect'
    }
    elseif ($fileTunaV6Events.Count -gt 0) {
        $class = 'active_file_tuna_v6_evidence'
    }
    elseif ($fallbackTailProof.YieldAuthorityRejectedCount -gt 0 -and
        $hasPostTunaFallbackEvidence) {
        $class = 'fallback_tail_yield_authority_invalid'
    }
    elseif ($fallbackTailProof.OtherOwnerGenerationMismatchCount -gt 0 -and
        $hasPostTunaFallbackEvidence) {
        $class = 'fallback_tail_owner_generation_mismatch'
    }
    elseif ($fallbackTailProof.FrontierRequestDispatchVerdict -eq 'fail' -and
        $hasPostTunaFallbackEvidence) {
        $class = 'fallback_frontier_request_dispatch_missing'
    }
    elseif ($fallbackTailProof.FrontierRepairVerdict -eq 'fail' -and
        $hasPostTunaFallbackEvidence) {
        $class = 'fallback_frontier_repair_stalled'
    }
    elseif ($fallbackTailProof.ProofReplayLocalYieldBlockedCount -gt 0 -and
        $fallbackTailProof.PairedYieldVerdict -eq 'fail' -and
        $hasPostTunaFallbackEvidence) {
        $class = 'post_fallback_frontier_replay_unsettled'
    }
    elseif ($fallbackTailProof.LocalYieldBlockedCount -gt 0 -and
        $fallbackTailProof.PairedYieldVerdict -eq 'fail' -and
        $hasPostTunaFallbackEvidence) {
        $class = 'fallback_tail_local_yield_missing'
    }
    elseif ($fallbackTailProof.PairedYieldVerdict -eq 'fail' -and
        $fallbackTailProof.RuntimeUnlockProbeRejectedByInboundFallbackOwnerCount -gt 0 -and
        $hasPostTunaFallbackEvidence) {
        $class = 'runtime_unlock_probe_rejected_by_inbound_fallback_owner'
    }
    elseif ($fallbackTailProof.PairedYieldVerdict -eq 'fail' -and
        $fallbackTailProof.QuiescentYieldGrantedCount -gt 0 -and
        $hasPostTunaFallbackEvidence) {
        $class = 'paired_fallback_tail_yield_missing'
    }
    elseif ($fallbackTailProof.QuiescenceVerdict -eq 'fail' -and
        $hasPostTunaFallbackEvidence) {
        $class = 'fallback_tail_quiescence_missing'
    }
    elseif ($fallbackRuntimeUnlockSeparationProof.Verdict -eq 'fail' -and
        $hasPostTunaFallbackEvidence) {
        $class = if ($fallbackRuntimeUnlockSeparationProof.FallbackUnavailableWithoutCoordinatorDenialCount -gt 0) {
            'stale_rejected_action_effect'
        }
        else {
            'runtime_fallback_separation_violation'
        }
    }
    elseif ($fallbackTailProof.Verdict -eq 'fail' -and
        $hasPostTunaFallbackEvidence) {
        $class = 'fallback_tail_reconciliation'
    }
    elseif ($postFallbackRuntimeUnlockResumeBlocked) {
        $class = if ($runtimeUnlockFallbackProofReplayPendingAfterPairedYieldUnresolvedEvents.Count -gt 0) {
            'fallback_proof_replay_pending_after_paired_yield'
        } else {
            'post_fallback_runtime_unlock_resume_blocked'
        }
    }
    elseif (($controlPlaneProof.StaleReplayTreadmillCount -gt $controlPlaneProof.StaleGenerationTreadmillScoreLimit -or
            $controlPlaneProof.CheckpointOwnerViolationCount -gt 0 -or
            $controlPlaneProof.ControlPlaneNonCurrentLegGenerationSendCount -gt 0) -and
        $hasPostTunaFallbackEvidence) {
        $class = 'fallback_control_plane_stale_generation_treadmill'
    }
    elseif ($hasPostTunaFallbackEvidence -and
        (
            $postTunaFallbackBulkActiveSuppressedDuringPressureEvents.Count -gt 0 -or
            (
                $postTunaFallbackControlPlanePressureMarkedEvents.Count -gt 0 -and
                $postTunaFallbackControlPlanePressureAllowedEvents.Count -eq 0 -and
                ($sessionLivenessTimeoutEvents.Count -gt 0 -or $peerDisconnectedTerminalEvents.Count -gt 0)
            ) -or
            (
                $postTunaFallbackLegacyControlLaneStarvationEvents.Count -gt 32 -and
                @($events | Where-Object {
                    $_.EventName -eq 'nkn_bridge_control_receive_recovery_suppressed' -and
                    (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -in @('bulk_receive_active', 'filetransfer_bulk_receive_active')
                }).Count -gt 0
            )
        )) {
        $class = 'fallback_control_lane_starvation_under_bulk_receive'
    }
    elseif ($controlPlaneProof.Verdict -eq 'fail' -and
        $hasPostTunaFallbackEvidence -and
        ($sessionLivenessTimeoutEvents.Count -gt 0 -or $peerDisconnectedTerminalEvents.Count -gt 0)) {
        $class = 'fallback_control_plane_starvation'
    }
    elseif ($runtimeUnlockAnswerRejectedTunaPathLeaseUnavailableEvents.Count -gt 0 -or
        $runtimeUnlockTunaPathLeaseRouteCommitRejectedEvents.Count -gt 0) {
        $class = 'tuna_path_lease_unavailable_at_answer'
    }
    elseif ($runtimeUnlockPreCommitProbeAckMissingCount -gt 0) {
        $class = 'runtime_unlock_precommit_probe_ack_missing'
    }
    elseif ($runtimeUnlockTransactionCommittedEvents.Count -gt 0 -and
        -not $runtimeUnlockHasPreCommitAckProof) {
        $class = 'runtime_unlock_route_commit_before_probe'
    }
    elseif ($runtimeUnlockProbeStartedEvents.Count -gt 0 -and
        $runtimeUnlockPreCommitProbeStartedEvents.Count -eq 0 -and
        $runtimeUnlockPreCommitProbeProtocolMismatchEvents.Count -gt 0 -and
        -not $runtimeUnlockHasPreCommitAckProof) {
        $class = 'runtime_unlock_precommit_probe_protocol_mismatch'
    }
    elseif ($runtimeUnlockTransactionPeerProofEvents.Count -gt 0 -and
        $runtimeUnlockPreCommitProbeStartedEvents.Count -gt 0 -and
        $runtimeUnlockTunaProbeSentEvents.Count -gt 0 -and
        $runtimeUnlockTunaProbeReceivedEvents.Count -eq 0 -and
        $runtimeUnlockTunaProbeAckReceivedEvents.Count -eq 0 -and
        $runtimeUnlockTunaProbeSidecarFailureEvents.Count -gt 0 -and
        $routeChanges.Count -eq 1 -and
        $routeChanges[0] -eq 'regular_nkn_v4_fast' -and
        $runtimeUnlockTransactionCommittedEvents.Count -eq 0 -and
        ($cleanRegularV4TerminalEvents.Count -gt 0 -or
         $regularV4TerminalBeforeActivationEvents.Count -gt 0)) {
        $class = 'runtime_unlock_tuna_probe_sidecar_closed_regular_v4_terminal'
    }
    elseif ($runtimeUnlockListenerRearmAfterProbeCloseFailedEvents.Count -gt 0 -and
        $runtimeUnlockTunaProbeSidecarFailureEvents.Count -gt 0) {
        $class = 'runtime_unlock_tuna_listener_unavailable_after_probe_close'
    }
    elseif ($runtimeUnlockTransactionPeerProofEvents.Count -gt 0 -and
        $runtimeUnlockPreCommitProbeStartedEvents.Count -gt 0 -and
        $runtimeUnlockTunaProbeSentEvents.Count -gt 0 -and
        $runtimeUnlockTunaProbeReceivedEvents.Count -eq 0 -and
        $runtimeUnlockTunaProbeAckReceivedEvents.Count -eq 0 -and
        ($runtimeUnlockTunaProbeSidecarFailureEvents.Count -gt 0 -or
         $runtimeUnlockPreCommitProbeFailedEvents.Count -gt 0 -or
         $runtimeUnlockProbeFailedEvents.Count -gt 0)) {
        $class = 'runtime_unlock_tuna_probe_path_not_established'
    }
    elseif ($runtimeUnlockTransactionPeerProofEvents.Count -gt 0 -and
        -not $runtimeUnlockHasPreCommitAckProof -and
        ($runtimeUnlockProbeMissingRejectedEvents.Count -gt 0 -or
         $sessionLivenessTimeoutEvents.Count -gt 0 -or
         $peerDisconnectedTerminalEvents.Count -gt 0)) {
        $class = 'runtime_unlock_offer_answer_without_probe'
    }
    elseif ($fallbackRuntimeUnlockSeparationProof.Verdict -eq 'fail' -and
        $routeChanges -contains 'post_tuna_fallback_v6') {
        $class = if ($fallbackRuntimeUnlockSeparationProof.FallbackUnavailableWithoutCoordinatorDenialCount -gt 0) {
            'stale_rejected_action_effect'
        }
        else {
            'runtime_fallback_separation_violation'
        }
    }
    elseif ($runtimeUnlockProbeInvalidRejectedEvents.Count -gt 0 -or
        $runtimeUnlockProbeFailedEvents.Count -gt 0) {
        $class = 'runtime_unlock_probe_failed'
    }
    elseif ($runtimeUnlockRegularV4PeerVisibleWindowDeliveryStartedEvents.Count -gt 0 -and
        $runtimeUnlockRegularV4ActivationWindowPeerVisibleEvents.Count -eq 0 -and
        ($runtimeUnlockRegularV4PeerVisibleWindowDeliveryFailedEvents.Count -gt 0 -or
         $runtimeUnlockRegularV4ActivationWindowFailedEvents.Count -gt 0) -and
        $routeChanges.Count -eq 1 -and
        $routeChanges[0] -eq 'regular_nkn_v4_fast' -and
        $runtimeUnlockTransactionCommittedEvents.Count -eq 0) {
        $class = 'runtime_unlock_regular_v4_peer_visible_window_delivery_failed'
    }
    elseif ($runtimeUnlockRegularV4ActivationWindowStartedEvents.Count -gt 0 -and
        $runtimeUnlockTransactionObservedSendEvents.Count -gt 0 -and
        $runtimeUnlockRegularV4ActivationWindowPeerVisibleEvents.Count -eq 0 -and
        ($runtimeUnlockRegularV4ActivationWindowFailedEvents.Count -gt 0 -or
         $runtimeUnlockRegularV4PeerVisibleWindowLateProofIgnoredEvents.Count -gt 0) -and
        $routeChanges.Count -eq 1 -and
        $routeChanges[0] -eq 'regular_nkn_v4_fast' -and
        $runtimeUnlockTransactionCommittedEvents.Count -eq 0) {
        $class = 'runtime_unlock_peer_visible_window_race'
    }
    elseif (($runtimeUnlockRegularV4ActivationWindowFailedEvents.Count -gt 0 -or
            $runtimeUnlockDispatchDeferredForRegularV4RecoveryEvents.Count -gt 0 -or
            (
                $runtimeUnlockBrokenStateRetrySuppressedEvents.Count -gt 0 -and
                $regularV4FrontierStallMissingRangeEvents.Count -gt 0
            )) -and
        $routeChanges.Count -eq 1 -and
        $routeChanges[0] -eq 'regular_nkn_v4_fast' -and
        $runtimeUnlockTransactionCommittedEvents.Count -eq 0 -and
        -not $runtimeUnlockHasPreCommitAckProof -and
        ($sessionLivenessTimeoutEvents.Count -gt 0 -or
         $peerDisconnectedTerminalEvents.Count -gt 0 -or
         $runtimeUnlockTransactionFailedEvents.Count -gt 0)) {
        $class = 'runtime_unlock_regular_v4_recovery_arbitration'
    }
    elseif ($runtimeUnlockBrokenStateRetrySuppressedEvents.Count -gt 0 -or
        $runtimeUnlockBrokenStateTransactionFailedEvents.Count -gt 0 -or
        ($runtimeUnlockBrokenStateFreshRetryConsumedEvents.Count -gt 0 -and
         $runtimeUnlockOfferNotObservedEvents.Count -gt 1 -and
         $runtimeUnlockTransactionPeerProofEvents.Count -eq 0)) {
        $class = 'runtime_unlock_broken_state_retry_churn'
    }
    elseif ($runtimeUnlockTransactionObservedSendEvents.Count -gt 0 -and
        $runtimeUnlockTransactionPeerProofEvents.Count -eq 0 -and
        ($runtimeUnlockTransactionLocalOnlyRejectedEvents.Count -gt 0 -or $sessionLivenessTimeoutEvents.Count -gt 0)) {
        $class = 'runtime_unlock_transaction_local_only'
    }
    elseif ($runtimeUnlockTransactionCommitPendingEvents.Count -gt $runtimeUnlockTransactionCommittedEvents.Count -and
        ($sessionLivenessTimeoutEvents.Count -gt 0 -or $runtimeUnlockTransactionFailedEvents.Count -gt 0)) {
        $class = 'runtime_unlock_transaction_commit_missing'
    }
    elseif ($runtimeUnlockOfferNotObservedEvents.Count -gt 0 -and
        $sessionRecoveryContractRetryDispatchedEvents.Count -gt 0 -and
        $sessionRecoveryContractRetryAuthorityObservedEvents.Count -gt 0 -and
        $sessionLivenessTimeoutEvents.Count -eq 0 -and
        $peerDisconnectedTerminalEvents.Count -eq 0) {
        $class = '(none)'
    }
    elseif ($runtimeUnlockOfferNotObservedEvents.Count -gt 0 -and
        $runtimeUnlockOfferPeerResponseTimeoutEvents.Count -gt 0 -and
        $sessionRecoveryContractRetryDispatchedEvents.Count -gt 0 -and
        $sessionRecoveryContractRetryAuthorityObservedEvents.Count -gt 0 -and
        $runtimeUnlockCutThroughPeerReceivedEvents.Count -eq 0 -and
        $sessionLivenessTimeoutEvents.Count -gt 0 -and
        $peerDisconnectedTerminalEvents.Count -gt 0 -and
        $routeChanges.Count -eq 1 -and
        $routeChanges[0] -eq 'regular_nkn_v4_fast') {
        $class = 'runtime_unlock_peer_response_not_received_under_regular_v4_recovery'
    }
    elseif ($runtimeUnlockOfferNotObservedEvents.Count -gt 0 -and
        $sessionRecoveryContractRetryDispatchedEvents.Count -gt 0 -and
        ($runtimeUnlockOfferRejectedWithoutObservationEvents.Count -gt 0 -or $runtimeUnlockReceiveRecoveryBlockedOfferEvents.Count -gt 0) -and
        $sessionLivenessTimeoutEvents.Count -gt 0 -and
        $peerDisconnectedTerminalEvents.Count -gt 0 -and
        $routeChanges.Count -eq 1 -and
        $routeChanges[0] -eq 'regular_nkn_v4_fast') {
        $class = 'runtime_unlock_offer_observation_blocked_by_receive_recovery'
    }
    elseif ($runtimeUnlockDispatchDeferredForRegularV4RecoveryEvents.Count -gt 0 -and
        $sessionLivenessTimeoutEvents.Count -gt 0 -and
        $peerDisconnectedTerminalEvents.Count -gt 0 -and
        $routeChanges.Count -eq 1 -and
        $routeChanges[0] -eq 'regular_nkn_v4_fast') {
        $class = 'runtime_unlock_dispatch_deferred_by_regular_v4_receive_recovery'
    }
    elseif ($runtimeUnlockOfferNotObservedEvents.Count -gt 0 -and
        $listenerRearmRequiredEvents.Count -gt 0 -and
        $listenerRearmCompletedEvents.Count -eq 0 -and
        ($listenerRearmFailedEvents.Count -gt 0 -or $listenerReadyUnavailableContradictionEvents.Count -gt 0) -and
        ($sessionLivenessTimeoutEvents.Count -gt 0 -or $peerDisconnectedTerminalEvents.Count -gt 0)) {
        $class = 'tuna_listener_rearm_coordination'
    }
    elseif ($runtimeUnlockOfferNotObservedEvents.Count -gt 0 -and
        $runtimeUnlockRetryScheduledEvents.Count -gt 0 -and
        $runtimeUnlockRetryQueuedBehindActiveNegotiationEvents.Count -gt 0 -and
        $sessionLivenessTimeoutEvents.Count -gt 0 -and
        $peerDisconnectedTerminalEvents.Count -gt 0 -and
        $routeChanges.Count -eq 1 -and
        $routeChanges[0] -eq 'regular_nkn_v4_fast') {
        $class = 'runtime_unlock_recovery_coordination'
    }
    elseif ($runtimeUnlockOfferNotObservedEvents.Count -gt 0 -and $sessionLivenessTimeoutEvents.Count -gt 0) {
        $class = 'runtime_unlock_liveness_timeout'
    }
    elseif ($runtimeUnlockOfferNotObservedEvents.Count -gt 0) {
        $class = 'runtime_unlock_offer_not_observed'
    }
    elseif ($sessionLivenessTimeoutEvents.Count -gt 0) {
        $class = 'session_liveness_timeout'
    }

    $regularV4EfficiencyPressureClass = if ($routeChanges.Count -eq 1 -and
        $routeChanges[0] -eq 'regular_nkn_v4_fast' -and
        (
            $regularV4FrontierRebindEvents.Count -gt 3 -or
            ($regularV4FrontierRebindEvents.Count -gt 0 -and $regularV4RepairSkippedNotYetSentEvents.Count -gt 0) -or
            (
                $regularV4FrontierRebindEvents.Count -gt 0 -and
                $regularV4FrontierStallMissingRangeEvents.Count -gt 0 -and
                ($regularV4RepairRequestedEvents.Count -gt 0 -or $regularV4RepairCachePressureEvents.Count -gt 0)
            )
        )) {
        'regular_v4_recovery_rewind_treadmill'
    }
    else {
        '(none)'
    }

    $runtimeUnlockHasMakeBeforeBreakEvidence =
        $runtimeUnlockTransactionStartedEvents.Count -gt 0 -or
        $runtimeUnlockPreCommitRouteEpochRecoveredEvents.Count -gt 0
    $runtimeUnlockHasMakeBeforeBreakInvalidEvidence =
        $runtimeUnlockProbeInvalidRejectedEvents.Count -gt 0 -or
        $runtimeUnlockProbeMissingRejectedEvents.Count -gt 0 -or
        $runtimeUnlockProbeFailedEvents.Count -gt 0 -or
        $runtimeUnlockPreCommitProbeFailedEvents.Count -gt 0
    $runtimeUnlockProbeCommitVerdict = if ($runtimeUnlockPreCommitProbeStartedEvents.Count -eq 0 -and
        $runtimeUnlockPairedCommitStartedEvents.Count -eq 0) {
        'none'
    } elseif ($runtimeUnlockPreCommitProbeAckMissingCount -gt 0) {
        'fail'
    } elseif ($runtimeUnlockPairedCommitConfirmedEvents.Count -gt 0 -and
        $runtimeUnlockPreCommitRouteEpochRecoveredEvents.Count -gt 0 -and
        $runtimeUnlockPairedCommitAbortedEvents.Count -eq 0) {
        'pass'
    } else {
        'fail'
    }

    $runtimeUnlockRegularV4RecoveryArbitrationVerdict = if ($runtimeUnlockRegularV4ActivationWindowStartedEvents.Count -eq 0 -and
        $runtimeUnlockDispatchDeferredForRegularV4RecoveryEvents.Count -eq 0) {
        'none'
    } elseif ($runtimeUnlockRegularV4ActivationWindowPeerVisibleEvents.Count -gt 0 -and
        $runtimeUnlockRegularV4ActivationWindowFailedEvents.Count -eq 0) {
        'pass'
    } else {
        'fail'
    }

    [pscustomobject]@{
        Class = $class
        FirstProofChainFailureClass = if ($null -ne $firstProofChainFailure) { $firstProofChainFailure.Class } else { '(none)' }
        FirstProofChainFailureEvent = if ($null -ne $firstProofChainFailure) { $firstProofChainFailure.Event } else { '(none)' }
        FirstProofChainFailureReason = if ($null -ne $firstProofChainFailure) { $firstProofChainFailure.Reason } else { '(none)' }
        FirstProofChainFailureSequence = if ($null -ne $firstProofChainFailure) { $firstProofChainFailure.Sequence } else { -1L }
        FirstProofChainFailureSourcePath = if ($null -ne $firstProofChainFailure) { $firstProofChainFailure.SourcePath } else { '(none)' }
        FirstProofChainFailureLineNumber = if ($null -ne $firstProofChainFailure) { $firstProofChainFailure.LineNumber } else { 0 }
        FirstProofChainFailureWriterSequence = if ($null -ne $firstProofChainFailure) {
            [int64]$firstProofChainFailure.WriterSequence
        } else { 0L }
        SemanticFailureDomain = if ($class -in @(
                'runtime_unlock_regular_v4_route_commit_send_drain_missing',
                'runtime_unlock_precommit_probe_start_handoff_missing',
                'runtime_unlock_uncommitted_tuna_fallback_proof_authority_missing',
                'runtime_unlock_precommit_fallback_recovery_handoff_suppressed',
                'runtime_unlock_uncommitted_tuna_fallback_handoff_precommit_authority_misbound',
                'runtime_unlock_retry_dispatch_fallback_paired_yield_successor_release_invalid',
                'post_tuna_fallback_paired_yield_transport_epoch_reauthorization_missing',
                'regular_v4_frontier_repair_pressure_authority_lifecycle_split',
                'regular_v4_frontier_repair_pressure_recovery_handoff_missing')) {
            'route_runtime'
        } else {
            '(none)'
        }
        RuntimeUnlockOfferNotObservedCount = $runtimeUnlockOfferNotObservedEvents.Count
        RuntimeUnlockRetryScheduledCount = $runtimeUnlockRetryScheduledEvents.Count
        RuntimeUnlockRetryQueuedBehindActiveNegotiationCount = $runtimeUnlockRetryQueuedBehindActiveNegotiationEvents.Count
        RuntimeUnlockRetryDispatchedCount = $sessionRecoveryContractRetryDispatchedEvents.Count
        RuntimeUnlockRetryAuthorityGrantedCount = $sessionRecoveryContractRetryAuthorityGrantedEvents.Count
        RuntimeUnlockRetryAuthorityObservedCount = $sessionRecoveryContractRetryAuthorityObservedEvents.Count
        RuntimeUnlockRetryAuthorityFailedCount = $sessionRecoveryContractRetryAuthorityFailedEvents.Count
        RuntimeUnlockRetryDispatchProofVerdict = $runtimeUnlockRetryDispatchProofVerdict
        RuntimeUnlockRetryDispatchChainClosureProofVerdict = $runtimeUnlockRetryDispatchChainClosureProofVerdict
        RuntimeUnlockRetryReleaseCount = $runtimeUnlockRetryDispatchReleaseCount
        RuntimeUnlockRetryDispatchAuthorityGrantedRawCount = $runtimeUnlockRetryDispatchInstallProof.AuthorityGrantedRawCount
        RuntimeUnlockRetryDispatchAuthorityGrantedCount = $runtimeUnlockRetryDispatchAuthorityGrantedEvents.Count
        RuntimeUnlockRetryDispatchDecisionStagedCount = $runtimeUnlockRetryDispatchInstallProof.DecisionStagedCount
        RuntimeUnlockRetryDispatchInstallReceiptIssuedCount = $runtimeUnlockRetryDispatchInstallProof.ReceiptIssuedCount
        RuntimeUnlockRetryDispatchInstallCommittedCount = $runtimeUnlockRetryDispatchInstallProof.CommittedCount
        RuntimeUnlockRetryDispatchInstallRejectedCount = $runtimeUnlockRetryDispatchInstallProof.RejectedCount
        RuntimeUnlockRetryDispatchInstallVerdict = $runtimeUnlockRetryDispatchInstallProof.Verdict
        RuntimeUnlockRetryDispatchInstallGrantEvidenceIncompleteRawCount = $runtimeUnlockRetryDispatchInstallProof.GrantEvidenceIncompleteRawCount
        RuntimeUnlockRetryDispatchInstallGrantEvidenceIncompleteDistinctCount = $runtimeUnlockRetryDispatchInstallProof.GrantEvidenceIncompleteDistinctCount
        RuntimeUnlockRetryDispatchInstallGrantEvidenceIncompleteRecoveredCount = $runtimeUnlockRetryDispatchInstallProof.GrantEvidenceIncompleteRecoveredCount
        RuntimeUnlockRetryDispatchInstallGrantEvidenceIncompleteUnresolvedCount = $runtimeUnlockRetryDispatchInstallProof.GrantEvidenceIncompleteUnresolvedCount
        RuntimeUnlockRetryDispatchInstallGrantEvidenceVerdict = $runtimeUnlockRetryDispatchInstallProof.GrantEvidenceVerdict
        RuntimeUnlockRetryDispatchAuthorityRejectedCount = $runtimeUnlockRetryDispatchAuthorityRejectedEvents.Count
        RuntimeUnlockRetryDispatchSuccessorAttemptMismatchCount = $runtimeUnlockRetryDispatchSuccessorAttemptMismatchEvents.Count
        RuntimeUnlockRetryDispatchZeroOfferSuccessorRejectedRawCount = $runtimeUnlockRetryZeroOfferSuccessorProof.RawCount
        RuntimeUnlockRetryDispatchZeroOfferSuccessorRejectedDistinctCount = $runtimeUnlockRetryZeroOfferSuccessorProof.DistinctCount
        RuntimeUnlockRetryDispatchZeroOfferSuccessorRejectedRecoveredCount = $runtimeUnlockRetryZeroOfferSuccessorProof.RecoveredCount
        RuntimeUnlockRetryDispatchZeroOfferSuccessorRejectedUnresolvedCount = $runtimeUnlockRetryZeroOfferSuccessorProof.UnresolvedCount
        RuntimeUnlockRetryDispatchZeroOfferSuccessorVerdict = $runtimeUnlockRetryZeroOfferSuccessorProof.Verdict
        RuntimeUnlockRetryDispatchFallbackPairedYieldSuccessorReleaseInvalidRawCount = $runtimeUnlockRetryFallbackPairedYieldSuccessorReleaseProof.RawCount
        RuntimeUnlockRetryDispatchFallbackPairedYieldSuccessorReleaseInvalidDistinctCount = $runtimeUnlockRetryFallbackPairedYieldSuccessorReleaseProof.DistinctCount
        RuntimeUnlockRetryDispatchFallbackPairedYieldSuccessorReleaseInvalidRecoveredCount = $runtimeUnlockRetryFallbackPairedYieldSuccessorReleaseProof.RecoveredCount
        RuntimeUnlockRetryDispatchFallbackPairedYieldSuccessorReleaseInvalidUnresolvedCount = $runtimeUnlockRetryFallbackPairedYieldSuccessorReleaseProof.UnresolvedCount
        RuntimeUnlockRetryDispatchFallbackPairedYieldSuccessorReleaseVerdict = $runtimeUnlockRetryFallbackPairedYieldSuccessorReleaseProof.Verdict
        RuntimeUnlockRetryDispatchDecisionTupleRejectedCount = $runtimeUnlockRetryDispatchDecisionTupleRejectedEvents.Count
        RuntimeUnlockRetryDispatchCurrentAuthorityRejectedCount = $runtimeUnlockRetryDispatchCurrentAuthorityRejectedEvents.Count
        RuntimeUnlockRetryDispatchObservedCount = $runtimeUnlockRetryDispatchObservedEvents.Count
        RuntimeUnlockRetryDispatchContractSettledCount = $runtimeUnlockRetryDispatchContractSettledEvents.Count
        RuntimeUnlockRetryDispatchSettlementReportedCount = $runtimeUnlockRetryDispatchSettlementReportedEvents.Count
        RuntimeUnlockRetryDispatchSettlementAcceptedCount = $runtimeUnlockRetryDispatchSettlementAcceptedEvents.Count
        RuntimeUnlockRetryDispatchSettlementIdempotentCount = $runtimeUnlockRetryDispatchSettlementIdempotentEvents.Count
        RuntimeUnlockRetryDispatchSettlementRejectedCount = $runtimeUnlockRetryDispatchSettlementRejectedEvents.Count
        RuntimeUnlockRetryDispatchSettlementDecisionIgnoredCount = $runtimeUnlockRetryDispatchSettlementDecisionIgnoredEvents.Count
        RuntimeUnlockRetryDispatchSettlementAcceptanceMissingCount = $runtimeUnlockRetryDispatchSettlementAcceptanceMissingEvents.Count
        RuntimeUnlockRetryDispatchCompleteBoundedClosureCount = $runtimeUnlockRetryDispatchCompleteBoundedClosureEvents.Count
        RuntimeUnlockRetryDispatchIncompleteBoundedClosureCount = $runtimeUnlockRetryDispatchIncompleteBoundedClosureEvents.Count
        RuntimeUnlockRetryDispatchFreshIndependentGrantCount = $runtimeUnlockRetryDispatchFreshIndependentGrantEvents.Count
        RuntimeUnlockRetryDispatchInvalidFreshGrantCount = $runtimeUnlockRetryDispatchInvalidFreshGrantEvents.Count
        RuntimeUnlockRetryDispatchUnsettledAuthorityCount = $runtimeUnlockRetryDispatchUnsettledAuthorityEvents.Count
        RuntimeUnlockRetryDispatchGrantBypassedByRetryBudgetCount = $runtimeUnlockRetryDispatchGrantBypassedByRetryBudgetEvents.Count
        RuntimeUnlockRetryMissingDispatchSuccessorLimitRejectedCount = $runtimeUnlockRetryMissingDispatchSuccessorLimitRejectedEvents.Count
        RuntimeUnlockRetryDispatchDuplicateObservedCount = $runtimeUnlockRetryDispatchDuplicateObservedCount
        RuntimeUnlockRetryDispatchDuplicateSettlementCount = $runtimeUnlockRetryDispatchDuplicateSettlementCount
        RuntimeUnlockRetryDispatchOrphanedSupersessionCount = $runtimeUnlockRetryDispatchOrphanedSupersessionCount
        RuntimeUnlockRetryDispatchSuccessorMissingAfterMissingDispatchCount = $runtimeUnlockRetryDispatchSuccessorMissingAfterMissingDispatchCount
        RuntimeUnlockRetryDispatchPostGrantHoldCount = $runtimeUnlockRetryDispatchPostGrantHoldCount
        RuntimeUnlockRetryDispatchPostGrantHoldRawCount = $runtimeUnlockRetryDispatchPostGrantHoldProof.RawCount
        RuntimeUnlockRetryDispatchPostGrantHoldDistinctCount = $runtimeUnlockRetryDispatchPostGrantHoldProof.DistinctCount
        RuntimeUnlockRetryDispatchPostGrantHoldRecoveredCount = $runtimeUnlockRetryDispatchPostGrantHoldProof.RecoveredCount
        RuntimeUnlockRetryDispatchPostGrantHoldUnresolvedCount = $runtimeUnlockRetryDispatchPostGrantHoldProof.UnresolvedCount
        RuntimeUnlockRetryDispatchPostGrantHoldVerdict = $runtimeUnlockRetryDispatchPostGrantHoldProof.Verdict
        RuntimeUnlockRetryDispatchMissingCount = $runtimeUnlockRetryDispatchMissingCount
        RuntimeUnlockRetryDispatchMissingAfterAuthorityGrantedCount = $runtimeUnlockRetryDispatchMissingAfterAuthorityGrantedCount
        RuntimeUnlockRetryMissingAuthorityAfterReleaseCount = $runtimeUnlockRetryMissingAuthorityAfterReleaseCount
        RuntimeUnlockRetryBlockedByRegularV4RecoveryCount = $runtimeUnlockRetryBlockedByRegularV4RecoveryEvents.Count
        RuntimeUnlockRetryHeldByRegularV4RecoveryCount = $runtimeUnlockRetryHeldByRegularV4RecoveryEvents.Count
        RuntimeUnlockRetryRejectedAfterRegularV4RecoveryCount = $runtimeUnlockRetryRejectedAfterRegularV4RecoveryEvents.Count
        RuntimeUnlockRetryRegularV4RecoverySettlementMissingCount = $runtimeUnlockRetryRegularV4RecoverySettlementMissingCount
